const ENCYCLOPEDIA = [{"id":"C11","icon":"history","title":"تاریخ قهوه","items":[{"id":9,"title":"تاریخچه و فرهنگ (History and Culture)","body":"<ul><li>افسانه‌ی چوپان اتیوپیایی «کلدی» که نشاط بزهایش را پس از خوردن میوه می‌بیند، نخستین‌بار در سال ۱۶۷۱ نوشته شد؛ گیاه‌شناسان خاستگاه قهوه را جنوب‌غربی اتیوپی می‌دانند.</li><li>کشت و دم‌آوری قهوه از قرن پانزدهم در یمن توسعه یافت؛ بندر مخا مرکز صادرات بود.</li><li>قهوه‌خانه‌ها از قرن شانزدهم در قاهره، دمشق، مکه و استانبول و در قرن هفدهم در اروپا (ونیز، لندن، پاریس، وین) رایج شدند و نقش اجتماعی و فکری مهمی داشتند.</li><li>هلندی‌ها و فرانسوی‌ها کشت را به جاوه، آمریکا و جزایر کارائیب بردند؛ برزیل از دهه‌ی ۱۷۲۰ آغاز کرد و در قرن نوزدهم بزرگ‌ترین تولیدکننده شد.</li><li>زنگ قهوه (Hemileia vastatrix) نخستین‌بار در ۱۸۶۷ در سیلان ثبت شد و تا ۱۸۹۰ صنعت قهوه‌ی آنجا تقریباً نابود شد؛ بسیاری از مزارع به چای روی آوردند.</li><li>فرهنگ مدرن: موج اول (قهوه‌ی انبوه و فوری)، موج دوم (کافه‌های برند)، موج سوم (قهوه‌ی تخصصی و ردیابی خاستگاه)؛ «موج چهارم» اصطلاح نه‌چندان پذیرفته‌شده برای رویکرد علمی‌تر است.</li></ul>","kind":"item","src":[["Wikipedia — History of coffee","https://en.wikipedia.org/wiki/History_of_coffee"],["Wikipedia — Hemileia vastatrix (coffee rust)","https://en.wikipedia.org/wiki/Hemileia_vastatrix"]]},{"id":173,"title":"تاریخچه‌ی قهوه (از افسانه تا امروز) – با جدول زمانی","body":"<p>این گاهشمار فقط رویدادهایی را آورده که منابع تاریخی معتبر برایشان وجود دارد. افسانه‌ی «کالدی»، چوپان اتیوپیایی که بزهایش پس از خوردن میوه‌ی قهوه سرحال شدند، نخستین‌بار در ۱۶۷۱ نوشته شد؛ یعنی قرن‌ها پس از ماجرا، و سند تاریخی نیست. مستندترین نقطه‌ی آغاز، خانقاه‌های صوفیه در یمن در قرن پانزدهم است.</p><h4>گاهشمار تاریخی قهوه</h4><div class=\"table-wrap\"><table><thead><tr><th>زمان</th><th>رویداد</th><th>توضیح</th></tr></thead><tbody><tr><td>پیش از ۱۴۰۰ میلادی</td><td>ریشه‌ی گیاهی در اتیوپی</td><td>گیاه قهوه بومی جنگل‌های جنوب‌غرب اتیوپی است. شواهد باستان‌شناختی یا تاریخی مستندی برای نوشیدن قهوه پیش از قرن پانزدهم وجود ندارد.</td></tr><tr><td>اواسط قرن پانزدهم</td><td>صوفیان یمن</td><td>نخستین گزارش‌های مستند از نوشیدن قهوه از خانقاه‌های صوفیه در یمن است؛ شب‌زنده‌داری و ذکر.</td></tr><tr><td>۱۵۱۱</td><td>ممنوعیت مکه</td><td>خائر بیگ، حاکم مکه، قهوه را ممنوع کرد؛ سلطان قاهره حکم را لغو کرد و در حدود ۱۵۲۴ قهوه دوباره آزاد بود.</td></tr><tr><td>۱۵۳۷</td><td>نخستین اشاره‌ی مکتوب در ایران</td><td>بنا بر دانشنامه‌ی ایرانیکا، عمادالدین محمود شیرازی، پزشک ایرانی، در این سال از قهوه یاد کرده است.</td></tr><tr><td>حدود ۱۵۵۴</td><td>قهوه‌خانه‌ی استانبول</td><td>دو بازرگان شامی، حکیم و شمس، نخستین قهوه‌خانه‌ی استانبول را در محله‌ی تحت‌القلعه گشودند.</td></tr><tr><td>قرن شانزدهم و هفدهم</td><td>قهوه‌خانه‌های ایران</td><td>قهوه‌خانه‌ها در دوره‌ی صفوی در قزوین و اصفهان گسترش یافتند و مرکز شعر، نقالی و گفتگو شدند.</td></tr><tr><td>حدود ۱۶۱۵</td><td>ورود به ونیز</td><td>بازرگانان ونیزی که از استانبول بازمی‌گشتند، قهوه را به ایتالیا آوردند.</td></tr><tr><td>۱۶۱۶</td><td>دزدی هلندی‌ها</td><td>هلندی‌ها نهال قهوه را از بندر مخا در یمن بیرون بردند و کشت آن را در مستعمرات خود آغاز کردند.</td></tr><tr><td>۱۶۴۵</td><td>نخستین قهوه‌خانه‌ی اروپا</td><td>در ونیز گشوده شد.</td></tr><tr><td>۱۶۵۰ و ۱۶۵۲</td><td>قهوه‌خانه در انگلستان</td><td>ابتدا در آکسفورد (مردی به نام یاکوب) و دو سال بعد در لندن به‌دست پاسکوا روزه.</td></tr><tr><td>۱۷۲۷</td><td>برزیل</td><td>فرانسیسکو دِ ملو پالیتا نهال قهوه را از گویان فرانسه به برزیل آورد؛ آغاز مسیری که برزیل را بزرگ‌ترین تولیدکننده کرد.</td></tr><tr><td>۱۸۸۴</td><td>نخستین دستگاه اسپرسو</td><td>آنجلو موریوندو در تورین ایتالیا دستگاهی برای دم سریع قهوه ثبت کرد.</td></tr><tr><td>۱۹۰۱</td><td>قهوه‌ی فوری و اسپرسو</td><td>ساتوری کاتو قهوه‌ی فوری را در آمریکا معرفی کرد و لوییجی بتسرا دستگاه اسپرسوی میلان را ثبت کرد.</td></tr><tr><td>۱۹۰۸</td><td>فیلتر کاغذی</td><td>ملیتا بنتس در آلمان فیلتر کاغذی را ثبت کرد.</td></tr><tr><td>۱۹۳۳</td><td>موکاپات</td><td>آلفونسو بیالتی موکاپات را در ایتالیا ساخت.</td></tr><tr><td>۱۹۳۸</td><td>نسکافه</td><td>نستله پس از سال‌ها تحقیق نسکافه را در سوئیس عرضه کرد.</td></tr><tr><td>۱۹۴۸</td><td>کرما</td><td>آچیله گاجا با دستگاه اهرمی، فشار بالا و کرمای امروزی اسپرسو را ممکن کرد.</td></tr><tr><td>۱۹۶۱</td><td>فائما E61</td><td>دستگاه پمپ‌دار فائما استاندارد اسپرسوسازهای مدرن شد.</td></tr><tr><td>۱۹۷۱</td><td>استارباکس</td><td>نخستین شعبه‌ی استارباکس در سیاتل گشوده شد و در ابتدا دانه‌ی قهوه می‌فروخت.</td></tr><tr><td>۲۰۰۰ به بعد</td><td>موج سوم</td><td>تأکید بر خاستگاه، رست روشن و دم‌آوری دستی در کافه‌های تخصصی.</td></tr><tr><td>۲۰۱۳</td><td>میراث یونسکو</td><td>فرهنگ و سنت قهوه‌ی ترک در فهرست میراث ناملموس یونسکو ثبت شد.</td></tr><tr><td>۲۰۱۵</td><td>قهوه‌ی عربی</td><td>یونسکو قهوه‌ی عربی را به‌عنوان نماد سخاوت ثبت کرد.</td></tr><tr><td>۲۰۱۹</td><td>قهوه‌ی یزدی</td><td>قهوه‌ی یزدی در فهرست آثار ملی ناملموس ایران ثبت شد.</td></tr></tbody></table></div>","kind":"item","src":[["Wikipedia — History of coffee","https://en.wikipedia.org/wiki/History_of_coffee"]]},{"id":194,"title":"تاریخچه‌ی تکامل ماشین‌های اسپرسو (از ۱۸۸۴ تا امروز)","body":"<h4 class=\"sub\">تاریخچه‌ی ماشین اسپرسو</h4><ul><li>۱۸۸۴: Angelo Moriondo ماشین بخار را برای دم انبوه ثبت کرد.</li><li>۱۹۰۱: Luigi Bezzera ماشینی ثبت کرد که یک سهم را جدا دم می‌کرد.</li><li>۱۹۰۳–۱۹۰۵: Desiderio Pavoni حق اختراع را خرید، مکانیزم تخلیه‌ی فشار افزود و از ۱۹۰۵ فروش را آغاز کرد.</li><li>۱۹۴۷–۱۹۴۸: Achille Gaggia ماشین پیستونی اهرمی را توسعه داد که فشار را تا حدود ۱۲ اتمسفر می‌رساند و کرما می‌ساخت؛ معمولاً نخستین ماشین مدرن اسپرسو دانسته می‌شود. ماشین‌های اولیه فقط حدود ۱٫۵ بار فشار داشتند.</li><li>۱۹۶۱: Faema E61 با پمپ و مبدل حرارتی؛ ۱۹۷۰: La Marzocco GS دوبویلر.</li></ul>","kind":"item","src":[["Wikipedia — Espresso","https://en.wikipedia.org/wiki/Espresso"],["Wikipedia — Espresso machine","https://en.wikipedia.org/wiki/Espresso_machine"]]},{"id":226,"title":"قهوه‌های ممنوع و ماجراهای عجیب تاریخ","body":"<ul><li>ممنوعیت‌ها: در ۱۵۱۱ قهوه در مکه ممنوع شد و در ۱۵۲۴ فتوای مفتی بزرگ عثمانی آن را مجاز دانست؛ در عثمانی در دوره‌هایی (از جمله مراد چهارم) قهوه‌خانه‌ها بسته شدند.</li><li>فردریک بزرگ در ۱۷۷۷ مصرف قهوه را برای عامه محدود کرد و مأمورانی («بوکشندگان قهوه») برای کشف قهوه‌ی قاچاق گماشت؛ جایگزین‌هایی مثل قهوه‌ی کاسنی رایج شد.</li><li>قهوه‌ی جایگزین (Ersatz): در محاصره‌ی قاره‌ای ناپلئون و جنگ‌های جهانی، کاسنی، جو و بلوط برشته جای قهوه را گرفت.</li><li>کانتات قهوه‌ی باخ (حدود ۱۷۳۲–۱۷۳۵) طنزی موسیقایی درباره‌ی اعتیاد به قهوه در لایپزیگ است.</li><li>داستان آزمایش پادشاه سوئد گوستاو سوم روی دو برادر دوقلو (یکی قهوه، یکی چای) روایتی مشهور است که سند محکمی ندارد.</li></ul>","kind":"item","src":[["Wikipedia — History of coffee","https://en.wikipedia.org/wiki/History_of_coffee"]]},{"id":473,"title":"قهوه در بحران‌ها و جنگ‌ها (Coffee in Crises & Wars)","body":"<h4 class=\"sub\">قهوه در جنگ‌ها</h4><ul><li>جنگ داخلی آمریکا: ارتش اتحادیه «عصاره‌ی قهوه» (Essence of Coffee) دریافت می‌کرد؛ سربازان آن را دوست نداشتند و متوقف شد. در جنوب آمریکا قهوه کمیاب بود و در لوئیزیانا از کاسنی استفاده شد.</li><li>محاصره‌ی قاره‌ای (اوایل قرن نوزدهم): کمبود قهوه در فرانسه باعث رواج گسترده‌ی کاسنی شد.</li><li>جنگ جهانی دوم: بلوط، کاسنی برشته و غلات جایگزین قهوه شدند؛ Postum (نوشیدنی سبوس و ملاس) وقتی قهوه سهمیه‌بندی شد محبوب شد. نسکافه از طریق جیره‌ی ارتش آمریکا مشهور شد و سربازان آمریکایی قهوه‌ی فوری را به بریتانیا بردند.</li></ul>","kind":"item","src":[["Wikipedia — Instant coffee","https://en.wikipedia.org/wiki/Instant_coffee"],["Wikipedia — Coffee substitute","https://en.wikipedia.org/wiki/Coffee_substitute"]]},{"id":710,"title":"قهوه در ایران: از صفوی تا امروز","body":"<p>قهوه در قرن شانزدهم میلادی، دوران صفوی، به ایران آمد. تجارت با امپراتوری عثمانی و جهان عرب آن را به اصفهان و شیراز رساند.</p><h4>قاجار و رقیب چای</h4><p>در دوره‌ی قاجار قهوه‌خانه‌ها که بیشتر چایخانه بودند گاهی قهوه هم سرو می‌کردند. با فراگیرشدن چای سیاه، مصرف قهوه افت کرد. </p><h4>قرن بیستم تا امروز</h4><ul><li>در قرن بیستم نخستین کافه‌های مدرن تهران، تا حدی الهام‌گرفته از فرهنگ کافه‌ی اروپایی، باز شد و قهوه جایگاهش را بازیافت.</li><li>دهه‌های ۱۹۹۰ و ۲۰۰۰: سفر خارجی، برندهای جهانی و گسترش کافی‌شاپ‌ها قهوه را به بخش مهمی از سبک زندگی جوانان تبدیل کرد.</li><li>امروز برگزاری رقابت‌های باریستا و جشنواره‌های قهوه رایج است و باریستاهای ایرانی در رقابت‌های بین‌المللی شرکت کرده‌اند.</li><li>تهران حدود ۳٬۰۰۰ کافی‌شاپ دارد.</li></ul>","kind":"item","src":[["Wikipedia — Coffee in Iran","https://en.wikipedia.org/wiki/Coffee_in_Iran"]]},{"id":711,"title":"قهوه‌ی ترک: تاریخ، آیین و روش","body":"<h4>تاریخ</h4><ul><li>۱۵۳۹: سندی حقوقی از «اتاق قهوه» در خانه‌ی باربروس خیرالدین پاشا در استانبول یاد می‌کند.</li><li>۱۵۴۳: چند کشتی به‌خاطر واردکردن قهوه در بندر استانبول دستور غرق‌شدن گرفتند.</li><li>۱۵۵۴ (برخی ۱۵۵۱): نخستین قهوه‌خانه‌ی استانبول را دو تاجر عرب گشودند.</li><li>طبق مورخی ارمنی، پانزده سال پس از ورود قهوه به استانبول بیش از ۶۰۰ قهوه‌خانه وجود داشت.</li><li>از ۱۵۳۸ تا ۱۶۳۶ عثمانی بر ساحل جنوبی یمن، از جمله موکا، مسلط بود.</li><li>سلطان مراد چهارم: قهوه‌خانه‌دار در بار اول «چوب‌خورده» و در بار دوم «در کیسه دوخته و به بسفر انداخته» می‌شد.</li></ul><h4>روش</h4><p>قهوه در جذوه‌ای مسی ریخته می‌شود که ته آن از گردنش پهن‌تر است. قهوه و آب را تا آستانه‌ی جوش گرم می‌کنند، به‌محض ظاهر شدن کف از حرارت برمی‌دارند و دو بار دیگر کوتاه می‌جوشانند. روش شن: جذوه در تابه‌ای از شن داغ روی شعله قرار می‌گیرد و معمولاً سه تا چهار بار تکرار می‌شود.</p><h4>آسیاب</h4><p>دانه باید «پودر بسیار ریز» شود؛ اندازه‌ی ذره حدود ۷۵ تا ۱۲۵ میکرون ذکر شده است. آسیاب برقی خانگی مناسب نیست و آسیاب دستی ویژه‌ی آسیاب بسیار ریز توصیه شده است. استثنا: «قهوه‌ی دیبک» که درشت کوبیده می‌شود تا روغن‌های معطر بماند.</p><h4>آیین‌ها</h4><ul><li>فال فنجان (tasseography): فنجان را در نعلبکی برمی‌گردانند تا خنک شود و الگوی تفاله خوانده شود.</li><li>خواستگاری: عروس‌خانم قهوه را برای خانواده‌ی داماد می‌آورد و گاهی برای فنجان داماد نمک می‌گذارد تا خُلق او را بسنجد؛ اگر بی‌ناراحتی بنوشد، صبور و خوش‌خلق شمرده می‌شود.</li><li>در برخی مناطق قهوه‌ی بی‌کف یعنی «شانسی نداری!».</li></ul><p>یونسکو فرهنگ و سنت قهوه‌ی ترک را در فهرست نمایندگان میراث ناملموس ثبت کرده است.</p>","kind":"item","src":[["Wikipedia — Turkish coffee","https://en.wikipedia.org/wiki/Turkish_coffee"]]},{"id":712,"title":"ماجرای دو کلیو و مارتینیک","body":"<p>طبق روایت خود گابریل دو کلیو (حدود ۱۶۸۷ تا ۱۷۷۴)، او در ۱۷۲۰ سه نهال قهوه را به مارتینیک برد. نهال‌ها از گلخانه‌های باغ سلطنتی گیاهان پاریس آمده بود که در ۱۷۱۳ دو بوته از هلند گرفته بود.</p><h4>داستان سفر</h4><p>او می‌گوید در سفر آب جیره‌بندی بود و سهم خود را با نهال‌ها تقسیم کرد. این داستان در بسیاری از تاریخ‌های قهوه تکرار شده است.</p><h4>اما قضیه چقدر دقیق است؟</h4><ul><li>گفته می‌شود ممکن است او واقعاً نهالی به مارتینیک برده باشد، ولی نخستین کسی نبود که قهوه را به کارائیب برد.</li><li>۱۷۱۵: قهوه در سن‌دومینگ (مستعمره‌ی فرانسه) و ۱۷۱۸ در سورینام (مستعمره‌ی هلند) کاشته می‌شد.</li><li>او بیشتر به‌خاطر نزدیکی زمان و گزارش‌های نمایشی خودش شهرت یافته است. منابع لاکور از تلاش او برای کشت و توزیع قهوه در مستعمره سخن می‌گویند، نه معرفی آن.</li><li>او از ۱۷۳۷ تا ۱۷۵۲ فرماندار گوادلوپ بود و ۲۹ نوامبر ۱۷۷۴ در پاریس درگذشت؛ روایت او در ۱۷۷۴ در مجله‌ی Année littéraire چاپ شد.</li></ul>","kind":"item","src":[["Wikipedia — Gabriel de Clieu","https://en.wikipedia.org/wiki/Gabriel_de_Clieu"]]},{"id":713,"title":"بابا بودان و قهوه‌ی هند","body":"<p>بابا بودان صوفیِ قرن هفدهم است که آرامگاهش در بابا بودانگیری، چیکمگالور کارناتاکا قرار دارد. بنا بر روایت، پس از بازگشت از حج (روایتی بازگشت را ۱۶۷۰ می‌داند) هفت دانه‌ی خام قهوه را از بندر موکا در یمن، گاهی در ریش پنهان، بیرون آورد و در دامنه‌ی تپه‌های چاندرادرونا کاشت. هفت عدد را مقدس در اسلام می‌دانند.</p><p><b>هشدار:</b> هیچ‌یک از ادعاهای این روایت سند معتبر ندارد و روایت دوم «افسانه‌ی رایج هندی» خوانده شده؛ پس این را تاریخ مستند ندانید.</p><h4>تاریخ مستندتر قهوه‌ی هند</h4><ul><li>اوایل ۱۶۰۰: ثبت نوشیدن قهوه در هنر و گزارش‌های دربار مغول، از جمله قهوه‌خانه‌ها (qahwakhana) در شاه‌جهان‌آباد (دهلی قدیم).</li><li>نیمه‌ی دوم ۱۶۰۰: شرکت هند شرقی هلند ظرفیت تجاری قهوه‌ی هند را دید و بعد روی جاوه متمرکز شد.</li><li>اواخر ۱۷۰۰: شرکت هند شرقی بریتانیا مزارع خود را در کورگ (کودآگو) ساخت.</li><li>اواسط ۱۹۰۰: شکر جای شیرین‌کننده‌های سنتی (نیشکر خام و عسل) را در قهوه‌ی فیلتر گرفت.</li></ul>","kind":"item","src":[["Wikipedia — Baba Budan","https://en.wikipedia.org/wiki/Baba_Budan"],["Wikipedia — Indian filter coffee","https://en.wikipedia.org/wiki/Indian_filter_coffee"]]},{"id":714,"title":"قهوه در ویتنام","body":"<p>ویتنام دومین تولیدکننده‌ی بزرگ قهوه پس از برزیل است و روبوستا حدود ۹۷٪ تولیدش را تشکیل می‌دهد؛ توسعه بیشتر در استان داک‌لاک در ارتفاعات مرکزی بوده است.</p><div class=\"table-wrap\"><table><thead><tr><th>سال</th><th>رویداد</th></tr></thead><tbody><tr><td>۱۸۵۷</td><td>گمان می‌رود مبلغان فرانسوی قهوه را وارد کردند.</td></tr><tr><td>۱۸۸۸</td><td>نخستین مزارع قهوه در استان‌های نین‌بین و کوانگ‌بین در تونکین.</td></tr><tr><td>دهه‌ی ۱۹۲۰</td><td>فرانسوی‌ها مناطق تولید در ارتفاعات مرکزی، به‌ویژه داک‌لاک، را باز کردند.</td></tr><tr><td>۱۹۳۰ و ۱۹۴۰</td><td>صادرات سالانه حدود ۱٬۵۰۰ تن و سپس حدود ۲٬۰۰۰ تن.</td></tr><tr><td>۱۹۶۹</td><td>نخستین کارخانه‌ی قهوه‌ی فوری در بین‌هوا با ظرفیت ۸۰ تن در سال.</td></tr><tr><td>۱۹۸۶</td><td>اصلاحات «دوی مویی» بخش خصوصی را آزاد کرد و رشد سریع شد.</td></tr><tr><td>۲۰۰۱</td><td>با افت قیمت جهانی، خانوارهای کشاورز وعده‌ها را کم کردند یا به کمک غذایی تکیه کردند.</td></tr><tr><td>۲۰۱۳</td><td>استارباکس نخستین فروشگاه خود در ویتنام را باز کرد؛ برداشت رکورد ۲۹٫۵ میلیون کیسه‌ای ۲۰۱۳–۲۰۱۴ قیمت را فروریخت.</td></tr><tr><td>۲۰۲۳</td><td>صادرات ۱٫۶۲ میلیون تن.</td></tr></tbody></table></div><p>برآورد بانک جهانی (۲۰۱۱): بدون کاشت دوباره، تولید تا اواسط دهه‌ی ۲۰۲۰ حدود ۳۰ تا ۴۰٪ کم می‌شود.</p>","kind":"item","src":[["Wikipedia — Coffee production in Vietnam","https://en.wikipedia.org/wiki/Coffee_production_in_Vietnam"]]},{"id":715,"title":"ابزارهای دم‌آوری: از سیفون تا ایروپرس","body":"<div class=\"table-wrap\"><table><thead><tr><th>سال</th><th>ابزار / رویداد</th></tr></thead><tbody><tr><td>۱۷۹۹</td><td>ریچارد دیرمن، آهنگر بیرمنگام انگلیس، نخستین آسیاب قهوه را ساخت.</td></tr><tr><td>۱۸۱۸</td><td>اینکریس ویلسون در آمریکا نخستین آسیاب دیواری را ثبت کرد.</td></tr><tr><td>۱۸۲۷</td><td>یوهان نورنبرگ ماشین وکیوم (سیفون) را ساخت.</td></tr><tr><td>۱۹۴۱</td><td>پیتر شلومبوم چمکس را ساخت؛ در ۱۹۵۸ طراحان مؤسسه‌ی فناوری ایلینوی آن را «یکی از بهترین محصولات طراحی‌شده‌ی دنیای مدرن» خواندند.</td></tr><tr><td>۲۰۰۴–۲۰۰۵</td><td>آلن آدلر ایروپرس را در گاراژ نمونه‌سازی و در نوامبر ۲۰۰۵ در CoffeeFest سیاتل رونمایی کرد.</td></tr><tr><td>۲۰۱۷</td><td>سازنده‌ی ایروپرس فیلتر فلزی را توصیه نکرد؛ تا ۲۰۲۴ فیلتر استیل خود را هم می‌فروشد.</td></tr></tbody></table></div><p>آسیاب‌های دستی در دهه‌ی ۲۰۲۰ برای پوراوور و اسپرسوی تک‌نفره دوباره محبوب شدند.</p>","kind":"item","src":[["Wikipedia — Coffee grinder","https://en.wikipedia.org/wiki/Coffee_grinder"],["Wikipedia — Vacuum coffee maker","https://en.wikipedia.org/wiki/Vacuum_coffee_maker"],["Wikipedia — Chemex Coffeemaker","https://en.wikipedia.org/wiki/Chemex_Coffeemaker"],["Wikipedia — AeroPress","https://en.wikipedia.org/wiki/AeroPress"]]}]},{"id":"C1","icon":"botany","title":"گیاه‌شناسی، کشت، برداشت و فرآوری قهوه","items":[{"id":0,"title":"مبانی گیاه‌شناسی (Botanical Basis)","body":"<p>قهوه سرده‌ای (Coffea) از خانواده‌ی روناسیان (Rubiaceae) است. ۱۳۳ گونه و یک هیبرید پذیرفته شده است. دو گونه‌ی تجاری اصلی عربیکا و روبوستا (کانفورا) هستند.</p>\n<div class=\"table-wrap\"><table><thead><tr><th>ویژگی</th><th>عربیکا (C. arabica)</th><th>روبوستا (C. canephora)</th></tr></thead><tbody>\n<tr><td>سهم تولید جهانی</td><td>حدود ۶۰٪ (بعضی منابع: حدود ۵۵٪)</td><td>حدود ۴۵٪</td></tr>\n<tr><td>کروموزوم</td><td>تتراپلوئید، ۴۴ کروموزوم (چهار نسخه از ۱۱ کروموزوم)</td><td>—</td></tr>\n<tr><td>کافئین</td><td>حدود ۱٫۵٪</td><td>حدود ۲٫۷٪</td></tr>\n<tr><td>قند</td><td>۶ تا ۹٪</td><td>۳ تا ۷٪</td></tr>\n<tr><td>ارتفاع کشت رایج</td><td>۱۲۰۰ تا ۱۵۰۰ متر</td><td>—</td></tr>\n<tr><td>دمای مناسب</td><td>میانگین ۱۵ تا ۲۴ °C</td><td>—</td></tr>\n<tr><td>بارش مناسب</td><td>۱٫۲ تا ۱٫۸ متر در سال، یکنواخت</td><td>—</td></tr>\n<tr><td>طعم</td><td>شیرین‌تر</td><td>تلخی بیشتر، طعم خاکی و چوبی، اسیدیته‌ی کمتر</td></tr>\n<tr><td>مقاومت</td><td>حساس‌تر به آفت و بیماری</td><td>مقاوم‌تر؛ به سم و علف‌کش کمتری نیاز دارد</td></tr>\n</tbody></table></div>\n<h4>خاستگاه عربیکا</h4><ul><li>عربیکا نتیجه‌ی تلاقی دو گونه‌ی دیپلوئید C. canephora و C. eugenioides است که بین ۱٫۰۸ میلیون تا ۵۴۳ هزار سال پیش رخ داده است.</li><li>خاستگاه آن ارتفاعات اتیوپی و فلات بومای سودان است.</li></ul>\n<h4>بوته و میوه</h4><ul><li>در مناطق گرمسیری بوته یا درخت کوچکی با ارتفاع ۳ تا ۳٫۵ متر است. گیاه وحشی عربیکا ۹ تا ۱۲ متر و ارقام تجاری حدود ۵ متر می‌شوند که اغلب تا ۲ متر هرس می‌شوند.</li><li>سه تا چهار سال پس از کاشت، گل‌های سفید و بسیار معطر ظاهر می‌شود.</li><li>میوه معمولاً دو دانه دارد؛ ۵ تا ۱۰٪ میوه‌ها فقط یک دانه دارند (پی‌بری).</li><li>هفت لایه‌ی گیلاس: پوست بیرونی، گوشت، لایه‌ی پکتین، پوسته‌ی پارچمنت، پوسته‌ی نقره‌ای، دانه (اندوسپرم) و برش مرکزی.</li><li>گیلاس حدود ۸ تا ۹ ماه پس از گل‌دهی می‌رسد (منابع بین ۸ تا ۹ ماه متفاوت‌اند).</li><li>درخت عربیکا پس از ۳ تا ۵ سال میوه می‌دهد و به‌طور میانگین ۵۰ تا ۶۰ سال (تا ۱۰۰ سال) بارور می‌ماند.</li></ul>\n","kind":"item","src":[["Wikipedia — Coffea","https://en.wikipedia.org/wiki/Coffea"],["Wikipedia — Coffea arabica","https://en.wikipedia.org/wiki/Coffea_arabica"],["Wikipedia — Coffea canephora","https://en.wikipedia.org/wiki/Coffea_canephora"],["Wikipedia — Coffee processing","https://en.wikipedia.org/wiki/Coffee_processing"]]},{"id":2,"title":"کاشت و فرآوری (Cultivation and Processing)","body":"<h4>روش‌های فرآوری پس از برداشت</h4>\n<div class=\"table-wrap\"><table><thead><tr><th>روش</th><th>شرح</th></tr></thead><tbody>\n<tr><td>خشک (طبیعی)</td><td>کل گیلاس خشک می‌شود، قدیمی‌ترین روش است. ابتدا گیلاس‌های نارس، بیش‌ازحد رسیده و آسیب‌دیده جدا می‌شوند. بسته به هوا تا چهار هفته طول می‌کشد. حدود ۹۰٪ عربیکای برزیل و تقریباً همه‌ی روبوستاها به این روش فرآوری می‌شوند.</td></tr>\n<tr><td>شسته (مرطوب)</td><td>پوست و بخشی از گوشت میوه با فشار در آب از روی صافی جدا می‌شود. حذف موسیلاژ با تخمیر معمولاً ۸ تا ۳۶ ساعت طول می‌کشد (بسته به دما، ضخامت لایه و غلظت آنزیم‌ها). تخمیر می‌تواند با آب اضافه یا «خشک» و فقط در آب میوه باشد. بعد دانه‌ها به رطوبت حدود ۱۰٪ می‌رسند (معمولاً زیر آفتاب تا ۱۲–۱۳٪ و بقیه با ماشین).</td></tr>\n<tr><td>عسلی (هانی)</td><td>بین شسته و طبیعی است: معمولاً بخشی از بدنه و شیرینی طبیعی را با بخشی از اسیدیته‌ی شسته نگه می‌دارد.</td></tr>\n<tr><td>نیمه‌خشک (Giling Basah)</td><td>در اندونزی و برزیل؛ پارچمنت با پوست‌گیری مکانیکی و خشک‌کردن نیمه در آفتاب با ۲۵ تا ۴۰٪ رطوبت فروخته می‌شود و بعد تا ۱۰–۱۲٪ خشک می‌شود.</td></tr>\n</tbody></table></div>\n<ul><li>هنگام خشک‌شدن دانه‌ها باید دائم جابه‌جا شوند تا کپک نزنند؛ فرآوری‌کننده باید ۲ تا ۳ بار در ساعت آن‌ها را شخم بزند.</li><li>پوست‌گیری (Hulling) پوسته‌ی باقی‌مانده را برمی‌دارد، از سنگ آسیاب ساده تا ماشین‌های ظریف.</li><li>مرتب‌سازی: جداسازی بر اساس چگالی با دمش هوا، سپس رنگ‌گیری. بهترین قهوه‌ها ممکن است دو یا سه بار با دست پاک‌سازی شوند.</li><li>درجه‌بندی بر اساس اندازه‌ی دانه، منطقه و ارتفاع، روش فرآوری و برداشت و کیفیت طعم انجام می‌شود.</li></ul>\n<h4>برداشت</h4><ul><li>برداشت انتخابی: فقط گیلاس‌های رسیده با دست چیده می‌شوند؛ بیشتر برای عربیکای باکیفیت.</li><li>برداشت یکجا (Strip): همه‌ی میوه‌ها صرف‌نظر از رسیدگی کنده می‌شوند و در کشورهایی مثل برزیل مکانیزه است.</li><li>تولید قهوه منبع درآمد ۱۲٫۵ میلیون خانوار است که بیشترشان در کشورهای در حال توسعه‌اند.</li></ul>\n","kind":"item","src":[["Wikipedia — Coffee processing","https://en.wikipedia.org/wiki/Coffee_processing"],["Wikipedia — Coffee production","https://en.wikipedia.org/wiki/Coffee_production"]]},{"id":16,"title":"ردپای اکولوژیک (Ecological Footprint)","body":"<p>ردپای آبی قهوه را مطالعه‌ی Chapagain و Hoekstra (۲۰۰۷) برای هلند برآورد کرده است: حدود ۱۴۰ لیتر آب برای یک فنجان قهوه (بر پایه‌ی ۷ گرم قهوه‌ی برشته)، شامل کشت و فرآوری.</p><ul><li>بیشترین حجم آن آب باران مصرف‌شده در کشت گیاه است؛ در فرآوری تر، آب فرآیندی فقط حدود ۰٫۳۴٪ کل است.</li><li>این عدد «آب مجازی» است و به‌معنای مصرف آب آشامیدنی نیست.</li><li>مطالعه‌ی ۲۰۰۷ در مجموع ۲۵ کشور تولیدکننده‌ی قهوه را بررسی کرده است.</li><li>میانگین جهانی آب مجازی قهوه (وزن‌دهی‌شده با تولید) ۲۰٬۹۸۷ مترمکعب به ازای هر تن است.</li><li>بیشترین مقدار برای توگو (۴۹٬۳۴۱ مترمکعب بر تن) و غنا (۴۷٬۵۵۴) و کمترین برای ویتنام (۶٬۰۵۴) گزارش شده است.</li><li>بیش از ۹۹٪ ردپای آبی قهوه از کشت گیاه می‌آید. منتقدان می‌گویند عدد ۱۴۰ لیتر آب سبز، آبی و خاکستری را جمع می‌زند و محل کشت را در نظر نمی‌گیرد.</li></ul>","kind":"item","src":[["Chapagain & Hoekstra 2007 — Water footprint of coffee and tea consumption in the Netherlands","https://ayhoekstra.nl/pubs/Chapagain-Hoekstra-2007.pdf"],["Coffee Habitat — The water footprint of coffee","https://www.coffeehabitat.com/2009/09/water-footprint-of-coffee/"],["Daily Coffee News — The measure of coffee's water footprint needs to be revised","https://dailycoffeenews.com/2016/04/01/the-measure-of-coffees-water-footprint-needs-to-be-revised"]]},{"id":174,"title":"آناتومی و فیزیولوژی درخت قهوه (مشروح)","body":"<h4>درخت</h4><ul><li>گیاه بوته یا درخت کوچک پرقدرتی است؛ ارتفاع رایج ۳ تا ۳٫۵ متر (ارقام تجاری عربیکا حدود ۵ متر و اغلب هرس‌شده تا ۲ متر).</li><li>برگ عربیکا ۶ تا ۱۲ سانتی‌متر طول و ۴ تا ۸ سانتی‌متر عرض دارد.</li><li>گل‌ها سفید و بسیار معطرند و سه تا چهار سال پس از کاشت ظاهر می‌شوند.</li></ul>\n<h4>میوه</h4><p>میوه‌ی قهوه هفت لایه دارد: پوست بیرونی، گوشت، لایه‌ی پکتین، پوسته‌ی پارچمنت، پوسته‌ی نقره‌ای، دانه و برش مرکزی. معمولاً دو دانه دارد و ۵ تا ۱۰٪ میوه‌ها فقط یک دانه (پی‌بری) دارند. رسیدن میوه حدود ۸ تا ۹ ماه طول می‌کشد.</p>\n<h4>بیماری و آفت</h4><div class=\"table-wrap\"><table><thead><tr><th>عامل</th><th>اطلاعات</th></tr></thead><tbody>\n<tr><td>زنگ قهوه (Hemileia vastatrix)</td><td>قارچی که توان فتوسنتز گیاه را کم می‌کند؛ لکه‌های زرد کم‌رنگ و ریزش برگ. برای رشد به دمای ۱۶ تا ۲۸ °C و آب آزاد نیاز دارد. در ۲۰۱۲ تولید آمریکای مرکزی را ۱۶٪ کاهش داد.</td></tr>\n<tr><td>سوسک میوه‌ی قهوه (Hypothenemus hampei)</td><td>رشد از تخم تا بالغ ۲۴ تا ۴۵ روز؛ ماده دو روز پس از نفوذ ۳۵ تا ۵۰ تخم می‌گذارد؛ یک گیاه می‌تواند ۳ تا ۵ نسل را میزبانی کند.</td></tr>\n<tr><td>برگ‌خوار قهوه (Leucoptera caffeina)</td><td>به‌عنوان آفت قهوه نام برده شده است.</td></tr>\n</tbody></table></div>\n","kind":"item","src":[["Wikipedia — Coffea","https://en.wikipedia.org/wiki/Coffea"],["Wikipedia — Coffea arabica","https://en.wikipedia.org/wiki/Coffea_arabica"],["Wikipedia — Coffee leaf rust","https://en.wikipedia.org/wiki/Coffee_leaf_rust"],["Wikipedia — Coffee berry borer","https://en.wikipedia.org/wiki/Coffee_berry_borer"],["Wikipedia — Coffee processing","https://en.wikipedia.org/wiki/Coffee_processing"]]},{"id":175,"title":"جغرافیای قهوه – نقشه‌ی کامل مناطق تولید (با جزئیات طعم)","body":"<p>این جدول فقط شامل اطلاعاتی است که در منابع زیر راستی‌آزمایی شد. طعم واقعی به فرآوری و برشته‌کاری هم وابسته است.</p>\n<div class=\"table-wrap\"><table><thead><tr><th>منطقه</th><th>مشخصات</th></tr></thead><tbody>\n<tr><td>اتیوپی — سیدامو</td><td>ارتفاع ۱۵۰۰ تا ۲۲۰۰ متر (Strictly High Grown). طعم: متعادل، با نت‌های توت و مرکبات و اسیدیته‌ی پیچیده.</td></tr>\n<tr><td>اتیوپی — هرر</td><td>فرآوری خشک و تقریباً کاملاً دستی. طعم: میوه‌ای، شرابی و موکا.</td></tr>\n<tr><td>اتیوپی — کافا</td><td>رشد وحشی در ارتفاع ۱۴۰۰ تا ۲۱۰۰ متر. طعم: عمیق، ادویه‌ای، شرابی یا شکلاتی با عطر گلی.</td></tr>\n<tr><td>اتیوپی — یرگاچف</td><td>شهر یرگاچف در ارتفاع حدود ۱۸۸۰ تا ۱۹۱۹ متر است و منطقه‌ی مهم کشت قهوه شناخته می‌شود. نام‌های سیدامو، یرگاچف، هرر، لیمو، جیما و کافا برندهای ثبت‌شده‌ی اتیوپی‌اند.</td></tr>\n<tr><td>کنیا</td><td>قهوه‌ی «Colombia mild»؛ طعم شدید، بدنه‌ی کامل و عطر خوشایند با نت کاکائو. ۷۰٪ از مزارع کوچک است و ۱۵۰ هزار کشاورز (برآورد ۲۰۱۲) دارد؛ در حراج بورس نایروبی ۱۲۷٫۸ میلیون دلار در سال قهوه‌ی ۲۰۲۲–۲۰۲۳ فروخته شد.</td></tr>\n<tr><td>کلمبیا</td><td>قهوه‌ی «ملایم و متعادل»؛ طعم حاصل خاک، ارتفاع، رقم و روش برداشت. محور اصلی: مثلث قهوه (کالداس، کیندیو، ریسارالدا). ۲۰۰۷ نشان مبدأ محافظت‌شده‌ی اتحادیه‌ی اروپا و ۲۰۱۱ ثبت منظر فرهنگی قهوه در یونسکو.</td></tr>\n<tr><td>برزیل</td><td>تقریباً همه‌ی قهوه به روش خشک (طبیعی) فرآوری می‌شود؛ گیلاس‌ها ۸ تا ۱۰ روز خشک می‌شوند. باغ‌ها حدود ۲۷٬۰۰۰ کیلومتر مربع و عمدتاً در میناس‌ژرایس، سائوپائولو و اسپریتوسانتو هستند. برداشت بیشتر از ژوئن تا سپتامبر است.</td></tr>\n<tr><td>هاوایی — کونا</td><td>ارتفاع ۵۰۰ تا ۳۲۰۰ فوت (حدود ۱۵۰ تا ۹۷۵ متر)؛ حدود ۸۰۰ مزرعه‌ی میانگین کمتر از ۵ ایکر. برداشت دستی چندمرحله‌ای از اوت تا ژانویه. مخلوط‌ها اغلب فقط حداقل ۱۰٪ کونا دارند؛ برچسب «۱۰۰٪ کونا» باید برجسته باشد.</td></tr>\n</tbody></table></div>\n<h4>تولید کشورها (۲۰۲۳)</h4>\n<div class=\"table-wrap\"><table><thead><tr><th>کشور</th><th>تولید (میلیون تن)</th></tr></thead><tbody>\n<tr><td>برزیل</td><td>۳٫۴۱ (حدود ۳۱٪ جهان)</td></tr><tr><td>ویتنام</td><td>۱٫۹۶</td></tr><tr><td>اندونزی</td><td>۰٫۷۶</td></tr><tr><td>کلمبیا</td><td>۰٫۶۸</td></tr><tr><td>اتیوپی</td><td>۰٫۵۶</td></tr><tr><td>کل جهان</td><td>۱۱٫۰۶</td></tr>\n</tbody></table></div>\n","kind":"item","src":[["Wikipedia — Coffee production in Ethiopia","https://en.wikipedia.org/wiki/Coffee_production_in_Ethiopia"],["Wikipedia — Coffee production in Kenya","https://en.wikipedia.org/wiki/Coffee_production_in_Kenya"],["Wikipedia — Colombian coffee","https://en.wikipedia.org/wiki/Colombian_coffee"],["Wikipedia — Coffee production in Brazil","https://en.wikipedia.org/wiki/Coffee_production_in_Brazil"],["Wikipedia — Kona coffee","https://en.wikipedia.org/wiki/Kona_coffee"],["Wikipedia — Yirgacheffe","https://en.wikipedia.org/wiki/Yirgacheffe"],["Wikipedia — Coffee","https://en.wikipedia.org/wiki/Coffee"]]},{"id":183,"title":"تأثیر تغییرات اقلیمی بر کشت قهوه و راهکار‌ها","body":"<h4>تهدیدها</h4><ul><li>مطالعه‌ی Bunn و همکاران (CIAT، PLOS ONE ۲۰۱۵) کاهش ۵۰٪ زمین مناسب عربیکا تا ۲۰۵۰ را در مجموع پیش‌بینی می‌کند.</li><li>نزدیک به ۸۰٪ زمین‌های گرم و خشک (مانند برزیل و آمریکای مرکزی) تا ۲۰۵۰ برای عربیکا نامناسب می‌شود.</li><li>حتی مناطق خنک‌تر و پایدارتر (ارتفاعات آفریقای شرقی، کلمبیا، اندونزی) ممکن است یک‌سوم از تناسب خود را از دست بدهند.</li><li>عربیکا نسبت به افزایش دما، بارش غیرقابل‌پیش‌بینی و شیوع آفت و بیماری بسیار حساس است.</li><li>زنگ قهوه و سوسک میوه‌ی قهوه تهدید جدی‌اند (جزئیات در مقاله‌ی «چرخه‌ی زندگی آفات تخصصی قهوه»).</li></ul><h4>مناطق کمتر آسیب‌پذیر یا بالقوه</h4><ul><li>کلمبیا، اتیوپی، کنیا و اندونزی: ۶۰٪ مناطق با دمای فصلی ثابت تا ۲۰۵۰ بدون تغییر ماندند.</li><li>آفریقای شرقی، اکوادور و احتمالاً اندونزی به‌عنوان مناطق کشت آینده معرفی شده‌اند.</li></ul><h4>راهکارها</h4><ul><li>اصلاح نژاد ارقام مقاوم به تنش اقلیمی متناسب با منطقه؛ World Coffee Research آزمایش چندمکانی ارقام (IMLVT) را در ۱۹ کشور اجرا می‌کند.</li><li>مدل‌های کسب‌وکاری که ریسک را بین کشاورز، خریدار و برشته‌کار تقسیم می‌کنند.</li><li>ارقام مقاوم به زنگ مانند هیبرید F1 استارمایا.</li></ul>\n","kind":"item","src":[["Daily Coffee News — New study maps dramatic projected decreases in suitable coffee land (۲۰۱۵)","https://dailycoffeenews.com/2015/10/27/new-study-maps-dramatic-projected-decreases-in-suitable-coffee-land"],["CIAT/Alliance Bioversity — Climate change: Arabica coffee faces a roasting","https://alliancebioversityciat.org/stories/climate-change-arabica-coffee-faces-roasting"],["Wikipedia — Coffee leaf rust","https://en.wikipedia.org/wiki/Coffee_leaf_rust"]]},{"id":216,"title":"تأثیر «قارچ‌های مایکوریزا» بر طعم قهوه (ناگفته)","body":"<p>قارچ‌های میکوریزا آربوسکولار (AMF) با ریشه‌ی گیاه همزیستی دارند. مطالعه‌ای در مجله‌ی <em>Revista Caatinga</em> روی نهال قهوه نتیجه گرفت که «استفاده از میکوریزا یک زیست‌فناوری امیدبخش است که کشت قهوه را از نظر مصرف کود پایدار می‌کند».</p><ul><li>سه گونه‌ی قارچ در سطوح مختلف کود فسفات روی خاک غیراستریل آزمایش شد؛ تلقیح بر همه‌ی متغیرهای اندازه‌گیری‌شده اثر داشت اما پاسخ به مقدار فسفر بستگی داشت.</li><li>دُزهای فسفر بالاتر از نصف توصیه‌ی استاندارد، مزیت میکوریزا را کم کردند.</li><li>دو گونه از قارچ‌ها در خاک با فسفر کمتر بهتر از شاهد رشد قهوه را تقویت کردند.</li></ul><p>این مطالعه رشد گیاه را سنجیده است، نه طعم فنجان. ارتباط مستقیم میکوریزا با طعم گزارش نشده است.</p>","kind":"item","src":[["Arbuscular mycorrhizal fungi and phosphorus doses on coffee growth under a non-sterile soil (Revista Caatinga)","https://www.scielo.br/j/rcaat/a/QjxByczpPN6cks5TpNHRjQq/abstract/?lang=en"]]},{"id":327,"title":"قهوه و محیط زیست (پایداری و بازیافت)","body":"<div class=\"table-wrap\"><table><thead><tr><th>موضوع</th><th>توضیح</th></tr></thead><tbody>\n<tr><td>آب مجازی</td><td>حدود ۱۴۰ لیتر آب برای تولید دانه‌های لازم برای یک فنجان؛ ۲۶٬۴۰۰ لیتر برای هر کیلوگرم قهوه‌ی برشته در آفریقا، آمریکای جنوبی یا آسیا.</td></tr>\n<tr><td>کشت آفتابی</td><td>از دهه‌ی ۱۹۷۰ بسیاری از کشاورزان به کشت آفتابی روی آوردند که قطع درختان و مصرف بیشتر کود و سم را لازم دارد.</td></tr>\n<tr><td>کشت سایه‌دار</td><td>زیستگاه حیات‌وحش فراهم می‌کند اما بازدهی کمتری دارد.</td></tr>\n<tr><td>ارقام مقاوم</td><td>روبوستا به علف‌کش و آفت‌کش کمتری نیاز دارد؛ هیبرید F1 استارمایا مقاومت ژنتیکی گسترده به زنگ قهوه دارد.</td></tr>\n<tr><td>کنترل زیستی آفت</td><td>پارازیتوئیدها، پرندگان شکارچی و قارچ‌های حشره‌کش (Beauveria bassiana) جایگزین حشره‌کش‌های پرهزینه و آسیب‌زننده به محیط‌اند.</td></tr>\n<tr><td>کود و میکوریزا</td><td>میکوریزا می‌تواند در خاک کم‌فسفر رشد را تقویت کند و مصرف کود فسفاتی را کاهش دهد.</td></tr>\n</tbody></table></div>","kind":"item","src":[["Wikipedia — Coffee","https://en.wikipedia.org/wiki/Coffee"],["Wikipedia — Coffee berry borer","https://en.wikipedia.org/wiki/Coffee_berry_borer"],["Wikipedia — Coffee leaf rust","https://en.wikipedia.org/wiki/Coffee_leaf_rust"],["Wikipedia — Coffea canephora","https://en.wikipedia.org/wiki/Coffea_canephora"]]},{"id":595,"title":"چرخه‌ی زندگی آفات تخصصی قهوه","body":"<h4>سوسک میوه‌ی قهوه (Hypothenemus hampei)</h4><ul><li>مدت رشد از تخم تا حشره‌ی بالغ ۲۴ تا ۴۵ روز و بسته به آب‌وهوا متغیر است.</li><li>ماده دو دوره‌ی لاروی دارد که هر کدام ۱۰ تا ۲۶ روز طول می‌کشد (نر یک دوره).</li><li>ماده‌ها ۳۵ تا ۱۹۰ روز عمر می‌کنند و دو روز پس از نفوذ به میوه ۳۵ تا ۵۰ تخم می‌گذارند.</li><li>یک گیاه می‌تواند ۳ تا ۵ نسل سوسک را میزبانی کند.</li><li>بومی آفریقای مرکزی است و در بیشتر کشورهای تولیدکننده‌ی قهوه حضور دارد؛ مثلاً گزارش اول آمریکا از برزیل ۱۹۲۶، کلمبیا اواخر دهه‌ی ۱۹۸۰، پورتوریکو ۲۰۰۷ و هاوایی ۲۰۱۰ است.</li><li>این آفت بر معیشت بیش از ۲۰ میلیون خانوار وابسته به برداشت قهوه اثر دارد.</li><li>کنترل زیستی (زنبورهای پارازیتوئید، پرندگان شکارچی، قارچ‌های حشره‌کش مثل Beauveria bassiana) مؤثر گزارش شده؛ حشره‌کش‌ها هزینه‌ی بالا و آسیب زیست‌محیطی دارند.</li></ul>\n<h4>زنگ قهوه (Hemileia vastatrix)</h4><ul><li>۱۸۶۱ اولین گزارش در کنار دریاچه‌ی ویکتوریا، ۱۸۶۷ در سیلان و ۱۸۶۹ توصیف رسمی توسط Berkeley و Broome. تا ۱۸۹۰ صنعت قهوه‌ی سریلانکا تقریباً نابود شد.</li><li>اپیدمی ۲۰۱۲ در آمریکای مرکزی تولید منطقه را ۱۶٪ کاهش داد؛ USAID خسارت ۲۰۱۲ تا ۲۰۱۴ را حدود یک میلیارد دلار و بیش از ۲ میلیون نفر متأثر برآورد کرد.</li><li>کنترل: ارقام مقاوم، قارچ‌کش‌های مسی مثل مخلوط بوردو، هرس برای تهویه و تغذیه‌ی کافی (نیتروژن و پتاسیم). هیبرید F1 «استارمایا» مقاومت ژنتیکی گسترده و کیفیت فنجان خوب دارد.</li></ul>","kind":"item","src":[["Wikipedia — Coffee berry borer","https://en.wikipedia.org/wiki/Coffee_berry_borer"],["Wikipedia — Coffee leaf rust","https://en.wikipedia.org/wiki/Coffee_leaf_rust"]]}]},{"id":"C2","icon":"roast","title":"برشته‌کاری و آسیاب","items":[{"id":3,"title":"برشته‌کاری (Roasting)","body":"<h4>پروفایل برشته‌کاری طعم را تعیین می‌کند. مراحل:</h4><ul><li>دانه سبز – بوی علفی.</li><li>مرحله زرد (۱۵۰ تا ۱۸۰ درجه سانتی‌گراد) – تبخیر رطوبت، دانه متورم می‌شود.</li><li>ترک اول (حدود ۱۹۶ درجه) – ترک‌خوردن دیواره‌های سلولی با فشار بخار و CO₂؛ شروع برشته‌کاری روشن.</li><li>توسعه – ۱ تا ۴ دقیقه پس از ترک اول، کاراملی‌سازی، واکنش مایارد.</li><li>ترک دوم (حدود ۲۲۴ درجه) – برشته‌کاری تیره.</li><li>تاریک – روغن روی سطح، طعم زغالی.</li></ul><p>درجه‌ی برشته‌کاری با مقیاس Agtron سنجیده می‌شود (جدول Coffee Review در مقاله‌ی «مقیاس‌های اندازه‌گیری» همین دسته آمده است).</p><p>شیمی: تخریب CGA، سنتز ملامویدین‌ها، تشکیل فورانول‌ها، پیرازین‌ها (آجیلی)، تیول‌ها (گوگردی)، آلدئید‌ها (میوه‌ای). پروفایل بهینه – منحنی با نرخ کاهشی (ROR) برای توسعه یکنواخت.</p>","kind":"item","src":[["Coffee Tower — First & second crack","https://coffee.towerofrecords.com/coffee/first-second-crack"],["Coffee Review — Roast definitions","https://www.coffeereview.com/roast-definitions/"]]},{"id":4,"title":"آسیاب (Grinding)","body":"<h4>اندازه‌ی ذرات برای روش‌ها</h4>\n<div class=\"table-wrap\"><table><thead><tr><th>روش</th><th>اندازه (میکرون)</th><th>توضیح</th></tr></thead><tbody>\n<tr><td>اسپرسو</td><td>۲۰۰–۴۰۰</td><td>ریزترین آسیاب و یکنواخت‌ترین توزیع لازم است؛ تغییر کوچک در ذرات زیر فشار ۹ بار باعث کانال‌شدن آب و استخراج ناهمگون می‌شود.</td></tr>\n<tr><td>پوراوور</td><td>۵۰۰–۸۰۰</td><td>آسیاب متوسط؛ جریان با گرانش است، پس تحمل کمی بیشتری نسبت به ناهمگونی ذرات دارد.</td></tr>\n<tr><td>کلد برو</td><td>۷۰۰–۹۰۰</td><td>متوسط-درشت، ۱۲ تا ۲۴ ساعت خیسانده می‌شود؛ یکنواختی ذرات بر راندمان استخراج و تعادل طعم اثر دارد.</td></tr>\n<tr><td>فرنچ پرس</td><td>۸۰۰–۱۰۰۰</td><td>درشت‌ترین آسیاب؛ ذرات درشت یکنواخت قهوه‌ی تمیز و پربدنه بدون رسوب زیاد می‌دهند.</td></tr>\n</tbody></table></div>\n<p>ذرات یکنواخت، مستقل از روش دم‌آوری، قابل‌پیش‌بینی‌تر استخراج می‌شوند. راهنمای اندازه‌ی آسیاب در بخش «ابزار» بازه‌های تقریبی بیشتری دارد.</p>\n<h4>آسیاب تیغه‌ای و سنگی (Burr)</h4><ul><li>آسیاب سنگی ذرات با اندازه‌ی یکنواخت تولید می‌کند که با فاصله‌ی دو سطح ساینده تعیین می‌شود؛ آسیاب تیغه‌ای ذرات ناهمگون می‌دهد.</li><li>آسیاب سنگی گرمای اصطکاکی بسیار کمتری تولید می‌کند. روغن‌ها و عطرها در صورت داغ‌شدن دانه هنگام آسیاب به‌راحتی تبخیر می‌شوند.</li><li>در مدل‌های بی‌پله (stepless) با مکانیزم‌هایی مثل چرخ‌حلزون تعداد تنظیم‌ها تقریباً بی‌نهایت است.</li><li>قهوه‌ی آسیاب‌شده تقریباً ۱۵ دقیقه ماندگاری بهینه دارد؛ پس بهتر است کوتاه پیش از دم‌آوری آسیاب شود.</li></ul>","kind":"item","src":[["Mahlkönig — Microns and grind consistency","https://www.mahlkoenig.com/blogs/news/microns-grind-consistency"],["Wikipedia — Burr mill","https://en.wikipedia.org/wiki/Burr_mill"],["Wikipedia — Coffee roasting","https://en.wikipedia.org/wiki/Coffee_roasting"]]},{"id":211,"title":"تأثیر «تاریخ برشته‌کاری» بر کافئین – افسانه یا واقعیت؟","body":"<p>کافئین ترکیبی پایدار است: تا ۲۰۰ °C پایدار می‌ماند و حدود ۲۸۵ °C کاملاً تجزیه می‌شود. دمای برشته‌کاری در این محدوده‌ی پایداری قرار دارد.</p><ul><li>دانه‌ی سبز ۱٫۰ تا ۲٫۵٪ وزنی کافئین دارد و مقدارش در گیاهان ارتفاع بالاتر بیشتر گزارش شده است.</li><li>برشته‌کاری ۱۵ تا ۱۸٪ جرم دانه را (عمدتاً آب) کم و حجمش را تقریباً دو برابر می‌کند؛ بنابراین بسته به اندازه‌گیری با وزن یا حجم، مقدار کافئین «در هر پیمانه» متفاوت به نظر می‌رسد.</li><li>آنچه با گذر زمان از بین می‌رود تازگی و عطر است: ماندگاری بهینه‌ی قهوه‌ی برشته‌ی دانه‌ای معمولاً حدود دو هفته و قهوه‌ی آسیاب‌شده حدود ۱۵ دقیقه ذکر شده است.</li><li>روبوستا بیش از عربیکا کافئین دارد (حدود ۲٫۷٪ در برابر ۱٫۵٪).</li></ul>","kind":"item","src":[["Wikipedia — Coffee roasting","https://en.wikipedia.org/wiki/Coffee_roasting"],["Wikipedia — Coffee bean","https://en.wikipedia.org/wiki/Coffee_bean"],["Wikipedia — Coffea canephora","https://en.wikipedia.org/wiki/Coffea_canephora"],["Quantification of Caffeine and Chlorogenic Acid in Green and Roasted Coffee Samples… Effect of Degree of Roasting (PMC8705492)","https://pmc.ncbi.nlm.nih.gov/articles/PMC8705492/"]]},{"id":579,"title":"آنالیز دقیق منحنی برشته‌کاری (Roasting Curve Analysis)","body":"<p>منحنی برشته‌کاری دمای دانه را بر حسب زمان ثبت می‌کند و ابزار اصلی تکرارپذیری برشته‌کاری است.</p>\n<h4>مراحل و نقاط دمایی</h4>\n<div class=\"table-wrap\"><table><thead><tr><th>مرحله</th><th>شرح</th></tr></thead><tbody>\n<tr><td>خشک‌شدن</td><td>فرایندی گرماگیر؛ تا حدود ۱۶۵ °C. این مرحله با زرد شدن دانه‌ها پایان می‌یابد.</td></tr>\n<tr><td>گرمازا شدن</td><td>در حدود ۱۷۵ °C واکنش‌ها گرمازا می‌شوند.</td></tr>\n<tr><td>ترک اول</td><td>حدود ۱۹۶ °C؛ آزاد شدن بخار و CO₂ از مرکز دانه. نقطه‌ی شروع مرحله‌ی توسعه (Development).</td></tr>\n<tr><td>ترک دوم</td><td>حدود ۲۲۴ °C.</td></tr>\n<tr><td>سطوح برشته‌کاری</td><td>از ۱۹۶ °C (Cinnamon) تا ۲۴۵ °C (Italian).</td></tr>\n</tbody></table></div>\n<h4>مرحله‌ی توسعه و سرعت افزایش دما (RoR)</h4><ul><li>مرحله‌ی توسعه زمان پس از ترک اول است؛ برشته‌کارانی که سطح روشن را ترجیح می‌دهند اغلب آن را کمتر از ۲۰٪ کل زمان برشته‌کاری نگه می‌دارند.</li><li>فاصله‌ی یک «کم‌توسعه‌یافته» تا برشته‌ی روشن بسیار باریک است؛ نیم درجه یا پنج ثانیه توسعه‌ی اضافه می‌تواند تفاوت بزرگی بسازد.</li><li>RoR سرعت افزایش دمای دانه است. پس از نقطه‌ی چرخش (Turning Point) مثبت می‌شود، به بیشینه می‌رسد، و در ترک اول و تا پایان کاهش می‌یابد.</li><li>به نقل از اسکات رائو: «برشته‌ی خوب با RoR مداوماً کاهنده به دست می‌آید.»</li><li>افت شدید RoR (Crash) به‌ویژه حوالی ترک اول فرایند را به «بیک‌شدن» می‌برد و طعم تخت و بی‌روح و شبیه مقوا می‌دهد.</li></ul>","kind":"item","src":[["Wikipedia — Coffee roasting","https://en.wikipedia.org/wiki/Coffee_roasting"],["Roest — Rate of Rise","https://www.roestcoffee.com/blog/rate-of-rise"],["Coffeeness — Coffee roast profiles","https://www.coffeeness.de/en/coffee-roast-profiles/"]]}]},{"id":"C3","icon":"chemistry","title":"شیمی، آب و علم استخراج قهوه","items":[{"id":1,"title":"ترکیب شیمیایی دانه (بر اساس وزن خشک)","body":"<p>ترکیب دانه‌ی سبز و تغییرات آن در برشته‌کاری:</p>\n<div class=\"table-wrap\"><table><thead><tr><th>ترکیب</th><th>مقدار گزارش‌شده</th><th>تغییر در برشته‌کاری / نقش</th></tr></thead><tbody>\n<tr><td>کافئین</td><td>عربیکا ۰٫۸–۱٫۴٪؛ روبوستا ۱٫۷–۴٫۰٪؛ در مجموع ۱٫۰–۲٫۵٪ وزنی (در ارتفاع بالاتر بیشتر)</td><td>آنتاگونیست گیرنده‌ی آدنوزین؛ تا ۲۰۰ °C پایدار است</td></tr>\n<tr><td>تری‌گونلین</td><td>۰٫۶–۱٫۰٪ در دانه‌ی سبز</td><td>در برشته‌کاری ۲۳۰ °C حدود ۸۵٪ آن به نیکوتینیک اسید تجزیه می‌شود</td></tr>\n<tr><td>اسیدهای کلروژنیک</td><td>عربیکا ۶۵ mg/g؛ روبوستا ۱۴۰ mg/g</td><td>بیش از ۷۰٪ در برشته‌کاری تخریب می‌شود؛ کمتر از ۳۰ mg/g در دانه‌ی برشته می‌ماند</td></tr>\n<tr><td>پروتئین</td><td>۸ تا ۱۲٪ دانه‌ی سبز خشک</td><td>اسیدهای آمینه آزاد به محصولات مایار تبدیل می‌شوند</td></tr>\n<tr><td>کربوهیدرات</td><td>حدود ۵۰٪ وزن خشک</td><td>—</td></tr>\n<tr><td>چربی</td><td>۱۱٫۷–۱۴ g/100g؛ عربیکا ۱۳٫۵–۱۷٫۴ و روبوستا ۹٫۸–۱۰٫۷</td><td>حدود ۲۰٪ این بخش دی‌ترپن‌ها (کافستول و کاهوئول) است</td></tr>\n</tbody></table></div>\n<ul><li>دی‌کتوپیپرازین‌ها که در برشته‌کاری از تجزیه‌ی اسیدهای آمینه ساخته می‌شوند، از ترکیبات اصلی تلخی‌اند؛ حدود ۲۰ تا ۳۰ میلی‌گرم از آن‌ها در اسپرسو هست.</li><li>در برشته‌کاری بخش عمده‌ی ترکیبات فرار ناخوشایند خنثی می‌شود.</li></ul>\n","kind":"item","src":[["Wikipedia — Coffee bean","https://en.wikipedia.org/wiki/Coffee_bean"],["Wikipedia — Caffeine","https://en.wikipedia.org/wiki/Caffeine"],["Wikipedia — Coffee roasting","https://en.wikipedia.org/wiki/Coffee_roasting"]]},{"id":14,"title":"پژوهش‌های علمی (داده‌های به‌روز) (Scientific Research)","body":"<p>منابع پایه‌ی این دسته (همه‌ی آن‌ها در مقاله‌های همین بخش به‌کار رفته‌اند):</p><ul><li>Hendon CA, Colonna-Dashwood L, Colonna-Dashwood M. The role of dissolved cations in coffee extraction. J Agric Food Chem 2014.</li><li>SCAA/SCA — استاندارد کیفیت آب (به نقل از 43factory).</li><li>Coffee bean، Caffeine، Decaffeination و Coffee preparation.</li></ul>","kind":"item","src":[["Hendon CA, Colonna-Dashwood L, Colonna-Dashwood M. The role of dissolved cations in coffee extraction. J Agric Food Chem 2014","https://researchportal.bath.ac.uk/en/publications/the-role-of-dissolved-cations-in-coffee-extraction/"],["43factory — Dissecting SCAA water quality standard","https://43factory.coffee/en/news/dissecting-scaas-water-quality-standard/"],["Wikipedia — Decaffeination","https://en.wikipedia.org/wiki/Decaffeination"]]},{"id":135,"title":"روش‌های جایگزین برای فیلتر کردن آب و تصفیه","body":"<p>پایه‌ی علمی: آب سخت دو نوع سختی دارد.</p><div class=\"table-wrap\"><table><thead><tr><th>نوع</th><th>علت</th><th>اثر جوشاندن</th></tr></thead><tbody><tr><td>سختی موقت</td><td>بی‌کربنات کلسیم و منیزیم محلول</td><td>جوشاندن بی‌کربنات را به کربنات تبدیل می‌کند و کربنات کلسیم رسوب می‌کند، پس سختی را کم می‌کند</td></tr><tr><td>سختی دائم</td><td>ترکیبات سولفات و کلرید</td><td>با جوشاندن به‌سختی حذف می‌شود</td></tr></tbody></table></div><ul><li>رسوب مواد معدنی در سیستم‌های گرمایشی جریان گرما به آب را مختل می‌کند، بازده را کم می‌کند و قطعات فلزی دیگ را بیش‌از‌حد داغ می‌کند؛ برای دستگاه اسپرسو مهم است.</li><li>طبقه‌بندی USGS (به mg/L معادل CaCO₃): نرم ۰–۶۰؛ نیمه‌سخت ۶۱–۱۲۰؛ سخت ۱۲۱–۱۸۰؛ بسیار سخت ۱۸۱ و بالاتر.</li><li>هدف قهوه طبق SCAA: سختی کلسیم و منیزیم ۵۱ تا ۶۸ mg/L و کلر صفر.</li></ul>","kind":"item","src":[["Wikipedia — Hard water","https://en.wikipedia.org/wiki/Hard_water"],["43factory — Dissecting SCAA water quality standard","https://43factory.coffee/en/news/dissecting-scaas-water-quality-standard/"]]},{"id":148,"title":"دانش بنیادی و علمی","body":"<h4>کافئین</h4><ul><li>فرمول C₈H₁₀N₄O₂؛ جرم مولی ۱۹۴٫۱۹۴ g/mol؛ جامد بلوری سفید و تلخ.</li><li>نقطه‌ی ذوب ۲۳۵ تا ۲۳۸ °C.</li><li>حلالیت در آب: حدود ۲ g/100 mL در دمای اتاق و ۶۶ g/100 mL در آب جوش.</li><li>مکانیسم: آنتاگونیست گیرنده‌های آدنوزین؛ با اشغال جایگاه اتصال آدنوزین از فعال شدن گیرنده جلوگیری می‌کند.</li><li>یک فنجان ۶ اونسی (حدود ۱۸۰ mL) قهوه معمولاً ۵۰ تا ۱۷۵ mg کافئین دارد، بسته به دانه، برشته‌کاری و روش دم‌آوری.</li></ul>\n<h4>اسیدهای کلروژنیک، تری‌گونلین و دی‌ترپن‌ها</h4><ul><li>اسید کلروژنیک: عربیکا ۶۵ mg/g و روبوستا ۱۴۰ mg/g در دانه‌ی سبز؛ بیش از ۷۰٪ در برشته‌کاری تخریب می‌شود.</li><li>تری‌گونلین: ۰٫۶ تا ۱٫۰٪؛ حدود ۸۵٪ آن در ۲۳۰ °C به نیکوتینیک اسید تجزیه می‌شود.</li><li>دی‌ترپن‌ها (کافستول و کاهوئول) حدود ۲۰٪ بخش چربی را می‌سازند و در آزمایش‌های in vitro از بافت کبد در برابر اکسیداسیون شیمیایی محافظت کرده‌اند.</li></ul>\n<h4>مایار و تلخی</h4><p>در برشته‌کاری اسیدهای آمینه به محصولات مایار تجزیه می‌شوند؛ دی‌کتوپیپرازین‌ها از ترکیبات اصلی تلخی‌اند (حدود ۲۰ تا ۳۰ mg در اسپرسو).</p>\n<h4>دما و استخراج</h4><ul><li>ایده‌آل بازده استخراج: ۱۸ تا ۲۲٪.</li><li>آب داغ نزدیک جوش (حدود ۹۶ °C) ترکیبات معطر را آزاد می‌کند و در نقطه‌ی جوش ترکیبات تلخ ظاهر می‌شود. دمای اسپرسو ۹۱ تا ۹۵ °C است.</li></ul>\n<p>دارسی در مقاله‌ی «قهوه و ریاضیات» هم مرور می‌شود.</p>","kind":"item","src":[["Wikipedia — Caffeine","https://en.wikipedia.org/wiki/Caffeine"],["Wikipedia — Coffee bean","https://en.wikipedia.org/wiki/Coffee_bean"],["Wikipedia — Coffee preparation","https://en.wikipedia.org/wiki/Coffee_preparation"]]},{"id":186,"title":"ترکیبات شیمیایی فرار (Volatile Compounds) – فهرست کامل‌تر از قبل","body":"<p>مطالعه‌ی «شناسایی ترکیبات کلیدی فعال در عطر قهوه‌های تجاری با GC-O/AEDA و OAV» (Foods، سپتامبر ۲۰۲۵) روی چند قهوه‌ی تجاری انجام شد.</p><ul><li>در مجموع ۸۵ ترکیب عطری شناسایی شد.</li><li>فورفورال، گایاکول و فورانئول بیشترین فاکتور رقت طعم (FD) را داشتند (تا ۲۱۸۷).</li><li>۴-وینیل-۲-متوکسی‌فنول (OAV برابر ۷۶۱ در یکی از نمونه‌ها) و فورانئول (OAV برابر ۲۵۰ در نمونه‌ای دیگر) بسیار اثرگذار بودند.</li><li>فوران‌ها، کتون‌ها و پیرازین‌ها اصلی‌ترین مشارکت‌کنندگان در عطر برشته، آجیلی و کاراملی بودند.</li><li>توصیف عطر نمونه‌ها: کلمبیا شکلاتی و آجیلی؛ Bench Maji میوه‌ای؛ ییرگاچف برشته؛ Baoshan چوبی و کاراملی.</li><li>نمونه‌ها در اسیدهای آلی و اسید کلروژنیک هم تفاوت داشتند؛ نمونه‌ی کلمبیا کینیک اسید بیشتری داشت که نویسندگان آن را به تخریب ناشی از برشته‌کاری نسبت می‌دهند.</li></ul><p>روش‌ها: استخراج SAFE، GC-MS/O با AEDA، HPLC برای ترکیبات غیرفرار، تحلیل OAV و آزمایش‌های بازترکیب و حذف برای تأیید نتایج.</p>","kind":"item","src":[["Identification of Key Aroma-Active Compounds in Commercial Coffee Using GC-O/AEDA and OAV Analysis (Foods, 2025) — خلاصه در DOAJ","https://doaj.org/article/07efd8cfe32c4ff4ab264180f04f41b7"],["PMC12469716","https://pmc.ncbi.nlm.nih.gov/articles/PMC12469716"]]},{"id":187,"title":"اندازه‌گیری دقیق سختی آب و تأثیر آن بر عصاره‌گیری (با اعداد)","body":"<h4>استاندارد آب SCAA</h4>\n<div class=\"table-wrap\"><table><thead><tr><th>پارامتر</th><th>هدف</th><th>بازه / توضیح</th></tr></thead><tbody>\n<tr><td>TDS</td><td>۱۵۰ mg/L</td><td>۷۵ تا ۲۵۰ mg/L؛ از خیلی نرم یا خیلی سخت‌شدن آب جلوگیری می‌کند</td></tr>\n<tr><td>سختی کلسیم و منیزیم</td><td>۳ تا ۴ grain/gallon</td><td>۵۱ تا ۶۸ mg/L؛ استخراج ترکیبات محلول را ممکن می‌کند و از تجهیزات محافظت می‌کند</td></tr>\n<tr><td>قلیائیت کل</td><td>حدود ۴۰ mg/L</td><td>از تلخی یا تختی ناخواسته جلوگیری می‌کند</td></tr>\n<tr><td>pH</td><td>۶٫۵ تا ۷٫۵</td><td>همراه با قلیائیت تعادل طعم را می‌سازد</td></tr>\n<tr><td>سدیم</td><td>حدود ۱۰ mg/L</td><td>کمتر از ۳۰ mg/L؛ ادراک شیرینی و اسیدیته را تغییر ندهد</td></tr>\n<tr><td>کلر</td><td>صفر</td><td>بوی استخر می‌دهد و عطر طبیعی را کم می‌کند</td></tr>\n<tr><td>بو و رنگ</td><td>شفاف</td><td>بدون کلر، سولفات، فنل یا آلودگی میکروبی</td></tr>\n</tbody></table></div>\n","kind":"item","src":[["43factory — Dissecting SCAA water quality standard","https://43factory.coffee/en/news/dissecting-scaas-water-quality-standard/"]]},{"id":188,"title":"تأثیر فشار هوا (Altitude) بر عصاره‌گیری در اسپرسو","body":"<p>ارتفاع از سطح دریا نقطه‌ی جوش آب را پایین می‌آورد؛ فشار ۹ بار اسپرسو را پمپ می‌سازد و به ارتفاع ربطی ندارد.</p>\n<div class=\"table-wrap\"><table><thead><tr><th>ارتفاع</th><th>نقطه‌ی جوش آب</th></tr></thead><tbody><tr><td>سطح دریا</td><td>۱۰۰ °C (دقیق: ۹۹٫۹۷)</td></tr><tr><td>۱۵۰۰ متر</td><td>۹۵٫۱ °C</td></tr><tr><td>۱۹۰۵ متر</td><td>۹۳٫۴ °C</td></tr><tr><td>۳۰۰۰ متر</td><td>۹۰٫۰ °C</td></tr></tbody></table></div><ul><li>دمای اسپرسو ۹۱ تا ۹۵ °C است؛ در ارتفاع‌های بالاتر از ~۳۰۰۰ متر آب حتی نمی‌تواند به این بازه برسد.</li><li>در ارتفاع بالا، دمای آب پوراوور را با دماسنج کنترل کنید.</li></ul>","kind":"item","src":[["Wikipedia — Boiling point","https://en.wikipedia.org/wiki/Boiling_point"],["Wikipedia — Coffee preparation","https://en.wikipedia.org/wiki/Coffee_preparation"]]},{"id":192,"title":"تأثیر دما‌های مختلف بر اسیدیته و تلخی (منحنی دقیق)","body":"<ul><li>آب «درست زیر نقطه‌ی جوش» (حدود ۹۶ °C) ترکیبات معطر را آزاد می‌کند؛ در نقطه‌ی جوش ترکیبات تلخ ظاهر می‌شوند.</li><li>دمای اسپرسو ۹۱ تا ۹۵ °C است.</li><li>روش‌هایی که قهوه را مدت بیشتری در آب داغ نگه می‌دارند آسیاب درشت‌تر می‌خواهند؛ فرنچ پرس معمولاً ۴ تا ۷ دقیقه خیسانده می‌شود.</li><li>هدف: بازده استخراج ۱۸ تا ۲۲٪؛ TDS آمریکایی ۱٫۱۵ تا ۱٫۳۵٪ و اروپایی ۱٫۲۰ تا ۱٫۴۵٪.</li><li>نسبت ترجیحی آب به قهوه معمولاً در محدوده‌ی ۱۵ تا ۱۸ به ۱ بر پایه‌ی جرم است.</li><li>آسیاب بیش‌ازحد ریز طعم «بیش‌استخراج‌شده»، تلخ و تند می‌دهد؛ دم‌آوری‌های بزرگ‌تر معمولاً قوی‌تر و تلخ‌ترند، چون ترکیبات تلخ دیرتر وارد نوشیدنی می‌شوند.</li><li>کلد برو (۸ تا ۲۴ ساعت خیساندن) اسیدیته‌ی بسیار پایینی دارد؛ ریسترتو از رست روشن می‌تواند بسیار اسیدی شود.</li><li>آب خروجی از دستگاه اسپرسو حدود ۸۸ °C و دمای نوشیدنی در فنجان حدود ۶۷ °C گزارش شده است؛ گرما بعضی طعم‌ها را برجسته و بعضی را کم‌رنگ می‌کند.</li></ul>","kind":"item","src":[["Wikipedia — Coffee preparation","https://en.wikipedia.org/wiki/Coffee_preparation"],["Wikipedia — Espresso","https://en.wikipedia.org/wiki/Espresso"],["Wikipedia — Taste","https://en.wikipedia.org/wiki/Taste"]]},{"id":209,"title":"تأثیر «مواد معدنی مختلف» بر طعم (با اعداد دقیق)","body":"<p>پژوهش Hendon و همکاران (J Agric Food Chem، ۲۰۱۴) نشان می‌دهد انحلال و استخراج مولکول‌های قهوه به یون‌های Na⁺ و Mg²⁺ و Ca²⁺ در آب بستگی دارد.</p><ul><li>این یون‌ها به بخش‌های هسته‌دوست ترکیبات قهوه متصل می‌شوند و نرخ و ترکیب استخراج را عوض می‌کنند.</li><li>نویسندگان با محاسبات DFT انرژی اتصال پنج اسید رایج قهوه، کافئین و اوژنول را کمّی کردند.</li><li>طبق استاندارد SCAA، سدیم حدود ۱۰ mg/L (کمتر از ۳۰) و قلیائیت حدود ۴۰ mg/L توصیه می‌شود.</li></ul>","kind":"item","src":[["Hendon CA, Colonna-Dashwood L, Colonna-Dashwood M. The role of dissolved cations in coffee extraction. J Agric Food Chem 2014","https://researchportal.bath.ac.uk/en/publications/the-role-of-dissolved-cations-in-coffee-extraction/"],["43factory — Dissecting SCAA water quality standard","https://43factory.coffee/en/news/dissecting-scaas-water-quality-standard/"]]},{"id":215,"title":"کافئین‌زدایی (Decaffeination) – روش‌هایی که کمتر شناخته شده‌اند","body":"<ul><li><strong>آب سوئیسی:</strong> روش بدون حلال؛ در سوئیس ۱۹۳۳ ابداع و ۱۹۸۰ تجاری شد. با عصاره‌ی قهوه‌ی سبز و اختلاف فشار اسمزی کافئین را می‌گیرد و رسیدن به هدف ۸ تا ۱۰ ساعت طول می‌کشد.</li><li><strong>حلال آلی (مستقیم و غیرمستقیم):</strong> با دی‌کلرومتان یا اتیل استات، ۸ تا ۱۲ بار تکرار تا کافئین به حد استاندارد برسد.</li><li><strong>CO₂ فوق‌بحرانی:</strong> ابداع Kurt Zosel؛ CO₂ با فشار حدود ۳۰۰ atm و ۶۵ °C کافئین را انتخاب‌وار حل می‌کند.</li><li><strong>تری‌گلیسرید:</strong> Torunn Atteraas Garin روشی با روغن حاصل از تفاله‌ی قهوه ابداع کرد.</li><li><strong>تاریخ:</strong> Ludwig Roselius اولین فرایند تجاری را ۱۹۰۶ ثبت کرد، ابتدا با بنزن؛ نگرانی سلامت به حلال‌های ایمن‌تر منجر شد.</li></ul>\n<h4>استانداردهای قانونی</h4><div class=\"table-wrap\"><table><thead><tr><th>منطقه</th><th>الزام</th></tr></thead><tbody><tr><td>آمریکا (FDA)</td><td>حذف دست‌کم ۹۷٪ کافئین</td></tr><tr><td>اتحادیه‌ی اروپا</td><td>۹۹٫۹٪ عاری از کافئین (از نظر جرمی)</td></tr><tr><td>کانادا</td><td>کمتر از ۰٫۱٪ در قهوه‌ی بدون کافئین</td></tr></tbody></table></div><p>«بدون کافئین» به معنای صفر کافئین نیست.</p>","kind":"item","src":[["Wikipedia — Decaffeination","https://en.wikipedia.org/wiki/Decaffeination"]]},{"id":228,"title":"مرزهای پژوهش قهوه","body":"<h4>قهوه‌ی سلولی (VTT فنلاند، ۲۰۲۱)</h4><ul><li>مرکز پژوهش‌های فنی فنلاند (VTT) به رهبری Heiko Rischer در سپتامبر ۲۰۲۱ اعلام کرد کشت سلولی قهوه را در بیوراکتور پر از محیط مغذی آغاز کرده و زی‌توده‌ی حاصل را برشته کرده است.</li><li>پنل حسی آموزش‌دیده و بررسی تحلیلی گزارش کردند طعم و بوی دم‌کرده «شبیه قهوه‌ی معمولی» است.</li><li>Rischer برآورد کرد تا ۴ سال تا افزایش تولید و تأیید قانونی فاصله دارند؛ فرایند تأیید در هر کشور فرق دارد.</li><li>انگیزه: برای تأمین تقاضای رو‌به‌رشد قهوه زمین بیشتری لازم خواهد بود که به جنگل‌زدایی به‌ویژه در جنگل‌های بارانی می‌انجامد.</li></ul>\n<h4>Coffea stenophylla</h4><ul><li>بومی گینه، ساحل عاج، لیبریا و سیرالئون؛ در سده‌ی هجدهم توسط Adam Afzelius کشف شد.</li><li>پس از پژوهش میدانی ۲۰۱۸، نمونه‌های زنده‌ی وحشی در ۲۰۱۹ و ۲۰۲۰ دوباره پیدا شدند.</li><li>گونه‌ای مقاوم به گرماست که در ارتفاع‌های پایین حدود ۱۵۰ متر هم رشد می‌کند (در برابر ۸۰۰ متر و بیشتر برای کشت رایج).</li><li>طعم آن «پیچیده و طبیعتاً شیرین با اسیدیته‌ی متوسط‌به‌بالا، میوه‌ای و دهان‌پر» توصیف شده است؛ گزارش ۱۸۹۸ از باغ گیاه‌شناسی سلطنتی ترینیداد آن را «عالی و برابر بهترین عربیکا» دانسته است.</li><li>پژوهشگران کشت آن را برای افزایش تاب‌آوری در برابر تغییر اقلیم و بیماری و گسترش تنوع ژنتیکی توصیه می‌کنند.</li></ul>","kind":"item","src":[["Bean Scene — Finland research centre brews its first cup of lab-grown coffee (۲۰۲۱)","https://www.beanscenemag.com.au/finland-research-centre-brews-its-first-cup-of-lab-grown-coffee"],["Wikipedia — Coffea stenophylla","https://en.wikipedia.org/wiki/Coffea_stenophylla"]]},{"id":349,"title":"قهوه و ریاضیات (Coffee & Mathematics)","body":"<h4>🧮 ۱-۱. مدل‌سازی عصاره‌گیری (Extraction Modeling)</h4><p>عصاره‌گیری قهوه، فرآیندی است که در آن آب، ترکیبات محلول دانه را حل کرده و به فنجان منتقل می‌کند. این فرآیند از معادله‌ی نفوذپذیری دارسی (Darcy’s Law) پیروی می‌کند:</p><p class=\"formula\" dir=\"ltr\">Q = (k · A · ΔP) / (μ · L)</p><h4>که در آن:</h4><ul><li>Q = دبی حجمی جریان (میلی‌لیتر بر ثانیه)</li><li>k = نفوذپذیری بستر قهوه (وابسته به اندازه ذرات و تراکم)</li><li>A = سطح مقطع سبد پورتافیلتر (سانتی‌متر مربع)</li><li>ΔP = افت فشار (معمولاً ۹ بار در اسپرسو)</li><li>μ = ویسکوزیته آب (وابسته به دما – با افزایش دما، کاهش می‌یابد)</li><li>L = ضخامت قرص قهوه (میلی‌متر – وابسته به دوز و تمپر)</li></ul><h4>کاربرد عملی:</h4><ul><li>اگر زمان عصاره‌گیری خیلی کوتاه است (کمتر از ۲۰ ثانیه) → k بزرگ است → آسیاب را ریزتر کنید.</li><li>اگر زمان عصاره‌گیری خیلی طولانی است (بیشتر از ۳۵ ثانیه) → k کوچک است → آسیاب را درشت‌تر کنید.</li></ul><h4 class=\"sub\">📊 مدل‌سازی سینتیک عصاره‌گیری (Extraction Kinetics)</h4><p>عصاره‌گیری یک فرآیند وابسته به زمان است که را می‌توان با مدل‌های ساده‌ی سینتیک (مثلاً مرتبه‌ی اول) و نظریه‌ی نفوذ فیلم توصیف کرد. یک شکل ساده و تقریبی:</p><p class=\"formula\" dir=\"ltr\">dC/dt = ks · (Cs − C)</p><h4>که در آن:</h4><ul><li>C = غلظت ترکیبات محلول در آب (گرم بر لیتر)</li><li>t = زمان (ثانیه)</li><li>ks = ثابت سرعت استخراج (وابسته به دما و اندازه ذرات)</li><li>Cs = غلظت اشباع در سطح دانه (حداکثر قابلیت حل شدن)</li></ul><h4>کاربرد عملی:</h4><ul><li>در دما‌های بالاتر، ks افزایش می‌یابد → عصاره‌گیری سریع‌تر، اما خطر استخراج ترکیبات تلخ بیشتر است.</li><li>در ذرات ریزتر، سطح تماس بیشتر → ks بالاتر → عصاره‌گیری کامل‌تر.</li></ul><h4 class=\"sub\">🔢 نسبت قهوه به آب (Brew Ratio) و درصد عصاره‌گیری (Extraction Yield)</h4><h4>نسبت قهوه به آب به‌صورت زیر محاسبه می‌شود:</h4><p class=\"formula\" dir=\"rtl\">نسبت دم‌آوری = وزن قهوه (گرم) ÷ وزن آب (گرم)</p><h4>درصد عصاره‌گیری (EY – Extraction Yield):</h4><p class=\"formula\" dir=\"rtl\">بازده استخراج (EY) = (وزن مواد جامد حل‌شده در فنجان ÷ وزن اولیه قهوه) × ۱۰۰</p><h4>مقادیر ایده‌آل:</h4><ul><li>جام طلایی SCAA: EY = ۱۸–۲۲٪</li><li>فیلتر: EY = ۱۸–۲۲٪</li><li>TDS (کل جامدات محلول) در فنجان:</li><li>فیلتر (جام طلایی SCAA): ۱٫۱۵–۱٫۳۵٪</li></ul><h4>کاربرد عملی:</h4><p>اگر EY کمتر از ۱۸٪ باشد → قهوه‌ی ترش و کم‌شیرین (Under-extracted)</p><p>اگر EY بیشتر از ۲۲٪ باشد → قهوه‌ی تلخ و گس (Over-extracted)</p><h4 class=\"sub\">📈 منحنی عصاره‌گیری (Extraction Curve) و نقاط بهینه</h4><h4>عصاره‌گیری به‌صورت منحنی S شکل (Sigmoid Curve) پیش می‌رود:</h4><ul><li>فاز اول (ابتدا): اسید‌های آلی و ترکیبات میوه‌ای (نت‌های روشن)</li><li>فاز دوم (میانه): قند‌ها و کارامل‌ها (شیرینی و بدنه)</li><li>فاز سوم (انتها): ترکیبات تلخ و گس (در صورت ادامه)</li></ul><h4>کاربرد عملی:</h4><p>برای اسپرسو، هدف متوقف کردن عصاره‌گیری در انتهای فاز دوم یا ابتدای فاز سوم است (۲۵–۳۰ ثانیه).</p><p>برای فیلتر، هدف رسیدن به تعادل بین فاز دوم و سوم (۲.۵–۳.۵ دقیقه).</p><h4 class=\"sub\">🧮 بهینه‌سازی برشته‌کاری با مدل‌های ریاضی</h4><p>برشته‌کاری یک فرآیند انتقال حرارت ناپایدار است که برای رسانش در دانه با معادله‌ی گرما (که از قانون فوریه می‌آید) مدل‌سازی می‌شود:</p><p class=\"formula\" dir=\"ltr\">∂T/∂t = α · ∇²T</p><h4>که در آن:</h4><ul><li>T = دما در نقطه‌ای از دانه</li><li>t = زمان</li><li>α = ضریب نفوذ حرارتی (وابسته به رطوبت و چگالی دانه)</li></ul><h4>کاربرد عملی:</h4><p>برای جلوگیری از سوختگی سطحی (Scorching) باید نرخ افزایش دما (RoR – Rate of Rise) کنترل شود:</p><ul><li>RoR ایده‌آل در ابتدا: بالاتر، و به‌تدریج کمتر</li><li>RoR ایده‌آل در پایان: چند درجه در دقیقه؛ مقدار دقیق به پروفایل بستگی دارد</li></ul><h4 class=\"sub\">📊 تحلیل آماری در کیاپینگ (Cupping Statistics)</h4><p>در کیاپینگ حرفه‌ای، از تحلیل واریانس (ANOVA) و تحلیل مؤلفه‌های اصلی (PCA) برای تشخیص تفاوت‌های معنادار بین نمونه‌ها استفاده می‌شود.</p><h4>فرمول ساده‌شده برای امتیازدهی نهایی (SCA Protocol):</h4><p class=\"formula\" dir=\"ltr\">Total Score = S₁ + S₂ + … + S₁₀   (هر پارامتر تا ۱۰ امتیاز؛ حداکثر ۱۰۰)</p><p>که در آن S_i امتیاز هر پارامتر (۰–۱۰) است.</p><h4>کاربرد عملی:</h4><ul><li>اگر اختلاف امتیاز داورها زیاد باشد، معمولاً نمونه دوباره کاپ می‌شود (آستانه‌ی دقیق به پروتکل بستگی دارد).</li><li>حداقل امتیاز برای Specialty: ۸۰ از ۱۰۰.</li></ul><h4 class=\"sub\">🤖 هوش مصنوعی و یادگیری ماشین در قهوه</h4><p>الگوریتم‌های رگرسیون و شبکه‌های عصبی برای پیش‌بینی طعم نهایی بر اساس داده‌های شیمیایی و حسی استفاده می‌شوند.</p><h4>مثال:</h4><h4>یک مدل رگرسیون خطی چندمتغیره برای پیش‌بینی امتیاز کیاپینگ:</h4><p class=\"formula\" dir=\"ltr\">Score = a₁ · Caffeine + a₂ · CGA + a₃ · pH + b</p><p>که ضرایب a₁, a₂, a₃ از داده‌های تاریخی به‌دست می‌آیند.</p><h4>کاربرد عملی:</h4><ul><li>برخی برشته‌کارها از چنین مدل‌ها برای پیشنهاد پروفایل استفاده می‌کنند؛ دقت آن به داده‌ی آموزشی بستگی دارد.</li><li>مدل‌ها ابزار کمکی‌اند و جایگزین چشیدن نیستند.</li></ul><h4 class=\"sub\">📉 مدل‌های اقتصادی و قیمت‌گذاری (Econometrics of Coffee)</h4><p>قیمت قهوه در بورس را با مدل‌های سری زمانی (Time Series) مانند ARIMA و GARCH تحلیل می‌کنند؛ نمونه‌ی ساده‌ی یک مدل ARMA:</p><p class=\"formula\" dir=\"ltr\">Pₜ = c + φ₁ Pₜ₋₁ + φ₂ Pₜ₋₂ + θ₁ εₜ₋₁ + εₜ</p><h4>کاربرد عملی:</h4><ul><li>پیش‌بینی قیمت برای خرید و فروش عمده.</li><li>مدیریت ریسک نوسانات بازار.</li></ul><h4 class=\"sub\">🧮 بهینه‌سازی چندهدفه (Multi-Objective Optimization)</h4><h4>در طراحی یک نوشیدنی ایده‌آل، چندین هدف متضاد وجود دارد:</h4><ul><li>حداکثر شیرینی</li><li>حداقل تلخی</li><li>حداکثر عطر</li><li>حداقل اسیدیته‌ی خشن</li></ul><p>این مسئله با روش Pareto Frontier حل می‌شود که مجموعه‌ای از راه‌حل‌های بهینه (نه یک راه‌حل واحد) ارائه می‌دهد.</p><h4>کاربرد عملی:</h4><ul><li>تنظیم همزمان دما، زمان، و نسبت قهوه به آب برای دستیابی به تعادل مطلوب.</li></ul>","kind":"item","src":[["Coffee Chronicler — Golden Cup standard","https://coffeechronicler.com/its-time-to-retire-the-golden-cup-standard/"]]},{"id":359,"title":"قهوه و مهندسی (Coffee & Engineering)","body":"<h4>جریان در بستر قهوه: قانون دارسی</h4><ul><li>قانون دارسی Q = (k·A·ΔP)/(μ·L) جریان آرام و آهسته‌ی سیال در محیط متخلخل را توصیف می‌کند: Q دبی، k نفوذپذیری، A سطح مقطع، μ لزجت دینامیکی، ΔP افت فشار و L طول نمونه.</li><li>این قانون برای جریان آرام (عدد رینولدز کمتر از ۱ و گاهی تا ۱۰) معتبر است؛ در عدد رینولدز بالاتر اثرات اینرسی مهم می‌شوند و معمولاً جمله‌ی Forchheimer افزوده می‌شود.</li><li>در اسپرسو k به اندازه‌ی ذرات و تراکم بستر وابسته است؛ آسیاب ریزتر k را کم می‌کند.</li></ul>\n<h4>کنترل PID دما</h4><ul><li>P به خطای فعلی پاسخ می‌دهد و فوراً اصلاح می‌کند اما به‌تنهایی اختلاف ثابت از نقطه‌ی هدف باقی می‌گذارد.</li><li>I مجموع خطاهای گذشته را در نظر می‌گیرد و خطای ماندگار را حذف می‌کند.</li><li>D روند تغییر خطا را پیش‌بینی می‌کند و با میرا کردن پاسخ، فراجهش را کم و پایداری را بیشتر می‌کند.</li><li>در کنترل دمای کوره‌ی مقاومتی، افزودن جسم سرد باعث افت دما می‌شود و جمله‌ی I می‌تواند فراجهش بسازد؛ راه‌حل «منجمد کردن انتگرال» در آن زمان معرفی می‌شود.</li></ul>\n<h4>ماشین اسپرسو</h4><ul><li>در طراحی «پیستون فنری»، اپراتور فنر را می‌کشد و فنر فشار اسپرسو را (معمولاً ۸ تا ۱۰ بار؛ ۱۱۶ تا ۱۴۵ psi) تأمین می‌کند.</li></ul>\n<h4>آسیاب</h4><ul><li>آسیاب سنگی ذراتی با اندازه‌ی یکنواخت می‌دهد که با فاصله‌ی دو سطح ساینده تعیین می‌شود و گرمای اصطکاکی بسیار کمتری از تیغه‌ای دارد؛ در گرمای زیاد روغن‌ها و عطرها تبخیر می‌شوند.</li></ul>\n","kind":"item","src":[["Wikipedia — Darcy's law","https://en.wikipedia.org/wiki/Darcy's_law"],["Wikipedia — PID controller","https://en.wikipedia.org/wiki/PID_controller"],["Wikipedia — Espresso machine","https://en.wikipedia.org/wiki/Espresso_machine"],["Wikipedia — Burr mill","https://en.wikipedia.org/wiki/Burr_mill"]]},{"id":370,"title":"قهوه و شیمی تجزیه (Coffee & Analytical Chemistry)","body":"<h4>کروماتوگرافی گازی-طیف‌سنجی جرمی (GC-MS)</h4><ul><li>ستون گازی مولکول‌ها را بر پایه‌ی تمایل آن‌ها به فاز ساکن جدا می‌کند و هر کدام در زمان متفاوتی خارج می‌شود.</li><li>در طیف‌سنج جرمی مولکول‌ها یونیزه و به قطعاتی با رفتار مشخص و تکرارپذیر شکسته می‌شوند و بر اساس نسبت جرم به بار آشکار می‌شوند.</li><li>نمونه را می‌توان با تزریق مایع، دفع حرارتی یا ریزاستخراج فاز جامد (SPME) وارد کرد؛ GC-MS در تحلیل ترکیبات معطر غذاها به‌طور گسترده به‌کار می‌رود.</li><li>در قهوه، ترکیب با اولفاکتومتری (GC-O) و تحلیل OAV برای یافتن ترکیبات کلیدی عطر استفاده شده است (مقاله‌ی «ترکیبات شیمیایی فرار»).</li></ul>\n<h4>کروماتوگرافی مایع با کارایی بالا (HPLC)</h4><ul><li>حلال تحت فشار (فاز متحرک) از ستونی پر از ذرات ریز (فاز ساکن) عبور می‌کند؛ هر ترکیب با سرعت خودش حرکت می‌کند.</li><li>آشکارساز هر ترکیب را به‌صورت پیک ثبت می‌کند و مساحت پیک متناسب با مقدار آن است.</li><li>رایج‌ترین حالت «فاز معکوس» است: فاز ساکن ناقطبی (مثلاً زنجیره‌های C18) و فاز متحرک آبی-قطبی؛ ترکیبات آب‌گریزتر دیرتر خارج می‌شوند.</li><li>آشکارسازهای UV-Vis و آرایه‌ی دیودی (DAD) رایج‌اند. در مطالعه‌ی بالا HPLC برای ترکیبات غیرفرار مثل اسیدهای آلی و کلروژنیک اسید استفاده شد.</li></ul>\n<p>برای مقیاس آگترون به مقاله‌ی «درجه‌ی برشته‌کاری» نگاه کنید.</p>","kind":"item","src":[["Wikipedia — Gas chromatography–mass spectrometry","https://en.wikipedia.org/wiki/Gas_chromatography–mass_spectrometry"],["Wikipedia — High-performance liquid chromatography","https://en.wikipedia.org/wiki/High-performance_liquid_chromatography"],["Foods 2025 — Key Aroma-Active Compounds in Commercial Coffee (DOAJ)","https://doaj.org/article/07efd8cfe32c4ff4ab264180f04f41b7"]]},{"id":584,"title":"شیمی آب فراتر از سختی","body":"<p>مقاله‌ی «سختی آب و تأثیر آن بر عصاره‌گیری» جدول استاندارد SCAA را دارد. اینجا نقش یون‌ها بر اساس منابع آمده است.</p><ul><li>ترکیبات طعمی قهوه به‌صورت گونه‌های بدون بار، اسیدها و نمک‌های مزدوج‌اند و انحلال و استخراجشان به مواد معدنی محلول آب بستگی دارد.</li><li>یون‌های Na⁺، Mg²⁺ و Ca²⁺ به بخش‌های هسته‌دوست مولکول‌های قهوه متصل می‌شوند و نرخ و ترکیب استخراج را تغییر می‌دهند.</li><li>پژوهش Hendon و همکاران (۲۰۱۴) با نظریه‌ی تابعیت چگالی انرژی اتصال پنج اسید قهوه، کافئین و ترکیب نماینده‌ی اوژنول را محاسبه کرد تا ترکیب معدنی ایده‌آل آب را توضیح دهد.</li><li>هر دو پارامتر سختی و قلیائیت اهمیت دارند: سختی (Ca و Mg) استخراج را ممکن می‌کند و قلیائیت از تلخی یا تختی ناخواسته جلوگیری می‌کند (SCAA).</li></ul>","kind":"item","src":[["Hendon CA, Colonna-Dashwood L, Colonna-Dashwood M. The role of dissolved cations in coffee extraction. J Agric Food Chem 2014","https://researchportal.bath.ac.uk/en/publications/the-role-of-dissolved-cations-in-coffee-extraction/"],["43factory — Dissecting SCAA water quality standard","https://43factory.coffee/en/news/dissecting-scaas-water-quality-standard/"]]}]},{"id":"C4","icon":"technique","title":"تکنیک‌ها، نکات و مرجع دم‌آوری","items":[{"id":5,"title":"روش‌های دم‌آوری (عصاره‌گیری) (Brewing Methods)","body":"<h4>اسپرسو</h4>\n<div class=\"table-wrap\"><table><thead><tr><th>پارامتر</th><th>مقدار</th></tr></thead><tbody>\n<tr><td>فشار آب ورودی</td><td>۸ تا ۱۰ بار</td></tr><tr><td>دمای آب در خروج از واحد</td><td>۸۶ تا ۹۰ °C (در فنجان ۶۴ تا ۷۰ °C)</td></tr><tr><td>زمان عبور آب</td><td>۲۰ تا ۳۰ ثانیه (عموماً ۲۵ تا ۳۰)</td></tr><tr><td>دوز قهوه</td><td>۶٫۵ تا ۷٫۵ گرم برای هر شات؛ سینگل، دبل و تریپل حدود ۷، ۱۴ و ۲۱ گرم</td></tr><tr><td>حجم در فنجان (با کرما)</td><td>۲۲٫۵ تا ۲۷٫۵ میلی‌لیتر</td></tr>\n</tbody></table></div>\n<ul><li>ریسترتو نصف حجم نورمال و لونگو دو تا سه برابر حجم نورمال است (برای دوز ۱۴ گرم: نورمال حدود ۶۰ و ریسترتو حدود ۳۰ میلی‌لیتر آب).</li><li>کرما لایه‌ای از کف متراکم روی نوشیدنی است که با انحلال بیشتر CO₂ در آب پرفشار پدید می‌آید.</li></ul>\n<h4>دم‌آوری فیلتری (راهنمای عمومی)</h4><ul><li>بازده استخراج ایده‌آل ۱۸ تا ۲۲٪.</li><li>TDS: استاندارد آمریکایی ۱٫۱۵ تا ۱٫۳۵٪؛ نروژی ۱٫۳۰ تا ۱٫۵۰٪؛ اروپایی ۱٫۲۰ تا ۱٫۴۵٪.</li><li>نسبت پیشنهادی از ۵۵ گرم در لیتر (آمریکایی) تا ۶۳ گرم در لیتر (نروژی) است.</li><li>روش‌هایی که قهوه را مدت بیشتری در آب داغ نگه می‌دارند آسیاب درشت‌تر می‌خواهند؛ فرنچ پرس معمولاً ۴ تا ۷ دقیقه.</li></ul>\n<h4>کلد برو و نیترو</h4><ul><li>آسیاب درشت ۱۲ تا ۲۴ ساعت در آب با دمای محیط (یا آب سرد) خیسانده می‌شود.</li><li>مطالعه‌ی ۲۰۱۷ نشان داد دم‌آوری ۲۴ ساعته در دمای پایین در حجم برابر کافئین بیشتری از دم‌آوری ۶ دقیقه‌ای در ۹۸ °C دارد.</li><li>اسیدیته‌ی pH مشابه است ولی اسید قابل‌تیتر کلد برو کمتر است.</li><li>نیترو کلد برو نیتروژن اضافه می‌کند تا بافت نرم بدهد؛ از شیر نیتروژنی مثل شیر آبجو سرو می‌شود، از اوایل دهه‌ی ۲۰۱۰ رایج شد و بدون یخ سرو می‌شود.</li></ul>\n","kind":"item","src":[["Wikipedia — Espresso","https://en.wikipedia.org/wiki/Espresso"],["Wikipedia — Coffee preparation","https://en.wikipedia.org/wiki/Coffee_preparation"],["Wikipedia — Cold brew coffee","https://en.wikipedia.org/wiki/Cold_brew_coffee"]]},{"id":11,"title":"نمونه‌ی یک دستور ایده‌آل (Single-Origin Ideal Recipe)","body":"<p>نمونه‌ی دستور مرجع: دستور قهرمان جهانی ۲۰۱۶ (World Brewers Cup، دوبلین، ۲۳ و ۲۴ ژوئن) تتسو کاسویا، باریستای Coffee Factory در ایباراکی ژاپن.</p><ul><li>قهوه: گیشای فرآوری طبیعی از Ninety Plus Gesha Estates پاناما.</li><li>۲۰ گرم قهوه با آسیاب درشت و ۳۰۰ گرم آب ۹۲ °C.</li><li>بلوم ۵۰ گرم برای ۴۵ ثانیه؛ سپس ۷۰ گرم در ۰:۴۵ و سه بار ۶۰ گرم در ۱:۳۰، ۲:۱۵ و ۳:۰۰.</li><li>دریپر در ۳:۳۰ برداشته می‌شود؛ TDS هدف ۱٫۳.</li></ul><p>روش کلی در مقاله‌ی «روش ۴:۶ در V60» آمده است. این دستور برای قهوه‌ی مسابقه بود؛ برای قهوه‌ی دیگر باید تنظیم شود.</p>","kind":"item","src":[["Kurasu — 2016 World Brewers Cup Champion: Tetsu Kasuya","https://kurasu.kyoto/blogs/kurasu-journal/2016-world-brewers-cup-champion-tetsu-kasuya"]]},{"id":12,"title":"تمامی گزینه‌ها، جایگزین‌ها و تضاد‌ها (All Variants)","body":"<ul><li><strong>غلیظ‌تر:</strong> ریسترتو نصف حجم نورمال و لونگو دو تا سه برابر آن است؛ بنابراین کم‌کردن حجم خروجی عصاره را غلیظ‌تر می‌کند.</li><li><strong>سرد:</strong> کلد برو (۱۲ تا ۲۴ ساعت خیساندن در آب با دمای محیط یا سرد) یا نیترو کلد برو؛ کلد برو اسید قابل‌تیتر کمتری دارد.</li><li><strong>بدون کافئین:</strong> روش‌هایی مثل آب سوئیسی (بدون حلال) یا CO₂ فوق‌بحرانی؛ «بدون کافئین» به معنای صفر نیست (آمریکا ≥۹۷٪ حذف، اتحادیه‌ی اروپا ۹۹٫۹٪).</li></ul>","kind":"item","src":[["Wikipedia — Espresso","https://en.wikipedia.org/wiki/Espresso"],["Wikipedia — Cold brew coffee","https://en.wikipedia.org/wiki/Cold_brew_coffee"],["Wikipedia — Decaffeination","https://en.wikipedia.org/wiki/Decaffeination"]]},{"id":21,"title":"فهرست مدل‌های سرو قهوه","body":"<h4>خانواده‌ی اسپرسو</h4><div class=\"table-wrap\"><table><thead><tr><th>نوشیدنی</th><th>تعریف</th></tr></thead><tbody><tr><td>ریسترتو (Ristretto)</td><td>شات اسپرسوی غیررقیق در دمی‌تاس؛ «پررنگ‌تر، پربدنه‌تر و با تلخی کمتر». نصف حجم نورمال (حدود ۲۰ میلی‌لیتر).</td></tr><tr><td>اسپرسو نورمال</td><td>حجم ۲۵ تا ۳۰ میلی‌لیتر با کرما، فشار ۸ تا ۱۰ بار.</td></tr><tr><td>دوپیو (Doppio)</td><td>شات دوبل در دمی‌تاس.</td></tr><tr><td>لونگو (Lungo)</td><td>«تمام آب» از قهوه عبور می‌کند و رقیق‌سازی نمی‌شود؛ دو تا سه برابر حجم نورمال (حدود ۶۰ میلی‌لیتر).</td></tr><tr><td>کافه کرما (Caffè crema)</td><td>لونگوی بلندتر؛ حدود ۱۲۰ تا ۱۸۰ میلی‌لیتر.</td></tr><tr><td>آمریکانو (Americano)</td><td>یک یا دو شات اسپرسو با ۱۵۰ تا ۴۰۰ میلی‌لیتر آب داغ؛ قدرتی نزدیک قهوه‌ی دم‌شده با طعمی متفاوت.</td></tr><tr><td>لانگ بلک (Long black)</td><td>گونه‌ای از آمریکانو و لونگو.</td></tr><tr><td>کورتادو (Cortado)</td><td>اسپانیایی؛ اسپرسو با «مقدار برابر» شیر بخارزده در لیوان کوچک برای کاهش تلخی.</td></tr><tr><td>فلت وایت (Flat white)</td><td>اسپرسو با میکروفوم؛ کوچک‌تر از لاته با نسبت قهوه به شیر بالاتر.</td></tr><tr><td>کاپوچینو (Cappuccino)</td><td>اسپرسو با شیر؛ حدود ۱۵۰ تا ۱۸۰ میلی‌لیتر.</td></tr><tr><td>کافه لاته (Caffè latte)</td><td>اسپرسو با شیر؛ حدود ۲۵۰ تا ۲۸۰ میلی‌لیتر.</td></tr><tr><td>ماکیاتو</td><td>اسپرسوی ماکیاتو حدود ۳۰ تا ۴۰ میلی‌لیتر؛ لاته ماکیاتو حدود ۲۵۰ میلی‌لیتر.</td></tr><tr><td>کافه موکا (Café mocha)</td><td>گونه‌ای از لاته؛ «معمولاً یک‌سوم اسپرسو و دوسوم شیر بخارزده» با شربت یا پودر شکلات.</td></tr><tr><td>ماروکینو (Marocchino)</td><td>اسپرسو، شیر بخارزده و پودر کاکائو.</td></tr><tr><td>کافه بومبون (Café bombón)</td><td>از والنسیا؛ اسپرسو با شیر تغلیظ‌شده‌ی شیرین به نسبت ۱:۱، لایه‌لایه در لیوان و معمولاً هم‌زده.</td></tr><tr><td>کافه کوبانو (Café cubano)</td><td>اسپرسوی دم‌شده با شکر؛ گونه‌ها: کورتادیتو (کمی شیر) و کافه کون لچه (شیر بخارزده).</td></tr><tr><td>کافه کورتو (Caffè corretto)</td><td>اسپرسو «اصلاح‌شده» با یک شات مشروب مثل گراپا، براندی یا سامبوکا.</td></tr><tr><td>کافه زورو (Café zorro)</td><td>یک دوپیو در آب داغ به نسبت ۱:۱.</td></tr><tr><td>فلت رد (Flat red)</td><td>اسپرسو با آب پرتقال و انار بخارزده؛ بدون شیر و شکر؛ ساخته‌ی کیف، ۲۰۱۶.</td></tr><tr><td>پدروکی (Pedrocchi / Caffè Padovano)</td><td>لایه‌های اسپرسو، خامه با شربت نعنا و پودر کاکائو؛ هم‌زده یا شیرین نمی‌شود.</td></tr><tr><td>اسپرسو کن پانا</td><td>از گونه‌های اسپرسو؛</td></tr></tbody></table></div><h4>سرد</h4><div class=\"table-wrap\"><table><thead><tr><th>نوشیدنی</th><th>تعریف</th></tr></thead><tbody><tr><td>فردو اسپرسو (Freddo espresso)</td><td>یونانی؛ دو شات اسپرسو (۳۰ تا ۵۰ میلی‌لیتر)، شکر و یخ (۶۰ تا ۱۰۰ میلی‌لیتر) با نسبت اسپرسو به یخ ۱:۲، شیک‌شده تا کف کند.</td></tr><tr><td>شیکراتو (Shakerato)</td><td>اسپرسو که با یخ شیک می‌شود.</td></tr><tr><td>ایس شات (Ice shot)</td><td>یک اسپرسوی تازه روی یخ در لیوان لاته؛ بدون شیر، شکر یا خامه.</td></tr><tr><td>کلد برو (Cold brew)</td><td>آسیاب درشت ۱۲ تا ۲۴ ساعت در آب سرد.</td></tr><tr><td>نیترو کلد برو</td><td>کلد برو با نیتروژن؛ از شیر نیتروژنی و بدون یخ سرو می‌شود.</td></tr><tr><td>فلش برو (Flash brew)</td><td>قهوه‌ی دریپ داغ مستقیم روی یخ؛ طعم و اسیدیته‌ی دم داغ را حفظ می‌کند.</td></tr><tr><td>فراپه یونانی (Greek frappé)</td><td>قهوه‌ی فوری اسپری‌خشک، شکر و شیر، اغلب شیک‌شده.</td></tr></tbody></table></div><h4>دم‌شده و سنتی</h4><div class=\"table-wrap\"><table><thead><tr><th>نوشیدنی</th><th>تعریف</th></tr></thead><tbody><tr><td>ردآی (Red eye)</td><td>قهوه‌ی دم‌شده‌ی معمولی با اسپرسو؛ «shot in the dark»؛ در استارباکس دابل‌شات «black eye» نام دارد.</td></tr><tr><td>قهوه‌ی ترک</td><td>قهوه‌ی بسیار ریز تا آستانه‌ی جوش می‌جوشد؛ شیرینی از sade (بدون شکر) تا şekerli (دو سه قاشق چای‌خوری).</td></tr><tr><td>قهوه‌ی عربی</td><td>عربیکای بسیار ریز جوشیده، اغلب با هل، میخک، زعفران یا دارچین؛ معمولاً بدون شکر و بی‌فیلتر.</td></tr><tr><td>یزدی (Yazdi coffee)</td><td>قهوه‌ی برشته که ساعت‌ها با گلاب، هل و شکر می‌جوشد و از ابریشم صاف می‌شود.</td></tr><tr><td>کوپی کوتوک (Kopi kothok)</td><td>تفاله‌ی قهوه با شکر جوشانده می‌شود؛ نسبت قهوه به شکر ۱:۲ (یا ۱:۱ برای تلخ‌تر).</td></tr><tr><td>کافه د اولا (Café de olla)</td><td>مکزیکی؛ در ظرف سفالی با دارچین و پیلونسیلو.</td></tr><tr><td>کافه تروپیرو (Café tropeiro)</td><td>برزیلی؛ پودر قهوه با آب جوشانده می‌شود.</td></tr><tr><td>قهوه‌ی تخم‌مرغ ویتنامی</td><td>زرده‌ی تخم‌مرغ، شکر، شیر تغلیظ‌شده و قهوه‌ی دریپ.</td></tr><tr><td>قهوه‌ی شیر (راد آیلند)</td><td>شربت قهوه‌ی شیرین در شیر، شبیه شیر شکلات.</td></tr></tbody></table></div><h4>با الکل و افزودنی‌های خاص</h4><div class=\"table-wrap\"><table><thead><tr><th>نوشیدنی</th><th>تعریف</th></tr></thead><tbody><tr><td>هات‌شات سوئدی (Hotshot)</td><td>یک بخش گالیانو، یک بخش قهوه، یک بخش خامه‌ی سنگین.</td></tr><tr><td>روده‌شایمر کافه (Rüdesheimer Kaffee)</td><td>براندی، قهوه، شکر و خامه‌ی فرم‌گرفته؛ آلمان، ۱۹۵۷.</td></tr><tr><td>کاراخیو (Carajillo)</td><td>اسپانیایی؛ قهوه با براندی، ویسکی، آنیسِت یا رام.</td></tr><tr><td>فاریزؤر (Pharisäer)</td><td>آلمانی؛ قهوه با رام (دوبل) و خامه‌ی فرم‌گرفته.</td></tr><tr><td>کافه کالوا (Café Calva)</td><td>قهوه با کالوادوس نرماندی.</td></tr><tr><td>ملیا (Melya)</td><td>قهوه با پودر کاکائو و عسل، گاهی با خامه.</td></tr></tbody></table></div><p>روش‌های دستی (V60، کمکس، فرنچ‌پرس، …) در مقاله‌های روش‌های دم‌آوری آمده‌اند.</p>","kind":"item","src":[["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"],["Wikipedia — Espresso","https://en.wikipedia.org/wiki/Espresso"],["Wikipedia — Cold brew coffee","https://en.wikipedia.org/wiki/Cold_brew_coffee"],["Wikipedia — Egg coffee","https://en.wikipedia.org/wiki/Egg_coffee"]]},{"id":23,"title":"خانواده اسپرسو (خالص و تغییرات حجمی)","body":"<h4 class=\"sub\">خانواده‌ی اسپرسو</h4><ul><li>اسپرسو قهوه‌ی غلیظی است که با عبور آب داغ تحت فشار بالا از قهوه‌ی ریز آسیاب‌شده ساخته می‌شود؛ هر سرو معمولاً ۲۵ تا ۳۰ میلی‌لیتر است.</li><li>استاندارد مؤسسه‌ی ملی اسپرسوی ایتالیا: فشار ورودی آب ۸ تا ۱۰ بار، دمای خروج آب ۸۶ تا ۹۰ درجه، دمای فنجان ۶۴ تا ۷۰ درجه، زمان عصاره‌گیری ۲۰ تا ۳۰ ثانیه و دوز تک‌شات ۶٫۵ تا ۷٫۵ گرم. دوبل و سه‌تایی حدود ۱۴ و ۲۱ گرم‌اند.</li><li>ریسترتو: شات کوتاه‌تر (حدود ۲۰ میلی‌لیتر) با آسیاب ریزتر. لونگو: شات بلندتر با آب بیشتر (حدود ۶۰ میلی‌لیتر؛ دو تا سه برابر حجم نرمال).</li><li>دوپیو (Doppio): دو شات اسپرسو در فنجان دمیتاس.</li><li>کرما: کف غلیظ روی شات است که از روغن‌های امولسیونه تشکیل می‌شود؛ فشار بالا CO₂ بیشتری در مایع حل می‌کند و کرما می‌سازد؛ مختص اسپرسو است.</li></ul>","kind":"note","src":[["Wikipedia — Espresso","https://en.wikipedia.org/wiki/Espresso"],["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"]]},{"id":30,"title":"اسپرسو + آب (رقیق‌شده)","body":"<h4 class=\"sub\">اسپرسو + آب</h4><ul><li>آمریکانو: یک یا دو شات اسپرسو با حدود ۱۵۰ تا ۴۰۰ میلی‌لیتر آب داغ.</li><li>لونگو: آب از میان قهوه عبور می‌کند، نه اینکه پس از اسپرسو اضافه شود؛ معمولاً کوچک‌تر از آمریکانو یا لانگ‌بلک است.</li><li>ریسترتو را می‌توان در آب یا شیر رقیق کرد و آمریکانو، لانگ‌بلک، لاته یا کاپوچینو ساخت.</li><li>آمریکانو یک شات اسپرسو است که با آب داغ و با نسبت ۱ به ۳ تا ۱ به ۴ رقیق می‌شود؛ معمولاً ۱۲۰ تا ۱۸۰ میلی‌لیتر آب داغ به اسپرسو اضافه می‌کنند.</li><li>لانگ‌بلک نوشیدنی استرالیا و نیوزیلند و شبیه آمریکانو است، اما اسپرسو را روی آب داغ می‌ریزند تا کرما سالم بماند.</li><li>لانگ‌بلک معمولاً در فنجان ۱۵۰ تا ۱۸۰ میلی‌لیتری و آمریکانو در فنجان ۲۵۰ تا ۳۰۰ میلی‌لیتری سرو می‌شود؛ لانگ‌بلک پررنگ‌تر و آمریکانو ملایم‌تر و رقیق‌تر است.</li><li>لونگو با آب اضافه‌ی عبوری از قهوه ساخته می‌شود: اسپرسوی معمولی ۲۵ تا ۳۰ میلی‌لیتر و لونگو ۵۰ تا ۷۰ میلی‌لیتر است، و استخراج لونگو تا یک دقیقه طول می‌کشد.</li></ul>","kind":"note","src":[["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"],["Wikipedia — Espresso","https://en.wikipedia.org/wiki/Espresso"],["Wikipedia — Caffè americano","https://en.wikipedia.org/wiki/Caff%C3%A8_americano"],["Wikipedia — Lungo","https://en.wikipedia.org/wiki/Lungo"],["Sage Appliances — Long black vs. Americano: Key differences","https://www.sageappliances.com/uk/en/blog/coffee-and-espresso/long-black-vs-americano.html"]]},{"id":35,"title":"نکته طلایی برای هر سه مدل","body":"<h4 class=\"sub\">آمریکانو در برابر لانگ‌بلک</h4><ul><li>آمریکانو: یک یا دو شات اسپرسو به‌علاوه‌ی ۳۰ تا ۴۷۰ میلی‌لیتر آب داغ؛ در تعریف دقیق‌تر آب روی اسپرسو ریخته می‌شود و این کار کرما را از بین می‌برد.</li><li>لانگ‌بلک: دو شات اسپرسو روی آب داغ (معمولاً حدود ۱۰۰ تا ۱۲۰ میلی‌لیتر) ریخته می‌شود؛ کرما حفظ می‌شود و آب کمتر از آمریکانو است، پس طعم قوی‌تر است.</li><li>تانن‌های باقی‌مانده در کرما به لانگ‌بلک بدنه‌ی کمی پرتر می‌دهد.</li><li>هر دو نوشیدنی از یک مواد ساخته می‌شوند؛ تفاوت فقط ترتیب ریختن است.</li><li>نسبت ۱ به ۱ اسپرسو و آب برای نسخه‌ی کوتاه «ایتالیانو» و روش‌های هنری ذکر شده است تا رقیق‌شدن زیاد نشود.</li></ul>","kind":"note","src":[["Wikipedia — Caffè Americano","https://en.wikipedia.org/wiki/Caff%C3%A8_Americano"],["Wikipedia — Long black","https://en.wikipedia.org/wiki/Long_black"]]},{"id":37,"title":"اسپرسو + شیر/کف (داغ)","body":"<h4 class=\"sub\">اسپرسو + شیر</h4><ul><li>کورتادو: مقدار کمی اسپرسو با شیر بخار‌داده‌شده‌ی هم‌اندازه تا «تلخی را خنثی کند».</li><li>فلت‌وایت: اسپرسو با میکروفوم؛ نسبت به لاته کوچک‌تر است، میکروفوم کمتر و نسبت قهوه به شیر بیشتر دارد.</li><li>موکا (café mocha): گونه‌ای از لاته؛ معمولاً یک‌سوم اسپرسو و دوسوم شیر بخار‌داده‌شده با شکلات (اغلب شربت).</li><li>ردآی (Red eye): قهوه‌ی فیلتری با اضافه‌ی اسپرسو برای شدت طعم یا کافئین بیشتر؛ در استارباکس دو شات را «black eye» می‌نامند.</li></ul><h4 class=\"sub\">فلت‌وایت</h4><ul><li>خاستگاه محل اختلاف است: کافه‌داران استرالیا و نیوزیلند هر دو مدعی‌اند (Alan Preston در سیدنی ۱۹۸۵؛ Cafe DKD در اوکلند)؛ Ian Bersten معتقد است احتمالاً دهه‌ی ۱۹۵۰ انگلستان.</li><li>طبق Anette Moldvaer: دابل اسپرسو (۵۰ میلی‌لیتر) با حدود ۱۳۰ میلی‌لیتر شیر و لایه‌ی ۵ میلی‌متری میکروفوم. در استرالیا فنجان حدود ۲۰۰ و در نیوزیلند حدود ۱۷۵ میلی‌لیتر؛ کاپوچینو در فنجان ۱۵۰–۱۶۰ میلی‌لیتری با کف ضخیم.</li></ul>","kind":"note","src":[["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"],["Wikipedia — Flat white","https://en.wikipedia.org/wiki/Flat_white"]]},{"id":50,"title":"نکته کلیدی برای تمام مدل‌های شیردار","body":"<h4 class=\"sub\">شیر در نوشیدنی‌های شیردار</h4><ul><li>بخار دادن شیر وقتی تمام می‌شود که به حدود ۷۰ درجه‌ی سانتی‌گراد برسد.</li><li>بالاتر از ۸۲ درجه شیر می‌سوزد و بافتش خراب می‌شود؛ کازئین دناتوره می‌شود و دیگر نمی‌تواند میکروفوم را نگه دارد.</li><li>میکروفوم براق و کمی غلیظ است با حباب‌های ریز و یکنواخت؛ شبیه رنگ خیس یا مارشمالوی ذوب‌شده.</li><li>چربی از حدود ۴۰ درجه شروع به اختلال در کف می‌کند و بالاتر از آن پروتئین بتا-لاکتوگلوبولین بیشتر ساختار کف را نگه می‌دارد.</li></ul>","kind":"note","src":[["Wikipedia — Microfoam","https://en.wikipedia.org/wiki/Microfoam"]]},{"id":52,"title":"اسپرسو + افزودنی‌های خاص (شیرین‌کننده، مشروب، بستنی، میوه، گاز)","body":"<h4 class=\"sub\">اسپرسو با افزودنی‌های ویژه</h4><ul><li>آفوگاتو: ژلاتو (فیوردی‌لاته یا وانیل) با اسپرسو روی آن؛ گاهی لیکور هم اضافه می‌شود؛ خاستگاه ناشناخته.</li><li>کافه کورتو: شات اسپرسو با کمی مشروب (معمولاً گراپا، گاهی سامبوکا یا براندی) که داخل اسپرسو ریخته یا کنارش سرو می‌شود تا خود فرد بریزد.</li><li>اسپرسو مارتینی: ودکا + لیکور قهوه + اسپرسو.</li><li>موکا: لاته‌ی شکلاتی با اسپرسو و شیر داغ؛ نام از بندر مخا (یمن)، مرکز تجارت قهوه از قرن ۱۵ تا ۱۷.</li><li>قهوه‌ی تخم‌مرغ ویتنامی: زرده‌ی تخم‌مرغ با شکر و شیر تغلیظ‌شده در بن‌ماری گرم (نه حرارت مستقیم) شلاق می‌خورد و قهوه‌ی روبوستای فیلترشده با phin روی آن ریخته می‌شود؛ در اواخر دهه‌ی ۱۹۴۰ در هانوی (Giang Café) ابداع شد، زرده به‌جای شیر کمیاب.</li></ul>","kind":"note","src":[["Wikipedia — Affogato","https://en.wikipedia.org/wiki/Affogato"],["Wikipedia — Caffè corretto","https://en.wikipedia.org/wiki/Caff%C3%A8_corretto"],["Wikipedia — Espresso martini","https://en.wikipedia.org/wiki/Espresso_martini"],["Wikipedia — Mocha (drink)","https://en.wikipedia.org/wiki/Mocha_(drink)"],["Wikipedia — Egg coffee","https://en.wikipedia.org/wiki/Egg_coffee"]]},{"id":59,"title":"نکات ایمنی و کیفی برای مدل‌های دارای افزودنی","body":"<h4 class=\"sub\">نوشیدنی‌های دارای افزودنی</h4><ul><li>ایریش کافی: ۵۰ میلی‌لیتر ویسکی ایرلندی، ۱۲۰ میلی‌لیتر قهوه‌ی سیاه داغ، دست‌کم یک قاشق چای‌خوری شکر و ۵۰ میلی‌لیتر خامه‌ی سرد؛ لیوان از پیش گرم می‌شود و خامه آهسته روی پشت قاشق ریخته می‌شود.</li><li>شکر برای شناور ماندن خامه ضروری ذکر شده است.</li><li>اسپرسو و تونیک: ابتدا تونیک یخی در لیوان و سپس اسپرسو برای لایه‌لایه شدن؛ برعکس آن کف ایجاد می‌کند.</li><li>آفوگاتو: یک اسکوپ ژلاتو (وانیل یا فیورده‌لاته) با اسپرسو؛ ژلاتو ذوب می‌شود و با اسپرسو در ته لیوان قاطی می‌شود.</li><li>آفوگاتو در ایتالیا دسر است و بیرون از آن اغلب نوشیدنی نوشته می‌شود.</li></ul>","kind":"note","src":[["Wikipedia — Irish coffee","https://en.wikipedia.org/wiki/Irish_coffee"],["Wikipedia — Espresso and tonic","https://en.wikipedia.org/wiki/Espresso_and_tonic"],["Wikipedia — Affogato","https://en.wikipedia.org/wiki/Affogato"]]},{"id":61,"title":"دم‌آوری ثقلی / فیلتری دستی (Pour-Over)","body":"<h4 class=\"sub\">دم‌آوری فیلتری دستی</h4><ul><li>فیلتر کاغذی قهوه را ملیتا در ۱۹۰۸ ابداع کرد؛ کمکس ۱۹۴۱ و Hario V60 در ۲۰۰۴ عرضه شدند.</li><li>فیلتر می‌تواند کاغذی، پارچه‌ای یا فلزی باشد؛ فیلتر فلزی روغن‌ها را عبور می‌دهد.</li><li>نسبت دم‌آوری ترجیحی بر پایه‌ی جرم ۱۵ تا ۱۸ به ۱ (آب به قهوه) است؛ یک فنجان ۲۴۰ میلی‌لیتری حدود ۱۴ تا ۱۶ گرم قهوه می‌خواهد.</li><li>روغن‌های معطر نزدیک ۹۶ درجه آزاد می‌شوند؛ آب باید کمی کمتر از جوش باشد.</li></ul>","kind":"note","src":[["Wikipedia — Pour-over coffee","https://en.wikipedia.org/wiki/Pour-over_coffee"],["Wikipedia — Coffee preparation","https://en.wikipedia.org/wiki/Coffee_preparation"]]},{"id":66,"title":"نکات طلایی برای کل دسته فیلتری","body":"<h4 class=\"sub\">نکات فیلتری</h4><ul><li>از ترازو استفاده کنید: نسبت‌ها بر پایه‌ی جرم تعریف می‌شوند (۵۵ گرم در لیتر استاندارد آمریکایی و ۶۳ گرم در لیتر نروژی).</li><li>آب «کمی کمتر از جوش» بهتر است.</li><li>فیلتر کاغذی، پارچه‌ای و فلزی طعم متفاوتی می‌دهند (فلزی بدنه و روغن بیشتر).</li><li>بازده استخراج ایده‌آل برای قهوه‌ی سنتی ۱۸ تا ۲۲ درصد است؛ زیر ۱۸ درصد معمولاً ترش و بالای ۲۲ درصد معمولاً تلخ می‌شود.</li><li>دمای پیشنهادی دم‌آوری ۹۱ تا ۹۴ درجه‌ی سانتی‌گراد است.</li><li>فیلتر کاغذی دی‌ترپن‌هایی مثل کافستول و کاهوئول را جدا می‌کند، اما فیلتر مشبک فلزی، نایلونی یا چینی این کار را نمی‌کند.</li><li>در دم‌آوری پورآور، ابتدا کمی آب داغ روی تفاله می‌ریزند و حدود ۳۰ تا ۴۵ ثانیه صبر می‌کنند (بلومینگ)؛ بعد بقیه‌ی آب را آهسته و دایره‌وار می‌ریزند.</li></ul>","kind":"note","src":[["Wikipedia — Coffee preparation","https://en.wikipedia.org/wiki/Coffee_preparation"],["Wikipedia — Pour-over coffee","https://en.wikipedia.org/wiki/Pour-over_coffee"],["Wikipedia — Coffee extraction","https://en.wikipedia.org/wiki/Coffee_extraction"],["Wikipedia — Drip coffee","https://en.wikipedia.org/wiki/Drip_coffee"],["Wikipedia — Coffee filter","https://en.wikipedia.org/wiki/Coffee_filter"]]},{"id":68,"title":"دم‌آوری غوطه‌وری و تحت فشار غیرالکتریکی","body":"<h4 class=\"sub\">غوطه‌وری و تحت فشار</h4><ul><li>فرنچ‌پرس: حدود ۳۰ گرم قهوه برای ۵۰۰ میلی‌لیتر آب ۹۳–۹۶ درجه، آسیاب درشت و حدود ۴ دقیقه (در روش‌های دیگر ۴ تا ۷ دقیقه و آب «کمی کمتر از جوش»).</li><li>ایروپرس: ساخته‌ی Alan Adler، معرفی‌شده در نوامبر ۲۰۰۵؛ دز مسابقه‌ای حدود ۱۴–۲۰ گرم با ۲۰۰–۲۳۰ میلی‌لیتر آب ۸۰–۹۲ درجه.</li><li>موکاپات: Bialetti Moka Express از ۱۹۳۳؛ فشار ۱–۲ بار؛ نسبت حدود ۱ به ۱۰؛ دارای سوپاپ ایمنی.</li></ul>","kind":"note","src":[["Wikipedia — French press","https://en.wikipedia.org/wiki/French_press"],["Wikipedia — AeroPress","https://en.wikipedia.org/wiki/AeroPress"],["Wikipedia — Moka pot","https://en.wikipedia.org/wiki/Moka_pot"]]},{"id":75,"title":"نکات طلایی برای کل دسته غوطه‌وری و تحت فشار","body":"<h4 class=\"sub\">نکات غوطه‌وری</h4><ul><li>در فرنچ‌پرس آسیاب درشت مناسب است و زمان تماس حدود ۴ دقیقه (تا ۷) است.</li><li>در موکاپات سوپاپ ایمنی وجود دارد و فشار فقط ۱–۲ بار است (بسیار کمتر از اسپرسو).</li><li>در ایروپرس دز و دمای آب (۸۰–۹۲ درجه) بر طعم اثر می‌گذارد.</li></ul>","kind":"note","src":[["Wikipedia — French press","https://en.wikipedia.org/wiki/French_press"],["Wikipedia — AeroPress","https://en.wikipedia.org/wiki/AeroPress"],["Wikipedia — Moka pot","https://en.wikipedia.org/wiki/Moka_pot"]]},{"id":77,"title":"قهوه‌ساز‌های اتوماتیک / قطره‌ای (Batch Brew & Drip)","body":"<h4 class=\"sub\">قهوه‌ساز قطره‌ای و پرکولاتور</h4><ul><li>قهوه‌ساز برقی: آب سرد از مخزن به محفظه‌ی گرمایش باریک (معمولاً آلومینیومی) می‌رود؛ با ترموسیفون از لوله‌ی عایق به سر اسپری می‌رسد و روی قهوه‌ی سبد پخش می‌شود و از فیلتر به کاراف می‌چکد؛ شیر یک‌طرفه برگشت آب را می‌گیرد، ترموستات المنت را قطع و وصل می‌کند و صفحه‌ی گرم‌نگه‌دار قهوه را گرم می‌دارد.</li><li>تاریخچه: Melitta Bentz ۱۹۰۸ (فیلتر کاغذی)؛ Willy Brand ۱۹۴۴ (قهوه‌ساز خودکار با فیلتر گرد)؛ Wigomat ۱۹۵۴ آلمان؛ اوایل ۱۹۷۰ برند Mr. Coffee؛ در دهه‌ی ۱۹۷۰ جای پرکولاتور را گرفتند.</li><li>پرکولاتور: بخار آب جوشان آب داغ را از لوله بالا می‌برد و روی قهوه‌ی درشت‌آسیاب‌شده می‌ریزد و دوباره به آب پایین می‌چکد؛ وقتی صدای «پرک‌پرک» به غرغر پیوسته تبدیل شد قهوه آماده است. جوشش مداوم بیش‌استخراج و تلخی می‌آورد. نخستین مدل مدرن ۱۸۱۹ (Laurens، پاریس)؛ ۱۸۸۹ (Hanson Goodrich، ثبت اختراع آمریکا ۴۰۸٬۷۰۷).</li></ul>","kind":"note","src":[["Wikipedia — Drip coffee","https://en.wikipedia.org/wiki/Drip_coffee"],["Wikipedia — Percolator","https://en.wikipedia.org/wiki/Percolator"]]},{"id":80,"title":"نکات ارتقاء کیفیت برای هر دو نوع قهوه‌ساز قطره‌ای (صنعتی و خانگی)","body":"<h4 class=\"sub\">قهوه‌ساز قطره‌ای و پرکولاتور</h4><ul><li>قهوه‌ساز برقی: آب سرد از مخزن به محفظه‌ی گرمایش باریک (معمولاً آلومینیومی) می‌رود؛ با ترموسیفون از لوله‌ی عایق به سر اسپری می‌رسد و روی قهوه‌ی سبد پخش می‌شود و از فیلتر به کاراف می‌چکد؛ شیر یک‌طرفه برگشت آب را می‌گیرد، ترموستات المنت را قطع و وصل می‌کند و صفحه‌ی گرم‌نگه‌دار قهوه را گرم می‌دارد.</li><li>تاریخچه: Melitta Bentz ۱۹۰۸ (فیلتر کاغذی)؛ Willy Brand ۱۹۴۴ (قهوه‌ساز خودکار با فیلتر گرد)؛ Wigomat ۱۹۵۴ آلمان؛ اوایل ۱۹۷۰ برند Mr. Coffee؛ در دهه‌ی ۱۹۷۰ جای پرکولاتور را گرفتند.</li><li>پرکولاتور: بخار آب جوشان آب داغ را از لوله بالا می‌برد و روی قهوه‌ی درشت‌آسیاب‌شده می‌ریزد و دوباره به آب پایین می‌چکد؛ وقتی صدای «پرک‌پرک» به غرغر پیوسته تبدیل شد قهوه آماده است. جوشش مداوم بیش‌استخراج و تلخی می‌آورد. نخستین مدل مدرن ۱۸۱۹ (Laurens، پاریس)؛ ۱۸۸۹ (Hanson Goodrich، ثبت اختراع آمریکا ۴۰۸٬۷۰۷).</li></ul>","kind":"note","src":[["Wikipedia — Drip coffee","https://en.wikipedia.org/wiki/Drip_coffee"],["Wikipedia — Percolator","https://en.wikipedia.org/wiki/Percolator"]]},{"id":81,"title":"نکته تشخیص تفاوت این دو مدل","body":"<h4 class=\"sub\">قهوه‌ساز قطره‌ای و پرکولاتور</h4><ul><li>قهوه‌ساز برقی: آب سرد از مخزن به محفظه‌ی گرمایش باریک (معمولاً آلومینیومی) می‌رود؛ با ترموسیفون از لوله‌ی عایق به سر اسپری می‌رسد و روی قهوه‌ی سبد پخش می‌شود و از فیلتر به کاراف می‌چکد؛ شیر یک‌طرفه برگشت آب را می‌گیرد، ترموستات المنت را قطع و وصل می‌کند و صفحه‌ی گرم‌نگه‌دار قهوه را گرم می‌دارد.</li><li>تاریخچه: Melitta Bentz ۱۹۰۸ (فیلتر کاغذی)؛ Willy Brand ۱۹۴۴ (قهوه‌ساز خودکار با فیلتر گرد)؛ Wigomat ۱۹۵۴ آلمان؛ اوایل ۱۹۷۰ برند Mr. Coffee؛ در دهه‌ی ۱۹۷۰ جای پرکولاتور را گرفتند.</li><li>پرکولاتور: بخار آب جوشان آب داغ را از لوله بالا می‌برد و روی قهوه‌ی درشت‌آسیاب‌شده می‌ریزد و دوباره به آب پایین می‌چکد؛ وقتی صدای «پرک‌پرک» به غرغر پیوسته تبدیل شد قهوه آماده است. جوشش مداوم بیش‌استخراج و تلخی می‌آورد. نخستین مدل مدرن ۱۸۱۹ (Laurens، پاریس)؛ ۱۸۸۹ (Hanson Goodrich، ثبت اختراع آمریکا ۴۰۸٬۷۰۷).</li></ul>","kind":"note","src":[["Wikipedia — Drip coffee","https://en.wikipedia.org/wiki/Drip_coffee"],["Wikipedia — Percolator","https://en.wikipedia.org/wiki/Percolator"]]},{"id":82,"title":"سرو نهایی برای هر دو","body":"<h4 class=\"sub\">قهوه‌ساز قطره‌ای و پرکولاتور</h4><ul><li>قهوه‌ساز برقی: آب سرد از مخزن به محفظه‌ی گرمایش باریک (معمولاً آلومینیومی) می‌رود؛ با ترموسیفون از لوله‌ی عایق به سر اسپری می‌رسد و روی قهوه‌ی سبد پخش می‌شود و از فیلتر به کاراف می‌چکد؛ شیر یک‌طرفه برگشت آب را می‌گیرد، ترموستات المنت را قطع و وصل می‌کند و صفحه‌ی گرم‌نگه‌دار قهوه را گرم می‌دارد.</li><li>تاریخچه: Melitta Bentz ۱۹۰۸ (فیلتر کاغذی)؛ Willy Brand ۱۹۴۴ (قهوه‌ساز خودکار با فیلتر گرد)؛ Wigomat ۱۹۵۴ آلمان؛ اوایل ۱۹۷۰ برند Mr. Coffee؛ در دهه‌ی ۱۹۷۰ جای پرکولاتور را گرفتند.</li><li>پرکولاتور: بخار آب جوشان آب داغ را از لوله بالا می‌برد و روی قهوه‌ی درشت‌آسیاب‌شده می‌ریزد و دوباره به آب پایین می‌چکد؛ وقتی صدای «پرک‌پرک» به غرغر پیوسته تبدیل شد قهوه آماده است. جوشش مداوم بیش‌استخراج و تلخی می‌آورد. نخستین مدل مدرن ۱۸۱۹ (Laurens، پاریس)؛ ۱۸۸۹ (Hanson Goodrich، ثبت اختراع آمریکا ۴۰۸٬۷۰۷).</li></ul>","kind":"note","src":[["Wikipedia — Drip coffee","https://en.wikipedia.org/wiki/Drip_coffee"],["Wikipedia — Percolator","https://en.wikipedia.org/wiki/Percolator"]]},{"id":84,"title":"نوشیدنی‌های سرد و یخی (Cold & Iced Coffees)","body":"<h4 class=\"sub\">کلد برو</h4><ul><li>کلد برو (cold brew) خیساندن قهوه‌ی درشت‌آسیاب در آب خنک برای مدت طولانی است؛ «عصاره‌گیری سرد» هم نامیده می‌شود. زمان ۱۲ تا ۲۴ ساعت، معمولاً در دمای اتاق.</li><li>صاف‌کردن با فیلتر کاغذی، توری فلزی ریز (مثل فرنچ‌پرس) یا نمد؛ حاصل کنسانتره‌ای است که با آب یا شیر رقیق می‌شود و بیشتر سرد سرو می‌شود.</li><li>نوع قطره‌ای آهسته: «کیوتو‌استایل» و در شرق آسیا «Dutch coffee».</li><li>کلد برو نیتروژنی در اوایل دهه‌ی ۲۰۱۰ پدید آمد و استارباکس تابستان ۲۰۱۶ آن را در ۵۰۰ شعبه عرضه کرد.</li><li>کافئین: دم‌آوری سرد ۲۴ ساعته در هر حجم برابر، بیش از ۶ دقیقه در ۹۸ درجه کافئین دارد؛ اسیدیته‌ی pH مشابه دم گرم، اما اسید قابل‌تیتر کمتر.</li><li>آیس‌کافی: گاه با دم گرم روی یخ (قوی‌تر دم می‌شود چون یخ رقیق می‌کند)؛ ژاپنی: در دوره‌ی تایشو (حدود ۱۹۲۰) با شربت و شیر؛ فراپه‌ی یونانی با قهوه‌ی فوری شلاق‌خورده، پس از المپیک ۲۰۰۴ آتن مشهور شد؛ مازاگران الجزایر حدود ۱۸۴۰.</li></ul>","kind":"note","src":[["Wikipedia — Cold brew coffee","https://en.wikipedia.org/wiki/Cold_brew_coffee"],["Wikipedia — Iced coffee","https://en.wikipedia.org/wiki/Iced_coffee"]]},{"id":93,"title":"نکات طلایی برای کل دسته نوشیدنی‌های سرد","body":"<h4 class=\"sub\">نکات سرد</h4><ul><li>کنسانتره‌ی کلد برو در ظرف دربسته‌ی یخچالی تا حدود هشت هفته نگه‌داری می‌شود.</li><li>در آیس‌کافی ذوب یخ رقیق می‌کند؛ پس قهوه را قوی‌تر دم کنید یا با یخ مستقیم دم کنید (روش ژاپنی).</li></ul>","kind":"note","src":[["Wikipedia — Cold brew coffee","https://en.wikipedia.org/wiki/Cold_brew_coffee"],["Wikipedia — Iced coffee","https://en.wikipedia.org/wiki/Iced_coffee"],["Wikipedia — Coffee preparation","https://en.wikipedia.org/wiki/Coffee_preparation"]]},{"id":95,"title":"روش‌های سنتی، منطقه‌ای و تاریخی (Traditional, Regional & Historical)","body":"<h4 class=\"sub\">قهوه‌ی ترک</h4><ul><li>قهوه‌ی بسیار ریز آسیاب‌شده بی‌فیلتر با آب سرد (و شکر در صورت تمایل) در جذوه (cezve؛ ibrik) مسی با گردن باریک می‌جوشد؛ به محض کف‌کردن برداشته و دو بار دیگر به جوش می‌رسد. در فنجان‌های کوچک حدود ۹۰ میلی‌لیتری با لیوان آب سرو می‌شود.</li><li>آسیاب بسیار ریز (حدود ۷۵–۱۲۵ میکرون)؛ برشته‌ی متوسط تا متوسط‌تیره؛ آسیاب برقی خانگی مناسب نیست. هل گاهی اضافه می‌شود و تفاوت اصلی قهوه‌ی ارمنی است.</li><li>تاریخ: قهوه تا ۱۵۳۹ در استانبول رایج بود؛ نخستین قهوه‌خانه‌ی استانبول ۱۵۵۴ (یا ۱۵۵۱) باز شد؛ فرهنگ و سنت قهوه‌ی ترکی در فهرست میراث ناملموس یونسکو ثبت شده است.</li></ul><h4 class=\"sub\">قهوه‌ی عربی</h4><ul><li>از عربیکا با برشته‌ی روشن تا تیره و هل (گاه میخک یا زعفران) ساخته و بی‌فیلتر جوشانده می‌شود؛ معمولاً بدون شکر. عربستان سعودی برشته‌ی روشن (رنگ طلایی)، خلیج بسیار روشن با زعفران فراوان و شام تیره یا مخلوط.</li><li>در دلّه یا جذوه دم می‌شود؛ در فنجان‌های بی‌دسته‌ی فینجان تا نیمه پر می‌شود؛ میهمان معمولاً سه فنجان می‌پذیرد؛ میزبان (یا پسر ارشد) ساعتگرد می‌ریزد؛ با خرما یا شیرینی سرو می‌شود. یونسکو آن را میراث ناملموس کشورهای عربی تأیید کرده است.</li></ul><h4 class=\"sub\">قهوه‌ی ویتنامی</h4><ul><li>کافه‌ی سوآ دا: قهوه‌ی تیره‌ی روبوستا با فیلتر فلزی phin روی شیر تغلیظ‌شده‌ی شیرین چکانده و روی یخ ریخته می‌شود؛ احتمالاً در دوران استعمار فرانسه به‌جای کافه‌اولهٔ شیر تازه (که زود فاسد می‌شد) پدید آمد.</li></ul>","kind":"note","src":[["Wikipedia — Turkish coffee","https://en.wikipedia.org/wiki/Turkish_coffee"],["Wikipedia — Arabic coffee","https://en.wikipedia.org/wiki/Arabic_coffee"],["Wikipedia — Vietnamese iced coffee","https://en.wikipedia.org/wiki/Vietnamese_iced_coffee"]]},{"id":109,"title":"نکات طلایی برای کل دسته سنتی و منطقه‌ای","body":"<h4 class=\"sub\">نکات سنتی</h4><ul><li>قهوه‌ی ترکی: زمان‌بندی بحرانی است؛ کف ضخیم نشانه‌ی دم خوب است؛ ظرف تنگ‌گردن جذوه کف را شکل می‌دهد.</li><li>قهوه‌ی عربی: سه فنجان، ساعتگرد، فنجان تا نیمه؛ با خرما سرو می‌شود.</li><li>روبوستای تیره با شیر تغلیظ‌شده در ویتنام.</li></ul>","kind":"note","src":[["Wikipedia — Turkish coffee","https://en.wikipedia.org/wiki/Turkish_coffee"],["Wikipedia — Arabic coffee","https://en.wikipedia.org/wiki/Arabic_coffee"],["Wikipedia — Vietnamese iced coffee","https://en.wikipedia.org/wiki/Vietnamese_iced_coffee"]]},{"id":111,"title":"مدرن، عملکردی (Functional) و عجیب","body":"<h4 class=\"sub\">نوشیدنی‌های مدرن</h4><ul><li>دالگونا: قهوه‌ی فوری، شکر و آب داغ به نسبت مساوی تا کرم‌شدن شلاق می‌خورد و روی شیر سرد یا گرم ریخته می‌شود.</li><li>به مکائو نسبت داده شده: Leong Kam Hon در ۱۹۹۷ (کافه‌ای در کولوان) آن را ساخت؛ تا ۲۰۰۴ که Chow Yun-fat ستایشش کرد توجه کمی جلب کرد. در ۲۰۲۰ در دوران کرونا و با برنامه‌ی تلویزیونی کره (Jung Il-woo، ژانویه ۲۰۲۰) و بعد یوتیوب و تیک‌تاک (مارس ۲۰۲۰) فراگیر شد.</li><li>نام از «dalgona»، آب‌نبات عسلی کره‌ای؛ بیشتر دالگونا‌های قهوه واقعاً دالگونا ندارند.</li><li>ردآی: قهوه‌ی فیلتری با اضافه‌ی اسپرسو؛ دو شات «بلک‌آی» (در استارباکس).</li><li>اسپرسو مارتینی: ۵۰ میلی‌لیتر ودکا، ۳۰ میلی‌لیتر لیکور قهوه و یک اسپرسوی قوی (دستور IBA)؛ مبتکر معمولاً Dick Bradsell در لندن در دهه‌ی ۱۹۸۰ (Soho Brasserie، حدود ۱۹۸۳) دانسته می‌شود اما قطعی نیست.</li></ul>","kind":"note","src":[["Wikipedia — Dalgona coffee","https://en.wikipedia.org/wiki/Dalgona_coffee"],["Wikipedia — Espresso martini","https://en.wikipedia.org/wiki/Espresso_martini"],["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"]]},{"id":119,"title":"نکات طلایی برای نوشیدنی‌های مدرن و عملکردی","body":"<h4 class=\"sub\">نکات مدرن</h4><ul><li>دالگونا: قهوه‌ی فوری، شکر و آب داغ به نسبت مساوی تا کرم‌شدن شلاق می‌خورد و روی شیر سرد یا گرم ریخته می‌شود.</li><li>برای فرآیند به شکر و آب هم‌مقدار با قهوه‌ی فوری نیاز است.</li><li>دالگونا که «قهوه‌ی دست‌زده» هم نامیده می‌شود، از ماکائو آمده است. به گزارش‌ها، لئونگ کام هون آن را در ۱۹۹۷ برای زوجی گردشگر در کافه‌اش در کولوان درست کرد؛ خودش می‌گوید مبتکر آن نیست و زوجی خارجی که میان ۱۹۹۵ و ۱۹۹۷ هنگام گرندپری ماکائو مشتری ثابت کافه بودند، شیوه‌ی ساخت را به او آموختند.</li><li>نام «دالگونا» را در ژانویه‌ی ۲۰۲۰ بازیگر کره‌ای Jung Il-woo گذاشت، چون طعمش به دالگونا، شیرینی کره‌ای شبیه کاراملِ حفره‌دار، می‌مانَد.</li><li>با قهوه‌ی آسیاب‌شده نمی‌شود؛ فرآیند خشک‌کردن قهوه‌ی فوری است که کف غلیظ را ممکن می‌کند.</li><li>در مارس ۲۰۲۰ و در دوران فاصله‌گذاری اجتماعی، دالگونا در تیک‌تاک وایرال شد.</li><li>در ۲۰۰۴ بازیگر هنگ‌کنگی چاو یون‌فات هنگام فیلم‌برداری در کولوان این نوشیدنی را در همان کافه نوشید و آن را به دوستانش توصیه کرد.</li><li>نیترو کلد برو مثل آبجوی کشی از شیر (تپ) ریخته می‌شود؛ یک تولیدکننده‌ی آمریکایی آن را از ۲۰۱۵ با کگ یخچالی به کافه‌ها و رستوران‌ها عرضه می‌کرد و ۲۰۱۷ قهوه‌ی گرم کشی هم راه انداخت.</li></ul>","kind":"note","src":[["Wikipedia — Dalgona coffee","https://en.wikipedia.org/wiki/Dalgona_coffee"],["Macao News — Whipped to perfection: the story behind Hon Kee Cafe","https://macaonews.org/food-drink/whipped-to-perfection-the-story-behind-local-macao-institution-hon-kee-cafe/"],["Tea & Coffee Trade Journal — Cold brew and nitro coffee on tap for growth","https://www.teaandcoffee.net/feature/22248/cold-brew-and-nitro-coffee-on-tap-for-growth/"]]},{"id":178,"title":"روش‌های غیرمعمول و افراطی دم‌آوری (برای علاقه‌مندان به تجربه‌های نادر)","body":"<h4>قهوه با تخم‌مرغ</h4><ul><li><strong>قهوه‌ی تخم‌مرغ ویتنامی (cà phê trứng):</strong> از هانوی؛ کف زرده سفت و غنی می‌سازد و تلخی را نرم می‌کند. به روایت پسر بنیان‌گذار، دستور اواخر دهه‌ی ۱۹۴۰ که شیر کمیاب بود پدید آمد و زرده جایگزین شیر شد. گونه‌ها: کاکائو، لوبیا سفید و ماچا، سرد یا گرم.</li><li><strong>قهوه‌ی تخم‌مرغ «سوئدی»:</strong> علی‌رغم نام، نوشیدنی آمریکایی است؛ قهوه‌ی آسیاب‌شده با یک تخم‌مرغ مخلوط و مثل قهوه‌ی کابویی می‌جوشد. تخم‌مرغ ته‌نشینی تفاله را آسان می‌کند و قهوه‌ی نرم می‌دهد.</li><li>نمونه‌های دیگر: ایتالیایی uovo sbattuto con caffè، قهوه‌ی تخم‌مرغ و براندی سریلانکا، café a la criolla کوبایی (اسپرسو با زرده، شکر و رام سفید) و kopi telur اندونزیایی.</li></ul>","kind":"item","src":[["Wikipedia — Egg coffee","https://en.wikipedia.org/wiki/Egg_coffee"]]},{"id":184,"title":"نکات نهایی و ظریف (که در هیچکدام از بخش‌های قبلی نیامد)","body":"<h4 class=\"sub\">نکات دقیق‌تر</h4><ul><li>قهوه‌ی آسیاب‌شده به‌دلیل سطح تماس بیشتر با اکسیژن سریع‌تر از دانه کهنه می‌شود؛ پس بسیاری پیش از دم آسیاب می‌کنند. عمر بهینه‌ی قهوه‌ی آسیاب‌شده حدود ۱۵ دقیقه و دانه‌ی برشته حدود دو هفته ذکر شده است.</li><li>نسبت دم‌آوری به‌صورت جرم قهوه به حجم آب تعریف می‌شود؛ نسبت ۱۵ تا ۱۸ به ۱ از نظر جرم ترجیح داده می‌شود و تفاوت‌ها در این بازه «به‌راحتی» حس می‌شود. استانداردها حدود ۵۵ گرم در لیتر (آمریکایی) تا ۶۳ گرم در لیتر (نروژی)، یعنی ۱۴ تا ۱۶ گرم برای فنجان ۲۴۰ میلی‌لیتری.</li><li>اسپرسو حدود ۷ گرم قهوه برای شات ۲۵ میلی‌لیتر.</li><li>دمای آب اسپرسو ۹۱ تا ۹۵ درجه است؛ ترکیب معدنی متعادل آب از عوامل استخراج است.</li><li>اسپرسو با فشار ۸ تا ۱۸ بار از «پاک» عبور می‌کند؛ آسیاب بسیار ریز جریان را کند می‌کند.</li><li>برشته‌کاری: دانه‌ی برشته باید از گرما، اکسیژن و نور محافظت شود؛ سردکردن و انجماد کهنگی را کند می‌کند.</li></ul>","kind":"note","src":[["Wikipedia — Coffee preparation","https://en.wikipedia.org/wiki/Coffee_preparation"],["Wikipedia — Coffee roasting","https://en.wikipedia.org/wiki/Coffee_roasting"]]},{"id":189,"title":"چگونه اسیدیته‌ی فنجان را تنظیم کنیم؟","body":"<p>در منابع یافت‌شده بحث مستقیمی درباره‌ی «تنظیم اسیدیته‌ی فنجان» نبود؛ آنچه راستی‌آزمایی شد:</p><ul><li>در برشته‌کاری بیش از ۷۰٪ اسیدهای کلروژنیک تخریب می‌شود (کمتر از ۳۰ mg/g در دانه‌ی برشته می‌ماند).</li><li>کلد برو و دم‌آوری گرم pH مشابهی دارند، اما کلد برو اسید قابل‌تیتر کمتری دارد؛ هم pH و هم اسید قابل‌تیتر بر طعم اثر دارند.</li><li>قلیائیت آب با تنظیم‌کنندگی اسیدیته مرتبط است: استاندارد SCAA قلیائیت حدود ۴۰ mg/L را برای جلوگیری از تلخی یا تختی ناخواسته توصیه می‌کند.</li><li>طبق Hendon و همکاران (۲۰۱۴) یون‌های Mg و Ca و Na نرخ و ترکیب استخراج اسیدهای قهوه را تغییر می‌دهند.</li></ul>","kind":"item","src":[["Wikipedia — Coffee bean","https://en.wikipedia.org/wiki/Coffee_bean"],["Wikipedia — Cold brew coffee","https://en.wikipedia.org/wiki/Cold_brew_coffee"],["43factory — Dissecting SCAA water quality standard","https://43factory.coffee/en/news/dissecting-scaas-water-quality-standard/"],["Hendon et al. 2014 — The role of dissolved cations in coffee extraction","https://researchportal.bath.ac.uk/en/publications/the-role-of-dissolved-cations-in-coffee-extraction/"]]},{"id":190,"title":"روش ۴:۶ در V۶۰","body":"<p>روش ۴:۶ را تتسو کاسویا (قهرمان World Brewers Cup ۲۰۱۶) ابداع کرد: کل آب به ۴۰٪ و ۶۰٪ تقسیم می‌شود.</p><ul><li>۴۰٪ اول در دو ریختن، تعادل اسیدیته و شیرینی را تعیین می‌کند.</li><li>۶۰٪ باقی در چند ریختن، قدرت قهوه را مشخص می‌کند.</li><li>هر ریختن پس از آن شروع می‌شود که آب قبلی کامل چکیده باشد.</li></ul>\n<h4>نسخه‌ی متوسط (۲۰ گرم قهوه، ۳۰۰ گرم آب ۹۳ °C، نسبت ۱:۱۵، آسیاب متوسط-درشت)</h4><div class=\"table-wrap\"><table><thead><tr><th>ریختن</th><th>مقدار</th><th>نقش</th></tr></thead><tbody><tr><td>۱ (بلوم)</td><td>۶۰ گرم</td><td>۴۰٪ اول</td></tr><tr><td>۲</td><td>۶۰ گرم</td><td>۴۰٪ اول</td></tr><tr><td>۳</td><td>۹۰ گرم</td><td>۶۰٪ دوم</td></tr><tr><td>۴</td><td>۹۰ گرم</td><td>۶۰٪ دوم</td></tr></tbody></table></div><p>فاصله‌ی هر ریختن حدود ۳۰ ثانیه و زمان کل حدود ۳ دقیقه و ۲۵ ثانیه است.</p>\n<h4>تنظیم</h4><ul><li>۴۰٪ اول: ۴۰ و ۸۰ گرم ← شیرین‌تر و کم‌اسیدتر؛ ۶۰ و ۶۰ ← متعادل؛ ۸۰ و ۴۰ ← روشن‌تر و اسیدی‌تر.</li><li>۶۰٪ دوم: یک ریختن ۱۸۰ گرمی ← بدنه‌ی سبک‌تر و تمیزتر؛ دو ریختن ۹۰ گرمی ← قدرت متوسط؛ سه ریختن ۶۰ گرمی ← پربدنه‌تر و قوی‌تر.</li><li>اگر بستر زود خالی شد آسیاب را ریزتر و اگر کند شد درشت‌تر کنید.</li></ul><p>نسخه‌ی مسابقه‌ی خود کاسویا (۵۰/۷۰ و سه ریختن ۶۰ گرمی در ۹۲ °C) در مقاله‌ی «نمونه‌ی یک دستور ایده‌آل» آمده است.</p>","kind":"item","src":[["Honest Coffee Guide — Tetsu Kasuya 4:6 method","https://honestcoffeeguide.com/brew-recipes/tetsu-kasuya-4-6-method/"],["Kurasu — 2016 World Brewers Cup Champion: Tetsu Kasuya","https://kurasu.kyoto/blogs/kurasu-journal/2016-world-brewers-cup-champion-tetsu-kasuya"]]},{"id":193,"title":"تأثیر چربی شیر بر بافت کف (Microfoam) – با درصد دقیق","body":"<ul><li>شیر گاو در هر ۲۴۰ میلی‌لیتر حدود ۳٫۴ گرم پروتئین و ۳٫۹ گرم چربی دارد؛ حدود ۸۰٪ پروتئین کازئین و ۲۰٪ آب‌پنیر است.</li><li>هر دو پروتئین روی سطح گلبول‌های چربی می‌نشینند و حباب‌ها را پایدار می‌کنند؛ چربی برای میکروفوم نرم و پایدار اهمیت دارد و به طعم و دهان‌احساسی هم کمک می‌کند.</li><li>گلبول‌های چربی ۰٫۱ تا ۱۰ میکرومتر قطر دارند و در شیر هموژنیزه یکنواخت‌تر پخش‌اند.</li><li>شیر بدون چربی کف پایدارتر می‌دهد چون پروتئین‌ها حباب را کامل می‌پوشانند، اما برای لاته‌آرت «بیش‌ازحد سفت» می‌شود.</li><li>پروتئین شیر بادام و جو دوسر «به‌مراتب کمتر» از شیر گاو و پروتئین سویا مشابه آن است.</li><li>کارشناسان توصیه می‌کنند هوادهی کامل پیش از ۳۸ °C (۱۰۰ °F) انجام شود؛ بعد از آن شکستن حباب‌های درشت دشوارتر است.</li><li>کف از دو راه از بین می‌رود: تخلیه‌ی مایع با گرانش و Ostwald ripening (حباب‌های بزرگ حباب‌های کوچک را می‌بلعند).</li></ul>","kind":"item","src":[["Perfect Daily Grind — Why does milk foam disintegrate?","https://perfectdailygrind.com/2021/01/why-does-milk-foam-disintegrate/"]]},{"id":203,"title":"قهوه‌های عجیب و نادر (نمونه‌های تاریخی)","body":"<h4>کوپی لواک</h4><ul><li>قهوه‌ای از دانه‌هایی که سیوِت نخل آسیایی می‌خورد و بعد دفع می‌کند؛ تخمیر و آنزیم‌های دستگاه گوارش دانه را تغییر می‌دهد.</li><li>به‌طور سنتی فضولات از مزارع و جنگل جمع می‌شد؛ پرورش فشرده با قفس و تغذیه‌ی اجباری این روش را عمدتاً جایگزین کرده است.</li><li>قیمت خرده‌فروشی تا حدود ۱۰۰ دلار بر کیلوگرم برای دانه‌ی پرورشی و ۱۳۰۰ دلار برای دانه‌ی وحشی گزارش شده است.</li><li>رفاه حیوان: قفس‌های کوچک، انزوا، رژیم ضعیف و مرگ‌ومیر بالا؛ TRAFFIC شرایط را «مثل مرغ‌های قفسی» توصیف کرده است. بررسی PETA در ۲۰۱۳ نیز مشکلات مشابهی گزارش کرد. تقلب در برچسب «وحشی» گسترده است.</li><li>پژوهش Marcone (2004) نشان داد هضم پروتئین‌های ذخیره را به پپتیدهای کوتاه‌تر می‌شکند و پروفایل اسیدآمینه و عطر را تغییر می‌دهد؛ مطالعه‌ی ۲۰۲۵ در Scientific Reports چربی کل و استرهای متیل کاپریلیک و کاپریک بیشتری در روبوستای فرآوری‌شده با سیوِت یافت.</li><li>در کاپینگ حرفه‌ای امتیازش دو نقطه کمتر از پایین‌ترین قهوه‌ی مقایسه‌ای بود و SCAA از اجماع صنعت نوشت که «فقط بد مزه است».</li></ul>\n<h4>Black Ivory (فیل، تایلند)</h4><ul><li>عربیکایی که فیل می‌خورد و دانه‌ها از فضولات برداشته می‌شوند؛ مطالعه‌ی اخیری طعم و شیمی آن را به تخمیر میکروبی در روده‌ی فیل ربط می‌دهد.</li><li>مکان اول: بنیاد فیل آسیایی مثلث طلایی در چیانگ‌سن؛ بعد به استان سورین با ۲۰ فیل منتقل شد.</li><li>فیل‌ها گیلاس خام را کنار برنج و موز می‌خورند؛ دانه‌ها ۱۰ تا ۷۲ ساعت در دستگاه گوارش می‌مانند.</li><li>بنیان‌گذار: Blake Dinkin (کانادایی)؛ تولید ۲۰۱۲ با ۱۵۰ کیلوگرم آغاز شد.</li><li>۳۳ کیلوگرم گیلاس خام یک کیلوگرم محصول می‌دهد؛ قیمت: ۵۰ دلار برای هر فنجان در هتل‌های لوکس.</li></ul>","kind":"item","src":[["Wikipedia — Kopi Luwak","https://en.wikipedia.org/wiki/Kopi_Luwak"],["Wikipedia — Black Ivory coffee","https://en.wikipedia.org/wiki/Black_Ivory_coffee"]]},{"id":204,"title":"راز‌های یک «کِرِمای» (Crema) عالی در اسپرسو","body":"<ul><li>کرما لایه‌ای از کف متراکم با بافت کرمی روی اسپرسوست که هنگام انحلال بیشتر CO₂ در آب پرفشار پدید می‌آید.</li><li>«Caffè crema» را Gaggia در ۱۹۴۸ برای نامیدن همین کف به‌کار برد.</li><li>حجم استاندارد اسپرسو با کرما ۲۲٫۵ تا ۲۷٫۵ میلی‌لیتر است و فشار آب ورودی ۸ تا ۱۰ بار.</li><li>ماشین‌های اولیه‌ی اسپرسو (۱۹۰۰ تا ۱۹۳۰) فشار حدود ۱٫۵ بار داشتند و کرما نمی‌ساختند؛ نوشیدنی‌شان سیاه‌رنگ با طعم سوخته و تلخ بود.</li><li>ماشین پیستونی گاجیا فشار را تا ۱۲ اتمسفر رساند و کرما پدید آمد؛ فروش این ماشین‌ها از ۱۹۴۸ آغاز شد.</li><li>کرما فومی روشن روی بدنه‌ی تیره‌تر نوشیدنی است و فقط در اسپرسو دیده می‌شود؛ از روغن‌های قهوه ساخته می‌شود که به‌صورت کلوئید درآمده‌اند.</li><li>کرما به‌همراه مواد جامد محلول و معلق، اسپرسو را غلیظ می‌کند و گران‌روی آن را شبیه عسل گرم می‌سازد.</li></ul>","kind":"item","src":[["Wikipedia — Espresso","https://en.wikipedia.org/wiki/Espresso"],["Wikipedia — Crema (coffee)","https://en.wikipedia.org/wiki/Crema_(coffee)"],["Wikipedia — Caffè crema","https://en.wikipedia.org/wiki/Caff%C3%A8_crema"]]},{"id":205,"title":"روش «نیتروژن‌دهی خانگی» (بدون دستگاه حرفه‌ای)","body":"<ul><li>نیترو کلد برو کلد برو + نیتروژن است تا بافت نرم بدهد.</li><li>از سیستم شیر نیتروژنی مثل شیر آبجو سرو می‌شود، در اوایل دهه‌ی ۲۰۱۰ معرفی شد و سرد ولی بدون یخ عرضه می‌شود، چون یخ کف روی آن را خراب می‌کند.</li><li>کلد برو را ۱۲ تا ۲۴ ساعت با آسیاب درشت در آب با دمای محیط یا سرد خیسانده می‌کنند.</li><li>نیتروژن را با کپسول‌های فشرده‌ی اکسید نیتروس (N2O) و دستگاه خامه‌زن به قهوه اضافه می‌کنند.</li><li>حباب‌های نیتروژن از حباب‌های دی‌اکسید کربن کوچک‌ترند و حس دهانی نرم‌تری از نوشیدنی‌های گازدار می‌دهند.</li><li>در روش خانگی، قهوه را در دستگاه خامه‌زن می‌ریزند، یک کپسول شارژ می‌کنند و ۳۰ ثانیه تکان می‌دهند؛ سپس گاز را آزاد می‌کنند و در لیوان سرو می‌کنند.</li><li>نیترو کلد برو کمی شیرین‌تر از کلد برو معمولی است و روی آن کفی کرم‌رنگ شبیه آبجوی گینس می‌نشیند؛ کافه‌ها آن را از کگ سرو می‌کنند و نسخه‌ی قوطی هم دارد.</li></ul>","kind":"item","src":[["Wikipedia — Cold brew coffee","https://en.wikipedia.org/wiki/Cold_brew_coffee"],["MasterClass — What Is Nitro Cold Brew?","https://www.masterclass.com/articles/what-is-nitro-cold-brew"],["America's Test Kitchen — How to Make Nitro Cold Brew Coffee","https://www.americastestkitchen.com/how_tos/11550-how-to-make-nitro-cold-brew-coffee"]]},{"id":208,"title":"تکنیک «ریختن با ارتفاع زیاد» (در اسپرسو برای کاهش تلخی)","body":"<p>بنابراین ادعای کاهش تلخی با این تکنیک را تأیید نمی‌کنم و مقاله فقط راهنمای تأییدشده‌ی دما و استخراج را می‌آورد:</p><ul><li>آب «درست زیر جوش» (حدود ۹۶ °C) ترکیبات معطر را آزاد می‌کند و در نقطه‌ی جوش ترکیبات تلخ ظاهر می‌شوند.</li><li>دمای اسپرسو ۹۱ تا ۹۵ °C.</li><li>بازده استخراج ایده‌آل ۱۸ تا ۲۲٪؛ بیشتر از آن به استخراج بیش‌ازحد نزدیک می‌شود.</li><li>استاندارد ایتالیایی فشار ورودی آب اسپرسو را حدود ۹ بار (با رواداری ۱ بار) و زمان استخراج را ۲۵ ثانیه (با رواداری ۵ ثانیه) تعیین می‌کند.</li><li>دستگاه Faema E61 در سال ۱۹۶۱ آب را تا ۹ بار تحت فشار قرار داد و کار با پمپ برقی را رایج کرد.</li><li>دُز استاندارد ایتالیایی حدود ۷ گرم قهوه‌ی آسیاب‌شده برای هر شات است و حجم شات حدود ۲۵ میلی‌لیتر با احتساب کرما.</li><li>آسیاب اسپرسو بسیار ریز است و استخراج ۲۰ تا ۳۰ ثانیه طول می‌کشد؛ هرچه آسیاب ریزتر باشد استخراج سریع‌تر انجام می‌شود.</li></ul>","kind":"item","src":[["Wikipedia — Coffee preparation","https://en.wikipedia.org/wiki/Coffee_preparation"],["Wikipedia — Espresso","https://en.wikipedia.org/wiki/Espresso"],["Wikipedia — Coffee extraction","https://en.wikipedia.org/wiki/Coffee_extraction"]]},{"id":223,"title":"زمان‌های دقیق هر مرحله از تهیه قهوه (برای برنامه‌ریزی دقیق)","body":"<div class=\"table-wrap\"><table><thead><tr><th>مرحله</th><th>زمان</th><th>توضیح</th></tr></thead><tbody>\n<tr><td>خشک‌کردن گیلاس (طبیعی)</td><td>تا ۴ هفته</td><td>بسته به هوا؛ برای بقیه‌ی روش‌ها «شسته»: تخمیر موسیلاژ ۸ تا ۳۶ ساعت</td></tr>\n<tr><td>رسیدن گیلاس</td><td>حدود ۸ تا ۹ ماه پس از گل‌دهی</td><td>Coffea / Coffee processing</td></tr>\n<tr><td>ماندگاری بهینه‌ی قهوه‌ی برشته‌ی دانه‌ای</td><td>حدود ۲ هفته</td><td>Coffee roasting</td></tr>\n<tr><td>ماندگاری بهینه‌ی قهوه‌ی آسیاب‌شده</td><td>حدود ۱۵ دقیقه</td><td>Coffee roasting</td></tr>\n<tr><td>اسپرسو</td><td>۲۰ تا ۳۰ ثانیه (معمولاً ۲۵–۳۰)</td><td>مؤسسه‌ی ملی اسپرسوی ایتالیا</td></tr>\n<tr><td>فرنچ پرس</td><td>۴ تا ۷ دقیقه</td><td>Coffee preparation</td></tr>\n<tr><td>روش ۴:۶ (نسخه‌ی متوسط)</td><td>حدود ۳ دقیقه و ۲۵ ثانیه</td><td>Honest Coffee Guide</td></tr>\n<tr><td>روش ۴:۶ مسابقه‌ی ۲۰۱۶</td><td>دریپر در ۳:۳۰ برداشته می‌شود</td><td>Kurasu</td></tr>\n<tr><td>کلد برو</td><td>۱۲ تا ۲۴ ساعت</td><td>Cold brew coffee</td></tr>\n<tr><td>هوادهی کامل شیر</td><td>پیش از ۳۸ °C</td><td>Perfect Daily Grind</td></tr>\n</tbody></table></div><p>روی زمان برشته‌کاری مقاله‌ی «منحنی برشته‌کاری» را ببینید.</p>","kind":"item","src":[["Wikipedia — Coffee processing","https://en.wikipedia.org/wiki/Coffee_processing"],["Wikipedia — Coffee roasting","https://en.wikipedia.org/wiki/Coffee_roasting"],["Wikipedia — Espresso","https://en.wikipedia.org/wiki/Espresso"],["Wikipedia — Coffee preparation","https://en.wikipedia.org/wiki/Coffee_preparation"],["Wikipedia — Cold brew coffee","https://en.wikipedia.org/wiki/Cold_brew_coffee"],["Honest Coffee Guide — 4:6 method","https://honestcoffeeguide.com/brew-recipes/tetsu-kasuya-4-6-method/"],["Perfect Daily Grind — Why does milk foam disintegrate?","https://perfectdailygrind.com/2021/01/why-does-milk-foam-disintegrate/"]]},{"id":599,"title":"فیزیک آشفته‌سازی (Agitation) در دم‌آوری دستی","body":"<p>آشفته‌سازی (Agitation) یعنی هر حرکتی که آب و قهوه را در بستر دم‌آوری مخلوط می‌کند: هم‌زدن، ریختن آب از ارتفاع، تعداد ریختن‌ها و چرخاندن دریپر.</p><ul><li>در روش ۴:۶ کاسویا، شکل و تعداد ریختن‌ها (و فاصله تا زمان تخلیه‌ی کامل آب قبلی) ابزار اصلی تنظیم طعم است: دو ریختن اول تعادل اسیدیته و شیرینی را و ریختن‌های بعدی قدرت را تعیین می‌کنند.</li><li>بازده استخراج ایده‌آل ۱۸ تا ۲۲٪ است.</li><li>هرچه آب بیشتر در تماس با ذرات بماند و بیشتر مخلوط شود، به‌طور کلی استخراج بیشتر است؛</li></ul>","kind":"item","src":[["Kurasu — Tetsu Kasuya","https://kurasu.kyoto/blogs/kurasu-journal/2016-world-brewers-cup-champion-tetsu-kasuya"],["Wikipedia — Coffee preparation","https://en.wikipedia.org/wiki/Coffee_preparation"]]}]},{"id":"C5","icon":"equipment","title":"تجهیزات، نگهداری و لوازم قهوه","items":[{"id":121,"title":"تجهیزات برشته‌کاری (Roasting Equipment)","body":"<h4 class=\"sub\">حقایق</h4><ul><li>برشته‌کن‌ها دو خانواده‌ی اصلی دارند: دیگ دوار (drum) و بستر سیال با هوای داغ (fluid-bed).</li><li>در برشته‌کن‌های صنعتی دود و ترکیبات فرار را معمولاً با اکسیدکننده (oxidizer) تصفیه می‌کنند.</li><li>پس از برشته‌کاری باید دانه‌ها را سریع خنک کرد تا فرآیند متوقف شود.</li><li>در برشته‌کاری حدود ۱۵ تا ۱۸ درصد جرم دانه (بیشتر رطوبت) از دست می‌رود.</li><li>قهوه‌ی برشته‌شده را معمولاً تا حدود دو هفته تازه می‌دانند.</li></ul><p>(برای برشته کردن دانه‌های سبز)</p><p class=\"num-line\">۱. برشته‌کن صنعتی (Industrial Roaster) – دستگاه‌های بزرگ با دیگ دوار و مشعل گازی.</p><p class=\"num-line\">۲. برشته‌کن نیمه‌صنعتی (Sample Roaster) – برای مغازه‌ها و کافه‌ها (۱–۵ کیلوگرم).</p><p class=\"num-line\">۳. برشته‌کن خانگی (Home Roaster) – دستگاه‌های رومیزی (مانند FreshRoast، Behmor).</p><p class=\"num-line\">۴. تابه چدنی (Cast Iron Pan) – برای برشته‌کاری سنتی روی اجاق.</p><p class=\"num-line\">۵. تابه مسی یا استیل ضخیم – برای توزیع یکنواخت حرارت.</p><p class=\"num-line\">۶. منقل ذغال (Charcoal Brazier) – برای برشته‌کاری سنتی روی آتش.</p><p class=\"num-line\">۷. دماسنج مادون‌قرمز (Infrared Thermometer) – برای اندازه‌گیری دمای دانه‌ها در حین برشته‌کاری.</p><p class=\"num-line\">۸. دستگاه خنک‌کن سریع (Cooling Tray/Fan) – برای متوقف کردن سریع فرآیند برشته‌کاری.</p><p class=\"num-line\">۹. کیسه‌های یک‌طرفه (One-Way Valve Bags) – برای نگهداری قهوه برشته‌شده و خروج گاز CO₂ بدون ورود هوا.</p><p class=\"num-line\">۱۰. هاون و دسته‌سنگ (Mortar &amp; Pestle) – برای کوبیدن سنتی دانه‌ها (مخصوص قهوه قجری و اتیوپی).</p><h4 class=\"sub\">وسایل برشته‌کاری پیشرفته و سنتی:</h4><p class=\"num-line\">۱۲. برشته‌کن بادی (Fluid Bed Roaster) – با هوای داغ (مثل FreshRoast).</p><p class=\"num-line\">۱۳. صافی جداکننده پوست (Chaff Collector / Sieve) – برای جمع‌آوری پوستک‌های جدا شده در حین برشته‌کاری.</p>","kind":"item","src":[["Wikipedia — Coffee roasting","https://en.wikipedia.org/wiki/Coffee_roasting"]]},{"id":122,"title":"آسیاب‌ها (Grinders)","body":"<h4 class=\"sub\">حقایق</h4><ul><li>آسیاب قهوه دو نوع اصلی دارد: تیغه‌ای (blade) و سنگی/صفحه‌ای (burr)؛ هر دو دستی و برقی موجودند.</li><li>آسیاب‌های burr بر پایه‌ی فاصله‌ی دو سطح، اندازه‌ی ذرات را کنترل می‌کنند؛ آسیاب‌های تیغه‌ای ذرات ناهمگون‌تری تولید می‌کنند.</li><li>تنظیم آسیاب می‌تواند «پله‌ای» (stepped) یا «بی‌پله» (stepless) باشد.</li><li>آسیاب‌ها یا «دوزر» (doser) دارند یا «بدون دوزر» (doserless)؛ آسیاب‌های دستی ترکی هم دسته‌ی جداگانه‌ای هستند.</li></ul><p>(برای تبدیل دانه به پودر با درجه‌های مختلف)</p><h4>آسیاب‌های دستی (Manual):</h4><p class=\"num-line\">۱. آسیاب دستی مخروطی (Hand Burr Grinder) – با تیغه‌های مخروطی فولادی.</p><p class=\"num-line\">۲. آسیاب دستی تخت (Flat Burr Hand Grinder) – با دو صفحه‌ی تخت.</p><p class=\"num-line\">۳. آسیاب سنگی دستی (Stone Hand Mill) – برای پودر فوق‌ریز (مشابه آسیاب‌های سنتی ترکی).</p><h4>آسیاب‌های برقی (Electric):</h4><p class=\"num-line\">۴. آسیاب مخروطی برقی (Electric Burr Grinder) – با موتور و صفحات مخروطی.</p><p class=\"num-line\">۵. آسیاب تخت برقی (Flat Burr Electric) – با صفحات تخت.</p><p class=\"num-line\">۶. آسیاب صنعتی (Industrial Grinder) – برای کافه‌ها و کارخانه‌ها با موتور قدرتمند و صفحات بزرگ.</p><p class=\"num-line\">۷. آسیاب چاقویی (Blade Grinder) – معمولی و ارزان‌قیمت (برای پودر ناهموار، مناسب نبوده و کیفیت پایین دارد).</p><p class=\"num-line\">۸. آسیاب مخصوص اسپرسو (Espresso Grinder) – با دقت بالا و تنظیمات میکرومتریک.</p><p class=\"num-line\">۹. آسیاب مخصوص ترک (Turkish Mill) – با صفحات فوق‌ریز برای پودر تالک‌مانند.</p><h4>قطعات آسیاب:</h4><p class=\"num-line\">۱۰. صفحات آسیاب (Burrs) – مخروطی یا تخت (فولادی یا سرامیکی).</p><p class=\"num-line\">۱۱. مهره تنظیم درجه آسیاب (Adjustment Ring/Nut) – برای تغییر فاصله صفحات.</p><p class=\"num-line\">۱۲. قیف ورودی دانه (Hopper) – مخزن نگهداری دانه‌ها.</p><p class=\"num-line\">۱۳. محفظه جمع‌آوری پودر (Grounds Bin/Drawer) – ظرف زیر آسیاب.</p><p class=\"num-line\">۱۴. برس تمیزکننده (Grinder Brush) – برای تمیز کردن صفحات و محفظه.</p><p class=\"num-line\">۱۵. دمنده (Bellows) – برای دمیدن پودر‌های باقی‌مانده در آسیاب.</p>","kind":"item","src":[["Wikipedia — Coffee grinder","https://en.wikipedia.org/wiki/Coffee_grinder"]]},{"id":123,"title":"دستگاه‌های اسپرسوساز و قطعات آنها (Espresso Machines & Parts)","body":"<h4 class=\"sub\">حقایق</h4><ul><li>در اسپرسوسازهای اهرمی/فنری (lever) فشار حدود ۸ تا ۱۰ بار ایجاد می‌شود.</li><li>مدل Faema E61 در سال ۱۹۶۱ با پمپ و مبدل حرارتی (heat exchanger) معرفی شد و دستگاه‌های پمپی را رایج کرد.</li><li>انواع سیستم گرمایش: تک‌بویلر (SB)، تک‌بویلر دوکاره (SB-DU)، مبدل حرارتی (HX)، دوبویلر (DB) و ترموبلاک؛ La Marzocco GS در ۱۹۷۰ را نخستین دوبویلر معرفی کرده‌اند.</li><li>دستگاه‌های حرفه‌ای تا حدود هفت گروه (group head) دارند و اجزای اصلی شامل پورتافیلتر و نازل بخار هستند.</li></ul><h4>دستگاه‌های اسپرسوساز:</h4><p class=\"num-line\">۱. دستگاه اسپرسوساز خانگی (Home Espresso Machine) – با مخزن آب جدا و پمپ ویبره‌ای.</p><p class=\"num-line\">۲. دستگاه اسپرسوساز نیمه‌حرفه‌ای (Semi-Professional) – با پمپ دوار و بویلر بزرگتر.</p><p class=\"num-line\">۳. دستگاه اسپرسوساز حرفه‌ای (Commercial Espresso Machine) – با بویلر بزرگ (یک یا چندبویلری)، پمپ دوار و پایداری دمایی بالا.</p><p class=\"num-line\">۴. دستگاه اسپرسوساز دستی (Manual Lever Machine) – مانند La Pavoni – بدون پمپ، با اهرم دستی برای ایجاد فشار.</p><p class=\"num-line\">۵. دستگاه اسپرسوساز اتوماتیک (Super-Automatic) – یک‌دکمه‌ای با آسیاب داخلی.</p><h4>قطعات اسپرسوساز:</h4><p class=\"num-line\">۶. گروه (Group Head) – جایی که پورتافیلتر به آن متصل می‌شود.</p><p class=\"num-line\">۷. پورتافیلتر (Portafilter) – دسته‌دار با سبد.</p><p class=\"num-line\">۸. سبد پورتافیلتر (Basket) – قابل‌تعویض با سایز‌های مختلف – قطعه بسیار ریز و کلیدی.</p><p class=\"num-line\">۹. تمپر (Tamper) – برای فشرده کردن پودر قهوه در سبد (جنس آلومینیوم، فولاد یا چوب) با سایز ۵۸ یا ۵۱ میلی‌متر.</p><p class=\"num-line\">۱۰. تمپر کالیبره (Calibrated Tamper) – با فنر برای فشار ثابت.</p><p class=\"num-line\">۱۱. توزیع‌کننده (Distribution Tool / Leveler) – برای پخش یکنواخت پودر قبل از تمپ.</p><p class=\"num-line\">۱۲. WDT Tool (Weiss Distribution Technique) – سوزن‌های ظریف برای شکستن توده‌های پودر.</p><p class=\"num-line\">۱۳. نازل بخار (Steam Wand) – برای بافت‌دهی شیر.</p><p class=\"num-line\">۱۴. جت بخار (Steam Tip / Nozzle) – نازل کوچک با ۱ تا ۴ سوراخ – قطعه ریز.</p><p class=\"num-line\">۱۵. کفی‌ساز شیر (Milk Frother Attachment) – برای کف‌دهی بدون تکنیک دستی.</p><p class=\"num-line\">۱۶. فشارسنج (Pressure Gauge) – نشان‌دهنده فشار پمپ.</p><p class=\"num-line\">۱۷. دماسنج گروه (Group Thermometer) – برای دمای دقیق آب.</p><p class=\"num-line\">۱۸. کف‌پوش ضدحرارت (Portafilter Mat) – برای قرار دادن پورتافیلتر داغ.</p><p class=\"num-line\">۱۹. مخزن آب (Water Tank) – در دستگاه‌های خانگی.</p><p class=\"num-line\">۲۰. اتصال مستقیم به آب (Plumbed-in Line) – در دستگاه‌های حرفه‌ای متصل به لوله‌کشی.</p><p class=\"num-line\">۲۱. فیلتر آب داخلی (Internal Water Filter) – برای کاهش املاح.</p><p class=\"num-line\">۲۲. برس تمیزکننده گروه (Group Brush) – تمیز کردن سبد و گروه.</p><p class=\"num-line\">۲۳. پارچ شیر (Milk Pitcher / Frothing Pitcher).</p><p class=\"num-line\">۲۴. دماسنج پارچ (Pitcher Thermometer) – برای اندازه‌گیری دمای شیر.</p><h4 class=\"sub\">قطعات بسیار ریز و یدکی:</h4><p class=\"num-line\">۲۵. واشر سرامیکی (Ceramic Washer) – برای اتصالات آب.</p><p class=\"num-line\">۲۶. فنر شیر برگشتی (Return Spring) – در دستگاه اسپرسو و موکاپات.</p><p class=\"num-line\">۲۷. مهره پلاستیکی قفل‌کن (Plastic Lock Nut) – برای تنظیم صفحات آسیاب.</p><p class=\"num-line\">۲۸. پیچ میکرومتریک (Micrometric Screw) – برای تنظیم دقیق درجه آسیاب.</p><p class=\"num-line\">۲۹. درپوش ضدگرد (Dust Cap) – برای نازل بخار.</p><p class=\"num-line\">۳۰. حلقه آب‌بندی (O-Ring) – در انواع سایز‌ها – برای پورتافیلتر و سیفون.</p><p class=\"num-line\">۳۱. فیلتر سبدی یدکی (Spare Basket) – با سوراخ‌های ریزتر یا درشت‌تر.</p><p class=\"num-line\">۳۲. پیچ گوشتی مخصوص (Specialty Screwdriver) – برای باز کردن گروه اسپرسوساز.</p>","kind":"item","src":[["Wikipedia — Espresso machine","https://en.wikipedia.org/wiki/Espresso_machine"]]},{"id":124,"title":"تجهیزات دم‌آوری دستی (فیلتری، غوطه‌وری، تحت فشار)","body":"<h4 class=\"sub\">حقایق</h4><ul><li>فیلتر کاغذی قهوه را Melitta در ۱۹۰۸ ابداع کرد؛ Chemex در ۱۹۴۱ و Hario V60 در ۲۰۰۴ عرضه شدند. فیلترها کاغذی، پارچه‌ای یا فلزی‌اند.</li><li>فرنچ‌پرس: حدود ۳۰ گرم قهوه برای ۵۰۰ میلی‌لیتر، آب ۹۳–۹۶ درجه، آسیاب درشت و حدود ۴ دقیقه؛ ثبت اختراع‌های مرتبط در ۱۸۵۲، ۱۹۲۴، ۱۹۲۹ (مونتا و کالیمانی) و ۱۹۵۸ (بونداینی) ثبت شده و Bodum Chambord شناخته‌شده‌ترین مدل است.</li><li>ایروپرس را Alan Adler ساخت و در نوامبر ۲۰۰۵ معرفی شد؛ بسته‌ی استاندارد ۳۵۰ فیلتر دارد و دُز مسابقه‌ای حدود ۱۴–۲۰ گرم قهوه با ۲۰۰–۲۳۰ میلی‌لیتر آب ۸۰–۹۲ درجه است.</li><li>موکاپات Bialetti Moka Express از ۱۹۳۳؛ فشار ۱–۲ بار، نسبت حدود ۱ به ۱۰، دارای سوپاپ ایمنی و ساخته‌شده از آلومینیوم یا استیل.</li></ul><h4>الف – وسایل فیلتری (Pour-Over &amp; Drip):</h4><p class=\"num-line\">۱. دریپر V۶۰ (V۶۰ Dripper) – از جنس سرامیک، شیشه، پلاستیک یا مس.</p><p class=\"num-line\">۲. کمکس (Chemex) – کاراف شیشه‌ای با فیلتر مخصوص.</p><p class=\"num-line\">۳. دریپر کالیتا ویو (Kalita Wave Dripper) – تخت با ۳ سوراخ.</p><p class=\"num-line\">۴. دریپر ملیتا (Melitta Dripper) – مخروطی یا ذوزنقه‌ای با شیارهای عمودی و یک یا چند سوراخ.</p><p class=\"num-line\">۵. دریپر ساده (Generic Dripper) – پلاستیکی یا فلزی بدون مارک خاص.</p><p class=\"num-line\">۶. فیلتر کاغذی V۶۰ (V۶۰ Paper Filter) – سایز ۰۱، ۰۲، ۰۳.</p><p class=\"num-line\">۷. فیلتر کاغذی کمکس (Chemex Filter) – ضخیم و مثلثی.</p><p class=\"num-line\">۸. فیلتر کاغذی کالیتا (Wave Filter) – تخت و چین‌خورده.</p><p class=\"num-line\">۹. فیلتر پارچه‌ای (Cloth Filter) – قابل‌شستشو و استفاده مجدد (مخصوص کمکس و برزیلی).</p><p class=\"num-line\">۱۰. فیلتر فلزی (Metal Filter) – توری استیل ضدزنگ (بدون کاغذ، روغن‌ها عبور می‌کنند).</p><p class=\"num-line\">۱۱. کتری گردن‌غازی (Gooseneck Kettle) – با دهانه‌ی باریک خمیده برای کنترل جریان – جنس استیل یا مس.</p><p class=\"num-line\">۱۲. کتری معمولی (Regular Kettle) – برای ریختن آب معمولی (فقط برای روش‌های ساده).</p><p class=\"num-line\">۱۳. ترازوی دارای تایمر (Scale with Timer) – ترازوی دیجیتال با کرونومتر داخلی.</p><p class=\"num-line\">۱۴. ترازوی قهوه (Coffee Scale) – با دقت ۰.۱ گرم و قابلیت تار.</p><p class=\"num-line\">۱۵. هم‌زن چوبی یا پلاستیکی (Stirrer) – برای هم‌زدن بستر قهوه در بلوم.</p><p class=\"num-line\">۱۶. راک (Brew Stand) – پایه مخصوص برای قرار دادن دریپر روی فنجان.</p><h4>ب – وسایل غوطه‌وری (Immersion):</h4><p class=\"num-line\">۱۷. فرنچ پرس (French Press) – استوانه شیشه‌ای یا استیل با پیستون و توری فلزی.</p><p class=\"num-line\">۱۸. پیستون فرنچ پرس (Plunger Assembly) – شامل توری، فنر و دسته.</p><p class=\"num-line\">۱۹. ایروپرس (AeroPress) – استوانه پلاستیکی با پیستون و کاپ فیلتر.</p><p class=\"num-line\">۲۰. کاپ فیلتر ایروپرس (Filter Cap) – با سوراخ‌های ریز.</p><p class=\"num-line\">۲۱. قیف ایروپرس (AeroPress Funnel) – برای ریختن آسان پودر.</p><p class=\"num-line\">۲۲. هم‌زن ایروپرس (AeroPress Stirrer) – پلاستیکی یا چوبی.</p><p class=\"num-line\">۲۳. کلور دریپر (Clever Dripper) – ترکیب غوطه‌وری و فیلتراسیون با دریچه تخلیه.</p><p class=\"num-line\">۲۴. سیفون (Siphon / Vacuum Pot) – دو محفظه شیشه‌ای با لوله مرکزی و فیلتر پارچه‌ای.</p><p class=\"num-line\">۲۵. مشعل سیفون (Siphon Burner) – الکلی یا هالوژنی.</p><p class=\"num-line\">۲۶. فیلتر سیفون (Siphon Filter) – پارچه‌ای یا شیشه‌ای.</p><p class=\"num-line\">۲۷. پرکولاتور (Percolator) – قهوه‌جوش قدیمی با لوله مرکزی و سبد.</p><p class=\"num-line\">۲۸. قوری چای‌خوری (Teapot-style Brewer) – برای روش‌های سنتی.</p><h4>ج – وسایل تحت فشار غیرالکتریکی (Stovetop):</h4><p class=\"num-line\">۲۹. موکاپات (Moka Pot) – آلومینیومی یا استیل با سه بخش (مخزن پایین، سبد، محفظه بالا).</p><p class=\"num-line\">۳۰. قطعات موکاپات:</p><p>- مخزن آب (Boiler)</p><p>- سبد قهوه (Filter Basket)</p><p>- لوله مرکزی (Central Tube)</p><p>- واشر سیلیکونی (Silicone Gasket) – قطعه ریز</p><p>- فیلتر فلزی (Metal Filter Plate) – قطعه ریز</p><p class=\"num-line\">۳۱. جذوه (Cezeve / Ibrik) – ظرف کوچک مسی یا برنجی با دسته بلند (مخصوص قهوه ترکی و قجری).</p><p class=\"num-line\">۳۲. دله (Dallah) – قوری مسی یا برنجی عربی با دهانه‌ی باریک.</p><p class=\"num-line\">۳۳. جبنه (Jebena) – کتری سفالی اتیوپی.</p>","kind":"item","src":[["Wikipedia — Pour-over coffee","https://en.wikipedia.org/wiki/Pour-over_coffee"],["Wikipedia — French press","https://en.wikipedia.org/wiki/French_press"],["Wikipedia — AeroPress","https://en.wikipedia.org/wiki/AeroPress"],["Wikipedia — Moka pot","https://en.wikipedia.org/wiki/Moka_pot"]]},{"id":125,"title":"ظروف سرو و نوشیدنی (Serveware & Drinkware)","body":"<h4 class=\"sub\">حقایق</h4><ul><li>نسبت دم‌آوری استاندارد بر پایه‌ی جرم تعریف می‌شود: حدود ۵۵ گرم در لیتر (استاندارد آمریکایی) و ۶۳ گرم در لیتر (استاندارد نروژی)؛ یک فنجان ۲۴۰ میلی‌لیتری تقریباً ۱۴ تا ۱۶ گرم قهوه می‌خواهد.</li><li>اسپرسو: حدود ۷ گرم قهوه برای یک شات ۲۵ میلی‌لیتری با آب ۹۱ تا ۹۵ درجه.</li><li>قهوه‌ی دم‌شده‌ای که داغ نگه داشته شود سریع طعمش را از دست می‌دهد و گرم‌کردن دوباره آن طعمی «گل‌آلود» می‌دهد؛ برای همین قمقمه‌ی عایق (thermal carafe) و نگهداری بدون اکسیژن مفید است.</li></ul><p class=\"num-line\">۱. فنجان اسپرسو (Espresso Cup) – سرامیکی، با دیواره ضخیم.</p><p class=\"num-line\">۲. فنجان کاپوچینو (Cappuccino Cup) – پهن‌تر.</p><p class=\"num-line\">۳. لیوان لاته (Latte Glass) – شیشه‌ای یا سرامیکی بلند.</p><p class=\"num-line\">۴. لیوان آمریکانو (Americano Mug) – با دسته.</p><p class=\"num-line\">۵. لیوان ماکیاتو (Macchiato Glass) – شیشه‌ای کوچک.</p><p class=\"num-line\">۶. فنجان قهوه ترک (Turkish Coffee Cup) – با نعلبکی فلزی.</p><p class=\"num-line\">۷. فنجان قهوه قجری – مشابه ترک اما با نقوش میناکاری یا فلزکاری سنتی ایران.</p><p class=\"num-line\">۸. لیوان کلد برو / فراپه (Cold Brew Glass) – شیشه‌ای ضخیم با نی.</p><p class=\"num-line\">۹. لیوان قهوه ایرلندی (Irish Coffee Glass) – مقاوم به حرارت با دسته.</p><p class=\"num-line\">۱۰. فنجان قهوه عربی (فینجان) – کوچک و بدون دسته؛ ظرف دم‌آوری «دلّه» (Dallah) است.</p><p class=\"num-line\">۱۱. کاسه سیفون (Siphon Glass) – محفظه پایین سیفون.</p><p class=\"num-line\">۱۲. قمقمه / تراول‌پات (Thermal Carafe) – برای نگهداری قهوه داغ.</p><p class=\"num-line\">۱۳. نعلبکی (Saucer) – زیر فنجان.</p><p class=\"num-line\">۱۴. قاشق قهوه (Coffee Spoon) – کوچک (برای هم زدن).</p><p class=\"num-line\">۱۵. قاشق اندازه‌گیری (Measuring Spoon).</p><h4 class=\"sub\">وسایل سرو و نمایش:</h4><p class=\"num-line\">۱۶. کاردک تزیین (Latte Art Needle / Etching Tool) – برای نقاشی روی کف شیر.</p><p class=\"num-line\">۱۷. شابلون تزیین (Stencil) – برای پاشیدن پودر کاکائو یا دارچین به‌صورت طرحدار.</p><p class=\"num-line\">۱۸. کاور فنجان (Cup Sleeve / Koozie) – برای حفظ دما و جلوگیری از سوختن دست.</p><p class=\"num-line\">۱۹. جعبه حمل قهوه (Coffee Travel Case) – برای حمل چندین نمونه دانه.</p><p class=\"num-line\">۲۰. بطری اسپری آب (Misting Sprayer) – برای مرطوب‌سازی دانه‌ها قبل از آسیاب (RDT).</p><h4>هـ – تجهیزات نگهداری و کنترل محیط:</h4><p class=\"num-line\">۲۱. بسته‌های جاذب اکسیژن (Oxygen Absorbers) – برای بسته‌بندی طولانی‌مدت.</p><p class=\"num-line\">۲۲. دستگاه کنترل رطوبت (Humidifier / Dehumidifier) – برای انبار دانه.</p><p class=\"num-line\">۲۳. دماسنج/رطوبت‌سنج دیجیتال با لاگ‌گیری (Data Logger) – برای ثبت تغییرات محیط.</p>","kind":"item","src":[["Wikipedia — Coffee preparation","https://en.wikipedia.org/wiki/Coffee_preparation"]]},{"id":126,"title":"وسایل جانبی و کمکی (Accessories & Tools)","body":"<h4 class=\"sub\">حقایق</h4><ul><li>نسبت دم‌آوری ترجیحی ۱۵ تا ۱۸ به ۱ (آب به قهوه، بر پایه‌ی جرم) است؛ برای همین ترازوی دقیق مهم‌ترین ابزار جانبی است.</li><li>هاون و دسته‌سنگ می‌تواند قهوه را برای روش‌های عربی و یونانی به‌اندازه‌ی کافی ریز کند.</li><li>اسیدها (مثل سیتریک و استیک) رسوب کربنات کلسیم و منیزیم را حل می‌کنند؛ جرم‌گیرها معمولاً بر همین پایه‌اند.</li></ul><p class=\"num-line\">۱. دستگاه توزین (Scale) – با دقت ۰.۱ گرم و قابلیت تار.</p><p class=\"num-line\">۲. تایمر (Timer) – دیجیتال یا کرونومتر داخلی در ترازو.</p><p class=\"num-line\">۳. دستگاه دم‌آوری خودکار (Auto Drip Brewer) – با قابلمه شیشه‌ای یا قمقمه‌ای.</p><p class=\"num-line\">۴. صافی مشبک (Sieve / Sifter) – برای جدا کردن پودر‌های خیلی ریز (فینز).</p><p class=\"num-line\">۵. اسپری رطوبت‌دهنده (Spray Bottle) – برای کاهش الکتریسیته ساکن دانه‌ها پیش از آسیاب (RDT – Ross Droplet Technique).</p><p class=\"num-line\">۶. ابزار WDT (Needle Tool) – سوزن‌های ظریف برای شکستن توده‌های پودر – قطعه بسیار ریز.</p><p class=\"num-line\">۷. قیف دُز (Dosing Funnel) – برای ریختن پودر در پورتافیلتر بدون ریزش.</p><p class=\"num-line\">۸. ناک‌باکس (Knock Box) – ظرف تخلیه‌ی تفاله با میله‌ی ضربه.</p><p class=\"num-line\">۹. برس تمیزکننده عمومی (Cleaning Brush) – برای تمیز کردن آسیاب، گروه، میزکار.</p><p class=\"num-line\">۱۰. قرص پاک‌کننده (Cafiza Tablets / Cleaning Tablets) – برای شستشوی عمیق دستگاه اسپرسو و گروه.</p><p class=\"num-line\">۱۱. مایع پاک‌کننده (Descaler Solution) – برای جرم‌گیری از بویلر و لوله‌ها.</p><p class=\"num-line\">۱۲. پورتافیلتر بدون ته (Bottomless / Naked Portafilter) – برای دیدن مستقیم جریان عصاره و تشخیص کانال‌شدن.</p><p class=\"num-line\">۱۳. پارچ توزیع (Dosing Cup) – ظرف کوچک برای وزن کردن و انتقال پودر به پورتافیلتر.</p><p class=\"num-line\">۱۴. قیف ریختن (Funnel) – برای ریختن دانه در قیف آسیاب.</p><p class=\"num-line\">۱۵. دستگاه خامه‌زن (Cream Whipper) – برای تهیه خامه فرم‌گرفته برای اسپرسو کن پانا.</p><p class=\"num-line\">۱۶. همزن برقی (Hand Mixer / Frother) – برای کف‌دهی شیر سرد (دالگونا، فراپه).</p><p class=\"num-line\">۱۷. شیکر کوکتل (Cocktail Shaker) – برای شیکراتو و فراپه یونانی.</p><p class=\"num-line\">۱۸. بلندر (Blender) – برای فراپوچینو و بولت‌پروف.</p><p class=\"num-line\">۱۹. یخ‌ساز (Ice Maker / Ice Tray) – برای تولید یخ کیوبی درشت و شفاف.</p><p class=\"num-line\">۲۰. نوار تست آب (Water Hardness Test Strip) – برای اندازه‌گیری سختی آب.</p><p class=\"num-line\">۲۱. فیلتر تصفیه آب (Water Filter Pitcher – مانند بریتا) – برای کاهش کلر و املاح.</p><p class=\"num-line\">۲۲. کیسه فیلتر پارچه‌ای (Nut Milk Bag / Coffee Sock) – برای صاف‌کردن کلد برو.</p>","kind":"item","src":[["Wikipedia — Coffee preparation","https://en.wikipedia.org/wiki/Coffee_preparation"],["Wikipedia — Descaling agent","https://en.wikipedia.org/wiki/Descaling_agent"]]},{"id":127,"title":"مواد اولیه و مصرفی (Consumables & Ingredients)","body":"<h4 class=\"sub\">حقایق</h4><ul><li>قهوه‌ی سبز در محیط کنترل‌شده ۱۲ تا ۱۸ ماه بدون افت محسوس کیفیت می‌ماند و از قهوه‌ی برشته‌شده پایدارتر است.</li><li>کنسانتره‌ی کلد برو در ظرف دربسته‌ی یخچالی تا حدود هشت هفته نگه‌داری می‌شود.</li></ul><p class=\"num-line\">۱. دانه قهوه سبز (Green Coffee Beans) – انواع عربیکا، روبوستا، لیبریکا.</p><p class=\"num-line\">۲. دانه قهوه برشته‌شده (Roasted Beans) – با درجات روشن، متوسط، تیره.</p><p class=\"num-line\">۳. قهوه فوری (Instant Coffee) – پودر یا گرانول.</p><p class=\"num-line\">۴. شیر کامل (Whole Milk) – با ۳.۵٪ چربی.</p><p class=\"num-line\">۵. شیر کم‌چرب (Skimmed Milk) – برای بافت‌دهی سبک‌تر.</p><p class=\"num-line\">۶. شیر‌های گیاهی: شیر سویا، بادام، جو دوسر، نارگیل، برنج، ماکادمیا.</p><p class=\"num-line\">۷. خامه (Heavy Cream / Whipping Cream) – برای اسپرسو کن پانا و قهوه ایرلندی.</p><p class=\"num-line\">۸. شیر تغلیظ‌شده شیرین (Condensed Milk) – برای بومبون، ویتنامی و کورتادیتو.</p><p class=\"num-line\">۹. شیر نیم‌نیم (Half &amp; Half) – برای کافه بروه.</p><p class=\"num-line\">۱۰. شکر سفید (White Sugar) – دانه‌ریز.</p><p class=\"num-line\">۱۱. شکر قهوه‌ای (Brown Sugar) – برای قهوه ایرلندی و برزیلی.</p><p class=\"num-line\">۱۲. نبات (Rock Candy) – برای قهوه قجری.</p><p class=\"num-line\">۱۳. ساکارز مایع / شربت ساده (Simple Syrup) – برای شیکراتو و نوشیدنی‌های سرد.</p><p class=\"num-line\">۱۴. شربت‌های طعم‌دهنده: وانیل، کارامل، فندق، شکلات، ادویه کدو، زنجبیل.</p><p class=\"num-line\">۱۵. عسل (Honey) – به‌جای شکر.</p><p class=\"num-line\">۱۶. شکلات تلخ (Dark Chocolate) – برای موکا و تزیین.</p><p class=\"num-line\">۱۷. پودر کاکائو (Cocoa Powder) – برای تزیین کاپوچینو، موکا، ماروکینو.</p><p class=\"num-line\">۱۸. هل (Cardamom) – کامل یا پودر – برای قهوه ترکی، عربی، قجری.</p><p class=\"num-line\">۱۹. زعفران (Saffron) – برای قهوه قجری و عربی.</p><p class=\"num-line\">۲۰. دارچین (Cinnamon) – چوب یا پودر.</p><p class=\"num-line\">۲۱. میخک (Clove) – برای قهوه برزیلی و مغربی.</p><p class=\"num-line\">۲۲. زنجبیل (Ginger) – پودر یا تازه – برای قهوه مغربی.</p><p class=\"num-line\">۲۳. فلفل سیاه (Black Pepper) – برای قهوه ادویه‌دار مغربی.</p><p class=\"num-line\">۲۴. کندر (Frankincense) – برای مراسم اتیوپی (بخور).</p><p class=\"num-line\">۲۵. ویسکی / براندی / گراپا / لیمونچلو – برای کافه کورتو و ایرلندی.</p><p class=\"num-line\">۲۶. تخم‌مرغ (Egg Yolk) – برای قهوه ویتنامی.</p><p class=\"num-line\">۲۷. پنیر لیپایوستو (Leipäjuusto) – پنیر فنلاندی برای کافه‌اوست.</p><p class=\"num-line\">۲۸. کره حیوانی بدون نمک (Unsalted Grass-fed Butter) – برای بولت‌پروف.</p><p class=\"num-line\">۲۹. روغن MCT (MCT Oil) – برای بولت‌پروف.</p><p class=\"num-line\">۳۰. خامه قنادی (Whipped Cream Canister) – برای تزیین فراپوچینو.</p>","kind":"item","src":[["Wikipedia — Coffee roasting","https://en.wikipedia.org/wiki/Coffee_roasting"],["Wikipedia — Coffee preparation","https://en.wikipedia.org/wiki/Coffee_preparation"]]},{"id":128,"title":"ابزار اندازه‌گیری و کنترل کیفیت (Measuring & QC Tools)","body":"<h4 class=\"sub\">حقایق</h4><ul><li>نسبت دم‌آوری بر پایه‌ی جرم، ۱۵ تا ۱۸ به ۱ است؛ ابزارهای اندازه‌گیری مثل ترازو و دماسنج پایه‌ی کنترل کیفیت‌اند.</li><li>آب اسپرسو معمولاً ۹۱ تا ۹۵ درجه و روغن‌های معطر نزدیک ۹۶ درجه آزاد می‌شوند.</li><li>در برشته‌کاری حدود ۱۵ تا ۱۸ درصد جرم دانه کاسته می‌شود؛ وزن‌کردن پیش و پس از برشته‌کاری راهی ساده برای کنترل درجه‌ی برشته‌کاری است.</li></ul><p class=\"num-line\">۱. رفرکتومتر (Refractometer) – برای اندازه‌گیری TDS (جامدات محلول) نوشیدنی – ابزار حرفه‌ای.</p><p class=\"num-line\">۲. PH متر (pH Meter) – برای اندازه‌گیری اسیدیته آب و عصاره.</p><p class=\"num-line\">۳. TDS متر آب (TDS Meter) – برای اندازه‌گیری املاح محلول آب (سختی را مستقیم نشان نمی‌دهد).</p><p class=\"num-line\">۴. میکروسکوپ (Microscope) – برای بررسی ذرات آسیاب (اندازه، شکل).</p><p class=\"num-line\">۵. طیف‌سنج (Spectrophotometer) – برای آنالیز ترکیبات شیمیایی.</p><p class=\"num-line\">۶. دستگاه رنگ‌سنج (Agtron Color Meter) – برای تعیین دقیق درجه برشته‌کاری.</p><p class=\"num-line\">۷. کارت رنگ Agtron (Agtron Color Card) – جایگزین دستگاه برای مقایسه بصری.</p><h4 class=\"sub\">ابزار‌های دقیق اندازه‌گیری (فراتر از ترازو و دماسنج):</h4><p class=\"num-line\">۸. دستگاه سنجش فعالیت آبی (Water Activity Meter) – برای اندازه‌گیری رطوبت فعال دانه‌ها.</p><p class=\"num-line\">۹. دستگاه سنجش دانسیته (Density Meter) – برای وزن مخصوص دانه‌ها.</p><p class=\"num-line\">۱۰. دستگاه سنجش اندازه ذرات (Laser Diffraction Particle Size Analyzer) – برای آنالیز توزیع اندازه پودر آسیاب – بسیار پیشرفته.</p><p class=\"num-line\">۱۱. دستگاه سنجش رنگ دیجیتال (Digital Colorimeter) – دقیق‌تر از Agtron.</p><p class=\"num-line\">۱۲. دستگاه سنجش اسیدیته عصاره (Titratable Acidity Kit) – برای اندازه‌گیری اسیدیته قابل‌تیتر.</p><p class=\"num-line\">۱۳. دستگاه سنجش قند (Refractometer Brix) – برای اندازه‌گیری درجه بریکس میوه قهوه در مزرعه.</p>","kind":"item","src":[["Wikipedia — Coffee preparation","https://en.wikipedia.org/wiki/Coffee_preparation"],["Wikipedia — Coffee roasting","https://en.wikipedia.org/wiki/Coffee_roasting"]]},{"id":129,"title":"تجهیزات نگهداری و بسته‌بندی (Storage & Packaging)","body":"<h4 class=\"sub\">حقایق</h4><ul><li>عمر قهوه‌ی برشته‌ی کامل بهینه حدود دو هفته است؛ قهوه‌ی آسیاب‌شده باید بلافاصله پس از آسیاب مصرف شود (حدود ۱۵ دقیقه).</li><li>قهوه پس از برشته‌کاری CO₂ آزاد می‌کند؛ برای همین بسته‌بندی خلأ باید چند روز پس از تخلیه‌ی گاز انجام شود و کیسه‌ی فویل‌دار شیر تخلیه‌ی فشار دارد.</li><li>سردکردن و انجماد روند کهنگی را کند می‌کنند؛ بسته‌بندی خلأ هم اکسیداسیون را آهسته می‌کند.</li></ul><p class=\"num-line\">۱. ظرف نگهداری دانه (Coffee Canister) – درب‌دار با واشر سیلیکونی و دریچه یک‌طرفه.</p><p class=\"num-line\">۲. کیسه زیپ‌دار (Ziplock Bag) – با دریچه یک‌طرفه.</p><p class=\"num-line\">۳. بسته‌بند خلأ (Vacuum Sealer) – برای بسته‌بندی بدون هوا.</p><p class=\"num-line\">۴. دستگاه بسته‌بندی حرارتی (Heat Sealer) – برای کیسه‌های یک‌طرفه.</p><p class=\"num-line\">۵. انبار قهوه (Coffee Cellar) – رک یا قفسه با ظروف کوچک برای دوزبندی روزانه.</p><p class=\"num-line\">۶. برچسب‌گذاری (Labeling Tags) – برای تاریخ و نوع قهوه.</p><p class=\"num-line\">۷. دماسنج محیط (Room Thermometer/Hygrometer) – برای کنترل دما و رطوبت محیط نگهداری.</p>","kind":"item","src":[["Wikipedia — Coffee roasting","https://en.wikipedia.org/wiki/Coffee_roasting"],["Wikipedia — Coffee preparation","https://en.wikipedia.org/wiki/Coffee_preparation"]]},{"id":130,"title":"لوازم نظافت و تعمیرات (Cleaning & Maintenance)","body":"<h4 class=\"sub\">حقایق</h4><ul><li>جرم‌گیرها اغلب اسیدند (استیک، سیتریک، گلیکولیک، فرمیک، لاکتیک، فسفریک، سولفامیک، هیدروکلریک)؛ اسیدهای ضعیف مثل سیتریک و استیک وقتی لازم است سطح آسیب نبیند ترجیح داده می‌شوند.</li><li>اسیدهای قوی می‌توانند پوست و چشم را بسوزانند؛ دستکش لاستیکی لازم است.</li><li>جرم‌گیری می‌تواند برنج را فرسوده کند (dezincification) و سرب را به لوله‌های آب آشامیدنی آزاد کند؛ دفترچه‌ی سازنده را دنبال کنید.</li></ul><p class=\"num-line\">۱. مایع جرم‌گیر مخصوص اسپرسوساز (Descaler) – برای حذف رسوبات کلسیم.</p><p class=\"num-line\">۲. پودر پاک‌کننده گروه (Group Head Cleaner / Cafiza) – پودر یا قرص.</p><p class=\"num-line\">۳. برس سیمی (Wire Brush) – برای تمیز کردن توری‌ها و فیلتر‌ها.</p><p class=\"num-line\">۴. سوزن تمیزکننده (Needle / Poker) – برای باز کردن سوراخ‌های مسدودشده نازل بخار – قطعه بسیار ریز.</p><p class=\"num-line\">۵. پارچه میکروفیبر (Microfiber Cloth) – برای خشک‌کردن قطعات.</p><p class=\"num-line\">۶. دستمال کتان (Linen Towel) – برای تمیز کردن ورق‌های فیلتر.</p><p class=\"num-line\">۷. آچار مخصوص (Special Wrench) – برای باز و بسته کردن صفحات آسیاب و هدگسکت.</p><p class=\"num-line\">۸. روغن مخصوص قطعات (Food-grade Grease) – برای روانکاری واشر‌ها و قطعات متحرک.</p><p class=\"num-line\">۹. مهره و پیچ‌های یدکی (Spare Screws &amp; Gaskets) – برای تعویض واشر‌ها و اتصالات.</p><p class=\"num-line\">۱۰. برس ریز نرم (Small Detail Brush) – برای تمیز کردن نقاط بسیار ریز (مانند سبد پورتافیلتر و نازل).</p>","kind":"item","src":[["Wikipedia — Descaling agent","https://en.wikipedia.org/wiki/Descaling_agent"]]},{"id":165,"title":"دستورالعمل‌های ایمنی و نگهداری طولانی‌مدت","body":"<p>زمان‌بندی دقیق پاک‌سازی را از دفترچه‌ی سازنده‌ی دستگاه بگیرید.</p><h4 class=\"sub\">رسوب و جرم‌گیری دستگاه</h4><ul><li>رسوب آهک عمدتاً کربنات کلسیم و منیزیم است و روی سطوح فلزی در تماس با آب داغ (بویلر، کتری) تشکیل می‌شود.</li><li>جرم‌گیرها معمولاً اسیدند؛ با کربنات‌ها واکنش می‌دهند، CO₂ آزاد می‌شود و نمک‌های محلول با آب شسته می‌شوند.</li><li>بویلر بخار اسپرسوساز کاملاً پر نمی‌شود، پس جرم‌گیر به بالای آن نمی‌رسد و شیرهای ایمنی و حسگرها ممکن است رسوب‌گرفته بمانند.</li><li>اسیدهای ضعیف (سیتریک، استیک) برای حفاظت از قطعه ترجیح داده می‌شوند؛ اسیدهای قوی سریع‌ترند اما خورنده‌اند.</li><li>هنگام جرم‌گیری دستکش بپوشید؛ اسید می‌تواند برنج را فرسوده کند و سرب به خط آب آشامیدنی بدهد.</li></ul><h4 class=\"sub\">نگهداری دانه</h4><ul><li>سه دشمن قهوه‌ی برشته: گرما، اکسیژن و نور.</li><li>دانه‌ی برشته‌ی کامل حدود دو هفته در اوج است و در شرایط خنک ممکن است تا حدود یک ماه بماند؛ قهوه‌ی آسیاب‌شده بسیار سریع‌تر کهنه می‌شود.</li><li>دانه‌ی سبز در محیط کنترل‌شده ۱۲ تا ۱۸ ماه پایدار می‌ماند.</li><li>برای کیسه‌ی تازه‌برشته، شیر تخلیه‌ی فشار CO₂ را خارج و از ورود هوا جلوگیری می‌کند.</li></ul>","kind":"item","src":[["Wikipedia — Descaling agent","https://en.wikipedia.org/wiki/Descaling_agent"],["Wikipedia — Coffee roasting","https://en.wikipedia.org/wiki/Coffee_roasting"],["Wikipedia — Coffee preparation","https://en.wikipedia.org/wiki/Coffee_preparation"]]},{"id":196,"title":"نگهداری از قهوه در سفر (زمانی که دستگاه و آسیاب در دسترس نیست)","body":"<h4 class=\"sub\">اصول</h4><ul><li>قهوه‌ی آسیاب‌شده خیلی سریع‌تر از دانه کهنه می‌شود (سطح تماس بیشتر با اکسیژن)؛ اگر آسیاب دستی همراه دارید، دانه را همراه ببرید و پیش از دم‌آوری آسیاب کنید.</li><li>هاون و دسته‌سنگ هم می‌تواند قهوه را به‌اندازه‌ی کافی ریز کند (مثلاً برای قهوه‌ی عربی و یونانی).</li><li>قهوه‌ی دم‌شده را داغ نگه ندارید؛ گرم‌کردن دوباره طعم «گل‌آلود» می‌دهد.</li><li>ایروپرس (Alan Adler، ۲۰۰۵) سبک و قابل‌حمل است و با آب ۸۰ تا ۹۲ درجه دم می‌شود.</li><li>کنسانتره‌ی کلد برو در ظرف دربسته تا حدود هشت هفته در یخچال می‌ماند.</li></ul>","kind":"item","src":[["Wikipedia — Coffee preparation","https://en.wikipedia.org/wiki/Coffee_preparation"],["Wikipedia — AeroPress","https://en.wikipedia.org/wiki/AeroPress"]]},{"id":217,"title":"«نور» و تأثیر آن بر تازگی دانه‌ها (هشدار برای فروشندگان)","body":"<p>نور، گرما و اکسیژن سه عامل شناخته‌شده‌ی کهنگی قهوه‌ی برشته‌اند.</p><h4 class=\"sub\">حقایق</h4><ul><li>قهوه‌ی برشته‌ی کامل را در ظرف دربسته و دور از نور نگه دارند؛ بهترین جنس ظرف سرامیک یا شیشه‌ی مات است و پلاستیک و فلز ممکن است طعم را تغییر بدهند.</li><li>در شرایط یادشده، دانه‌ی برشته‌ی کامل حدود دو هفته می‌ماند؛ در هفته‌ی نخست ظرف باید باز یا تخلیه شود تا CO₂ خارج شود. قهوه‌ی آسیاب‌شده در چند روز کهنه می‌شود.</li><li>پرتو فرابنفش و نور مرئی با طول‌موج کوتاه انرژی لازم برای شکستن پیوندهای چربی‌های سیرنشده و رنگدانه‌ها را فراهم می‌کند و بدون گرما رادیکال آزاد می‌سازد.</li><li>اکسیژن «دشمن اصلی» قهوه‌ی برشته شمرده می‌شود؛ کاهش اکسیژن ظرف به ۰٫۵٪ می‌تواند ماندگاری را حدود ۲۰ برابر کند.</li><li>قهوه‌ی بسته‌بندی‌شده‌ی خلأ در یک پژوهش پنج برابر کندتر از قهوه‌ی بسته‌بندی‌شده با هوا کهنه شد.</li><li>قهوه‌ی پرشده با نیتروژن شش ماه ماندگاری حسی داشت، در برابر سه ماه برای قهوه‌ی بدون نیتروژن.</li><li>کیسه‌ی دارای شیر یک‌طرفه‌ی تخلیه (بدون نشتی) اکسیژن ۰٪ و CO₂ بالای ۴۰٪ را نگه داشت؛ نیمی از شش کیسه‌ی آزمایش‌شده نشتی داشت.</li></ul>","kind":"item","src":[["SCA — What is the shelf life of roasted coffee? A literature review on coffee staling","https://sca.coffee/sca-news/2012/02/15/what-is-the-shelf-life-of-roasted-coffee-a-literature-review-on-coffee-staling"],["Wikipedia — Coffee bean storage","https://en.wikipedia.org/wiki/Coffee_bean_storage"],["Open Exam Prep — Roasted coffee shelf life, degassing and freshness","https://open-exam-prep.com/study-guides/sca-q-grader/storage-packaging-knowledge-review/roasted-coffee-shelf-life"],["Wikipedia — Coffee roasting","https://en.wikipedia.org/wiki/Coffee_roasting"]]},{"id":229,"title":"تمیز کردن و نگهداری از تجهیزات – نکات ریز و حیاتی","body":"<p>جرم‌گیری و تمیزکاری:</p><h4 class=\"sub\">نکات</h4><ul><li>رسوب بویلر عمدتاً کربنات کلسیم و منیزیم است و با اسید حل می‌شود.</li><li>اسیدهای ضعیف مثل سیتریک و استیک (سرکه) از اسیدهای قوی ملایم‌ترند؛ اما سازنده‌ی دستگاه ممکن است محلول خاصی توصیه کند — دفترچه را دنبال کنید.</li><li>اسید می‌تواند برنج را فرسوده کند؛ پس از جرم‌گیری باید خوب آبکشی شود.</li><li>بویلر بخار کاملاً پر نمی‌شود و جرم‌گیر به بالای آن نمی‌رسد؛ مراقب شیرهای ایمنی و حسگرها باشید.</li><li>هنگام کار با اسیدهای قوی از دستکش لاستیکی و پیش‌بند استفاده کنید.</li></ul>","kind":"item","src":[["Wikipedia — Descaling agent","https://en.wikipedia.org/wiki/Descaling_agent"]]}]},{"id":"C6","icon":"additive","title":"مکمل‌ها و افزودنی‌های قهوه","items":[{"id":13,"title":"مواد افزودنی قهوه و محصولات مرتبط","body":"<h4 class=\"sub\">افزودنی‌ها: خلاصه</h4><ul><li>جانشین شیر هر ماده‌ای است که شبیه شیر باشد و مانند آن به‌کار برود؛ شیرهای گیاهی مانند بادام، سویا، جو دوسر، نارگیل و فندق و نیز کرمرهای قهوه در این دسته‌اند.</li><li>کرمر قهوه محصولی مصنوعی است که برای جایگزینی شیر در قهوه ساخته شد؛ بسیاری از آن‌ها روغن گیاهی هیدروژنه دارند و بسیاری سدیم کازئینات، پروتئینی برگرفته از شیر که لاکتوز ندارد.</li><li>کرمر به‌صورت مایع یا گرانول عرضه می‌شود؛ گرانول خشک به یخچال نیاز ندارد، ولی کرمر مایع پس از باز شدن باید در یخچال بماند.</li><li>سوکرالوز حدود ۶۰۰ برابر شکر شیرین است و در برابر گرما پایدار می‌ماند؛ آسپارتام در پخت یا دمای بالا تجزیه می‌شود.</li><li>شیر جو دوسر نیز در نسخه‌هایی مخصوص قهوه عرضه می‌شود.</li></ul>","kind":"item","src":[["Wikipedia — Milk substitute","https://en.wikipedia.org/wiki/Milk_substitute"],["Wikipedia — Sugar substitute","https://en.wikipedia.org/wiki/Sugar_substitute"],["Wikipedia — Non-dairy creamer","https://en.wikipedia.org/wiki/Non-dairy_creamer"]]},{"id":247,"title":"شیر و جایگزین‌های شیر","body":"<h4 class=\"sub\">شیرهای گیاهی</h4><ul><li>سویا: سابقه‌ی نوشیدنی سویا در چین طولانی است و ریشه‌ی آن را به اوایل سلسله‌ی هان (۲۰۲ ق‌م تا ۹ م) می‌رساند؛ پروتئینش تقریباً هم‌اندازه‌ی شیر گاو است. انواع غنی‌شده می‌توانند کلسیم، ویتامین D و B12 داشته باشند، اما همه‌ی برندها غنی نیستند.</li><li>بادام: بادام از خاورمیانه آمده و حدود قرن هشتم با مورها به جنوب اروپا رسید؛ قدیمی‌ترین سند ذکرشده برای شیر گیاهی، کتاب آشپزی ۱۲۲۶ از عراق امروزی درباره‌ی شیر بادام است. با خرد کردن بادام با آب و صاف کردن تفاله ساخته می‌شود و چربی اشباع و کالری کمی دارد.</li><li>جو دوسر: شیر جو دوسر نسبتاً تازه توسعه یافته، طعم ملایم شبیه فرنی دارد و نسخه‌های مخصوص نوشیدن مستقیم یا مصرف در قهوه موجود است.</li><li>نارگیل: از مخلوط آب با مغز رنده‌ی نارگیل رسیده ساخته می‌شود؛ بسیار پرچرب و پرکالری و کم‌پروتئین است.</li><li>برنج: در نسخه‌ی غنی‌شده کلسیم و B12 و D2 دارد؛ به‌دلیل آرسنیک معدنی، سازمان استاندارد غذایی بریتانیا مصرف آن را برای نوزادان و خردسالان توصیه نمی‌کند.</li><li>دیگر: ماکادمیا، بادام‌هندی و فندق؛ بادام‌زمینی و نخود؛ شاهدانه، کتان، چیا و کینوا.</li></ul>","kind":"item","src":[["Wikipedia — Milk substitute","https://en.wikipedia.org/wiki/Milk_substitute"]]},{"id":248,"title":"شیرین‌کننده‌ها","body":"<h4 class=\"sub\">شیرین‌کننده‌ها</h4><ul><li>آسپارتام: ۱۹۶۵ (James Schlatter)، حدود ۱۸۰–۲۰۰ برابر ساکارز.</li><li>ساخارین: ۱۸۷۹ (Remsen و Fahlberg)، حدود ۳۰۰–۵۰۰ برابر ساکارز.</li><li>سوکرالوز: ۱۹۷۶، حدود ۶۰۰ برابر.</li><li>استویا: حدود ۲۵۰ برابر؛ عصاره‌ی میوه‌ی راهب (monk fruit): حدود ۳۰۰ برابر.</li><li>اریتریتول: حدود ۰٫۶۵ تا ۰٫۸ برابر شیرینی ساکارز؛ زایلیتول: تقریباً برابر ساکارز.</li><li>در برخی ارقام (ساخارین، آسپارتام، اریتریتول) اعداد متفاوتی گزارش شده و بازه ذکر شد.</li></ul>","kind":"item","src":[["Wikipedia — Sugar substitute","https://en.wikipedia.org/wiki/Sugar_substitute"]]},{"id":249,"title":"ادویه‌جات","body":"<h4 class=\"sub\">ادویه‌ها در قهوه</h4><ul><li>هل: دانه‌ی گیاهان Elettaria و Amomum از تیره‌ی زنجبیل است؛ هل سبز از Elettaria cardamomum و هل سیاه از Amomum subulatum. هل تلخ‌ترین‌ها نیست اما «سومین ادویه‌ی گران پس از زعفران و وانیل» است. در خاورمیانه ادویه‌ی سنتی قهوه و چای است و در برخی مناطق قهوه و هل را با هم در هاون چوبی (mihbaj) می‌کوبند و در تابه (mehmas) می‌پزند. دانه‌ی هل تا ۸٪ اسانس دارد.</li><li>دارچین: دارچین سیلان (C. verum، «دارچین حقیقی») پوست داخلی نازک سریلانکا است؛ طعم ظریف دارد. کاسیا بخش عمده‌ی دارچین بازار جهانی است، سفت‌تر و قرمز‌قهوه‌ای و تندتر است. کاسیا معمولاً بیش از ۱ میلی‌گرم کومارین در هر گرم دارد؛ حد قابل‌تحمل روزانه‌ی EFSA برابر ۰٫۱ میلی‌گرم بر کیلوگرم وزن بدن است. سینامالدهید حدود ۹۰٪ اسانس را می‌سازد.</li><li>زعفران: گمان می‌رود خاستگاهش ایران (خراسان) باشد؛ ایران حدود ۹۰٪ تولید جهان را دارد. برای هر کیلوگرم حدود ۱۵۰٬۰۰۰ گل لازم است. کروسین رنگ، پیکروکروسین طعم تلخ و سافرانال عطر اصلی است.</li></ul><h4 class=\"sub\">میخک و زنجبیل</h4><ul><li>میخک (Syzygium aromaticum) بومی جزایر مالوکو در اندونزی است؛ اوژنول ۷۲ تا ۹۰ درصد اسانس آن را می‌سازد و عامل اصلی عطرش است. امروز اندونزی بزرگ‌ترین تولیدکننده است. FDA آمریکا میخک را برای هیچ کاربرد دارویی تأیید نکرده است.</li><li>زنجبیل از جنوب‌شرق آسیای دریایی آمده و فقط به‌صورت کشت‌شده وجود دارد. ۶-جینجرول ترکیب اصلی تندی است؛ شوگائول‌ها در گرما یا اسید از جینجرول‌ها پدید می‌آیند و تندترند. در ۲۰۲۳ تولید جهانی حدود ۴٫۹ میلیون تن بود و هند حدود ۴۵٪ آن را داشت.</li></ul>","kind":"item","src":[["Wikipedia — Cardamom","https://en.wikipedia.org/wiki/Cardamom"],["Wikipedia — Cinnamon","https://en.wikipedia.org/wiki/Cinnamon"],["Wikipedia — Saffron","https://en.wikipedia.org/wiki/Saffron"],["Wikipedia — Clove","https://en.wikipedia.org/wiki/Clove"],["Wikipedia — Ginger","https://en.wikipedia.org/wiki/Ginger"]]},{"id":250,"title":"چربی‌ها و روغن‌ها","body":"<h4 class=\"sub\">خامه و چربی‌ها</h4><ul><li>آمریکا: نیم‌ونیم ۱۰٫۵–۱۸٪ چربی؛ خامه‌ی سبک ۱۸–۳۰٪؛ خامه‌ی شلاقی ۳۰–۳۶٪ (قله‌های نرم)؛ خامه‌ی سنگین ۳۶٪ یا بیشتر (قله‌های پایدار).</li><li>بریتانیا: خامه‌ی تک ۱۸٪؛ خامه‌ی شلاقی ۳۵٪؛ خامه‌ی دوبل ۴۸٪.</li><li>استرالیا: خامه‌ی بی‌نام دست‌کم ۳۵٪ چربی؛ سوئیس: ۳۵٪.</li><li>طبق مقررات آمریکا، خامه‌ی سنگین دست‌کم ۳۶ درصد چربی شیر دارد و خامه‌ی شلاقی سبک ۳۰ درصد یا بیشتر ولی کمتر از ۳۶ درصد.</li><li>خامه‌ی سنگین و خامه‌ی شلاقی سنگین یک محصول‌اند؛ خامه‌ای که فقط «شلاقی» نوشته شده، همان نوع سبک‌تر است.</li><li>خامه‌ی پرچرب‌تر پایدارتر شلاق می‌خورد، اما اگر بیش از حد زده شود، بافتی کلوخه‌ای و شبیه کره پیدا می‌کند.</li><li>خامه‌ی بسته‌ی بریتانیایی حدود ۵۵ درصد چربی دارد و حداقل قانونی چربی در فرانسه ۱۲ درصد است.</li></ul>","kind":"item","src":[["Wikipedia — Cream","https://en.wikipedia.org/wiki/Cream"],["U.S. Government Publishing Office — 21 CFR 131.150, Heavy cream","https://govinfo.gov/content/pkg/CFR-2023-title21-vol2/pdf/CFR-2023-title21-vol2-sec131-150.pdf"],["CulinaryLore — Is Heavy Cream Not the Same as Whipping Cream?","https://culinarylore.com/food-myths:is-heavy-cream-not-the-same-as-whipping-cream"]]},{"id":251,"title":"شکلات و کاکائو","body":"<h4 class=\"sub\">شکلات و کاکائو</h4><ul><li>کاکائو حدود ۵۳۰۰ سال پیش در جنوب‌شرقی اکوادور کنونی (فرهنگ مایو-چینچیپه) اهلی شد.</li><li>واژه‌ی «chocolate» در ۱۵۷۹ در اسپانیایی و در ۱۶۰۴ در انگلیسی ثبت شد؛ نخستین محموله‌ی رسمی دانه‌ی کاکائو به اروپا ۱۵۸۵.</li><li>۱۸۲۸: Coenraad van Houten پرس هیدرولیکی ثبت کرد که کره‌ی کاکائو را از لیکر شکلات جدا می‌کرد و تولید انبوه پودر کاکائو را ممکن ساخت.</li><li>شکلات تلخ شبیه لیکر کاکائو با کره‌ی کاکائوی کمی بیشتر است و با درصد کاکائو تعریف می‌شود؛ شکلات شیری با جایگزینی بخشی یا بیشتر جامدات غیرچرب کاکائو با جامدات شیر؛ شکلات سفید با جایگزینی کامل.</li><li>جامدات کاکائو شامل همه‌ی اجزای دانه‌ی کاکائو؛ «لیکر شکلات» تقریباً نصف جامدات غیرچرب و نصف کره‌ی کاکائو است.</li></ul>","kind":"item","src":[["Wikipedia — Chocolate","https://en.wikipedia.org/wiki/Chocolate"],["Wikipedia — Cocoa solids","https://en.wikipedia.org/wiki/Cocoa_solids"]]},{"id":252,"title":"طعم‌دهنده‌های مصنوعی و طبیعی","body":"<h4 class=\"sub\">طعم‌دهنده‌ها</h4><ul><li>وانیل: طعم شیرین و گرم می‌دهد؛ هم به‌صورت عصاره و هم غلاف مصرف می‌شود.</li><li>دارچین سیلان طعم ظریف و کاسیا طعم تندتر دارد.</li><li>هل از رایج‌ترین طعم‌دهنده‌های قهوه‌ی خاورمیانه است.</li></ul>","kind":"item","src":[["Wikipedia — Vanilla","https://en.wikipedia.org/wiki/Vanilla"],["Wikipedia — Cinnamon","https://en.wikipedia.org/wiki/Cinnamon"],["Wikipedia — Cardamom","https://en.wikipedia.org/wiki/Cardamom"]]},{"id":253,"title":"میوه‌ها و پوست مرکبات","body":"<h4 class=\"sub\">پوست مرکبات</h4><ul><li>«زست» (zest) بخش بیرونی رنگی پوست است که با خراشیدن برای طعم تند استفاده می‌شود.</li><li>بخش سفید (پیت/آلبیدو) در بیشتر گونه‌ها خام «تلخ» است.</li><li>قطعه‌ی بزرگ پوست («تویست») برای تزیین کوکتل رایج است.</li><li>فلاودو (اگزوکارپ) لایه‌ی بیرونی رنگی پوست است و زست از همین لایه گرفته می‌شود؛ پوست کامل مجموعه‌ی فلاودو و آلبیدو است.</li><li>مقدار پیت در گونه‌ها فرق دارد: نارنگی تقریباً پیت ندارد، اما پوملو و خویشاوندان سیترون پیت ضخیم‌تری دارند.</li><li>پیت لیمو و سیترون را می‌توان شکری کرد و شیرینی‌ای به نام ساکسید (succade) از آن ساخت.</li><li>در گریپ‌فروت، فلاودو پر از غده‌های روغنی است و آلبیدو فاقد این غده‌هاست؛ در روغن آن لیمونن ۹۳ تا ۹۴ درصد ترپنوئیدهای فرار را تشکیل می‌داد (اندازه‌گیری روی یک درخت).</li><li>برای زست باید از میوه‌ی بدون واکس استفاده کرد و اگر واکس دارد ابتدا آن را پاک کرد.</li></ul>","kind":"item","src":[["Wikipedia — Citrus peel","https://en.wikipedia.org/wiki/Citrus_peel"],["Wikipedia — Zest (ingredient)","https://en.wikipedia.org/wiki/Zest_(ingredient)"],["Wikipedia — Hesperidium","https://en.wikipedia.org/wiki/Hesperidium"],["PMC — Assessing the Biosynthetic Capabilities of Secretory Glands in Citrus Peel","https://pmc.ncbi.nlm.nih.gov/articles/PMC3375987/"]]},{"id":254,"title":"مواد پروتئینی و مکمل‌های ورزشی","body":"<h4 class=\"sub\">پروتئین و کلاژن</h4><ul><li>پروتئین وی: مخلوطی از پروتئین‌های جداشده از آب‌پنیر (α-لاکتالبومین، β-لاکتوگلوبولین، آلبومین سرم، ایمونوگلوبولین‌ها). ایزوله‌ی وی (WPI) بیش از ۹۰٪ پروتئین (وزن خشک) دارد. در شیر گاو پروتئین حدود ۲۰٪ وی و ۸۰٪ کازئین است.</li><li>EFSA شواهدی برای ادعای کاهش وزن نیافت و وی را در ساخت قدرت و توده‌ی بدون‌چربی تقریباً هم‌ارز دیگر منابع پروتئین دانست.</li><li>کلاژن: فراوان‌ترین پروتئین پستانداران (حدود ۲۵ تا ۳۵٪ پروتئین بدن)؛ مکمل‌های هیدرولیزشده در معده به پپتید و آمینواسید شکسته می‌شوند و مقاله «شواهد خوبی» برای اثر خوراکی بر پوست نمی‌یابد (تا ۲۰۲۵ شواهد بالینی وجود ندارد).</li></ul>","kind":"item","src":[["Wikipedia — Whey protein","https://en.wikipedia.org/wiki/Whey_protein"],["Wikipedia — Collagen","https://en.wikipedia.org/wiki/Collagen"]]},{"id":255,"title":"مکمل‌های عملکردی و آرام‌بخش","body":"<h4 class=\"sub\">ال‌تیانین</h4><ul><li>ال‌تیانین عمدتاً در گیاه چای (Camellia sinensis) و برخی قارچ‌ها است؛ حدود ۱٪ وزن خشک چای سیاه، سبز و سفید؛ سایه‌دادن (ماچا، گیوکورو) آن را افزایش می‌دهد.</li><li>بررسی EFSA ۲۰۱۱: «شواهد ناکافی برای رابطه‌ی علّی» با شناخت، استرس، خواب. مرور ۲۰۲۰: ۲۰۰–۴۰۰ میلی‌گرم در روز ممکن است استرس و اضطراب حاد را کم کند اما برای مصرف دارویی کافی نیست؛ مرور ۲۰۲۵: پژوهش محدود و ناهمگون است.</li></ul>","kind":"item","src":[["Wikipedia — Theanine","https://en.wikipedia.org/wiki/Theanine"]]},{"id":256,"title":"تزیینات و گارنیش","body":"<h4 class=\"sub\">گارنیش</h4><ul><li>«تویست» پوست مرکبات برای تزیین کوکتل رایج است؛ زست بخش رنگی بیرونی پوست برای طعم تند؛ بخش سفید پوست خام «تلخ» است.</li><li>دارچین: سینامالدهید حدود ۹۰٪ اسانس را می‌سازد؛ دارچین سیلان ظریف و کاسیا تندتر و پرکومارین است.</li><li>شکلات و کاکائو و جزئیات آن‌ها در مقاله‌ی «شکلات و کاکائو».</li></ul>","kind":"item","src":[["Wikipedia — Citrus peel","https://en.wikipedia.org/wiki/Citrus_peel"],["Wikipedia — Cinnamon","https://en.wikipedia.org/wiki/Cinnamon"],["Wikipedia — Chocolate","https://en.wikipedia.org/wiki/Chocolate"]]},{"id":258,"title":"انواع شکلات و مشتقات آن","body":"<h4 class=\"sub\">انواع شکلات</h4><ul><li>تلخ، شیری و سفید — تعریف و تفاوت‌شان در مقاله‌ی «شکلات و کاکائو» بالا آمده است.</li><li>کره‌ی کاکائو «ماده‌ای است که ویژگی‌های فیزیکی شکلات را تعریف می‌کند» و در هر سه نوع هست.</li><li>در قرن نوزدهم شکلات شیری مدرن و فرآیند کانچینگ (conching) پدید آمد و شکلات از نوشیدنی به خوراکی جامد تبدیل شد.</li><li>شکلات تلخ در اتحادیه‌ی اروپا دست‌کم ۳۵٪ جامدات کاکائو دارد و شیر در آن نیست.</li><li>شکلات شیری در اتحادیه‌ی اروپا دست‌کم ۲۵٪ جامدات کاکائو، ۱۴٪ جامدات شیر و ۳٫۵٪ چربی شیر دارد.</li><li>شکلات سفید از کره‌ی کاکائو، شکر و جامدات شیر ساخته می‌شود و چون جامدات بدون‌چربی کاکائو ندارد، رنگ عاجی دارد؛ حداقل کره‌ی کاکائو در اتحادیه‌ی اروپا ۲۰٪ است.</li><li>شکلات روبی را شرکت Barry Callebaut ساخت؛ توسعه‌اش از ۲۰۰۴ شروع شد و در ۲۰۱۷ عرضه شد. شکلات کامپوند به‌جای کره‌ی کاکائو از چربی‌های گیاهی استفاده می‌کند.</li><li>مقررات آمریکا برای شکلات شیری دست‌کم ۱۰٪ لیکور شکلات، ۳٫۳۹٪ چربی شیر و ۱۲٪ جامدات شیر را لازم می‌داند.</li><li>در آمریکا برای شکلات تلخ «استاندارد هویت» جداگانه‌ای وجود ندارد.</li><li>استاندارد آمریکا برای شکلات سفید دست‌کم ۲۰٪ کره‌ی کاکائو، ۱۴٪ جامدات کل شیر و ۳٫۵٪ چربی شیر می‌خواهد و شیرین‌کننده‌ی کربوهیدراتی آن نباید از ۵۵٪ بیشتر باشد.</li></ul>","kind":"item","src":[["Wikipedia — Chocolate","https://en.wikipedia.org/wiki/Chocolate"],["Wikipedia — Types of chocolate","https://en.wikipedia.org/wiki/Types_of_chocolate"],["FDA — Small entity compliance guide: standard of identity, white chocolate","https://www.fda.gov/regulatory-information/search-fda-guidance-documents/small-entity-compliance-guide-standard-identity-white-chocolate"],["Registrar Corp — FDA chocolate regulations","https://www.registrarcorp.com/blog/food-beverage/food-beverage-regulations/fda-chocolate-regulations"]]},{"id":259,"title":"شیرین‌کننده‌های نادر و سنتی","body":"<h4 class=\"sub\">عسل و شیرین‌کننده‌های سنتی</h4><ul><li>عسل و گونه‌های تک‌گل در مقاله‌ی «عسل» توضیح داده شده است؛ هر نوع بسته به گلی که زنبورها از آن تغذیه کرده‌اند طعم دارد.</li><li>استویا و عصاره‌ی میوه‌ی راهب جزو شیرین‌کننده‌های طبیعی‌اند و به‌ترتیب حدود ۲۵۰ و ۳۰۰ برابر ساکارز شیرین‌ترند.</li><li>عسل می‌تواند بیش از ۱۰۰ ترکیب فرار داشته باشد که بیشترِ طعم و بوی آن را تعیین می‌کنند؛ عسل چندگل از سالی به سال دیگر، بسته به گل‌های شکوفا، طعم متفاوتی دارد.</li><li>عسل مانوکا از عسل‌های روشن‌تر مثل شبدر تیره‌تر است و طعمی خاکی و کمی تلخ دارد.</li><li>جگری، پانلا، موسکووادو و پیلونسیو همگی شکرهای خام نیشکری‌اند؛ شکر نخل از شیره‌ی ساقه‌ی گل نخل‌ها به‌دست می‌آید.</li><li>شیره‌ی خرما از میوه‌ی نخل خرما و ملاس انار از چاشنی‌های خاورمیانه، قفقاز جنوبی و بالکان است.</li></ul>","kind":"item","src":[["Wikipedia — Honey","https://en.wikipedia.org/wiki/Honey"],["Wikipedia — Sugar substitute","https://en.wikipedia.org/wiki/Sugar_substitute"],["Wikipedia — List of unrefined sweeteners","https://en.wikipedia.org/wiki/List_of_unrefined_sweeteners"]]},{"id":260,"title":"کرم‌ها و خامه‌های خاص","body":"<h4 class=\"sub\">خامه‌های خاص</h4><ul><li>برای خامه‌ی قهوه (اسپرسو کن پانا، قهوه‌ی ایرلندی) خامه‌ی ۳۰–۳۶٪ چربی «قله‌ی نرم» و ۳۶٪+ «قله‌ی پایدار» می‌دهد.</li><li>در بریتانیا خامه‌ی دوبل ۴۸٪ و خامه‌ی شلاقی ۳۵٪ چربی دارد.</li><li>برای قهوه معمولاً خامه‌ی سبک یا نیم‌ونیم انتخاب می‌شود؛ خامه‌ی قهوه در کانادا ۱۰ یا ۱۸ درصد و در سوئیس ۱۵ درصد چربی دارد.</li><li>گاهی خامه در قهوه به شکل گلوله‌های روغنی جدا می‌شود که «فدرینگ» نام دارد؛ بالا بردن مواد جامد بدون چربی آن را کم می‌کند، ولی پرهزینه است.</li><li>در نسخه‌های آشپزی، پایدارکننده‌ها از شکستن خامه هنگام گرم‌شدن جلوگیری می‌کنند؛ برای سس‌های داغ، خامه‌ی دوبل یا کرم‌فرش پرچرب بهتر است.</li><li>پودر خامه‌ی سنگین به‌عنوان سفیدکننده‌ی قهوه به کار می‌رود و نیاز به یخچال ندارد.</li><li>دستگاه‌های خامه‌زن با گاز اکسید نیتروس هم می‌توانند هوا را در خامه‌ی پرچرب وارد و آن را شلاق بزنند.</li></ul>","kind":"item","src":[["Wikipedia — Cream","https://en.wikipedia.org/wiki/Cream"],["U.S. Government Publishing Office — 21 CFR 131.150, Heavy cream","https://govinfo.gov/content/pkg/CFR-2023-title21-vol2/pdf/CFR-2023-title21-vol2-sec131-150.pdf"],["CulinaryLore — Is Heavy Cream Not the Same as Whipping Cream?","https://culinarylore.com/food-myths:is-heavy-cream-not-the-same-as-whipping-cream"]]},{"id":261,"title":"روغن‌ها و چربی‌های غیرمعمول","body":"<h4 class=\"sub\">روغن‌ها و MCT</h4><ul><li>تری‌گلیسرید زنجیره‌متوسط (MCT) تری‌گلیسریدی است با اسیدهای چرب ۶ تا ۱۲ کربنی؛ منابع تجاری اصلی روغن هسته‌ی نخل و روغن نارگیل‌اند.</li><li>پودر MCT خرده‌فروشی روغن MCT روی نشاسته است و کربوهیدرات هم دارد.</li><li>بر پایه‌ی یک مرور نظام‌مند ۲۰۲۰، MCT انرژی دریافتی بعدی را نسبت به چربی‌های زنجیره‌بلند کم می‌کند اما بر اشتها اثر ندارد؛ شواهد درباره‌ی کاهش وزن و عملکرد ورزشی قطعی نیست.</li><li>ممکن است در برخی شرایط کتوژنز و اسیدوز متابولیک ایجاد کند؛ برای افراد با بیماری خاص مشورت پزشک لازم است.</li></ul>","kind":"item","src":[["Wikipedia — Medium-chain triglyceride","https://en.wikipedia.org/wiki/Medium-chain_triglyceride"]]},{"id":262,"title":"ادویه‌جات نادر و منطقه‌ای","body":"<h4 class=\"sub\">ادویه‌های نادر و منطقه‌ای</h4><ul><li>هل سیاه (Amomum subulatum) بومی هیمالیای شرقی و عمدتاً کشت‌شده در شرق نپال، سیکیم، دارجیلینگ و جنوب بوتان است.</li><li>زعفران: ایران حدود ۹۰٪ تولید جهان را دارد؛ حدود ۱۵۰٬۰۰۰ گل برای یک کیلوگرم لازم است.</li><li>وانیل دومین ادویه‌ی گران جهان است؛ ۴۲٪ تولید ۲۰۲۳ از ماداگاسکار بود.</li></ul>","kind":"item","src":[["Wikipedia — Cardamom","https://en.wikipedia.org/wiki/Cardamom"],["Wikipedia — Saffron","https://en.wikipedia.org/wiki/Saffron"],["Wikipedia — Vanilla","https://en.wikipedia.org/wiki/Vanilla"]]},{"id":263,"title":"عسل‌های خاص و تک‌گلی","body":"<h4 class=\"sub\">عسل</h4><ul><li>ترکیب: حدود ۱۷٪ آب و ۸۲٪ کربوهیدرات؛ فروکتوز حدود ۵۱٪ و گلوکز حدود ۴۴٪.</li><li>عسل تک‌گل از شهد عمدتاً یک نوع گل (مثلاً شبدر، بهارنارنج، گندم‌سیاه) است و رنگ و طعم متمایز دارد.</li><li>بلورین‌شدن نشانه‌ی فساد نیست و با گرمای ملایم آب می‌شود؛ عسل پرگلوکز (مثل براسیکا) زود و شاه‌بلوط و توپلو دیر یا هرگز بلور می‌شوند.</li><li>عسل ممکن است اسپور Clostridium botulinum داشته باشد؛ به نوزادان داده نشود (بعد از یک‌سالگی عموماً ایمن).</li><li>رنگ از زرد روشن تا قهوه‌ای تیره است و بیش از ۱۰۰ ترکیب فرار در آن یافت می‌شود.</li></ul>","kind":"item","src":[["Wikipedia — Honey","https://en.wikipedia.org/wiki/Honey"]]},{"id":264,"title":"طعم‌دهنده‌های عصاره‌ای و طبیعی","body":"<h4 class=\"sub\">وانیل و عصاره‌ها</h4><ul><li>گونه‌ی اصلی تجاری V. planifolia (وانیل بوربن/ماداگاسکار) است؛ V.×tahitensis در جنوب اقیانوس آرام و V. pompona در غرب هند و آمریکای مرکزی و جنوبی کشت می‌شوند.</li><li>وانیلین ترکیب اصلی طعم است؛ Charles Gobley در ۱۸۵۸ آن را از غلاف وانیل جدا کرد. حدود ۹۵٪ محصولات «وانیلی» با وانیلین مصنوعی (از لیگنین) طعم می‌گیرند.</li><li>عصاره‌ی وانیل (اصل یا تقلبی) دست‌کم ۳۵٪ الکل دارد.</li><li>عمل‌آوری چهار مرحله دارد: کشتن، عرق‌دهی، خشک‌کردن آهسته و کنداسیون ۵–۶ ماهه.</li></ul>","kind":"item","src":[["Wikipedia — Vanilla","https://en.wikipedia.org/wiki/Vanilla"]]},{"id":265,"title":"مواد معدنی و نمک‌ها","body":"<h4 class=\"sub\">نمک</h4><ul><li>نمک عمدتاً سدیم کلرید (NaCl) است؛ نمک سفره ۹۷ تا ۹۹٪ NaCl.</li><li>نمک تلخی غذا را کم می‌کند و غذا را خوش‌طعم‌تر و نسبتاً شیرین‌تر نشان می‌دهد؛ این پایه‌ی افزودن پنج‌شیار نمک به قهوه‌ی تلخ است.</li><li>حلالیت ۳۵۹ گرم در لیتر.</li><li>آب دریا حدود ۳٫۵ درصد شوری دارد، یعنی حدود ۳۵ گرم نمک محلول در هر کیلوگرم آب.</li><li>تولید جهانی نمک در سال ۲۰۱۸ حدود ۳۰۰ میلیون تن بود؛ مصارف خوراکی ۱۷٫۵ درصد آن را شامل می‌شود.</li><li>سازمان جهانی بهداشت مصرف کمتر از ۲۰۰۰ میلی‌گرم سدیم در روز را توصیه می‌کند که برابر ۵ گرم نمک است.</li><li>در پژوهشی که در سال ۱۹۹۵ در مجله‌ی Chemical Senses منتشر شد، افزودن نمک به مخلوط ترکیبات شیرین و تلخ آن را شیرین‌تر و کم‌تلخ‌تر کرد؛ اثر برعکس دیده نشد.</li><li>کانال سدیمی ENaC در یاخته‌های چشایی با نمک کم فعال می‌شود؛ نمک زیاد گیرنده‌های ترش و تلخ را هم فعال می‌کند و سازوکار دقیق کاهش تلخی هنوز کاملاً روشن نیست.</li><li>پتاسیم کلرید شاخص شوری ۰٫۶ دارد (سدیم کلرید ۱) و جزء اصلی جانشین‌های نمک است.</li></ul>","kind":"item","src":[["Wikipedia — Salt","https://en.wikipedia.org/wiki/Salt"],["Wikipedia — Saltiness","https://en.wikipedia.org/wiki/Saltiness"],["ScienceAlert — People are adding salt to their morning coffee","https://www.sciencealert.com/people-are-adding-salt-to-their-morning-coffee-for-a-rather-bizarre-reason"]]},{"id":266,"title":"مکمل‌های انرژی‌زا و هوشمند (نوین)","body":"<h4 class=\"sub\">مکمل‌های انرژی‌زا</h4><ul><li>ال‌کارنیتین: «شواهدی وجود ندارد که متابولیسم چربی را تغییر دهد یا به کاهش وزن کمک کند»؛ کیفیت پژوهش درباره‌ی عملکرد ورزشی پایین و نتایج ناهمسان است. دوز ۰٫۵ تا ۱ گرم در روز ایمن شمرده می‌شود و حدود ۳ گرم می‌تواند تهوع، اسهال و بوی ماهی بدن بدهد.</li><li>تائورین: در برخی نوشیدنی‌های انرژی‌زا ۱ تا ۳ گرم در هر وعده؛ مطالعات بالینی باکیفیت کم است. EFSA مصرف تا ۶ گرم در روز را «احتمالاً ایمن» می‌داند و منابع دیگر تا ۳ گرم در روز.</li><li>گوارانا: دانه‌ی آن تا حدود ۶٪ کافئین دارد (دانه‌ی سبز قهوه ۱ تا ۳٪)، یعنی چند برابر دانه‌ی قهوه؛ FDA آن را فقط به‌عنوان افزودنی طعم تأیید کرده است.</li><li>یربا ماته: کافئین ۰٫۷ تا ۱٫۷٪ وزن خشک و تئوبرومین ۰٫۳ تا ۰٫۹٪؛ ماته‌ی داغ با آب ۷۰ تا ۸۰ درجه دم می‌شود. IARC نوشیدن مداوم ماته‌ی بسیار داغ (بالای ۶۵ درجه) را «احتمالاً» عامل سرطان مری دانسته است؛ ماته‌ی سرد چنین ارتباطی ندارد.</li></ul>","kind":"item","src":[["Wikipedia — Levocarnitine","https://en.wikipedia.org/wiki/Levocarnitine"],["Wikipedia — Taurine","https://en.wikipedia.org/wiki/Taurine"],["Wikipedia — Guarana","https://en.wikipedia.org/wiki/Guarana"],["Wikipedia — Yerba mate","https://en.wikipedia.org/wiki/Yerba_mate"]]},{"id":267,"title":"مکمل‌های رنگی و بصری (گارنیش نادر)","body":"<h4 class=\"sub\">زعفران، هل و خرما در قهوه‌ی عربی</h4><ul><li>هل رایج‌ترین افزودنی قهوه‌ی عربی است و در شبه‌جزیره‌ی عربستان «ضروری‌ترین» ادویه شمرده می‌شود؛ گاهی میخک و در عربستان سعودی دارچین هم اضافه می‌شود.</li><li>زعفران در شبه‌جزیره‌ی عربستان و کشورهای خلیج فارس استفاده می‌شود؛ قهوه‌ی خلیجی (qahwa khaleeji) رنگ زرد روشن خود را از زعفران و هل فراوان می‌گیرد.</li><li>قهوه‌ی یمنی اغلب با ادویه‌ی محلی «حواج» دم می‌شود.</li><li>قهوه‌ی عربی داغ در فنجان‌های کوچک بدون دسته (فنجان) سرو می‌شود؛ معمولاً شیرین نیست، و سه سطح شیرینی دارد: ساده، متوسط و شیرین.</li><li>تقریباً همیشه با خرما همراه است؛ به‌طور کلی برای متعادل کردن تلخی با خرما، میوه‌ی خشک یا شکرپوشیده، آجیل و شیرینی سرو می‌شود.</li><li>دانه‌ی قهوه‌ی شکلات‌پوش هم به‌تنهایی خورده می‌شود و هم گارنیش غذاها و دسرهاست.</li></ul>","kind":"item","src":[["Wikipedia — Arabic coffee","https://en.wikipedia.org/wiki/Arabic_coffee"],["Wikipedia — List of coffee dishes","https://en.wikipedia.org/wiki/List_of_coffee_dishes"]]},{"id":268,"title":"مکمل‌های عجیب و آزمایشگاهی (برای کافه‌های تجربی)","body":"<h4 class=\"sub\">نیتروژن مایع و نیترو کلد برو</h4><ul><li>نیتروژن مایع نقطه‌ی جوش حدود ۱۹۶− درجه‌ی سانتی‌گراد دارد؛ رستوران‌ها و بارمن‌ها برای بستنی سریع (کریستال یخ ریزتر و بافت نرم‌تر)، خنک‌کردن لیوان و کوکتل دودی استفاده می‌کنند.</li><li>خطرها: سوختگی سرمایی، خفگی (نیتروژن بی‌رنگ و بی‌بو است و اکسیژن را جابه‌جا می‌کند)، افزایش فشار در ظرف بسته، و آسیب شدید داخلی در صورت بلعیدن (حداقل یک مورد برداشتن معده).</li><li>نیترو کلد برو: کلد برو که با گاز نیتروژن از شیر مخصوص (مثل آبجو) سرو می‌شود؛ بافت نرم و «سر کف» غنی دارد و معمولاً سرد و بدون یخ سرو می‌شود.</li></ul>","kind":"item","src":[["Wikipedia — Liquid nitrogen","https://en.wikipedia.org/wiki/Liquid_nitrogen"],["Wikipedia — Nitro cold brew","https://en.wikipedia.org/wiki/Nitro_cold_brew"]]},{"id":269,"title":"مکمل‌های وگان و بدون گلوتن","body":"<h4 class=\"sub\">گلوتن و جایگزین‌ها</h4><ul><li>قهوه در فهرست غذاهای ذاتاً بدون گلوتن نیامده؛ برای مبتلایان به سلیاک جزئیات را از سازنده بپرسید.</li><li>غلات ذاتاً بدون گلوتن هم می‌توانند هنگام برداشت، حمل، آسیاب و فرآوری آلوده شوند؛ محصولات فرآوری‌شده و طعم‌دار ممکن است گلوتن به‌عنوان غلظت‌دهنده داشته باشند.</li><li>جو دوسر: بحث‌برانگیز است چون اغلب با غلات حاوی گلوتن آلوده می‌شود؛ شیر جو دوسر را برای سلیاک بررسی کنید. تنها درمان پذیرفته‌شده‌ی بیماری سلیاک رژیم بدون گلوتن مادام‌العمر است.</li><li>شیرهای گیاهی (سویا، بادام، نارگیل، برنج) در مقاله‌ی «شیرهای گیاهی» آمده‌اند.</li></ul>","kind":"item","src":[["Wikipedia — Gluten-free diet","https://en.wikipedia.org/wiki/Gluten-free_diet"],["Wikipedia — Milk substitute","https://en.wikipedia.org/wiki/Milk_substitute"]]},{"id":270,"title":"مواد افزودنی‌ برای کاهش اسیدیته (برای معده‌های حساس)","body":"<h4 class=\"sub\">کاهش اسیدیته</h4><ul><li>جوش‌شیرین (بی‌کربنات سدیم) با اسید واکنش می‌دهد و CO2 آزاد می‌کند و به‌عنوان ضداسید برای سوءهاضمه و سوزش معده کاربرد دارد؛ چون یون سدیم دارد، مصرف آن سدیم به بدن می‌افزاید و برای مقدار مصرف باید با پزشک یا داروساز مشورت کرد.</li><li>pH قهوه‌ی دم‌کرده‌ی داغ حدود ۵ است و اسید معده بین ۱ تا ۳ قرار دارد.</li><li>طبق نظر یک متخصص تغذیه، قهوه‌ی سیاه حدود ۵٫۲، قهوه‌ی کم‌اسید حدود ۵٫۷ و کلدبرو حدود ۵٫۱ pH دارد؛ یعنی تفاوت کم است.</li><li>در یک پژوهش، pH نمونه‌های دم‌کرده‌ی سرد و داغ بین ۴٫۸۵ و ۵٫۱۳ بود و قهوه‌ی داغ اسیدهای تیتراسیونیِ بیشتری داشت.</li><li>روش‌های پیشنهادی: افزودن شیر، انتخاب رست تیره، فیلتر کاغذی و حدود یک‌چهارم قاشق چای‌خوری جوش‌شیرین در دم‌کرده. در صورت رفلاکس یا GERD باید علت را از پزشک پرسید.</li></ul>","kind":"item","src":[["Wikipedia — Sodium bicarbonate","https://en.wikipedia.org/wiki/Sodium_bicarbonate"],["Banner Health — Is low-acid coffee better for a sensitive stomach?","https://www.bannerhealth.com/healthcareblog/advise-me/is-low-acid-coffee-better-for-a-sensitive-stomach"],["Sci.News — Hot brew coffee has more antioxidants than cold brew","https://www.sci.news/othersciences/chemistry/hot-cold-brew-coffee-antioxidants-06585.html"]]}]},{"id":"C7","icon":"dessert","title":"غذاها، دسرها و نوشیدنی‌های ترکیبی قهوه‌ای","items":[{"id":284,"title":"کیک‌ها و شیرینی‌های قهوه‌ای","body":"<h4 class=\"sub\">کیک‌های قهوه‌ای</h4><ul><li>«coffee cake» دو معنا دارد: (۱) نان شیرین آمریکایی که کنار قهوه سرو می‌شود و معمولاً خودش قهوه ندارد؛ (۲) کیکی با طعم قهوه (مثلاً کیک قهوه و گردو).</li><li>تیرامیسو: بیسکویت ساووی‌اردی خیس‌خورده در قهوه، زرده، شکر، ماسکارپونه و کاکائو؛ اولین ثبت منتشرشده دهه‌ی ۱۹۷۰ و ابداع ادعایی ۱۹۶۹ در تره‌ویزو.</li><li>بستنی قهوه: نخستین ظهور شناخته‌شده در ۱۸۶۹ (پارفه‌ی قهوه)؛ Häagen-Dazs در ۱۹۶۰ آن را کنار شکلات و وانیل عرضه کرد.</li></ul>","kind":"item","src":[["Wikipedia — Coffee cake","https://en.wikipedia.org/wiki/Coffee_cake"],["Wikipedia — Tiramisu","https://en.wikipedia.org/wiki/Tiramisu"],["Wikipedia — Coffee ice cream","https://en.wikipedia.org/wiki/Coffee_ice_cream"]]},{"id":296,"title":"دسر‌ها و پودینگ‌های قهوه‌ای","body":"<h4 class=\"sub\">تیرامیسو</h4><ul><li>ترکیب سنتی: بیسکویت ساووی‌اردی (انگشتی) خیس‌خورده در قهوه، زرده‌ی تخم‌مرغ، شکر، ماسکارپونه و پودر کاکائو؛ برخی نسخه‌ها شراب مارسالا دارند.</li><li>ریشه در شمال‌شرق ایتالیا (ونتو و فریولی-ونتزیا جولیا) دارد؛ مرگ‌نامه‌ها رستوران Le Beccherie در تره‌ویزو را مبتکر آن در ۲۴ دسامبر ۱۹۶۹ می‌دانند و در منو در ۱۹۷۲ آمد. دستور آن پیش از دهه‌ی ۱۹۶۰ در کتاب‌های آشپزی دیده نمی‌شود؛ خاستگاه دقیق مبهم است.</li><li>نام از ایتالیایی «tirami su» یعنی «بلندم کن / سرحالم کن» است.</li></ul>","kind":"item","src":[["Wikipedia — Tiramisu","https://en.wikipedia.org/wiki/Tiramisu"]]},{"id":307,"title":"نوشیدنی‌های الکلی","body":"<h4 class=\"sub\">قهوه‌ی ایرلندی و لیکور قهوه</h4><ul><li>دستور استاندارد: ۵۰ میلی‌لیتر ویسکی ایرلندی، ۱۲۰ میلی‌لیتر قهوه‌ی داغ، ۵۰ میلی‌لیتر خامه‌ی سرد تازه و یک قاشق چای‌خوری شکر.</li><li>یک روایت ابداع را به Joe Sheridan سرآشپز پایگاه هوایی Foynes (کانتی کلر ایرلند) در ۱۹۴۲ یا ۱۹۴۳ نسبت می‌دهد. Stanton Delaplane می‌گوید همراه با Buena Vista Cafe سان‌فرانسیسکو سرو آن را در ۱۰ نوامبر ۱۹۵۲ آغاز کرد.</li><li>لیکور قهوه نوشیدنی الکلی شیرین با طعم قهوه است؛ بیشتر لیکورها ۱۵ تا ۵۵٪ الکل دارند. کالوا لیکور قهوه‌ی مکزیکی است.</li></ul>","kind":"item","src":[["Wikipedia — Irish coffee","https://en.wikipedia.org/wiki/Irish_coffee"],["Wikipedia — Coffee liqueur","https://en.wikipedia.org/wiki/Coffee_liqueur"]]},{"id":308,"title":"نوشیدنی‌های غیرالکلی","body":"<h4 class=\"sub\">نوشیدنی‌های غیرالکلی</h4><ul><li>کاپا موکا: هات‌چاکلت با اسپرسو یا قهوه که در قهوه‌خانه‌های آمریکا رایج است؛ نام از بندر مخا (یمن). هات‌چاکلت از شکلات ذوب‌شده یا پودر کاکائو با شیر/آب داغ و معمولاً شکر ساخته می‌شود؛ پودر کاکائو چربی کمتری از شکلات بار دارد.</li><li>کاکائو حدود ۶۷۰۰ سال پیش در اکوادور کنونی اهلی شد؛ مایاها و آزتک‌ها نوشیدنی کاکائو می‌نوشیدند؛ ۱۸۲۸ پرس Van Houten پودر کاکائو را ممکن کرد.</li><li>جو برشته‌ی Barleycup و Caffè d’orzo در مقاله‌ی «مدل‌های غیرقهوه‌ای» آمده است.</li></ul>","kind":"item","src":[["Wikipedia — Hot chocolate","https://en.wikipedia.org/wiki/Hot_chocolate"],["Wikipedia — Mocha (drink)","https://en.wikipedia.org/wiki/Mocha_(drink)"]]},{"id":309,"title":"شکلات‌ها و آب‌نبات‌ها","body":"<h4 class=\"sub\">شکلات و مالت</h4><ul><li>موکا و شکلات: هات‌چاکلت ترکیب‌شده با اسپرسو را «کاپا موکا» می‌نامند؛ شکلات و کاکائو در مقاله‌ی «شکلات و کاکائو».</li><li>پودر شیر مالت‌دار (malted milk) از جو مالت‌شده، آرد گندم و پودر شیر کامل تبخیرشده ساخته می‌شود؛ James Horlick و William Horlick در ۱۸۷۳ شرکت را ساختند؛ ۱۸۸۳ حق اختراع فرمول با شیر خشک؛ ۱۸۸۷ علامت «malted milk» ثبت شد. در شیک مالت، نوشیدنی‌های Horlicks، Ovaltine و Milo و آب‌نباتی مثل Maltesers به‌کار می‌رود.</li></ul>","kind":"item","src":[["Wikipedia — Hot chocolate","https://en.wikipedia.org/wiki/Hot_chocolate"],["Wikipedia — Malted milk","https://en.wikipedia.org/wiki/Malted_milk"]]},{"id":310,"title":"غذا‌های شور با قهوه","body":"<h4 class=\"sub\">قهوه در غذاهای شور</h4><ul><li>سس رد‌آی (Red-eye gravy): سس رقیق جنوب آمریکا از چربی ژامبون سرخ‌شده و قهوه‌ی سیاه؛ تابه با قهوه دگلیز می‌شود و قهوه و چربی با نسبت مساوی ترکیب می‌شوند؛ با ژامبون، گریتس یا بیسکویت سرو می‌شود. در لوئیزیانا نسخه‌ی کاجون از رست‌بیف و گاهی جایگزین قهوه‌ی کاسنی استفاده می‌کند.</li><li>نام «رد‌آی» از ظاهر سس می‌آید: وقتی سنتی تهیه شود، قهوه زیر چربی می‌نشیند و در کاسه‌ی گرد شبیه چشمی سرخ دیده می‌شود. نام‌های دیگرش «سس بیچاره» و «سس ته‌ماندن» است.</li><li>برای پررنگ‌تر شدن رنگ قرمز می‌توان فلفل قرمز افزود؛ بعضی دستور‌ها به‌جای قهوه آب به‌کار می‌برند.</li><li>در بخش‌هایی از آلاباما خردل یا کچاپ در سس مخلوط می‌شود.</li><li>سس قهوه از دست‌کم ۱۹۰۴ در آشپزی آمریکایی به‌کار رفته و می‌تواند شیرین یا شور باشد؛ نسخه‌های شور با ماهی سالمون و استیک سرو می‌شوند.</li><li>در فهرست غذاهای قهوه‌دار، رابِ اسپرسو برای دنده‌ی خوک و سس قهوه برای فیله‌میونیون آمده است.</li></ul>","kind":"item","src":[["Wikipedia — Red-eye gravy","https://en.wikipedia.org/wiki/Red-eye_gravy"],["Wikipedia — Coffee sauce","https://en.wikipedia.org/wiki/Coffee_sauce"],["Wikipedia — List of coffee dishes","https://en.wikipedia.org/wiki/List_of_coffee_dishes"]]},{"id":311,"title":"دسر‌های منجمد و اسموتی","body":"<h4 class=\"sub\">آفوگاتو</h4><ul><li>یک اسکوپ ژلاتو (فیوردی‌لاته یا وانیل) که اسپرسو روی آن ریخته می‌شود؛ گاهی آمارتو، کالوا یا لیکور دیگر اضافه می‌کنند و بیسکوتی کنارش سرو می‌شود.</li><li>خاستگاه ناشناخته است؛ واژه در ۱۹۸۸ برای نخستین‌بار در فرهنگ‌های انگلیسی ثبت شد. در ایتالیا معمولاً دسر و خارج از ایتالیا اغلب نوشیدنی است.</li><li>نام آفوگاتو (آفوگاتو آل کافه) به‌معنای تحت‌اللفظی «غرق‌شده در قهوه» است.</li><li>معمولاً در لیوان بلند با ته باریک سرو می‌شود تا بستنی در اسپرسو آب شود، و با قاشق یا نی خورده می‌شود.</li><li>یک دستور خانگی برای یک نفر نیم فنجان ژلاتوی وانیلی با یک شات اسپرسوی داغ (حدود ۴۴ میلی‌لیتر) است؛ قهوه‌ی دم‌شده‌ی خیلی قوی هم جای اسپرسو می‌نشیند.</li><li>برای اینکه ژلاتو شکلش را بیشتر نگه دارد، لیوان را از قبل سرد کنید و فوراً سرو کنید تا بافت‌ها از هم جدا بمانند.</li><li>گونه‌ها شامل افزودن آمارتو، بیچرین یا کالوا، یا ژلاتو با ویسکی، شکلات داغ، کیرش، وین‌سانتو و شراب پورت است.</li></ul>","kind":"item","src":[["Wikipedia — Affogato","https://en.wikipedia.org/wiki/Affogato"],["Once Upon a Chef — Affogato recipe","https://www.onceuponachef.com/recipes/affogato.html"],["Simply Scratch — Affogato","https://www.simplyscratch.com/affogato/"]]},{"id":312,"title":"غذاها و دسرهای دارای قهوه","body":"<h4 class=\"sub\">غذاهای دارای قهوه</h4><ul><li>Café liégeois: دسر سرد از قهوه‌ی کمی شیرین، بستنی با طعم قهوه و خامه‌ی شانتیی.</li><li>Opera cake: کیک لایه‌ای اسفنج بادام آغشته به شربت قهوه، با گاناش، باترکریم قهوه و روکش شکلات.</li><li>Tiramisu: با لیکور قهوه تهیه می‌شود.</li><li>سس قهوه: سس حاوی قهوه (گاهی با قهوه‌ی فوری)، شیرین یا شور؛ در آشپزی آمریکایی دست‌کم از ۱۹۰۴ دیده شده است. نسخه‌ی شیرین از شکر، شربت ساده، شربت افرا یا شربت طلایی ساخته می‌شود و گاهی شیر تبخیرشده، ویسکی، تخم‌مرغ و خامه دارد؛ روی کیک، بستنی، پنکیک، پودینگ، وافل، فلان و سیب‌زمینی شیرین و نسخه‌ی شور برای ماهی سالمون و استیک.</li><li>در پورتوریکو برخی قنادی‌ها شیرینی‌های محلی مثل فلان قهوه می‌سازند.</li></ul>","kind":"item","src":[["Wikipedia — List of coffee dishes","https://en.wikipedia.org/wiki/List_of_coffee_dishes"],["Wikipedia — Coffee sauce","https://en.wikipedia.org/wiki/Coffee_sauce"],["Wikipedia — Social aspects of coffee","https://en.wikipedia.org/wiki/Social_aspects_of_coffee"]]},{"id":313,"title":"نوشیدنی‌های ترکیبی خاص","body":"<h4 class=\"sub\">نوشیدنی‌های ترکیبی</h4><ul><li>یوئن‌یوئنگ: قهوه با چای (هنگ‌کنگ، ۱۹۳۶).</li><li>قهوه‌ی تخم‌مرغ ویتنامی (هانوی، اواخر دهه‌ی ۱۹۴۰) و دالگونا (مکائو ۱۹۹۷، جهانی‌شدن ۲۰۲۰).</li></ul>","kind":"item","src":[["Wikipedia — Coffee culture","https://en.wikipedia.org/wiki/Coffee_culture"],["Wikipedia — Egg coffee","https://en.wikipedia.org/wiki/Egg_coffee"],["Wikipedia — Dalgona coffee","https://en.wikipedia.org/wiki/Dalgona_coffee"]]}]},{"id":"C8","icon":"sensory","title":"حسیات، کیاپینگ، گریدبندی و عیب‌یابی","items":[{"id":6,"title":"آنالیز حسی (کیاپینگ) (Sensory Analysis)","body":"<h4>پروتکل کاپینگ SCA (خلاصه)</h4><ul><li>نسبت: ۸ تا ۸٫۵ گرم قهوه به ازای هر ۱۵۰ میلی‌لیتر آب؛ آسیاب کمی درشت‌تر از فیلتر معمولی، به‌طوری که ۷۰ تا ۷۵٪ ذرات از الک شماره‌ی ۲۰ (US) رد شوند.</li><li>آب: حدود ۹۳°C؛ پس از ریختن آب، طبق پروتکل ۳ تا ۵ دقیقه قبل از ارزیابی صبر کنید.</li><li>عطر خشک و مرطوب را قبل از شکستن لایه‌ی بالایی (کراست) ببویید، سپس با قاشق مزه کنید.</li><li>معیارها: عطر، طعم، پس‌طعم، اسیدیته، بدنه، تعادل، یکنواختی، فنجان تمیز، شیرینی و امتیاز کلی.</li><li>امتیاز ۸۰ و بالاتر «قهوه‌ی تخصصی» محسوب می‌شود.</li></ul><p>نمونه‌ها با چند فنجان تکرار می‌شوند و باید از نظر تازگی برشته‌کاری یکسان باشند.</p>","kind":"item","src":[["SCA — Cupping Protocol","https://sca.coffee/research/protocols-best-practices"]]},{"id":164,"title":"عیب‌یابی (Troubleshooting)","body":"<h4 class=\"sub\">عیب‌یابی بر پایه‌ی استخراج</h4><ul><li>بازده استخراج مطلوب برای بیشتر نوشیدنی‌های سنتی قهوه ۱۸٪ تا ۲۲٪ است.</li><li>زیر ۱۸٪ (کم‌استخراج): ترشِ ناموزون، چون اسیدها زودتر حل می‌شوند و قندها و ترکیبات تلخ‌کننده‌ی متعادل‌کننده دیرتر.</li><li>بالای ۲۲٪ (بیش‌استخراج): غالباً تلخ. (تجهیزات پیشرفته می‌توانند بدون این تلخی از ۲۲٪ بگذرند.)</li><li>غلظت (TDS) = نسبت دم × درصد استخراج. بازه‌های معمول: آمریکای شمالی ۱٫۱۵–۱٫۳۵٪؛ کشورهای شمال اروپا ۱٫۳۰–۱٫۵۰٪؛ اروپا ۱٫۲۰–۱٫۴۵٪. ریسترتو بیش از ۵٪ مواد محلول دارد.</li><li>نمودار کنترل دم‌آوری (SCAA): ناحیه‌ی بهینه مستطیلی در مرکز است که نه بیش‌استخراج است و نه کم‌استخراج، نه خیلی قوی و نه خیلی ضعیف؛ نسخه‌های SCAE (اروپایی) و NCA (نروژی) هم هستند.</li></ul>","kind":"item","src":[["Wikipedia — Coffee extraction","https://en.wikipedia.org/wiki/Coffee_extraction"]]},{"id":170,"title":"گرید‌های قهوه و عیوب (Grading & Defects)","body":"<h4>درجه‌بندی قهوه‌ی سبز بر پایه‌ی طبقه‌بندی SCAA</h4><ul><li>در این طبقه‌بندی، نمونه‌ی بررسی‌شده ۳۰۰ گرم قهوه‌ی پوست‌گرفته است (در عمل اغلب ۱۰۰ گرم هم استفاده می‌شود).</li><li>عیب‌ها دو دسته‌اند: عیب‌های اولیه (دسته‌ی ۱) و عیب‌های ثانویه (دسته‌ی ۲)؛ هر عیب بر حسب تعداد معادل «یک عیب کامل» شمرده می‌شود.</li></ul><div class=\"table-wrap\"><table><thead><tr><th>درجه</th><th>حداکثر عیب کامل</th><th>شرط‌ها</th></tr></thead><tbody><tr><td>تخصصی (۱)</td><td>۵</td><td>بدون عیب اولیه؛ بدون طعم ناخوشایند (Fault/Taint)</td></tr><tr><td>ممتاز (۲)</td><td>۸</td><td>عیب اولیه مجاز؛ تا ۳ کوئیکر</td></tr><tr><td>تجاری (Exchange، ۳)</td><td>۹ تا ۲۳</td><td>بدون طعم ناخوشایند؛ تا ۵ کوئیکر</td></tr><tr><td>زیر استاندارد (۴)</td><td>۲۴ تا ۸۶</td><td>شرط کیفی خاصی ندارد</td></tr><tr><td>خارج از درجه (۵)</td><td>بیش از ۸۶</td><td>پایین‌ترین دسته</td></tr></tbody></table></div><p>برای «قهوه‌ی تخصصی» علاوه بر این، پروتکل SCA امتیاز کاپینگ حداقل ۸۰ را می‌خواهد (نمونه: «صفر عیب دسته‌ی ۱ و حداکثر ۵ عیب دسته‌ی ۲»).</p>","kind":"item","src":[["FAO — Green Coffee Classification and Grading (SCAA)","https://www.fao.org/4/x6939e/x6939e13.htm"],["SCA — Cupping Protocol","https://sca.coffee/research/protocols-best-practices"]]},{"id":171,"title":"عیب‌های دانه‌ی سبز (دسته‌ی ۱ و ۲)","body":"<h4>عیب‌های دسته‌ی ۱ (اولیه)</h4><div class=\"table-wrap\"><table><thead><tr><th>عیب</th><th>تعداد معادل یک عیب کامل</th></tr></thead><tbody><tr><td>سیاه کامل (Full Black)</td><td>۱</td></tr><tr><td>ترش کامل (Full Sour)</td><td>۱</td></tr><tr><td>میوه‌ی خشک/غلاف (Pod/Cherry)</td><td>۱</td></tr><tr><td>سنگ بزرگ</td><td>۲</td></tr><tr><td>سنگ متوسط</td><td>۵</td></tr><tr><td>چوب بزرگ</td><td>۲</td></tr><tr><td>چوب متوسط</td><td>۵</td></tr></tbody></table></div><h4>عیب‌های دسته‌ی ۲ (ثانویه)</h4><div class=\"table-wrap\"><table><thead><tr><th>عیب</th><th>تعداد معادل یک عیب کامل</th></tr></thead><tbody><tr><td>پوستک (Parchment)</td><td>۲ تا ۳</td></tr><tr><td>پوسته (Hull/Husk)</td><td>۲ تا ۳</td></tr><tr><td>شکسته/ترک‌خورده</td><td>۵</td></tr><tr><td>آسیب حشره</td><td>۲ تا ۵</td></tr><tr><td>نیمه‌سیاه (Partial Black)</td><td>۲ تا ۳</td></tr><tr><td>نیمه‌ترش (Partial Sour)</td><td>۲ تا ۳</td></tr><tr><td>شناور (Floater)</td><td>۵</td></tr><tr><td>صدف‌شکل (Shell)</td><td>۵</td></tr><tr><td>سنگ کوچک</td><td>۱</td></tr><tr><td>چوب کوچک</td><td>۱</td></tr><tr><td>آسیب آب</td><td>۲ تا ۵</td></tr></tbody></table></div><p>این جدول از طبقه‌بندی SCAA نقل‌شده در FAO است؛ ویرایش‌های جدیدتر SCA ممکن است تفاوت‌هایی داشته باشند.</p>","kind":"item","src":[["FAO — Green Coffee Classification and Grading (SCAA)","https://www.fao.org/4/x6939e/x6939e13.htm"]]},{"id":179,"title":"روش‌های اندازهگیری و کنترل کیفیت پیشرفته (QC)","body":"<h4 class=\"sub\">کنترل کیفیت</h4><ul><li>بازده استخراج مطلوب برای بیشتر نوشیدنی‌های سنتی قهوه ۱۸٪ تا ۲۲٪ است.</li><li>زیر ۱۸٪ (کم‌استخراج): ترشِ ناموزون، چون اسیدها زودتر حل می‌شوند و قندها و ترکیبات تلخ‌کننده‌ی متعادل‌کننده دیرتر.</li><li>بالای ۲۲٪ (بیش‌استخراج): غالباً تلخ. (تجهیزات پیشرفته می‌توانند بدون این تلخی از ۲۲٪ بگذرند.)</li><li>غلظت (TDS) = نسبت دم × درصد استخراج. بازه‌های معمول: آمریکای شمالی ۱٫۱۵–۱٫۳۵٪؛ کشورهای شمال اروپا ۱٫۳۰–۱٫۵۰٪؛ اروپا ۱٫۲۰–۱٫۴۵٪. ریسترتو بیش از ۵٪ مواد محلول دارد.</li><li>نمودار کنترل دم‌آوری (SCAA): ناحیه‌ی بهینه مستطیلی در مرکز است که نه بیش‌استخراج است و نه کم‌استخراج، نه خیلی قوی و نه خیلی ضعیف؛ نسخه‌های SCAE (اروپایی) و NCA (نروژی) هم هستند.</li></ul>","kind":"item","src":[["Wikipedia — Coffee extraction","https://en.wikipedia.org/wiki/Coffee_extraction"]]},{"id":191,"title":"تشخیص دانه‌های معیوب با چشم غیرمسلح (برای خریداران حرفه‌ای)","body":"<h4 class=\"sub\">عیب دانه</h4><ul><li>قهوه‌ی اسپشیالتی (واژه‌ی Erna Knutsen، ۱۹۷۴) باید امتیاز ۸۰ یا بیشتر در فرم کاپینگ SCA بگیرد.</li><li>حداکثر ۵ عیب در هر ۳۵۰ گرم دانه‌ی فرآوری‌شده.</li><li>رده‌بندی: ۸۰–۸۴٫۹۹ بسیار خوب؛ ۸۵–۸۹٫۹۹ عالی؛ ۹۰–۱۰۰ برجسته.</li><li>پی‌بری (peaberry): دانه‌ی تک‌هسته‌ای که ۱۰ تا ۱۵ درصد دانه‌ها را می‌سازد؛ برتری طعمی آن باور رایج است نه حقیقت اثبات‌شده.</li><li>در طبقه‌بندی قهوه‌ی سبز SCA، عیب‌ها در دو رده‌ی اول (اولیه) و دوم (ثانویه) قرار می‌گیرند و وزن هر کدام به شدت عیب بستگی دارد.</li><li>یک دانه‌ی سیاه کامل (رده‌ی ۱) معادل سه دانه‌ی سیاه جزئی (رده‌ی ۲) است و پنج دانه‌ی شکسته یا بریده یک عیب کامل رده‌ی ۲ حساب می‌شود.</li><li>عیب‌های فنولی، سیب‌زمینی‌ای و کپک روی کیفیت فنجان اثر شدید دارند اما معمولاً با چشم دیده نمی‌شوند.</li><li>در طبقه‌بندی SCAA روی نمونه‌ی ۳۰۰ گرمی: درجه‌ی اسپشیالتی تا ۵ عیب کامل بدون عیب اولیه و بدون کواکر؛ درجه‌ی پریمیوم تا ۸ عیب کامل و تا ۳ کواکر؛ درجه‌ی اکسچنج ۹ تا ۲۳ عیب کامل.</li><li>پی‌بری‌ها (peaberry) که زمانی عیب به حساب می‌آمدند، امروز اغلب ارزشمند شمرده می‌شوند.</li></ul>","kind":"item","src":[["Wikipedia — Specialty coffee","https://en.wikipedia.org/wiki/Specialty_coffee"],["Wikipedia — Coffee bean","https://en.wikipedia.org/wiki/Coffee_bean"],["SCA — Grounding Green Grading in Sensory Science","https://sca.coffee/sca-news/25/issue-24-grounding-green-grading"],["FAO — Coffee: green coffee classification and grading","https://www.fao.org/4/X6939E/X6939e13.htm"]]},{"id":207,"title":"تأثیر «رنگ فنجان» بر درک طعم","body":"<h4 class=\"sub\">رنگ فنجان و طعم</h4><ul><li>پژوهش Van Doorn، Wuillemin و Spence (۲۰۱۴، Flavour): آزمایش ۱ با ۱۸ داوطلب و فنجان‌های سفید سرامیکی، شیشه‌ی شفاف و چینی آبی؛ آزمایش ۲ با ۳۶ داوطلب و فنجان‌های شیشه‌ای یکسان با دسته‌ی سفید، آبی یا شفاف.</li><li>آزمایش ۱: شدت قهوه در فنجان سفید به‌طور معنادار بیش از شیشه‌ی شفاف ارزیابی شد (p = ۰٫۰۲۶). شیرینی و تلخی تفاوت معناداری نداشتند.</li><li>آزمایش ۲: شیرینی در فنجان سفید معناداراً کمتر از شفاف و آبی بود (p = ۰٫۰۴۱)؛ در شدت و تلخی اثر معنادار نبود.</li><li>نویسندگان حدس می‌زنند زمینه‌ی سفید ظاهر «قهوه‌ای‌بودن» نوشیدنی را تغییر می‌دهد و بر شدت و شیرینی ادراک‌شده اثر می‌گذارد. نمونه‌ها کوچک بودند؛ نتیجه را قطعی ندانید.</li></ul>","kind":"item","src":[["Van Doorn, Wuillemin & Spence (2014), Flavour 3:10 — Does the colour of the mug influence the taste of the coffee?","https://flavourjournal.biomedcentral.com/articles/10.1186/2044-7248-3-10"]]},{"id":220,"title":"روش‌های اندازه‌گیری دقیق کیفیت قهوه (فراتر از کیاپینگ)","body":"<p>فراتر از کاپینگ، چند اندازه‌گیری عددی به کنترل کیفیت کمک می‌کند.</p><div class=\"table-wrap\"><table><thead><tr><th>آزمون</th><th>چه چیزی را می‌سنجد</th><th>مقدار مرجع</th></tr></thead><tbody><tr><td>رنگ (Agtron)</td><td>عدد درجه‌ی برشته‌کاری با اندازه‌گیری بازتاب نور؛ عدد کمتر یعنی تیره‌تر</td><td>روشن بیش از ۸۰ تا بسیار تیره ۲۵–۴۰ (جدول Coffee Review)</td></tr><tr><td>TDS (رفرکتومتری)</td><td>درصد مواد جامد محلول در فنجان</td><td>استاندارد «جام طلایی» SCAA: ۱٫۱۵ تا ۱٫۳۵٪</td></tr><tr><td>بازده استخراج (EY)</td><td>سهمی از قهوه که در آب حل شده</td><td>۱۸ تا ۲۲٪ در استاندارد جام طلایی</td></tr><tr><td>توزیع اندازه‌ی ذرات</td><td>یکنواختی آسیاب و میزان ذرات ریز</td><td>در پروتکل کاپینگ SCA: ۷۰–۷۵٪ ذرات از الک شماره‌ی ۲۰ رد شوند</td></tr></tbody></table></div><p>جام طلایی خود هم مورد انتقاد است و فقط یک راهنماست، نه قانون.</p>","kind":"item","src":[["Coffee Review — Roast definitions (Agtron)","https://www.coffeereview.com/roast-definitions/"],["Coffee Chronicler — Golden Cup standard","https://coffeechronicler.com/its-time-to-retire-the-golden-cup-standard/"],["SCA — Cupping Protocol","https://sca.coffee/research/protocols-best-practices"]]},{"id":221,"title":"عیوب پنهان در قهوه که حتی متخصصان هم ممکن است نادیده بگیرند","body":"<h4 class=\"sub\">عیوب مرتبط با فرآوری</h4><ul><li>شسته (washed): تخمیر ۸ تا ۳۶ ساعت و شست‌وشو؛ اگر تخمیر با دقت کنترل نشود طعم ترش ناخواسته می‌گیرد.</li><li>طبیعی (natural): خشک‌کردن کل گیلاس تا حدود چهار هفته؛ برای جلوگیری از کپک باید زیر و رو شود؛ در مناطق بسیار بارانی عملی نیست.</li><li>هانی (honey): بخشی از موسیلاژ روی دانه می‌ماند و در معرض کپک و باکتری است؛ دانه‌ها ۲ تا ۳ بار در ساعت زیر و رو می‌شوند. معمولاً بدنه‌ی شربتی، شیرینی بیشتر و اسیدیته‌ی گرد دارد.</li><li>فرآوری ماشینی بدون تخمیر ابزار تنظیم طعم را از فرآوری‌کننده می‌گیرد و خطر دانه‌ی شکسته را بالا می‌برد.</li></ul>","kind":"item","src":[["Wikipedia — Coffee processing","https://en.wikipedia.org/wiki/Coffee_processing"]]},{"id":224,"title":"عواملی که باعث تغییر طعم قهوه در طول روز می‌شوند (فیزیک حسی)","body":"<h4 class=\"sub\">عواملی که طعم را عوض می‌کنند</h4><ul><li>دما یک حس جداست و می‌تواند تجربه‌ی طعم را تغییر دهد؛ گرما برخی طعم‌ها را برجسته و برخی را کم‌رنگ می‌کند.</li><li>بو یکی از چند عامل تعیین‌کننده‌ی طعم است، کنار مزه، بافت و دما؛ ویروس‌هایی مثل آنفلوآنزا می‌توانند بویایی را مختل کنند.</li><li>پس‌مزه (aftertaste) ممکن است با خود غذا فرق داشته باشد.</li><li>گیرنده‌های مزه بیشترین پاسخ را به مولکول‌هایی دارند که در دمای اتاق یا کمی بالاتر (حدود ۲۰ تا ۳۵ درجه) هستند.</li><li>گیرنده‌های تلخی وقتی قهوه داغ است کم‌حساس‌ترند؛ پس قهوه‌ی داغ از قهوه‌ی هم‌دمای اتاق کم‌تلخ‌تر به نظر می‌رسد.</li><li>قهوه‌ی داغ ترکیبات معطر بیشتری آزاد می‌کند و این ترکیبات روی طعم دریافت‌شده اثر زیادی دارند.</li><li>طبق پژوهش UC Davis، بیشتر مردم قهوه‌ی سیاه را در ۵۸ تا ۶۶ درجه بیشتر می‌پسندند.</li></ul>","kind":"item","src":[["Wikipedia — Taste","https://en.wikipedia.org/wiki/Taste"],["Live Science — Why does room-temperature coffee taste so bad?","https://livescience.com/19288-room-temperature-coffee-taste.html"],["Barista Magazine — The temperature paradox: why specialty coffee tastes better cool","https://www.baristamagazine.com/the-temperature-paradox-why-specialty-coffee-tastes-better-cool/"]]},{"id":316,"title":"روان‌شناسی چشایی و تأثیر ذهن بر طعم (Sensory Psychology)","body":"<h4 class=\"sub\">مزه و بو</h4><ul><li>پنج مزه‌ی پایه: شیرینی، ترشی، شوری، تلخی و اومامی.</li><li>تلخی «یکی از حساس‌ترین مزه‌ها» است و احتمالاً نقش محافظتی دارد؛ تغییرات ژن TAS2R38 در شدت حس برخی ترکیبات تلخ اثر دارد.</li><li>بو، بافت، دما و chemesthesis (گرما یا خنکی) هم در طعم نقش دارند؛ مزه‌های پایه فقط بخشی از طعم هستند.</li><li>طعم تلخ در تعریف ویکی‌پدیا از حساس‌ترین مزه‌هاست؛ بسیاری آن را ناخوشایند می‌یابند، اما گاهی عمداً افزوده می‌شود.</li><li>گیرنده‌ی TAS2R38 از معدود گیرنده‌های چشایی است که اثرش بر نحوه‌ی چشیدن افراد نشان داده شده است؛ دو هاپلوتایپ رایج PAV («چشنده») و AVI («نا‌چشنده») دارد.</li><li>پژوهش‌ها جمعیت را حدود ۲۵٪ نا‌چشنده، ۵۰٪ چشنده‌ی متوسط و ۲۵٪ ابرچشنده می‌دانند؛ قهوه در میان غذاهایی فهرست شده که ابرچشنده‌ها کمتر می‌پسندند.</li><li>نمک مزه‌ی تلخی را سرکوب می‌کند؛ ابرچشنده‌ها معمولاً نمک بیشتری مصرف می‌کنند.</li><li>هنجارهای فرهنگی هم ادراک را شکل می‌دهند؛ غذایی که در فرهنگی سنتاً گرم خورده می‌شود، سرد معمولاً ناخوشایند به‌شمار می‌آید.</li></ul>","kind":"item","src":[["Wikipedia — Taste","https://en.wikipedia.org/wiki/Taste"],["Wikipedia — Supertaster","https://en.wikipedia.org/wiki/Supertaster"],["Wikipedia — TAS2R38","https://en.wikipedia.org/wiki/TAS2R38"]]},{"id":319,"title":"اصول «کیاپینگ» در خانه (ارزیابی حسی برای همه)","body":"<h4 class=\"sub\">کاپینگ</h4><ul><li>کاپینگ در اواخر قرن نوزدهم در آمریکا (از جمله با Hills Brothers سان‌فرانسیسکو) به رویه‌ی استاندارد صنعت تبدیل شد.</li><li>روش: عطر را عمیق ببویید و قهوه را از قاشق می‌مکید تا هوا بخورد و روی زبان پخش شود. آب معمولاً کمی کمتر از جوش است.</li><li>ویژگی‌های ارزیابی‌شده: بدنه، شیرینی، اسیدیته، طعم و پس‌طعم؛ توصیف‌ها مانند میوه‌ای/مرکباتی، شکلاتی، گلی و خاکی.</li><li>ابزار: تف‌دان، قاشق مخصوص دسته‌کوتاه و کاسه‌ی عمیق، فنجان شیشه‌ای ۸ اونسی (۲۴۰ میلی‌لیتر) و جداول نمونه.</li><li>برای این اعداد به پروتکل رسمی SCA مراجعه کنید.</li></ul>","kind":"item","src":[["Wikipedia — Coffee cupping","https://en.wikipedia.org/wiki/Coffee_cupping"]]},{"id":589,"title":"تکنیک Salami Shot و آنالیز برش‌های عصاره‌گیری","body":"<h4 class=\"sub\">Salami shot</h4><ul><li>تمرین آموزشی باریستا: یک شات اسپرسو به سه فنجان زمان‌بندی‌شده تقسیم می‌شود — ۱۰ ثانیه‌ی اول فنجان ۱، ۱۰ ثانیه‌ی بعد فنجان ۲، و بقیه فنجان ۳؛ سپس به ترتیب چشیده می‌شوند.</li><li>بخش اول: ترش و تیز (به‌ویژه برشته‌ی روشن)؛ میانی: شیرینی و میوه؛ انتها: تلخی — در برشته‌ی روشن ملایم و متعادل و در تیره تند و ماندگار.</li><li>نتیجه‌ی پیشنهادی: برشته‌ی روشن اغلب از استخراج طولانی‌تر سود می‌برد و تیره به شات کوتاه‌تر نیاز دارد؛ این روش کمک می‌کند طعم‌ها را جدا بشناسید و هنگام تنظیم (dial-in) تصمیم بگیرید.</li></ul>","kind":"item","src":[["Clive Coffee — The Salami Shot","https://clivecoffee.com/blogs/learn/the-salami-shot"]]},{"id":593,"title":"دایرةالمعارف حسی WCR (Sensory Lexicon)","body":"<h4 class=\"sub\">واژگان حسی</h4><ul><li>عطر: ۱۷ توصیف‌گر رایج از جمله حیوانی، خاکستری، شکلاتی، گلی، میوه‌ای/مرکباتی، آجیلی، ادویه‌ای و چوبی؛ برخی نامطلوب‌اند (مثلاً فاسد) و برخی (مثل حیوانی و لاستیکی) لزوماً منفی نیستند.</li><li>مزه‌های پایه: اسیدیته، تلخی، شیرینی، شوری و ترشی؛ اسیدیته مطلوب و ترشی ناخوشایند است.</li><li>بدنه (body): احساس فیزیکی نوشیدنی که با شیر کم‌چرب تا پرچرب مقایسه می‌شود. گس‌بودن (astringency): خشکی دهان که برای برخی نامطلوب است.</li></ul>","kind":"item","src":[["Wikipedia — Coffee tasting","https://en.wikipedia.org/wiki/Coffee_tasting"]]}]},{"id":"C9","icon":"health","title":"سلامت، فیزیولوژی و پزشکی قهوه","items":[{"id":7,"title":"تأثیرات فیزیولوژیکی (Physiological Effects)","body":"<ul><li>مکانیسم: کافئین گیرنده‌های آدنوزین (به‌ویژه A2a) را مهار می‌کند و همین بیداری را بالا می‌برد؛ آزادسازی کاتکول‌آمین‌ها هم بر قلب و رگ‌ها اثر می‌گذارد.</li><li>جذب: تقریباً کامل است و اوج غلظت خون ۳۰ دقیقه تا ۲ ساعت پس از نوشیدن رخ می‌دهد.</li><li>نیمه‌عمر: در بزرگسالان حدود ۵ ساعت؛ در سیگاری‌ها حدود نصف و در بارداری تا ۱۵ ساعت.</li><li>عوارض: ضربان قلب سریع، لرزش، بی‌خوابی، سردرد، تحریک معده و تکرر ادرار (Mayo Clinic).</li><li>قطع ناگهانی ممکن است سردرد، خستگی، تحریک‌پذیری و ضعف تمرکز بدهد و معمولاً طی چند روز برطرف می‌شود (Mayo Clinic).</li></ul>","kind":"item","src":[["StatPearls — Caffeine (NCBI Bookshelf)","https://www.ncbi.nlm.nih.gov/books/NBK519490/"],["Mayo Clinic — Caffeine: How much is too much?","https://www.mayoclinic.org/healthy-lifestyle/nutrition-and-healthy-eating/in-depth/caffeine/art-20045678"]]},{"id":15,"title":"تحلیل ریسک‌ها و موارد منع مصرف (صرفاً اطلاع‌رسانی، بدون اخلاق‌گرایی)","body":"<ul><li>بارداری: ACOG مصرف کمتر از ۲۰۰ میلی‌گرم در روز را «متوسط» می‌داند؛ FDA و Mayo Clinic هم می‌گویند باردار، در حال تلاش برای بارداری یا شیرده با پزشک درباره‌ی محدودیت مشورت کند.</li><li>مصرف همراه با داروهای حاوی افدرین می‌تواند فشار خون را بالا ببرد و خطر حمله‌ی قلبی، سکته یا تشنج را زیاد کند (Mayo Clinic).</li><li>کافئین ممکن است اضطراب، بی‌اختیاری ادرار یا اختلال تشنجی را بدتر کند (Mayo Clinic).</li><li>کافئین با آنزیم CYP1A2 متابولیزه می‌شود؛ داروهایی که این آنزیم را مهار می‌کنند (مثلاً تیزانیدین که نباید همزمان مصرف شود) با آن تداخل دارند (StatPearls). فهرست کامل را از داروساز یا پزشک بپرسید.</li></ul><p>این مطلب اطلاع‌رسانی است و جایگزین نظر پزشک نیست.</p>","kind":"item","src":[["ACOG — Moderate Caffeine Consumption During Pregnancy","https://www.acog.org/clinical/clinical-guidance/committee-opinion/articles/2010/08/moderate-caffeine-consumption-during-pregnancy"],["Mayo Clinic — Caffeine: How much is too much?","https://www.mayoclinic.org/healthy-lifestyle/nutrition-and-healthy-eating/in-depth/caffeine/art-20045678"],["StatPearls — Caffeine (NCBI Bookshelf)","https://www.ncbi.nlm.nih.gov/books/NBK519490/"],["FDA — Spilling the Beans: How Much Caffeine Is Too Much?","https://www.fda.gov/consumers/consumer-updates/spilling-beans-how-much-caffeine-too-much"]]},{"id":160,"title":"نکات ایمنی، بهداشت و واکنش‌های جانبی","body":"<h4>مسمومیت با کافئین</h4><ul><li>علائم مصرف زیاد (FDA): افزایش ضربان قلب، تپش قلب، فشار خون بالا، بی‌خوابی، اضطراب، لرزش، دل‌آشوبه و تهوع، سردرد.</li><li>اثرات سمی مانند تشنج می‌تواند با مصرف سریع حدود ۱۲۰۰ میلی‌گرم (کمتر از نصف قاشق چای‌خوری کافئین خالص) دیده شود (FDA).</li><li>دُز کشنده در منابع بالینی ۱۰ تا ۱۴ گرم گزارش شده است (StatPearls).</li><li>مقدار توصیه‌شده‌ی روزانه برای بیشتر بزرگسالان: حداکثر ۴۰۰ میلی‌گرم (FDA)؛ EFSA هم همین عدد و دُز تکی ۲۰۰ میلی‌گرم را نگران‌کننده نمی‌داند.</li><li>محصولات کافئین خالص و غلیظ می‌توانند عواقب جدی و حتی مرگ داشته باشند (FDA).</li></ul><h4>تداخل با داروها و عوامل مؤثر بر متابولیسم کافئین</h4><ul><li>نیمه‌عمر کافئین در بزرگسالان سالم بین ۳ تا ۷ ساعت است.</li><li>کافئین سوبسترای آنزیم CYP1A2 است. داروی ضدافسردگی فلووکسامین دفع کافئین را بیش از ۹۰٪ کم می‌کند و نیمه‌عمر آن را از ۴٫۹ ساعت به ۵۶ ساعت می‌رساند.</li><li>سیگار نیمه‌عمر را در مردان سیگاری ۳۰ تا ۵۰٪ کوتاه می‌کند.</li><li>در زنانی که قرص ضدبارداری می‌خورند نیمه‌عمر تقریباً دو برابر می‌شود.</li><li>در بارداری، به‌ویژه سه‌ماهه‌ی سوم، متابولیسم کافئین کند می‌شود و نیمه‌عمر تا ۱۵ ساعت می‌رسد (در مقابل ۲٫۵ تا ۴٫۵ ساعت در بزرگسالان غیرباردار).</li><li>اگر دارو مصرف می‌کنید، تداخل را از پزشک یا داروساز بپرسید.</li></ul>","kind":"item","src":[["FDA — Spilling the Beans: How Much Caffeine Is Too Much?","https://www.fda.gov/consumers/consumer-updates/spilling-beans-how-much-caffeine-too-much"],["StatPearls — Caffeine (NCBI Bookshelf)","https://www.ncbi.nlm.nih.gov/books/NBK519490/"],["EFSA — Caffeine","https://www.efsa.europa.eu/en/topics/topic/caffeine"],["Wikipedia — Caffeine (بخش‌های فارماکوکینتیک و تداخل دارویی، با ارجاع به منابع اولیه)","https://en.wikipedia.org/wiki/Caffeine"]]},{"id":177,"title":"قهوه و سلامت روان (مکانیسم‌های عصبی) – ناگفته","body":"<p>قهوه و سلامت روان:</p><ul><li>کافئین دوزهای بالا می‌تواند اضطراب، لرزش و تپش قلب را بیشتر کند؛ در افراد مبتلا به اختلال پانیک حساسیت بیشتر است.</li><li>مصرف متعادل در مطالعات مشاهده‌ای با خلق بهتر یا خطر افسردگی کمتر همراه بوده، اما علّیت ثابت نیست.</li><li>نیمه‌عمر کافئین در بزرگسالان حدود ۵ ساعت است و در سیگاری‌ها حدود نصف و در بارداری تا ۱۵ ساعت می‌شود (StatPearls).</li><li>قطع ناگهانی کافئین ممکن است چند روز خلق پایین، خستگی و سردرد بدهد.</li></ul>","kind":"item","src":[["StatPearls — Caffeine (NCBI Bookshelf)","https://www.ncbi.nlm.nih.gov/books/NBK519490/"],["Mayo Clinic — Caffeine: How much is too much?","https://www.mayoclinic.org/healthy-lifestyle/nutrition-and-healthy-eating/in-depth/caffeine/art-20045678"]]},{"id":197,"title":"قهوه در طب سنتی ایرانی و چینی (مکمل بخش سلامت)","body":"<h4>قهوه در متون پزشکی کهن</h4><ul><li>اولین اشاره‌ی پزشکی که معمولاً به قهوه نسبت می‌دهند، واژه‌ی «بونچوم» در آثار رازی (پزشک ایرانی سده‌ی دهم میلادی) است؛ اما روایت‌های بعدی می‌گویند بونچوم از ریشه‌ی یک گیاه ساخته می‌شد، نه از دانه‌ی قهوه.</li><li>شواهد تاریخی یا باستان‌شناختی تأییدشده‌ای از نوشیدن قهوه پیش از سده‌ی پانزدهم وجود ندارد.</li><li>پزشکان و دانشمندان اولیه‌ی دنیای اسلام با این تصور که اثر قهوه شبیه حشیش یا الکل است مخالفت کردند.</li></ul><h4>چارچوب مزاج‌شناسی (Humorism)</h4><p>طب سنتی ایرانی بر نظریه‌ی اخلاط و مزاج بنا شده است. ابن‌سینا در «قانون» (۱۰۲۵ میلادی) این نظریه‌ی یونانی-رومی را نظام‌مند کرد و بیماری و درمان را بر پایه‌ی کیفیت‌های گرم/سرد و تر/خشک دسته‌بندی کرد.</p><div class=\"table-wrap\"><table><thead><tr><th>خلط</th><th>کیفیت</th><th>مزاج</th></tr></thead><tbody><tr><td>خون</td><td>گرم و تر</td><td>دموی</td></tr><tr><td>صفرا</td><td>گرم و خشک</td><td>صفراوی</td></tr><tr><td>سودا</td><td>سرد و خشک</td><td>سوداوی</td></tr><tr><td>بلغم</td><td>سرد و تر</td><td>بلغمی</td></tr></tbody></table></div><p>جایگاه علمی: اشاره شده که نظریه‌ی اخلاط تا ۱۸۵۸ به‌طور قطعی رد نشده بود، اما امروز شبه‌علم شناخته می‌شود؛ کشف میکروب‌ها توضیح اخلاطی بیماری را کنار زد.</p><h4>طب سنتی چینی</h4><p>درباره‌ی TCM، مفاهیمی مثل چی و مریدین شواهد علمی ندارند: سرمقاله‌ی Nature در ۲۰۰۷ نوشت این طب «کم‌پژوهش و بدون پشتوانه است و بیشتر درمان‌هایش مکانیسم منطقی ندارند».</p>","kind":"item","src":[["Wikipedia — History of coffee","https://en.wikipedia.org/wiki/History_of_coffee"],["Wikipedia — Humorism","https://en.wikipedia.org/wiki/Humorism"],["Wikipedia — Traditional Chinese medicine (با ارجاع به سرمقاله‌ی Nature 2007)","https://en.wikipedia.org/wiki/Traditional_Chinese_medicine"]]},{"id":199,"title":"تأثیر قهوه بر میکروبیوم روده (جدیدترین تحقیقات ۲۰۲۴–۲۰۲۵)","body":"<p>مرور ادبیاتی در مجله‌ی <em>Nutrients</em> (۲۰۲۴) شواهد انسانی و حیوانی درباره‌ی اثر قهوه بر میکروبیوتای روده را جمع‌بندی کرده است.</p><ul><li>به گزارش این مرور، بیشترِ مطالعات نشان داده‌اند مصرف متوسط قهوه (کمتر از ۴ فنجان در روز) نسبت نسبی شاخه‌های باکتریایی Firmicutes و Actinobacteria را بالا و Bacteroidetes را پایین می‌برد.</li><li>مصرف متوسط، Bifidobacterium را افزایش و Enterobacteria را کاهش داده است.</li><li>قهوه بر حرکات، ترشح و جذب در روده اثر دارد.</li><li>مصرف زیاد (بیش از ۵ فنجان در روز) در این مرور با ریفلاکس، بیماری‌های پریودنتال و پیشرفت بیماری کرون مرتبط دانسته شده است.</li></ul><p>نویسندگان نتیجه می‌گیرند اثرهای مفید مصرف متوسط روی میکروبیوتا و حرکات روده «پیشنهاد می‌شود»؛ این مرور ادبیاتی است و ارتباط‌ها لزوماً علت‌ومعلولی نیستند.</p>","kind":"item","src":[["Saygili S, Hegde S, Shi XZ. Effects of Coffee on Gut Microbiota and Bowel Functions in Health and Diseases: A Literature Review. Nutrients 2024;16(18):3155","https://research.lstmed.ac.uk/en/publications/effects-of-coffee-on-gut-microbiota-and-bowel-functions-in-health-6/"]]},{"id":201,"title":"تأثیر قهوه بر روی متابولیسم چربی","body":"<p>یک فرامطالعه‌ی ۱۸ کارآزمایی تصادفی‌شده (۲۲۸ بزرگسال) نشان داد مکمل کافئین پیش از ورزش هوازی در حالت سیر (کمتر از ۵ ساعت پس از غذا) اکسیداسیون چربی را «تا حدی متوسط» افزایش می‌دهد.</p><ul><li>دُزها ۳ تا ۹ میلی‌گرم به ازای هر کیلوگرم وزن بدن بودند و ۳۰ تا ۱۲۰ دقیقه قبل از ورزش داده شدند.</li><li>اثر در دُزهای کمتر از ۶ mg/kg دیده شد، نه در ۶ mg/kg و بالاتر (احتمالاً متأثر از یک کارآزمایی پرت).</li><li>در مصرف‌کنندگان عادتیِ کافئین اثر معناداری دیده نشد، اما فقط ۳ کارآزمایی این زیرگروه را بررسی کرده بودند.</li><li>این یافته مربوط به کافئینِ مکمل در زمان ورزش است، نه اثر قهوه بر کاهش وزن.</li></ul>","kind":"item","src":[["Examine: Caffeine increases fat oxidation during fed-state aerobic exercise (خلاصه‌ی فرامطالعه‌ی ۱۸ کارآزمایی)","https://examine.com/research-feed/study/9oxPLd"]]},{"id":202,"title":"تأثیر قهوه بر روی باروری و بارداری (با اعداد دقیق)","body":"<ul><li>ACOG مصرف کمتر از ۲۰۰ میلی‌گرم کافئین در روز را در بارداری «متوسط» می‌داند؛ EFSA هم برای بارداری و شیردهی سقف ۲۰۰ میلی‌گرم در روز را بی‌خطر می‌داند.</li><li>درباره‌ی سقط: ACOG می‌گوید یک مطالعه‌ی بزرگ هیچ رابطه‌ای بین مصرف کافئین و خطر سقط ندید و مطالعه‌ی دیگری در دُزهای بالاتر خطر بیشتری یافت؛ به همین دلیل درباره‌ی مصرف زیاد توصیه‌ی قطعی ممکن نیست.</li><li>درباره‌ی زایمان زودرس: دو مطالعه‌ی بزرگ ارتباطی نیافتند و مصرف متوسط عامل زایمان زودرس به نظر نمی‌رسد (ACOG).</li><li>همیشه با پزشک مشورت کنید.</li></ul>","kind":"item","src":[["ACOG — Moderate Caffeine Consumption During Pregnancy","https://www.acog.org/clinical/clinical-guidance/committee-opinion/articles/2010/08/moderate-caffeine-consumption-during-pregnancy"],["EFSA — Caffeine","https://www.efsa.europa.eu/en/topics/topic/caffeine"]]},{"id":210,"title":"قهوه و «کیفیت خواب» – نکته‌ای که هیچ‌کس نگفته","body":"<ul><li>کافئین گیرنده‌ی آدنوزین را مهار می‌کند و خواب‌آلودگی را عقب می‌اندازد (StatPearls).</li><li>در یک کارآزمایی خانگی (Drake و همکاران، ۲۰۱۳) دُز ثابت ۴۰۰ میلی‌گرم کافئین در لحظه‌ی خواب، ۳ ساعت و حتی ۶ ساعت قبل از خواب در مقایسه با دارونما اختلال معنادار خواب ایجاد کرد؛ نویسندگان توصیه کردند مصرف قابل‌توجه کافئین دست‌کم ۶ ساعت قبل از خواب قطع شود.</li><li>حساسیت افراد فرق می‌کند و نیمه‌عمر کافئین حدود ۵ ساعت (با تغییرات زیاد) است.</li></ul>","kind":"item","src":[["Drake et al. 2013, J Clin Sleep Med — Caffeine effects on sleep taken 0, 3, or 6 hours before going to bed","https://pubmed.ncbi.nlm.nih.gov/24235903/"],["StatPearls — Caffeine (NCBI Bookshelf)","https://www.ncbi.nlm.nih.gov/books/NBK519490/"]]},{"id":212,"title":"قهوه و «پیری» (Anti-Aging)","body":"<p>شواهد ضدپیری مستقیم برای قهوه وجود ندارد.</p><ul><li>مرور چتری BMJ (۲۰۱۷) در مصرف حدود ۳ تا ۴ فنجان در روز خطر نسبی مرگ‌ومیر کلی ۰٫۸۳ گزارش کرد؛ اما مطالعات مشاهده‌ای‌اند و علّیت اثبات نشده است.</li><li>قهوه سرشار از ترکیبات فنلی و آنتی‌اکسیدان است، ولی «آنتی‌اکسیدان بالا» لزوماً به معنی پیری کندتر نیست.</li><li>اصلی‌ترین عوامل سالمندی سالم: خواب، تحرک، تغذیه و عدم مصرف دخانیات.</li></ul>","kind":"item","src":[["Poole et al. 2017, BMJ — Coffee consumption and health: umbrella review of meta-analyses","https://www.bmj.com/content/359/bmj.j5024"]]},{"id":225,"title":"تأثیر قهوه بر روی هورمون‌های استرس (کورتیزول)","body":"<p>در مطالعه‌ی Lovallo و همکاران (۲۰۰۵) روی مصرف‌کنندگان روزانه‌ی کافئین، پاسخ کورتیزول به کافئین با مصرف مداوم کاهش می‌یابد ولی از بین نمی‌رود.</p><ul><li>پس از پرهیز از کافئین، یک دُز آزمایشی در طول روز افزایش چشمگیر کورتیزول ایجاد کرد.</li><li>پس از ۵ روز مصرف ۳۰۰ mg در روز، پاسخ تا حدی کاهش یافت اما در ساعات بعدازظهر هنوز بالا بود.</li><li>پس از ۵ روز مصرف ۶۰۰ mg در روز، تحمل کامل‌تر بود و افزایش کورتیزول فقط مدت کوتاهی پس از دُز میانه‌ی روز دیده شد.</li></ul>","kind":"item","src":[["Lovallo WR et al. Caffeine stimulation of cortisol secretion across the waking hours in relation to caffeine intake levels. Psychosom Med 2005","https://pmc.ncbi.nlm.nih.gov/articles/PMC2257922/"]]},{"id":321,"title":"قهوه و سلامت (Health)","body":"<h4>خلاصه‌ی شواهد (مرور چتری BMJ ۲۰۱۷)</h4><p>این مرور ۲۰۱ فراتحلیل از مطالعات مشاهده‌ای و ۱۷ فراتحلیل از مطالعات مداخله‌ای را بررسی کرد. نتیجه‌ی نویسندگان: مصرف قهوه در حد معمول به‌طور کلی بی‌خطر به نظر می‌رسد.</p><div class=\"table-wrap\"><table><thead><tr><th>پیامد</th><th>یافته (در مقایسه با مصرف‌نکردن)</th></tr></thead><tbody><tr><td>مرگ‌ومیر کلی</td><td>خطر نسبی ۰٫۸۳ در حدود ۳ تا ۴ فنجان در روز</td></tr><tr><td>مرگ‌ومیر قلبی‌عروقی</td><td>خطر نسبی ۰٫۸۱</td></tr><tr><td>بیماری قلبی‌عروقی</td><td>خطر نسبی ۰٫۸۵</td></tr><tr><td>سرطان (مصرف زیاد در برابر کم)</td><td>۱۸٪ خطر کمتر</td></tr><tr><td>دیابت نوع ۲</td><td>فواید در سطوح مختلف مصرف</td></tr><tr><td>کبد</td><td>قوی‌ترین ارتباط؛ کاهش خطر سیروز و فیبروز</td></tr></tbody></table></div><h4>هشدارها</h4><ul><li>بارداری: مصرف زیاد با افزایش خطر وزن کم هنگام تولد (OR ۱٫۳۱)، زایمان زودرس در سه‌ماهه‌ی اول (۱٫۲۲) و از دست رفتن بارداری (۱٫۴۶) همراه بوده است.</li><li>شکستگی در زنان: افزایش خطر اندک، در حالی که در مردان اثر محافظتی دیده شد.</li><li>قهوه‌ی بدون فیلتر: دی‌ترپن‌ها LDL و تری‌گلیسرید را بالا می‌برند (Harvard).</li><li>عوارض کافئین زیاد: سردرد، بی‌خوابی، عصبی‌بودن، تپش قلب، لرزش و تحریک معده (Mayo Clinic).</li></ul><p>این یافته‌ها از مطالعات مشاهده‌ای‌اند و علّیت قطعی را اثبات نمی‌کنند.</p>","kind":"item","src":[["Poole et al. 2017, BMJ — Coffee consumption and health: umbrella review of meta-analyses","https://www.bmj.com/content/359/bmj.j5024"],["Harvard T.H. Chan — Coffee","https://nutritionsource.hsph.harvard.edu/food-features/coffee/"],["Mayo Clinic — Caffeine","https://www.mayoclinic.org/healthy-lifestyle/nutrition-and-healthy-eating/in-depth/caffeine/art-20045678"]]},{"id":381,"title":"قهوه و علوم اعصاب (Coffee & Neuroscience)","body":"<h4>مکانیسم: آدنوزین</h4><ul><li>کافئین گیرنده‌های آدنوزین (A1، A2a، A2b، A3) را مهار می‌کند؛ مهار A2a به‌ویژه مسئول اثر بیداری است.</li><li>کافئین آزادسازی کاتکول‌آمین‌ها را هم تحریک می‌کند و بر قلب و رگ‌ها اثر می‌گذارد.</li></ul><h4>جذب و نیمه‌عمر</h4><ul><li>جذب خوراکی تقریباً کامل است؛ اوج غلظت ۳۰ دقیقه تا ۲ ساعت بعد.</li><li>نیمه‌عمر در بزرگسالان حدود ۵ ساعت؛ در سیگاری‌ها حدود نصف و در بارداری تا ۱۵ ساعت.</li><li>متابولیسم کافئین با آنزیم CYP1A2 انجام می‌شود.</li></ul><h4>خواب</h4><p>در کارآزمایی Drake و همکاران (۲۰۱۳) دُز ۴۰۰ میلی‌گرم حتی ۶ ساعت قبل از خواب اختلال معنادار خواب ایجاد کرد؛ نویسندگان توصیه کردند مصرف قابل‌توجه کافئین دست‌کم ۶ ساعت قبل از خواب قطع شود.</p><h4>قطع کافئین</h4><ul><li>شروع علائم: ۱۲ تا ۲۴ ساعت پس از قطع؛ اوج: ۲۰ تا ۵۱ ساعت؛ مدت: ۲ تا ۹ روز.</li><li>علائم: سردرد (تا حدود ۵۰٪ موارد)، خستگی، خواب‌آلودگی، تحریک‌پذیری و ضعف تمرکز.</li><li>حدود ۱۳٪ مصرف‌کنندگان منظم دچار ناراحتی یا اختلال عملکرد قابل‌توجه می‌شوند.</li></ul><h4>ورزش</h4><p>طبق بیانیه‌ی ISSN، کافئین با دُز ۳ تا ۶ میلی‌گرم به ازای هر کیلوگرم وزن، معمولاً ۶۰ دقیقه قبل از ورزش، استقامت را ۲ تا ۴٪ بهبود می‌دهد و در سه فراتحلیل اثر کوچک (۲ تا ۷٪) روی قدرت دیده شده است. عوارض با دُز به‌طور خطی بالا می‌رود: تپش قلب، اضطراب، سردرد و اختلال خواب.</p>","kind":"item","src":[["StatPearls — Caffeine","https://www.ncbi.nlm.nih.gov/books/NBK519490/"],["StatPearls — Caffeine Withdrawal","https://www.ncbi.nlm.nih.gov/sites/books/NBK430790/"],["Drake et al. 2013, J Clin Sleep Med","https://pubmed.ncbi.nlm.nih.gov/24235903/"],["ISSN position stand: caffeine and exercise performance (2021)","https://link.springer.com/article/10.1186/s12970-020-00383-4"]]},{"id":393,"title":"قهوه و اپیدمیولوژی (Coffee & Epidemiology)","body":"<h4>مرور چتری BMJ (۲۰۱۷)</h4><p>این مرور ۲۰۱ فراتحلیل از مطالعات مشاهده‌ای را برای ۶۷ پیامد سلامت و ۱۷ فراتحلیل از مطالعات مداخله‌ای را برای ۹ پیامد بررسی کرد. بیشترین فایده در حدود ۳ تا ۴ فنجان در روز دیده شد و نویسندگان نتیجه گرفتند مصرف معمول قهوه به‌طور کلی بی‌خطر به نظر می‌رسد.</p><div class=\"table-wrap\"><table><thead><tr><th>پیامد</th><th>یافته</th></tr></thead><tbody><tr><td>مرگ‌ومیر کلی</td><td>خطر نسبی ۰٫۸۳ (۳ تا ۴ فنجان در برابر مصرف‌نکردن)</td></tr><tr><td>مرگ‌ومیر قلبی‌عروقی</td><td>۰٫۸۱ (بازه‌ی اطمینان ۰٫۷۲ تا ۰٫۹۰)</td></tr><tr><td>بیماری قلبی‌عروقی</td><td>۰٫۸۵ (۰٫۸۰ تا ۰٫۹۰)</td></tr><tr><td>سرطان (مصرف زیاد در برابر کم)</td><td>۰٫۸۲ (۰٫۷۴ تا ۰٫۸۹)؛ یعنی ۱۸٪ کمتر</td></tr><tr><td>دیابت نوع ۲</td><td>فواید در سطوح مختلف مصرف</td></tr><tr><td>کبد</td><td>قوی‌ترین ارتباط؛ کاهش سیروز و فیبروز</td></tr></tbody></table></div><h4>پارکینسون</h4><p>فراتحلیل دوز-پاسخ Qi و Li (۲۰۱۴) شامل ۱۳ مطالعه و ۹۰۱٬۷۶۴ شرکت‌کننده برای قهوه: بیشترین محافظت در حدود ۳ فنجان در روز (خطر نسبی تعدیل‌شده برای سیگار ۰٫۷۲؛ بازه‌ی اطمینان ۰٫۶۵ تا ۰٫۸۱)؛ ارتباط در مردان قوی‌تر از زنان و در آمریکا ضعیف‌تر از اروپا و آسیا بود. نویسندگان مطالعات بیشتر را لازم دانستند.</p><h4>بارداری</h4><ul><li>ACOG: مصرف کمتر از ۲۰۰ میلی‌گرم در روز «متوسط» است.</li><li>در مرور BMJ مصرف زیاد با خطر بیشتر وزن کم هنگام تولد (۱٫۳۱)، زایمان زودرس در سه‌ماهه‌ی اول (۱٫۲۲) و از دست رفتن بارداری (۱٫۴۶) همراه بود.</li></ul><h4>سرطان و نوشیدنی داغ</h4><p>IARC خود قهوه را «غیرقابل‌طبقه‌بندی» (گروه ۳) دانست، اما نوشیدنی‌های بالای ۶۵ درجه را «احتمالاً سرطان‌زا» (۲A) برای مری.</p><h4>چربی خون</h4><p>قهوه‌ی بدون فیلتر دی‌ترپن دارد که LDL و تری‌گلیسرید را بالا می‌برد؛ قهوه‌ی فیلتری و فوری تقریباً دی‌ترپن ندارد (Harvard).</p><p>همه‌ی این یافته‌ها مشاهده‌ای‌اند و علّیت را اثبات نمی‌کنند. برای بیماری یا بارداری با پزشک مشورت کنید.</p>","kind":"item","src":[["Poole et al. 2017, BMJ — Coffee consumption and health: umbrella review","https://www.bmj.com/content/359/bmj.j5024"],["Qi & Li 2014, Geriatr Gerontol Int — Dose-response meta-analysis on coffee, tea and caffeine with risk of Parkinson's disease","https://pubmed.ncbi.nlm.nih.gov/23879665/"],["ACOG — Moderate Caffeine Consumption During Pregnancy","https://www.acog.org/clinical/clinical-guidance/committee-opinion/articles/2010/08/moderate-caffeine-consumption-during-pregnancy"],["IARC Vol. 116 — Evaluation (NCBI Bookshelf)","https://www.ncbi.nlm.nih.gov/books/NBK543943/"],["Harvard T.H. Chan — Coffee","https://nutritionsource.hsph.harvard.edu/food-features/coffee/"]]},{"id":555,"title":"قهوه و درمان‌های جایگزین (Coffee & Alternative Therapies)","body":"<p>در ادامه، شواهد هر روش به‌طور کلی آمده است؛ نه ادعای مربوط به قهوه.</p><h4>طب سوزنی</h4><ul><li>طب سوزنی کاشتن سوزن‌های ظریف در پوست برای درمان مشکلات سلامت است و از طب سنتی چینی بیش از ۲۵۰۰ سال پیش آمده است.</li><li>NCCIH می‌گوید برای چند نوع درد از جمله کمردرد و گردن‌درد، درد زانوی ناشی از آرتروز و درد پس از جراحی ممکن است مفید باشد. کالج پزشکان آمریکا آن را در میان گزینه‌های غیردارویی خط اول کمردرد مزمن توصیه می‌کند.</li><li>شواهدی برای کاهش علائم آلرژی فصلی، بی‌اختیاری استرسی در زنان و تهوع ناشی از درمان سرطان هم هست.</li><li>عوارض کم است، ولی سوزن غیراستریل و تزریق نادرست می‌تواند عارضه بسازد.</li><li>NCCIH درباره‌ی ارتباط کافئین با طب سوزنی چیزی ندارد؛ هیچ «نقطه‌ی قهوه» تأییدشده‌ای نیست.</li></ul><h4>هومیوپاتی</h4><ul><li>اصل هومیوپاتی این است که هرچه دوز کمتر باشد اثر بیشتر است؛ بسیاری از فرآورده‌ها چنان رقیق‌اند که مولکولی از ماده‌ی اولیه در آن‌ها نمی‌ماند (NCCIH).</li><li>به گزارش NCCIH شواهد کمی برای اثربخشی آن در هیچ بیماری مشخصی هست؛ ارزیابی ۲۰۱۵ استرالیا هم به شواهد معتبری نرسید.</li><li>برخی فرآورده‌ها ممکن است مقدار قابل‌توجه ماده‌ی فعال داشته باشند و عارضه یا تداخل دارویی بسازند. جایگزین کردن درمان رایج با روش بی‌اثبات خطرناک است.</li></ul><h4>آروماتراپی</h4><ul><li>شواهد پزشکی کافی برای پیشگیری یا درمان هیچ بیماری با آروماتراپی نیست؛ نتایج مطالعات ناهمسو است (بعضی بهبود خواب، اضطراب و درد را دیده‌اند و بعضی تغییری ندیده‌اند).</li><li>اسانس‌ها غلیظ‌اند و بدون رقیق‌سازی با روغن حامل (مثل جوجوبا یا نارگیل) می‌توانند پوست را تحریک کنند.</li><li>خوردن اسانس خطرناک است: مقدارهای کم تا ۲ میلی‌لیتر علائم بالینی و ۴ میلی‌لیتر مسمومیت شدید گزارش شده است.</li></ul><h4>طب سنتی ایرانی و چینی</h4><p>جایگاه علمی مزاج‌شناسی و TCM در مقاله‌ی «قهوه در طب سنتی ایرانی و چینی» آمده است.</p>","kind":"item","src":[["NCCIH (NIH) — Homeopathy","https://www.nccih.nih.gov/health/homeopathy"],["NCCIH (NIH) — Acupuncture: What You Need To Know","https://www.nccih.nih.gov/health/acupuncture-what-you-need-to-know"],["Wikipedia — Aromatherapy","https://en.wikipedia.org/wiki/Aromatherapy"]]},{"id":605,"title":"جدول دقیق کافئین در روش‌های دم‌آوری","body":"<p>میزان کافئین یک فنجان قهوه بسیار متغیر است و به نوع دانه، مقدار قهوه، روش و زمان دم‌آوری بستگی دارد. عددهای قابل‌استناد:</p><div class=\"table-wrap\"><table><thead><tr><th>مرجع</th><th>عدد</th></tr></thead><tbody><tr><td>FDA</td><td>قهوه‌ی دم‌کرده‌ی معمولی: حدود ۱۱۳ تا ۲۴۷ میلی‌گرم در هر ۱۲ اونس مایع (حدود ۳۶۰ میلی‌لیتر)</td></tr><tr><td>Harvard T.H. Chan</td><td>یک فنجان ۸ اونسی (حدود ۲۴۰ میلی‌لیتر): حدود ۹۵ میلی‌گرم</td></tr><tr><td>FDA و EFSA</td><td>سقف توصیه‌شده برای بزرگسالان سالم: ۴۰۰ میلی‌گرم در روز</td></tr></tbody></table></div><p>اگر تحلیل آزمایشگاهی معتبر پیدا شود، اضافه می‌شود.</p>","kind":"item","src":[["FDA — Spilling the Beans","https://www.fda.gov/consumers/consumer-updates/spilling-beans-how-much-caffeine-too-much"],["Harvard T.H. Chan — Coffee","https://nutritionsource.hsph.harvard.edu/food-features/coffee/"],["EFSA — Caffeine","https://www.efsa.europa.eu/en/topics/topic/caffeine"]]}]},{"id":"C10","icon":"economics","title":"اقتصاد، بازاریابی و صنعت قهوه","items":[{"id":8,"title":"اقتصاد و بازار جهانی (Economics and Global Market)","body":"<ul><li>سهم گونه‌ها: عربیکا حدود ۶۰٪ و روبوستا حدود ۴۰٪ تولید جهانی (Crop Trust).</li><li>بورس: قرارداد آتی «Coffee C» (عربیکا) در ICE با نماد KC معامله می‌شود؛ اندازه‌ی هر قرارداد ۳۷٬۵۰۰ پوند است.</li><li>مصرف سرانه: در برآورد Statista برای ۲۰۲۰، هلند با ۸٫۳ کیلوگرم در سال در صدر بود و کشورهای شمال اروپا (فنلاند، سوئد، نروژ) پس از آن قرار داشتند.</li><li>گواهی‌ها: Fairtrade، ارگانیک و Rainforest Alliance؛ برای Fairtrade به مقاله‌ی «اقتصاد، بازاریابی و زنجیره‌ی تأمین» نگاه کنید.</li></ul>","kind":"item","src":[["Crop Trust — Coffee","https://www.croptrust.org/knowledge-hub/crops/crop/coffee/"],["ICE — Coffee C Futures","https://www.ice.com/products/15/Coffee-C-Futures"],["Statista — Top coffee drinking nations","https://www.statista.com/chart/8602/top-coffee-drinking-nations/"]]},{"id":152,"title":"اقتصاد، بازاریابی و زنجیره تأمین","body":"<p class=\"num-line\">۱. بورس و قیمت‌گذاری:</p><ul><li>قرارداد‌های آتی (Futures):</li><li>عربیکا: در بورس بین‌المللی نیویورک (ICE) – نماد «KC»</li><li>روبوستا: در بورس لندن معامله می‌شود</li><li>هر قرارداد Coffee C = ۳۷٬۵۰۰ پوند</li><li>قیمت پایه (C Price):</li><li>قیمت معاملات آتی عربیکا بسیار پرنوسان است (در سال‌های اخیر از حدود ۱۰۰ تا بیش از ۳۰۰ سنت برای هر پوند)؛ قیمت روز را از بورس بررسی کنید.</li><li>تحت تأثیر عوامل: آب و هوا (ال‌نینو، خشکسالی)، سیاسی (جنگ‌ها، تحریم‌ها)، و عرضه/تقاضا</li><li>حق بیمه (Premium):</li><li>قهوه‌های تخصصی (Specialty با امتیاز ۸۰+): معمولاً با پریمیوم قابل‌توجه بالاتر از C Price معامله می‌شوند؛ مقدار آن به کیفیت و مبدأ بستگی دارد و برای قهوه‌های ممتاز بسیار بالا می‌رود</li><li>قهوه‌های ارگانیک و Fair Trade: پریمیوم‌های ثابت یا قراردادی روی قیمت پایه (برای مثال پریمیوم ارگانیک و پریمیوم اجتماعی Fairtrade)</li></ul><h4 class=\"sub\">گواهی‌ها و استاندارد‌ها:</h4><ul><li>USDA Organic: بدون سموم، کود‌های شیمیایی، و GMO – هزینه صدور و نگهداری سالانه</li><li>Fairtrade: از ۱ اوت ۲۰۲۳ حداقل قیمت عربیکای شسته ۱٫۸۰ دلار بر پوند (از ۱٫۴۰) و روبوستای طبیعی ۱٫۲۰ دلار؛ پریمیوم Fairtrade ۰٫۲۰ دلار؛ مابه‌التفاوت ارگانیک ۰٫۴۰ دلار بر پوند</li><li>Rainforest Alliance: حفاظت از تنوع زیستی، مدیریت یکپارچه آفات، حقوق کارگران</li><li>UTZ Certified: بهره‌وری بالا با استاندارد‌های کشاورزی خوب (اکنون ادغام شده با Rainforest Alliance)</li><li>۴C (Common Code): استاندارد پایه‌ی اجتماعی، زیست‌محیطی و اقتصادی</li><li>SCA (Specialty Coffee Association): استاندارد‌های کیاپینگ – حداقل امتیاز ۸۰ برای عضویت در دسته تخصصی</li></ul><h4 class=\"sub\">ردیابی (Traceability):</h4><ul><li>ردیابی مستقیم (Direct Trade): خریداران (مثل رستوران‌ها و برشته‌کاران) با کشاورزان بدون واسطه قرارداد می‌بندند – شفافیت کامل در قیمت و کیفیت</li><li>ردیابی دیجیتال (مثلاً بلاکچین یا QR): برخی شرکت‌ها اطلاعات مزرعه تا فنجان را با کد QR در دسترس می‌گذارند؛ نمونه‌ها متنوع و بعضی پروژه‌ها متوقف شده‌اند.</li><li>مزایا: افزایش اعتماد، کاهش تقلب، و پرداخت منصفانه به کشاورز</li></ul><h4 class=\"sub\">تأثیرات زیست‌محیطی:</h4><ul><li>ردپای کربن (Carbon Footprint):</li><li>برآوردهای ردپای کربن هر کیلوگرم قهوه بسیار متفاوت است (از چند کیلوگرم تا بیش از ده کیلوگرم CO₂ معادل) و به روش محاسبه و مبدأ بستگی دارد</li><li>حمل هوایی ردپای حمل‌ونقل را چندین برابر حمل دریایی می‌کند (برای قهوه‌ی تازه‌ی ویژه رایج نیست)</li><li>آب مجازی (Virtual Water):</li><li>برآورد رایج: حدود ۱۴۰ لیتر «آب مجازی» برای یک فنجان (عمدتاً آب باران در کشت)</li><li>بازیافت تفاله (Spent Coffee Grounds):</li><li>تبدیل به سوخت زیستی (گلوله‌های سوختی)</li><li>کمپوست غنی از نیتروژن</li><li>ماده اولیه برای کشت قارچ صدفی (Pleurotus ostreatus)</li></ul><p><strong>کف قیمت فیرتریید (مصوب ۱۵ ژوئیه ۲۰۲۶؛ برای قراردادهای امضاشده از ۱ دسامبر ۲۰۲۶):</strong> قیمت FOB به دلار برای هر پوند — عربیکا شسته ۲٫۰۰ و طبیعی ۱٫۹۵؛ روبوستا شسته ۱٫۳۵ و طبیعی ۱٫۳۰؛ حق بیمه‌ی (پرمیوم) فیرتریید ۰٫۲۰ و افزوده‌ی ارگانیک ۰٫۴۰ دلار بر پوند. پرمیوم علاوه بر کف قیمت یا قیمت بازار، هرکدام بالاتر باشد، پرداخت می‌شود.</p>","kind":"item","src":[["ICE — Coffee C Futures","https://www.ice.com/products/15/Coffee-C-Futures"],["Fairtrade International — Minimum Price for coffee Q&A (March 2023)","https://www.fairtrade.net/content/dam/fairtrade/fairtrade-international/FP-for-coffee-QA-March-2023.pdf"],["Chapagain & Hoekstra 2007 — Water footprint of coffee and tea consumption in the Netherlands","https://ayhoekstra.nl/pubs/Chapagain-Hoekstra-2007.pdf"],["Fairtrade International — Coffee price announcement (30 July 2026)","https://www.fairtrade.net/content/dam/fairtrade/fairtrade-international/standards/standards-and-pricing-work-in-progress/2026-07-30_Coffee%20Price%20Announcement_EN.pdf"]]},{"id":180,"title":"بسته‌بندی و برچسبگذاری حرف‌های (برای صادرات و فروش)","body":"<h4 class=\"sub\">بسته‌بندی و برچسب</h4><ul><li>بسته‌بندی «نگه می‌دارد، محافظت می‌کند، حفظ می‌کند، حمل می‌کند، اطلاع می‌دهد و می‌فروشد».</li><li>محافظت: در برابر ضربه، لرزش، ساییدگی، فشار و دما و مانع اکسیژن، بخار آب، نور خورشید و گرد و غبار.</li><li>اطلاعات: دستور مصرف، حمل، بازیافت، شماره‌ی سری/بچ و تاریخ انقضا یا «best before».</li><li>برچسب‌گذاری قانونی است: بیان دقیق وزن خالص از مهم‌ترین الزامات است؛ در آمریکا Fair Packaging and Labeling Act، در بریتانیا Weights and Measures (Packaged Goods) Regulations. مقررات صادرات کشور مقصد را جداگانه بررسی کنید.</li><li>عمر قهوه‌ی برشته (حدود دو هفته) و نیاز به دور بودن از اکسیژن، نور و گرما در مقاله‌ی «تجهیزات نگهداری و بسته‌بندی» آمده است.</li></ul>","kind":"item","src":[["Wikipedia — Packaging and labeling","https://en.wikipedia.org/wiki/Packaging_and_labeling"],["Wikipedia — Coffee roasting","https://en.wikipedia.org/wiki/Coffee_roasting"]]},{"id":195,"title":"تکنیک‌های روان‌شناسی در طراحی منوی کافه (برای فروش بیشتر)","body":"<h4 class=\"sub\">مهندسی منو</h4><ul><li>مهندسی منو (Menu engineering) «طراحی منو برای حداکثر کردن سود رستوران» است؛ ۱۹۸۲ توسط Michael L. Kasavana و Donald I. Smith معرفی شد.</li><li>دو رویکرد: «نقاط شیرین» (جای‌گذاری اقلام در جاهایی که مشتری بیشتر نگاه می‌کند، بر پایه‌ی اثر موقعیت ترتیبی) — مقاله می‌گوید شواهد تجربی برای اثربخشی آن نیست؛ و تحلیل حاشیه‌ی هزینه (شناسایی «primes»: اقلام با هزینه‌ی کم و سود ناخالص بالاتر از میانگین).</li></ul>","kind":"item","src":[["Wikipedia — Menu engineering","https://en.wikipedia.org/wiki/Menu_engineering"]]},{"id":206,"title":"تأثیر صدا و محیط بر ادراک طعم (نورومارکتینگ قهوه)","body":"<h4 class=\"sub\">صدا و طعم</h4><ul><li>Woods و همکاران (۲۰۱۱، Food Quality and Preference): شیرینی گزارش‌شده در صدای بلند به‌طور معنادار کمتر از شرایط ساکت بود (آزمایش ۱) و ترد‌بودن شدیدتر ارزیابی شد (آزمایش ۲).</li><li>Yan و Dando (۲۰۱۵، Journal of Experimental Psychology: Human Perception and Performance) صدای شبیه کابین هواپیما با اوج نزدیک ۲۹۰ هرتز و شدت حدود ۸۰ تا ۸۵ دسی‌بل را با اتاق عادی مقایسه کردند.</li><li>در صدای کابین، شدت شیرینی در همه‌ی غلظت‌ها کم شد و شدت اومامی در غلظت‌های بالاتر زیاد شد؛ شوری، ترشی و تلخی تغییری نکردند.</li><li>نویسندگان گفته‌اند شیرینی و اومامی گیرنده‌ی مشترک دارند و شاید به همین دلیل فقط این دو طعم اثر گرفتند.</li><li>در آزمایش Woods و همکاران، صدای آرام ۴۵ تا ۵۵ دسی‌بل و صدای بلند ۷۵ تا ۸۵ دسی‌بل بود و شیرینی، شوری و میزان دوست‌داشتن ارزیابی شد.</li></ul>","kind":"item","src":[["Woods et al. (2011), Food Quality and Preference 22(1):42-47 — Effect of background noise on food perception","https://research.wur.nl/en/publications/effect-of-background-noise-on-food-perception"],["PsyPost — Taste perception is influenced by extreme noise conditions (Yan & Dando, 2015)","https://www.psypost.org/taste-perception-is-influenced-by-extreme-noise-conditions/"],["Hearing Review — Cornell University study finds noise affects taste buds","https://hearingreview.com/inside-hearing/research/cornell-university-study-finds-noise-affects-taste-buds"],["Flavour (BioMed Central) — Airplane noise and the taste of umami (figure)","https://flavourjournal.biomedcentral.com/articles/10.1186/2044-7248-3-2/figures/1"]]},{"id":227,"title":"نکات طلایی برای خرید قهوه (هیچ‌کجا گفته نشده)","body":"<h4 class=\"sub\">خرید قهوه</h4><ul><li>عمر بهینه‌ی دانه‌ی برشته‌شده حدود دو هفته است و تا حدود یک ماه (در جای خنک) تازه به‌حساب می‌آید؛ قهوه‌ی آسیاب‌شده بسیار زودتر کهنه می‌شود، پس دانه‌ی کامل بخرید و پیش از دم آسیاب کنید.</li><li>قهوه‌ی تازه‌برشته گاز CO2 آزاد می‌کند؛ بسته‌بندی‌ها از کیسه‌های دارای سوپاپ تخلیه‌ی فشار استفاده می‌کنند.</li><li>در برشته‌ی روشن و متوسط سطح دانه خشک است و دانه‌های تیره براق‌اند؛ هرچه از کرک دوم دورتر باشد روغن بیشتر دیده می‌شود. چون رنگ با کهنگی هم تیره می‌شود، رنگ به‌تنهایی شاخص ضعیفی است.</li><li>دانه‌ی سبز تا ۱۲ تا ۱۸ ماه در شرایط کنترل‌شده بدون افت محسوس می‌ماند.</li><li>قهوه‌ی اسپشیالتی دست‌کم ۸۰ امتیاز SCA دارد.</li></ul>","kind":"item","src":[["Wikipedia — Coffee roasting","https://en.wikipedia.org/wiki/Coffee_roasting"],["Wikipedia — Specialty coffee","https://en.wikipedia.org/wiki/Specialty_coffee"]]},{"id":322,"title":"قهوه در صنایع غیرخوراکی (قهوه فراتر از فنجان)","body":"<h4 class=\"sub\">قهوه فراتر از فنجان</h4><ul><li>تولید قهوه بیش از ۴۰ میلیون تن زیست‌توده‌ی باقی‌مانده در سال تولید می‌کند — پایه‌ی بسیاری از کاربردهای غیرخوراکی.</li><li>فیلتر کاغذی: حدود ۱۰۰ گرم بر متر مربع خمیر الیاف بلند؛ Melitta از ۱۹۹۸ تا ۶۰٪ بامبو استفاده کرده است.</li><li>از یک تن میوه‌ی تازه‌ی قهوه فقط حدود ۲۰۰ کیلوگرم قهوه‌ی سبز عربیکا به دست می‌آید؛ بقیه به پسماند تبدیل می‌شود.</li><li>پوسته‌ی خشک (هاسک) و پوسته‌ی پارچمنت به‌عنوان سوخت پخت‌وپز و گرمایش، چسب بریکت، افزودنی آجر و سرامیک و ماده‌ی خام تخته‌ی نئوپان به کار می‌روند.</li><li>پوسته‌ی نقره‌ای (silver skin) پیش‌ماده‌ی کربن فعال است و تفاله‌ی خمیری (پالپ) به کود و خوراک دام و بیوگاز تبدیل می‌شود.</li><li>از هر تن قهوه‌ی سبز حدود ۶۵۰ کیلوگرم تفاله‌ی مصرف‌شده به دست می‌آید؛ تفاله در کمپوست، بستر قارچ صدفی، سوخت زیستی و تا ۱۰ تا ۱۵ درصد جایگزین ماسه در بتن استفاده شده است.</li><li>تفاله‌ی قهوه به‌عنوان پرکننده در پلیمرهای زیستی مانند پلی‌لاکتید (PLA) پیشنهاد شده است.</li></ul>","kind":"item","src":[["Wikipedia — Coffee production","https://en.wikipedia.org/wiki/Coffee_production"],["Wikipedia — Coffee filter","https://en.wikipedia.org/wiki/Coffee_filter"],["Wikipedia — Used coffee grounds","https://en.wikipedia.org/wiki/Used_coffee_grounds"],["PMC — Exploring Spent Coffee Grounds: Morphological Analysis and Chemical Characterization","https://pmc.ncbi.nlm.nih.gov/articles/PMC11677221"]]},{"id":439,"title":"قهوه و روان‌شناسی مصرف‌کننده (Coffee & Consumer Psychology)","body":"<h4 class=\"sub\">برند و درک طعم</h4><ul><li>پژوهش Imane Bouzidi (دانشکده‌ی کسب‌وکار کپنهاگ): ۱۲۲ نفر در دانمارک (۲۰ تا ۴۰ سال، نیمی زن و نیمی مرد) قهوه‌ی چهار برند را چشیدند؛ همه‌ی نمونه‌ها را یک برشته‌کار (Kontra) برشته کرده بود و برای هر برند دو قهوه‌ی باکیفیت بالا و پایین استفاده شد.</li><li>برند بین‌المللی بالاترین امتیاز طعم و بیشترین مصرف را گرفت، «صرف‌نظر از کیفیت»؛ انتظار از برند اغلب بر تفاوت واقعی کیفیت غلبه کرد.</li></ul><h4 class=\"sub\">رنگ لیوان</h4><ul><li>پژوهشی در مجله‌ی Flavour: قهوه در لیوان سفید قوی‌تر و کم‌شیرین‌تر از لیوان شفاف یا آبی ارزیابی شد؛ ارزیابی تلخی همان الگوی شدت را داشت. در آزمایش دوم با لیوان شیشه‌ای و غلاف رنگی هم قهوه در لیوان سفید کم‌شیرین‌تر بود.</li></ul>","kind":"item","src":[["SCA — Can You Taste the Brand in Your Coffee?","https://sca.coffee/sca-news/2017/12/13/can-taste-brand-coffee"],["The Conversation — Bitter coffee today? Try changing the colour of your cup","https://theconversation.com/bitter-coffee-today-try-changing-the-colour-of-your-cup-33248"]]},{"id":527,"title":"قهوه و طراحی صنعتی و ارگونومی (Coffee & Industrial Design & Ergonomics)","body":"<h4 class=\"sub\">طراحی صنعتی و ارگونومی</h4><ul><li>Melitta Bentz نخستین فیلتر کاغذی تجاری (دیسک ۹۴ میلی‌متری) را در ۸ ژوئیه ۱۹۰۸ ساخت تا تلخی ناشی از دم‌آوری بیش از حد را بگیرد؛ ۱۹۳۶/۳۷ فیلتر بادبزنی؛ ۱۹۶۳ یا ۱۹۶۵ سیستم «۱×».</li><li>Hario V60 در ۲۰۰۴ عرضه شد و در ۲۰۰۷ جایزه‌ی طراحی خوب ژاپن را برد.</li><li>طراحی نگه‌دارنده: مخروطی یا کف‌تخت، اندازه‌ی فیلتر، شیارها، شکل کف، تعداد و اندازه‌ی سوراخ‌ها، جنس و دسته؛ شیار و کف و سوراخ بر زمان دم‌آوری، بای‌پس، کانال‌شدن و گرفتگی اثر می‌گذارند.</li><li>نگه‌دارنده‌ی فلزی و چینی گرما را بیش از شیشه و پلاستیک نگه می‌دارند؛ پیش‌گرم کنید.</li><li>فیلتر کاغذی دی‌ترپن‌هایی مثل کافستول و کاهوئول را می‌گیرد؛ فلزی، نایلونی و چینی نمی‌گیرند. فولاد ضدزنگ، سرامیک، شیشه‌ی سیلیکات و چینی در تماس با غذا ایمن‌اند.</li></ul>","kind":"item","src":[["Wikipedia — Coffee filter","https://en.wikipedia.org/wiki/Coffee_filter"]]},{"id":602,"title":"آنالیز عمیق هزینه‌ی تمام‌شده (COGS) در کافه","body":"<h4 class=\"sub\">هزینه‌ی تمام‌شده</h4><ul><li>COGS ارزش ثبت‌شده‌ی کالای فروخته‌شده در یک دوره است؛ فرمول: موجودی ابتدای دوره + خریدها − موجودی پایان دوره.</li><li>هدف رایج برای COGS حدود ۳۰ تا ۳۵٪ فروش است؛ یعنی حاشیه‌ی سود ناخالص ۶۵ تا ۷۰٪ برای پوشش سایر هزینه‌ها لازم است.</li><li>موجودی را باید پس از بسته‌شدن در آخرین روز ماه شمارش کرد؛ این عدد موجودی ابتدای ماه بعد می‌شود.</li><li>COGS ایده‌آل از وزن دقیق دستور و قیمت مواد حساب می‌شود. اختلاف یک تا دو درصدی با COGS واقعی پذیرفتنی است؛ اختلاف بیشتر به ضایعات، پرریزی، مصرف کارکنان یا سرقت اشاره دارد.</li><li>در مثال یک لاته‌ی ۱۶ اونسی، هزینه‌ی دو شات اسپرسو، شربت وانیل و شیر روی هم ۸۱٫۶ سنت شد. در قیمت‌گذاری «کلیدی» (keystone) قیمت منو دو برابر COGS است.</li></ul>","kind":"item","src":[["Wikipedia — Cost of goods sold","https://en.wikipedia.org/wiki/Cost_of_goods_sold"],["Fresh Cup — Cost of goods and profitability","https://freshcup.com/cost-of-goods-and-profitability/"],["Square — How to price coffee drinks","https://squareup.com/us/en/the-bottom-line/operating-your-business/how-to-price-coffee-drinks"]]},{"id":607,"title":"روان‌شناسی طراحی بسته‌بندی قهوه","body":"<h4 class=\"sub\">بسته‌بندی و برچسب</h4><ul><li>بسته‌بندی «نگه می‌دارد، محافظت می‌کند، حفظ می‌کند، حمل می‌کند، اطلاع می‌دهد و می‌فروشد».</li><li>محافظت: در برابر ضربه، لرزش، ساییدگی، فشار و دما و مانع اکسیژن، بخار آب، نور خورشید و گرد و غبار.</li><li>اطلاعات: دستور مصرف، حمل، بازیافت، شماره‌ی سری/بچ و تاریخ انقضا یا «best before».</li><li>برچسب‌گذاری قانونی است: بیان دقیق وزن خالص از مهم‌ترین الزامات است؛ در آمریکا Fair Packaging and Labeling Act، در بریتانیا Weights and Measures (Packaged Goods) Regulations. مقررات صادرات کشور مقصد را جداگانه بررسی کنید.</li><li>عمر قهوه‌ی برشته (حدود دو هفته) و نیاز به دور بودن از اکسیژن، نور و گرما در مقاله‌ی «تجهیزات نگهداری و بسته‌بندی» آمده است.</li></ul>","kind":"item","src":[["Wikipedia — Packaging and labeling","https://en.wikipedia.org/wiki/Packaging_and_labeling"],["Wikipedia — Coffee roasting","https://en.wikipedia.org/wiki/Coffee_roasting"]]},{"id":609,"title":"چک‌لیست کیفیت کافه (الهام‌گرفته از رهنمودهای SCA)","body":"<p>جدول پیشین ساختگی بود و برداشته شد. SCA برنامه‌ی آموزشی و گواهی مهارت (Coffee Skills Program) برای باریستاها، برشته‌کاران و ... دارد و استاندارد آب و کاپینگ منتشر می‌کند. در ادامه چک‌لیستی از عملکردهای کیفی کافه می‌بینید که به رهنمودهای شناخته‌شده‌ی SCA نزدیک است، نه یک گواهی رسمی.</p><div class=\"table-wrap\"><table><thead><tr><th>حوزه</th><th>عملکرد پیشنهادی</th><th>توضیح</th></tr></thead><tbody><tr><td>تجهیزات</td><td>آسیاب برر مناسب و دستگاه اسپرسوی پایدار</td><td>آسیاب پره‌ای برای اسپرسو مناسب نیست</td></tr><tr><td>آموزش</td><td>آموزش پرسنل (مثلاً مسیر آموزشی SCA)</td><td>مهارت اسپرسو، شیر و حسی</td></tr><tr><td>آب</td><td>فیلتراسیون و آزمون منظم سختی/قلیائیت/TDS</td><td>استاندارد آب SCAA (به نقل از 43factory): TDS بین ۷۵ تا ۲۵۰ mg/L با هدف حدود ۱۵۰؛ سختی ۵۱ تا ۶۸ mg/L؛ قلیائیت حدود ۴۰ mg/L؛ pH بین ۶٫۵ تا ۷٫۵؛ سدیم کمتر از ۳۰ mg/L</td></tr><tr><td>کالیبراسیون</td><td>ثبت دوز، بازده و زمان و تنظیم آسیاب در طول روز</td><td>هر شیفت و با هر کیسه‌ی تازه</td></tr><tr><td>کاپینگ</td><td>برگزاری کاپینگ دوره‌ای با تیم</td><td>ثبت یادداشت و بهبود</td></tr><tr><td>منو</td><td>حداقل چند روش دم‌آوری یا مبدأ</td><td>تنوع برای مشتری</td></tr><tr><td>بهداشت</td><td>برنامه‌ی تمیزکاری روزانه و هفتگی (بک‌فلاش، تمیزی گروه و بخار)</td><td>ثبت در دفترچه</td></tr><tr><td>شفافیت</td><td>ذکر مبدأ، فرآوری و تاریخ برشته‌کاری روی منو یا بسته</td><td>اعتماد مشتری</td></tr></tbody></table></div><h4 class=\"sub\">✅ چگونه شروع کنید؟</h4><ol><li>وضعیت فعلی (آب، تجهیزات، آموزش) را با چک‌لیست بالا بسنجید.</li><li>ضعیف‌ترین حوزه (معمولاً آب یا کالیبراسیون) را اول اصلاح کنید.</li><li>برای پرسنل آموزش‌های معتبر بگیرید و نتیجه را مستند کنید.</li><li>به‌صورت دوره‌ای کاپینگ و ارزیابی مشتری انجام دهید.</li></ol>","kind":"item","src":[["43factory — Dissecting SCAA water quality standard","https://43factory.coffee/en/news/dissecting-scaas-water-quality-standard/"],["SCA — Cupping Protocol","https://sca.coffee/research/protocols-best-practices"]]},{"id":700,"title":"تولید قهوه به تفکیک کشور و اقتصاد جهانی","kind":"item","body":"<h4 class=\"sub\">تولید و اقتصاد قهوه (داده‌ی ۲۰۲۳ FAOSTAT)</h4><ul><li>تولید جهانی قهوه‌ی سبز ≈ ۱۱٫۰۶ میلیون تن: برزیل ۳٫۴۱ (۳۱٪)، ویتنام ۱٫۹۶، اندونزی ۰٫۷۶، کلمبیا ۰٫۶۸، اتیوپی ۰٫۵۶ میلیون تن.</li><li>در ۲۰۲۰ برزیل ۳۹٪ تولید ۱۷۵٫۶ میلیون کیسه‌ی ۶۰ کیلویی را داشت.</li><li>صنعت جهانی قهوه در ۲۰۲۳ حدود ۴۹۵٫۵ میلیارد دلار ارزش داشت؛ بیش از ۱۰۰ میلیون نفر در کشورهای در حال توسعه درآمد اصلی‌شان از قهوه است (و ۱۲٫۵ میلیون خانوار تولید).</li><li>عربیکا حدود سه‌چهارم قهوه‌ی کشت‌شده است؛ روبوستا ۴۰–۵۰٪ کافئین بیشتر دارد. آینده‌ی عربیکا در بورس نیویورک (KC) و روبوستا در ICE معامله می‌شود.</li><li>بیشترین مصرف سرانه: فنلاند ۱۲ کیلوگرم در سال، نروژ ۹٫۹، ایسلند ۹ و دانمارک ۸٫۷.</li><li>هر تن گیلاس تازه ≈ ۲۰۰ کیلوگرم عربیکای سبز یا ۲۲۰ کیلوگرم روبوستا.</li></ul>","src":[["Wikipedia — Coffee","https://en.wikipedia.org/wiki/Coffee"],["Wikipedia — Coffee production","https://en.wikipedia.org/wiki/Coffee_production"]]}]},{"id":"C12","icon":"culture","title":"فرهنگ، جامعه و آیین‌های قهوه","items":[{"id":17,"title":"تنوع‌های ملی (Variations by Country)","body":"<h4 class=\"sub\">فرهنگ قهوه به تفکیک کشور</h4><ul><li>ایتالیا: اسپرسو معمولاً ایستاده پشت پیشخوان نوشیده می‌شود نه همراه‌بر؛ نوشیدنی‌های شیردار معمولاً فقط صبح. Caffè Florian ونیز قدیمی‌ترین کافه‌ی ایتالیاست. ساکنان تریسته سالانه حدود ۱۵۰۰ فنجان (حدود دو برابر میانگین ایتالیا) می‌نوشند.</li><li>اتریش (وین): قهوه‌خانه محل گفت‌وگو، مطالعه و تبادل فرهنگی است؛ گفته می‌شود کاپوچینو از Kapuziner وینی پدید آمد.</li><li>سوئد: «فیکا» (fika) — استراحت قهوه با شیرینی — نهاد اجتماعی مرکزی است؛ قهوه ۱۶۸۵ به گوتنبرگ رسید و محدودیت‌ها ۱۸۲۳ برداشته شد.</li><li>فنلاند: معمولاً رتبه‌ی اول مصرف سرانه (حدود ۱۲ کیلو در سال). آلمان و کشورهای شمال اروپا: قهوه‌ی تلخ قوی کنار غذا و پرکردن رایگان.</li><li>آمریکا: بزرگ‌ترین بازار قهوه؛ اغلب همراه‌بر و فنجان بزرگ (تا ۲۴ اونس).</li><li>ژاپن: نخستین کافه ۱۸۸۸ در توکیو؛ کیسا‌تن‌ها از دهه‌ی ۱۹۲۰ شکوفا و در دهه‌ی ۱۹۷۰ فراگیر شدند. هنگ‌کنگ: یوئن‌یوئنگ (قهوه با چای) در ۱۹۳۶. شانگهای حدود ۶۵۰۰ کافه؛ کره‌ی جنوبی: افزایش ۹۰۰٪ کافه‌ها از ۲۰۰۶ تا ۲۰۱۱؛ آلبانی در ۲۰۱۶ بیشترین کافه به نسبت جمعیت (۶۵۴ در هر ۱۰۰ هزار نفر).</li><li>استرالیا: مهاجران یونانی فرهنگ کافه را ساختند. ترکیه و سرزمین‌های عثمانی: قهوه‌ی ترکی غالب؛ قهوه‌خانه‌ها تا ۱۶۰۰ در زندگی عثمانی برجسته بودند.</li><li>یمن: صوفیان قهوه می‌نوشیدند تا هنگام ذکر تمرکز کنند؛ قهوه از بندر مخا صادر می‌شد.</li></ul><h4 class=\"sub\">وین و کیسا‌تن</h4><ul><li>وین: از اکتبر ۲۰۱۱ در فهرست ملی میراث ناملموس اتریش؛ میز مرمر، صندلی تونه، میز روزنامه؛ با قهوه لیوان آب سرد می‌آورند و بی‌درخواست پر می‌کنند؛ پژوهش‌های جدید نخستین قهوه‌خانه را به Johannes Theodat (۱۶۸۵) نسبت می‌دهند و افسانه‌ی Kulczycki را رد می‌کنند.</li><li>کیسا‌تن ژاپنی: «چای‌خانه‌ی» قهوه‌فروش آرام، الهام‌گرفته از سالن‌های پاریس و وین؛ سرویس صبحانه با نان تست ضخیم و تخم‌مرغ.</li></ul>","kind":"item","src":[["Wikipedia — Coffee culture","https://en.wikipedia.org/wiki/Coffee_culture"],["Wikipedia — Viennese coffee house culture","https://en.wikipedia.org/wiki/Viennese_coffee_house_culture"],["Wikipedia — Kissaten","https://en.wikipedia.org/wiki/Kissaten"]]},{"id":156,"title":"هنر، فلسفه و فرهنگ قهوه","body":"<h4 class=\"sub\">موج‌های قهوه</h4><ul><li>موج اول: بی‌تفاوت به خاستگاه و نوع نوشیدنی؛ قهوه‌ی فوری، قوطی خرده‌فروشی و قهوه‌ی دایز؛ تمرکز بر قیمت پایین و طعم ثابت (برندهایی مثل Folgers و Maxwell House).</li><li>موج دوم: از اواخر دهه‌ی ۱۹۶۰ با Peet’s Coffee در برکلی (برشته‌ی تیره و تأکید بر کشور خاستگاه)؛ الهام‌بخش بنیانگذاران استارباکس؛ آغاز نوشیدنی‌های اسپرسویی ایتالیایی‌سبک.</li><li>موج سوم: تأکید بر کیفیت بالاتر، مزارع تک‌خاستگاه و برشته‌ی روشن که طعم‌های متمایز را آشکار می‌کند؛ اصطلاح را معمولاً به Trish Rothgeb (مقاله‌ی ۲۰۰۳) نسبت می‌دهند؛ Timothy J. Castle پیش‌تر (دسامبر ۱۹۹۹/ژانویه ۲۰۰۰) به‌کار برده بود. Jonathan Gold: «دانه‌ها از مزارع تأمین می‌شوند نه کشورها».</li></ul>","kind":"item","src":[["Wikipedia — Third wave of coffee","https://en.wikipedia.org/wiki/Third_wave_of_coffee"]]},{"id":176,"title":"قهوه در ادیان و فرهنگ‌های معنوی","body":"<h4 class=\"sub\">قهوه و دین</h4><ul><li>صوفیان یمن در اواخر قرن پانزدهم قهوه را برای بیداری در عبادت‌های شبانه و حالتی «مستی معنوی» هنگام ذکر به کار می‌بردند.</li><li>۱۵۱۱: دادگاه شرعی مکه به‌دلیل اثر محرک قهوه را ممنوع کرد. ۱۵۲۴: سلطان سلیمان این ممنوعیت را لغو و مفتی اعظم ابوالسعود فتوای جواز داد؛ قاهره ۱۵۳۲ ممنوعیت مشابهی گذاشت.</li><li>کلیسای ارتدوکس اتیوپی پیش از قرن ۱۸ قهوه را ممنوع کرده بود؛ در اواخر قرن نوزدهم (با نوشیدن امپراتور منلیک و کوشش ابونا متیوس برای زدودن باور «نوشیدنی مسلمانان») نگرش نرم شد.</li><li>پاپ کلمنت هشتم: برخی نمایندگان کلیسا در ایتالیا قهوه را «نوشیدنی شیطان» می‌خواندند و می‌گویند پاپ پس از چشیدن تأییدش کرد؛ درستی داستان نامعلوم است (سال معمول ۱۶۰۰).</li></ul>","kind":"item","src":[["Wikipedia — History of coffee","https://en.wikipedia.org/wiki/History_of_coffee"]]},{"id":181,"title":"تفاوت‌های فرهنگی و آداب نوشیدن قهوه در کشور‌های مختلف","body":"<h4 class=\"sub\">فرهنگ قهوه به تفکیک کشور</h4><ul><li>ایتالیا: اسپرسو معمولاً ایستاده پشت پیشخوان نوشیده می‌شود نه همراه‌بر؛ نوشیدنی‌های شیردار معمولاً فقط صبح. Caffè Florian ونیز قدیمی‌ترین کافه‌ی ایتالیاست. ساکنان تریسته سالانه حدود ۱۵۰۰ فنجان (حدود دو برابر میانگین ایتالیا) می‌نوشند.</li><li>اتریش (وین): قهوه‌خانه محل گفت‌وگو، مطالعه و تبادل فرهنگی است؛ گفته می‌شود کاپوچینو از Kapuziner وینی پدید آمد.</li><li>سوئد: «فیکا» (fika) — استراحت قهوه با شیرینی — نهاد اجتماعی مرکزی است؛ قهوه ۱۶۸۵ به گوتنبرگ رسید و محدودیت‌ها ۱۸۲۳ برداشته شد.</li><li>فنلاند: معمولاً رتبه‌ی اول مصرف سرانه (حدود ۱۲ کیلو در سال). آلمان و کشورهای شمال اروپا: قهوه‌ی تلخ قوی کنار غذا و پرکردن رایگان.</li><li>آمریکا: بزرگ‌ترین بازار قهوه؛ اغلب همراه‌بر و فنجان بزرگ (تا ۲۴ اونس).</li><li>ژاپن: نخستین کافه ۱۸۸۸ در توکیو؛ کیسا‌تن‌ها از دهه‌ی ۱۹۲۰ شکوفا و در دهه‌ی ۱۹۷۰ فراگیر شدند. هنگ‌کنگ: یوئن‌یوئنگ (قهوه با چای) در ۱۹۳۶. شانگهای حدود ۶۵۰۰ کافه؛ کره‌ی جنوبی: افزایش ۹۰۰٪ کافه‌ها از ۲۰۰۶ تا ۲۰۱۱؛ آلبانی در ۲۰۱۶ بیشترین کافه به نسبت جمعیت (۶۵۴ در هر ۱۰۰ هزار نفر).</li><li>استرالیا: مهاجران یونانی فرهنگ کافه را ساختند. ترکیه و سرزمین‌های عثمانی: قهوه‌ی ترکی غالب؛ قهوه‌خانه‌ها تا ۱۶۰۰ در زندگی عثمانی برجسته بودند.</li><li>یمن: صوفیان قهوه می‌نوشیدند تا هنگام ذکر تمرکز کنند؛ قهوه از بندر مخا صادر می‌شد.</li></ul><h4 class=\"sub\">وین و کیسا‌تن</h4><ul><li>وین: از اکتبر ۲۰۱۱ در فهرست ملی میراث ناملموس اتریش؛ میز مرمر، صندلی تونه، میز روزنامه؛ با قهوه لیوان آب سرد می‌آورند و بی‌درخواست پر می‌کنند؛ پژوهش‌های جدید نخستین قهوه‌خانه را به Johannes Theodat (۱۶۸۵) نسبت می‌دهند و افسانه‌ی Kulczycki را رد می‌کنند.</li><li>کیسا‌تن ژاپنی: «چای‌خانه‌ی» قهوه‌فروش آرام، الهام‌گرفته از سالن‌های پاریس و وین؛ سرویس صبحانه با نان تست ضخیم و تخم‌مرغ.</li></ul>","kind":"item","src":[["Wikipedia — Coffee culture","https://en.wikipedia.org/wiki/Coffee_culture"],["Wikipedia — Viennese coffee house culture","https://en.wikipedia.org/wiki/Viennese_coffee_house_culture"],["Wikipedia — Kissaten","https://en.wikipedia.org/wiki/Kissaten"]]},{"id":213,"title":"قهوه در مذهب شیعه و ایران عصر صفوی – نکته‌ی تاریخی","body":"<ul><li>در دوره‌ی صفوی قهوه‌خانه‌ها در شهرهایی مثل اصفهان و قزوین رونق گرفتند؛ مکان گفت‌وگو، شعر و نقالی بودند و مسافران اروپایی از آن‌ها نوشته‌اند.</li><li>در جهان اسلام درباره‌ی حلال یا حرام بودن قهوه (به‌خاطر بیدارکنندگی و اجتماعات قهوه‌خانه) مناقشه بود؛ در ۱۵۱۱ در مکه ممنوع شد و در ۱۵۲۴ مفتی بزرگ عثمانی در دوران سلطان سلیمان مصرف آن را مجاز دانست.</li><li>سند قطعی از فتوای رسمی «مکروه» در مذهب شیعه دوره‌ی صفوی در دست نیست؛ این موضوع نیاز به پژوهش تاریخی دقیق‌تر دارد.</li></ul>","kind":"item","src":[["Wikipedia — History of coffee","https://en.wikipedia.org/wiki/History_of_coffee"]]},{"id":315,"title":"هنر سرو قهوه (Advanced Serving & Presentation)","body":"<h4 class=\"sub\">لاته‌آرت و سرو</h4><ul><li>لاته‌آرت: ریختن میکروفوم داخل اسپرسو برای ساختن نقش روی لاته، کاپوچینو یا شکلات داغ؛ نقش از تضاد کف سفید و کرمای قهوه‌ای پدید می‌آید.</li><li>تاریخچه: ابتدا در ایتالیا (بدون تاریخ مشخص)؛ در سیاتل دهه‌های ۱۹۸۰ و ۱۹۹۰ با David Schomer رواج یافت؛ او توسعه‌ی میکروفوم را به Jack Kelly در ۱۹۸۶ نسبت می‌دهد؛ طرح قلب تا ۱۹۸۹ و رزتا را Schomer در ۱۹۹۲ ساخت.</li><li>الگوهای پایه: قلب و لاله (tulip)؛ رزتا پیچیده‌تر. روش‌ها: ریختن آزاد (free pour) و حکاکی (etching) با چوب پس از ریختن شیر.</li><li>میکروفوم: کفی از هوا در شیر؛ همراه با کرما دو کلوئید ناپایدارند، پس طرح‌ها فقط مدت کوتاهی می‌مانند.</li></ul>","kind":"item","src":[["Wikipedia — Latte art","https://en.wikipedia.org/wiki/Latte_art"]]},{"id":317,"title":"فرهنگ‌های خاص سرو قهوه در جهان","body":"<h4 class=\"sub\">مراسم‌های ویژه‌ی قهوه</h4><ul><li>مراسم قهوه‌ی اتیوپی/اریتره: معمولاً زن خانه اجرا می‌کند؛ روی زمین علف پهن می‌شود؛ دانه‌ی سبز در تابه روی شعله برشته و عطرش میان مهمانان پخش می‌شود؛ با هاون چوبی mukecha آسیاب و در ظرف سفالی jebena دم و چندبار صاف می‌شود؛ در فنجان‌های بی‌دسته ریخته می‌شود. شکر رایج است؛ در مناطق روستایی نمک یا کره‌ی ادویه‌دار (niter kibbeh). خوراکی کنارش: ذرت بوداده، بادام‌زمینی یا هیمباشا.</li><li>سه دور: اول «abol/awel»، دوم «tona/kale’i»، سوم «baraka» یعنی «برکت». ممکن است بخور سوزانده شود.</li><li>قهوه‌ی عربی: فنجان‌های بی‌دسته تا نیمه، سه فنجان، ساعتگرد با خرما؛ قهوه‌ی ترکی با لیوان آب.</li></ul>","kind":"item","src":[["Wikipedia — Coffee ceremony","https://en.wikipedia.org/wiki/Coffee_ceremony"],["Wikipedia — Arabic coffee","https://en.wikipedia.org/wiki/Arabic_coffee"],["Wikipedia — Turkish coffee","https://en.wikipedia.org/wiki/Turkish_coffee"]]},{"id":318,"title":"جدول مقایسه‌ای روش‌های سرو بر اساس کشور","body":"<h4 class=\"sub\">فرهنگ قهوه به تفکیک کشور</h4><ul><li>ایتالیا: اسپرسو معمولاً ایستاده پشت پیشخوان نوشیده می‌شود نه همراه‌بر؛ نوشیدنی‌های شیردار معمولاً فقط صبح. Caffè Florian ونیز قدیمی‌ترین کافه‌ی ایتالیاست. ساکنان تریسته سالانه حدود ۱۵۰۰ فنجان (حدود دو برابر میانگین ایتالیا) می‌نوشند.</li><li>اتریش (وین): قهوه‌خانه محل گفت‌وگو، مطالعه و تبادل فرهنگی است؛ گفته می‌شود کاپوچینو از Kapuziner وینی پدید آمد.</li><li>سوئد: «فیکا» (fika) — استراحت قهوه با شیرینی — نهاد اجتماعی مرکزی است؛ قهوه ۱۶۸۵ به گوتنبرگ رسید و محدودیت‌ها ۱۸۲۳ برداشته شد.</li><li>فنلاند: معمولاً رتبه‌ی اول مصرف سرانه (حدود ۱۲ کیلو در سال). آلمان و کشورهای شمال اروپا: قهوه‌ی تلخ قوی کنار غذا و پرکردن رایگان.</li><li>آمریکا: بزرگ‌ترین بازار قهوه؛ اغلب همراه‌بر و فنجان بزرگ (تا ۲۴ اونس).</li><li>ژاپن: نخستین کافه ۱۸۸۸ در توکیو؛ کیسا‌تن‌ها از دهه‌ی ۱۹۲۰ شکوفا و در دهه‌ی ۱۹۷۰ فراگیر شدند. هنگ‌کنگ: یوئن‌یوئنگ (قهوه با چای) در ۱۹۳۶. شانگهای حدود ۶۵۰۰ کافه؛ کره‌ی جنوبی: افزایش ۹۰۰٪ کافه‌ها از ۲۰۰۶ تا ۲۰۱۱؛ آلبانی در ۲۰۱۶ بیشترین کافه به نسبت جمعیت (۶۵۴ در هر ۱۰۰ هزار نفر).</li><li>استرالیا: مهاجران یونانی فرهنگ کافه را ساختند. ترکیه و سرزمین‌های عثمانی: قهوه‌ی ترکی غالب؛ قهوه‌خانه‌ها تا ۱۶۰۰ در زندگی عثمانی برجسته بودند.</li><li>یمن: صوفیان قهوه می‌نوشیدند تا هنگام ذکر تمرکز کنند؛ قهوه از بندر مخا صادر می‌شد.</li></ul><h4 class=\"sub\">وین و کیسا‌تن</h4><ul><li>وین: از اکتبر ۲۰۱۱ در فهرست ملی میراث ناملموس اتریش؛ میز مرمر، صندلی تونه، میز روزنامه؛ با قهوه لیوان آب سرد می‌آورند و بی‌درخواست پر می‌کنند؛ پژوهش‌های جدید نخستین قهوه‌خانه را به Johannes Theodat (۱۶۸۵) نسبت می‌دهند و افسانه‌ی Kulczycki را رد می‌کنند.</li><li>کیسا‌تن ژاپنی: «چای‌خانه‌ی» قهوه‌فروش آرام، الهام‌گرفته از سالن‌های پاریس و وین؛ سرویس صبحانه با نان تست ضخیم و تخم‌مرغ.</li></ul>","kind":"item","src":[["Wikipedia — Coffee culture","https://en.wikipedia.org/wiki/Coffee_culture"],["Wikipedia — Viennese coffee house culture","https://en.wikipedia.org/wiki/Viennese_coffee_house_culture"],["Wikipedia — Kissaten","https://en.wikipedia.org/wiki/Kissaten"]]},{"id":320,"title":"فرهنگ قهوه در ایران – از صفویه تا امروز","body":"<h4 class=\"sub\">قهوه در ایران</h4><ul><li>قهوه در دوره‌ی صفوی (قرن شانزدهم) از راه تجارت با عثمانی و جهان عرب به ایران رسید و به شهرهایی مثل اصفهان و شیراز راه یافت.</li><li>در دوره‌ی قاجار قهوه‌خانه‌ها بیشتر محل چای بودند و گاهی قهوه هم داشتند؛ با فراگیرشدن چای سیاه مصرف قهوه کاهش یافت.</li><li>در سده‌ی بیستم نخستین کافه‌های مدرن تهران، با الهام از فرهنگ کافه‌ی اروپایی، جایگاه قهوه را بازگرداندند. امروز قهوه پس از چای دومین نوشیدنی گرم محبوب ایران است.</li><li>جنوب (بوشهر و خوزستان) قهوه‌ی تلخ عربی‌سبک با هل و زعفران را ترجیح می‌دهد؛ شهرها بیشتر نوشیدنی‌های اروپایی مثل اسپرسو، لاته و کاپوچینو.</li><li>ایران تقریباً همه‌ی دانه‌ی قهوه‌اش را وارد می‌کند چون اقلیم برای تولید انبوه مناسب نیست.</li><li>ژان شاردن (سیاح فرانسوی، قرن هفدهم) قهوه‌خانه‌ی ایرانی را جایی برای خبر، بحث سیاسی، بازی و قصه‌گویی توصیف کرد.</li></ul>","kind":"item","src":[["Wikipedia — Coffee in Iran","https://en.wikipedia.org/wiki/Coffee_in_Iran"],["Wikipedia — Coffeehouse","https://en.wikipedia.org/wiki/Coffeehouse"]]},{"id":323,"title":"قهوه در ادیان و آیین‌های معنوی","body":"<h4 class=\"sub\">قهوه و دین</h4><ul><li>صوفیان یمن در اواخر قرن پانزدهم قهوه را برای بیداری در عبادت‌های شبانه و حالتی «مستی معنوی» هنگام ذکر به کار می‌بردند.</li><li>۱۵۱۱: دادگاه شرعی مکه به‌دلیل اثر محرک قهوه را ممنوع کرد. ۱۵۲۴: سلطان سلیمان این ممنوعیت را لغو و مفتی اعظم ابوالسعود فتوای جواز داد؛ قاهره ۱۵۳۲ ممنوعیت مشابهی گذاشت.</li><li>کلیسای ارتدوکس اتیوپی پیش از قرن ۱۸ قهوه را ممنوع کرده بود؛ در اواخر قرن نوزدهم (با نوشیدن امپراتور منلیک و کوشش ابونا متیوس برای زدودن باور «نوشیدنی مسلمانان») نگرش نرم شد.</li><li>پاپ کلمنت هشتم: برخی نمایندگان کلیسا در ایتالیا قهوه را «نوشیدنی شیطان» می‌خواندند و می‌گویند پاپ پس از چشیدن تأییدش کرد؛ درستی داستان نامعلوم است (سال معمول ۱۶۰۰).</li></ul>","kind":"item","src":[["Wikipedia — History of coffee","https://en.wikipedia.org/wiki/History_of_coffee"]]},{"id":405,"title":"قهوه و علوم سیاسی و اجتماعی (Coffee & Political & Social Sciences)","body":"<h4 class=\"sub\">قهوه‌خانه‌ها و جامعه</h4><ul><li>مکه: قهوه‌خانه‌ها در قرن پانزدهم رسیدند؛ روحانیان آن‌ها را محل اجتماعات سیاسی و نوشیدن می‌دیدند و از ۱۵۱۲ تا ۱۵۲۴ ممنوع شدند اما ممنوعیت دوام نیاورد.</li><li>استانبول: طبق ابراهیم پچوی تا حدود ۱۵۵۵ قهوه‌خانه‌ای نبود؛ دو مرد از حلب و دمشق در تخته‌قلعه باز کردند؛ آن‌ها را «مدارس حکمت» هم نامیده‌اند.</li><li>بلگراد ۱۵۲۱ (نخستین در اروپا)، ساراییوو حدود ۱۵۳۲؛ لندن: Pasqua Rosée در ۱۶۵۲؛ تا ۱۶۷۵ بیش از ۳۰۰۰ قهوه‌خانه در انگلستان و حدود ۵۵۰ در لندن در اوج قرن هجدهم؛ وین: Johannes Diodato در ۱۶۸۵ (افسانه‌ی Kulczycki افسانه تلقی می‌شود).</li></ul>","kind":"item","src":[["Wikipedia — Coffeehouse","https://en.wikipedia.org/wiki/Coffeehouse"]]},{"id":417,"title":"قهوه و فمینیسم (Coffee & Feminism)","body":"<h4 class=\"sub\">زنان در تولید قهوه (گزارش سازمان بین‌المللی قهوه)</h4><ul><li>تا ۷۰٪ نیروی کار تولید قهوه را زنان تأمین می‌کنند (بسته به منطقه)؛ در کار مزرعه تا ۹۰٪ و در برداشت تا ۸۰٪؛ در سامانه‌های بسیار مکانیزه مثل برزیل سهم زنان کمتر است.</li><li>حدود ۲۰ تا ۳۰٪ مزارع قهوه را زنان اداره می‌کنند (حدود ۵ میلیون از ۲۵ میلیون تولیدکننده).</li><li>زنان به‌طور میانگین ۲۵٪ کمتر از مردان زمین دارند؛ شکاف از ۲۰٪ در اوگاندا تا ۴۰٪ در تانزانیا. در نیکاراگوئه ۴۵٪ خانوارهای مردسرپرست زمین دارند و کمی بیش از ۱۰٪ خانوارهای زن‌سرپرست.</li><li>درآمد فروش قهوه در خانوارهای زن‌سرپرست در اتیوپی ۳۹٪ و در اوگاندا ۴۴٪ کمتر است. در کلمبیا و اکوادور قیمت دریافتی زنان و مردان مشابه بود.</li><li>در اوگاندا ۳۹٪ سرپرستان مرد حساب پس‌انداز شخصی دارند در برابر ۲۴٪ سرپرستان زن؛ زنان کمتر وام می‌گیرند (در کلمبیا و اکوادور تفاوتی در دسترسی به وام دیده نشد).</li><li>گزارش ارقام دستمزد کارگران را ارائه نمی‌کند.</li></ul>","kind":"item","src":[["ICO — گزارش برابری جنسیتی (ICC 122-11)","https://ico.org/documents/cy2017-18/icc-122-11e-gender-equality.pdf"]]},{"id":429,"title":"قهوه و گردشگری (Coffee & Tourism)","body":"<h4 class=\"sub\">گردشگری قهوه</h4><ul><li>منظر فرهنگی قهوه‌ی کلمبیا در ۲۰۱۱ در فهرست میراث جهانی یونسکو ثبت شد: ۱۸ سکونتگاه شهری در شش مکان در «محور قهوه» که تا دره‌ی کائوکا ادامه دارد؛ روش‌های سنتی کشت، فرهنگ منطقه و جشن‌های ویژه‌اش را حفظ کرده است؛ شامل شهرهایی مثل آرمنیا، کالارکا، سالامینا، پریرا و ریوسوسیو.</li><li>قهوه‌خانه‌های تاریخی مکه، استانبول، لندن و وین هم مقصد فرهنگی‌اند (جزئیات در مقاله‌ی «قهوه‌خانه‌ها و جامعه»).</li></ul>","kind":"item","src":[["Wikipedia — Coffee Cultural Landscape of Colombia","https://en.wikipedia.org/wiki/Coffee_Cultural_Landscape_of_Colombia"],["Wikipedia — Coffeehouse","https://en.wikipedia.org/wiki/Coffeehouse"]]},{"id":451,"title":"قهوه و فلسفه‌ی شرق (Coffee & Eastern Philosophy)","body":"<h4 class=\"sub\">قهوه و سنت صوفیانه</h4><ul><li>سلسله‌های صوفی در یمن از قهوه (قهوه) برای بیدار ماندن در ذکر شبانه استفاده می‌کردند؛ هدف حمایت از عبادت و تمرکز بود. نام قهوه از بندر مخا گرفته شد.</li><li>پیوند قهوه با صوفیان یمن و زائران مکه در قرن پانزدهم برای رسیدن آن به ترکیه، مصر و شام ذکر می‌شود.</li><li>در قرن شانزدهم برخی علما قهوه را با الکل و حشیش یکی شمردند و دیگران آن را غیرمسکر و مجاز دانستند و به کاربردش برای بیداری در نماز و مطالعه و نقش اجتماعی‌اش استناد کردند؛ سرانجام قهوه‌خانه‌ها پذیرفته شدند.</li><li>قهوه‌خانه‌های عربی «مکتب‌خانه‌ی حکیمان» نامیده شدند، یعنی مرکز بحث فکری و نه فقط استراحت.</li></ul>","kind":"item","src":[["Wikipedia — Coffeehouses in Arabic culture","https://en.wikipedia.org/wiki/Coffeehouses_in_Arabic_culture"],["Wikipedia — Coffee in world cultures","https://en.wikipedia.org/wiki/Coffee_in_world_cultures"]]}]},{"id":"C13","icon":"art","title":"قهوه در هنر، رسانه و ورزش","items":[{"id":182,"title":"کافه و قهوه در ادبیات، سینما و هنر‌های تجسمی (برای بخش فرهنگی)","body":"<h4 class=\"sub\">قهوه در هنر</h4><ul><li>«کانتات قهوه» باخ (۱۷۳۲–۱۷۳۵) نمونه‌ی مستند حضور قهوه در هنر موسیقی است؛ جزئیات در مقاله‌ی «قهوه در ادبیات، شعر، سینما…» آمده است.</li><li>متن «کانتات قهوه» از کریستیان فریدریش هنریسی (پیکاندر) است؛ اثری طنز درباره‌ی اعتیاد به قهوه که ده بخش و سه خواننده‌ی سولو (سوپرانو، تنور، باس) دارد.</li><li>در داستان، پدری می‌کوشد دخترش را از نوشیدن قهوه بازدارد؛ دختر می‌پذیرد قهوه را کنار بگذارد به شرط یافتن عاشق، اما پنهانی به خواستگاران می‌گوید باید اجازه‌ی نوشیدن قهوه را به او بدهند.</li><li>احتمالاً این اثر در ۱۷۳۵ در قهوه‌خانه‌ی تسیمرمان لایپزیگ اجرا شد.</li><li>«تراس کافه در شب» ون‌گوگ در ۱۸۸۸ در آرل کشیده شد و در موزه‌ی کرولر-مولر هلند است؛ نخستین بار در ۱۸۹۱ با عنوان «قهوه‌خانه، شامگاه» نمایش داده شد.</li><li>«شب‌گردها» اثر ادوارد هاپر در ۱۹۴۲ تمام شد و در موسسه‌ی هنر شیکاگو است؛ چهار نفر را در یک غذاخوری شبانه نشان می‌دهد.</li></ul>","kind":"item","src":[["Wikipedia — Coffee Cantata","https://en.wikipedia.org/wiki/Coffee_Cantata"],["Wikipedia — Café Terrace at Night","https://en.wikipedia.org/wiki/Caf%C3%A9_Terrace_at_Night"],["Wikipedia — Nighthawks (Hopper)","https://en.wikipedia.org/wiki/Nighthawks_(Hopper)"],["Wikipedia — Coffee culture","https://en.wikipedia.org/wiki/Coffee_culture"]]},{"id":200,"title":"قهوه و ورزش (علم تمرین)","body":"<h4 class=\"sub\">قهوه و ورزش</h4><ul><li>کافئین «کمک‌ارگوژنیک اثبات‌شده» برای انسان توصیف می‌شود.</li><li>دوز حدود ۵ میلی‌گرم به ازای هر کیلوگرم می‌تواند عملکرد سرعت، دوی و دوچرخه‌سواری زمان‌دار و توان دوچرخه را بهبود دهد؛ ممکن است خستگی عضلانی و مرکزی را به تعویق بیندازد.</li><li>پیش از ورزش هوازی اکسیداسیون چربی را بالا می‌برد (به‌ویژه در افراد با آمادگی کمتر).</li><li>نیمه‌عمر کافئین در بزرگسالان سالم ۳ تا ۷ ساعت است.</li><li>EFSA تا ۴۰۰ میلی‌گرم در روز (حدود ۵٫۷ میلی‌گرم بر کیلو) را برای بزرگسالان غیرباردار بی‌خطر می‌داند.</li></ul>","kind":"item","src":[["Wikipedia — Caffeine","https://en.wikipedia.org/wiki/Caffeine"]]},{"id":324,"title":"قهوه در ادبیات، شعر، سینما و هنر‌های تجسمی (با مثال‌های دقیق)","body":"<h4 class=\"sub\">قهوه و موسیقی/ادبیات</h4><ul><li>«کانتات قهوه» (BWV 211) اثر یوهان سباستین باخ، احتمالاً بین ۱۷۳۲ و ۱۷۳۵ با متن Picander (Christian Friedrich Henrici) نوشته شد و احتمالاً در قهوه‌خانه‌ی تسیمرمان لایپزیگ، جایی که باخ «کولژیوم موزیکوم» را رهبری می‌کرد، اجرا شد.</li><li>داستان: اپرای کمیک کوچک و طنزآمیز درباره‌ی اعتیاد به قهوه؛ پدر (Schlendrian) می‌کوشد دخترش Lieschen را از قهوه بازدارد؛ او حاضر می‌شود قهوه را کنار بگذارد به شرط یافتن عاشق، و به خواستگاران می‌گوید باید نوشیدن قهوه را اجازه دهند. سه‌گانه‌ی پایانی می‌گوید قهوه‌نوشی طبیعی است.</li></ul>","kind":"item","src":[["Wikipedia — Coffee Cantata","https://en.wikipedia.org/wiki/Coffee_Cantata"]]},{"id":325,"title":"قهوه در ورزش و تناسب‌اندام (علم تمرین)","body":"<h4 class=\"sub\">قهوه و تناسب‌اندام</h4><ul><li>کافئین کمک‌ارگوژنیک اثبات‌شده است؛ حدود ۵ میلی‌گرم بر کیلو عملکرد را بهتر می‌کند.</li><li>نیمه‌عمر ۳ تا ۷ ساعت؛ برای خواب مصرف دیروقت را در نظر بگیرید.</li><li>سقف ایمن ۴۰۰ میلی‌گرم در روز (EFSA و Health Canada).</li><li>هر فنجان قهوه‌ی فیلتری ۶ اونسی حدود ۵۰ تا ۱۷۵ میلی‌گرم کافئین دارد؛ دم‌شده‌ی قطره‌ای ۲۰۷ میلی‌لیتری ۱۱۵–۱۷۵ و بی‌کافئین ۵–۱۵ میلی‌گرم.</li><li>مرور موضع‌گیری انجمن بین‌المللی تغذیه ورزشی: دوزهای ۳ تا ۶ میلی‌گرم بر کیلوگرم وزن بدن به‌طور پیوسته عملکرد ورزشی را بهتر می‌کنند و حداقل دوز مؤثر شاید تا ۲ میلی‌گرم بر کیلوگرم پایین باشد.</li><li>رایج‌ترین زمان مصرف ۶۰ دقیقه پیش از تمرین است؛ در استقامت هوازی بهبود ۲ تا ۴ درصد گزارش شده است.</li><li>دوزهای خیلی بالا مثل ۹ میلی‌گرم بر کیلوگرم با عوارض زیاد همراه‌اند و برای اثر کمک‌ارگوژنیک لازم نیستند.</li><li>EFSA می‌گوید دوز تکی تا ۲۰۰ میلی‌گرم برای بزرگسالان نگرانی ایمنی ایجاد نمی‌کند، حتی اگر کمتر از دو ساعت پیش از ورزش شدید مصرف شود.</li><li>اثر کافئین بر خواب و اضطراب بین افراد فرق می‌کند و ممکن است به تفاوت‌های ژنتیکی مربوط باشد.</li></ul>","kind":"item","src":[["Wikipedia — Caffeine","https://en.wikipedia.org/wiki/Caffeine"],["PMC — International Society of Sports Nutrition position stand: caffeine and exercise performance","https://pmc.ncbi.nlm.nih.gov/articles/PMC7777221"],["EUFIC — EFSA opinion on the safety of caffeine","https://eufic.org/en/whats-in-food/article/efsa-opinion-on-the-safety-of-caffeine"],["FoodNavigator — EFSA: 400mg of caffeine a day is safe","https://www.foodnavigator.com/Article/2015/01/16/efsa-400mg-of-caffeine-a-day-is-safe/"]]},{"id":484,"title":"قهوه و هنر‌های رزمی (Coffee & Martial Arts)","body":"<h4>⚡ کافئین و عملکرد ورزشی</h4><p>بیانیه‌ی ISSN (۲۰۲۱): کافئین با دُز ۳ تا ۶ میلی‌گرم به ازای هر کیلوگرم وزن بدن، معمولاً ۶۰ دقیقه قبل از ورزش، استقامت را ۲ تا ۴٪ بهبود داده و در سه فراتحلیل اثر کوچک ۲ تا ۷٪ بر قدرت دیده شده است. عوارض با افزایش دُز بیشتر می‌شود (تپش قلب، اضطراب، سردرد و اختلال خواب). برای مثال برای فرد ۷۰ کیلویی دُز ۳ تا ۶ میلی‌گرم بر کیلوگرم برابر ۲۱۰ تا ۴۲۰ میلی‌گرم است، که از سقف ۴۰۰ میلی‌گرم روزانه‌ی FDA/EFSA هم بالاتر می‌رود؛ حواستان به مجموع مصرف روزانه باشد.</p>","kind":"item","src":[["ISSN position stand: caffeine and exercise performance (2021)","https://link.springer.com/article/10.1186/s12970-020-00383-4"],["EFSA — Caffeine","https://www.efsa.europa.eu/en/topics/topic/caffeine"]]},{"id":496,"title":"قهوه و فرهنگ عامه (Coffee & Pop Culture)","body":"<h4 class=\"sub\">قهوه و فرهنگ عامه</h4><ul><li>استارباکس ۳۰ مارس ۱۹۷۱ در بازار Pike Place سیاتل توسط Jerry Baldwin، Zev Siegl و Gordon Bowker تأسیس شد و الهام‌بخش آن Alfred Peet بود؛ Howard Schultz در ۱۹۸۷ آن را خرید. فراپوچینو در ۱۹۹۵ با نام استارباکس عرضه شد (پس از خرید The Coffee Connection در ۱۹۹۴). تا نوامبر ۲۰۲۲ حدود ۳۵٬۷۱۱ شعبه در ۸۰ کشور.</li><li>«کانتات قهوه»ی باخ (۱۷۳۲–۱۷۳۵) نمونه‌ی مستند حضور قهوه در موسیقی است.</li></ul>","kind":"item","src":[["Wikipedia — Starbucks","https://en.wikipedia.org/wiki/Starbucks"],["Wikipedia — Coffee Cantata","https://en.wikipedia.org/wiki/Coffee_Cantata"]]},{"id":716,"title":"هنر لاته‌آرت: تاریخ و گریدبندی","body":"<p>لاته‌آرت روشی است که با ریختن میکروفوم در شات اسپرسو الگو می‌سازد؛ طرح از ترکیب کرمای اسپرسو (امولسیون روغن قهوه و قهوه‌ی دم‌شده) و میکروفوم (هوا در شیر) پدید می‌آید و روی لاته، کاپوچینو یا شکلات داغ اجرا می‌شود.</p><h4>تاریخچه</h4><ul><li>لاته‌آرت پس از معرفی اسپرسو و ساخت میکروفوم در چند کشور مستقل شکل گرفت و ابتدا در ایتالیا.</li><li>در آمریکا در دهه‌های ۱۹۸۰ و ۱۹۹۰ در سیاتل رشد کرد و دیوید شومر آن را رایج کرد. او ساخت میکروفوم را به جک کلی از Uptown Espresso در ۱۹۸۶ نسبت می‌دهد.</li><li>۱۹۸۹: طرح قلب نشان ویژه‌ی Espresso Vivace شومر بود؛ ۱۹۹۲ شومر روزتا را از روی عکسی از Cafe Mateki ایتالیا ساخت.</li><li>در ایتالیا لوئیجی لوپی از Caffè Musetti با ویدیوهای آموزشی آن را رایج کرد؛ او و شومر اواخر دهه‌ی ۱۹۹۰ از راه اینترنت آشنا شدند.</li><li>۲۰۰۲: لوپی در مسابقات جهانی باریستا چهارم شد و اعتبار جهانی گرفت.</li></ul><h4>روش‌ها و طرح‌ها</h4><p>فری‌پور: الگو هنگام ریختن شکل می‌گیرد. اچینگ: پس از ریختن با چوب نقش می‌کشند. قلب و لاله طرح‌های پایه‌اند و روزتا طرح پیچیده‌تر درجه‌های بالاتر.</p><h4>گریدبندی (LAGS)</h4><p>لوئیجی لوپی و لوکا رامونی آن را ساختند: ابتدا پنج درجه با رنگ‌های سفید، نارنجی، سبز، قرمز و سیاه، و بعدها طلایی به‌عنوان درجه‌ی ششم.</p>","kind":"item","src":[["Wikipedia — Latte art","https://en.wikipedia.org/wiki/Latte_art"]]}]},{"id":"C14","icon":"folklore","title":"خرافات، فال و باورهای عامیانه","items":[{"id":198,"title":"تاریخچه‌ی فال قهوه (قهوه‌خوانی) – از ابتدا تا به‌امروز","body":"<h4 class=\"sub\">فال قهوه</h4><ul><li>فال قهوه شاخه‌ای از «تاسئوگرافی» (tasseography) است: تفسیر الگوهای تفاله‌ی چای، قهوه یا شراب. نام از tasse فرانسوی («فنجان») که ریشه‌ی عربی دارد.</li><li>طبق برخی منابع، فال قهوه در کاخ‌های عثمانی در قرن شانزدهم پدید آمد.</li><li>روش: فنجان روی نعلبکی وارونه می‌شود و نقش‌های ته‌نشین‌شده خوانده می‌شوند؛ نیمه‌ی پایین فنجان گذشته و نیمه‌ی بالا آینده؛ برخی خوانندگان فنجان را عمودی هم تقسیم می‌کنند (چپ منفی، راست مثبت). برخی باور دارند فنجان پیش‌بینی بیش از چهل روز را نشان نمی‌دهد.</li><li>فال‌گیری باور فرهنگی است و پایه‌ی علمی ندارد.</li></ul>","kind":"item","src":[["Wikipedia — Tasseography","https://en.wikipedia.org/wiki/Tasseography"]]},{"id":462,"title":"قهوه و طالع‌بینی، طلسم‌ها و خرافات (Coffee & Divination, Spells & Superstitions)","body":"<h4 class=\"sub\">فال و باورها</h4><ul><li>فال قهوه یکی از انواع تاسئوگرافی است؛ گزارش‌های تاریخی آن به قرن شانزدهم عثمانی می‌رسد و در انگلستان اواخر قرن نوزدهم فال چای سرگرمی مجلسی بود.</li><li>این‌ها باور و سرگرمی فرهنگی‌اند؛ پایه‌ی علمی ندارند.</li><li>در فال قهوه‌ی ترکی، فنجان معمولاً از وسط افقی تقسیم می‌شود: نمادهای نیمه‌ی پایین به گذشته و نمادهای نیمه‌ی بالا به آینده مربوط‌اند.</li><li>در تقسیم عمودی فنجان برای پرسش‌های بله و خیر، سمت چپ منفی و سمت راست مثبت خوانده می‌شود.</li><li>برخی فالگیران باور دارند فنجان گذشته را نشان می‌دهد و رویدادهای بیش از چهل روز بعد را نمی‌توان از آن خواند.</li><li>فال قهوه سنتاً با قهوه‌ی عربی یا ترکی انجام می‌شود، چون ته‌نشین غلیظ می‌دهد؛ پس از نوشیدن، فنجان را وارونه روی نعلبکی می‌گذارند و می‌چرخانند تا تفاله شکل بگیرد.</li><li>تفسیر شکل‌ها به فالگیر بستگی دارد و یک شکل می‌تواند برای دو فالگیر دو معنای متفاوت داشته باشد؛ منبع‌ها شواهد معتبری برای یک خاستگاه واحد نیافته‌اند.</li></ul>","kind":"item","src":[["Wikipedia — Tasseography","https://en.wikipedia.org/wiki/Tasseography"],["Food Network — Fortune telling with Turkish coffee grinds","https://www.foodnetwork.com/fn-dish/how-to/2021/04/fortune-telling-with-turkish-coffee-grinds-melis-aydogan"],["USC Digital Folklore Archive — Turkish Coffee Fortune Telling","https://folklore.usc.edu/?p=66057"]]},{"id":701,"title":"خرافات رایج درباره‌ی قهوه: درست یا غلط؟","body":"<h4 class=\"sub\">باورهای رایج: شواهد</h4><ul><li>قلب و عروق: مصرف متوسط عامل خطر بیماری عروق کرونر نیست؛ ۳ تا ۵ فنجان در روز قهوه‌ی کافئین‌دار با خطر کمتر بیماری قلبی-عروقی و ۳ تا ۴ فنجان با خطر کمتر سکته همراه است؛ بیش از ۵ فنجان با خطر بیشتر. قهوه‌ی بدون فیلتر LDL را بالا می‌برد. راهنمای ESC سال ۲۰۲۱: ۳ تا ۴ فنجان «احتمالاً بی‌ضرر و شاید تا حدی مفید».</li><li>مرگ‌ومیر: مرور چتری ۲۰۱۷ قهوه را در سطوح معمول مصرف «عموماً ایمن» دانست؛ فراتحلیل ۲۰۱۴: چهار فنجان در روز با ۱۶٪ کاهش خطر مرگ از هر علت، بدون ارتباط با مرگ سرطانی.</li><li>بارداری:  ارتباط احتمالی با سقط یا وزن کم تولد مطرح است اما کیفیت مطالعات محدود است.</li><li>بیشتر یافته‌ها مشاهده‌ای است و با کیفیت مطالعه، سن، جنس، سلامت و اندازه‌ی سرو فرق می‌کند.</li></ul>","kind":"item","src":[["Wikipedia — Coffee and health","https://en.wikipedia.org/wiki/Coffee_and_health"]]},{"id":702,"title":"سنت‌های قهوه‌ی میهمانی و آیین‌های نمادین","body":"<h4 class=\"sub\">آیین‌ها و میهمانی</h4><ul><li>خواستگاری ترکی: خانواده‌ی داماد به خانه‌ی عروس می‌روند؛ دختر قهوه را می‌پزد و برای داماد گاهی به‌جای شکر نمک می‌ریزد — اگر بی‌نارضایتی بنوشد او را صبور و خوش‌اخلاق می‌داند. در برخی مناطق قهوه‌ی بدون کف نشانه‌ی رد است.</li><li>معمولاً ابتدا یک لیوان آب برای شست‌وشوی دهان می‌دهند و قهوه را با شیرینی کوچک (مثل راحت‌الحلقوم) در فنجان چینی ظریف سرو می‌کنند؛ فال قهوه (tasseography) هم بخشی از جو اجتماعی است.</li><li>قهوه‌ی عربی: سه فنجان، ساعتگرد، با خرما (مقاله‌ی «قهوه‌ی عربی»).</li></ul>","kind":"item","src":[["Wikipedia — Turkish coffee","https://en.wikipedia.org/wiki/Turkish_coffee"],["Wikipedia — Arabic coffee","https://en.wikipedia.org/wiki/Arabic_coffee"]]}]},{"id":"C15","icon":"vocabulary","title":"واژگان، اصطلاحات و آموزش قهوه","items":[{"id":230,"title":"مقیاس‌های اندازه‌گیری جهانی (روش‌های غیرکتابی)","body":"<h4>مقیاس Agtron (شدت برشته‌کاری)</h4><p>عدد کمتر یعنی برشته‌ی تیره‌تر. جدول Coffee Review:</p><div class=\"table-wrap\"><table><thead><tr><th>دسته</th><th>عدد Agtron</th><th>توضیح</th></tr></thead><tbody><tr><td>روشن</td><td>بیش از ۸۰</td><td>قهوه‌ای روشن تا دارچینی؛ بدنه‌ی سبک؛ بدون روغن سطحی</td></tr><tr><td>متوسط‑روشن</td><td>۷۰ تا ۸۰</td><td>اسیدیته‌ی روشن و شیرین</td></tr><tr><td>متوسط</td><td>۶۰ تا ۷۰</td><td>اسیدیته‌ی متعادل، بدنه‌ی کامل‌تر</td></tr><tr><td>متوسط‑تیره</td><td>۵۰ تا ۶۰</td><td>ممکن است قطرات روغن دیده شود</td></tr><tr><td>تیره</td><td>۴۰ تا ۵۰</td><td>از لکه‌ی روغن تا سطح براق؛ طعم برشته‌ی تلخ</td></tr><tr><td>بسیار تیره</td><td>۲۵ تا ۴۰</td><td>سطح سیاه و روغنی</td></tr><tr><td>بسیار تیره‌ی افراطی</td><td>کمتر از ۲۵</td><td>سطح براق سیاه؛ تلخی سوخته</td></tr></tbody></table></div><p>اعداد بین دستگاه‌ها و منابع کمی متفاوت‌اند.</p>","kind":"item","src":[["Coffee Review — Roast definitions (Agtron)","https://www.coffeereview.com/roast-definitions/"]]},{"id":541,"title":"قهوه و آموزش (Coffee & Education)","body":"<h4 class=\"sub\">آموزش قهوه</h4><ul><li>SCAA در ۱۹۸۲ به‌عنوان انجمن غیرانتفاعی صنعت قهوه‌ی تخصصی تأسیس شد (اعضا در بیش از ۴۰ کشور). در ژانویه ۲۰۱۷ با SCAE ادغام و «Specialty Coffee Association» (SCA) شد با بیش از ۱۰٬۰۰۰ عضو فعال.</li><li>باریستا: معمولاً کارمند قهوه‌خانه که نوشیدنی‌های اسپرسویی می‌سازد؛ واژه ایتالیایی و به‌معنای «بارمن» است. مربی معمولاً برشته‌کار یا صاحب کافه است؛ کلاس آموزشی هست اما بیشتر باریستاها سرکار یاد می‌گیرند. نوشیدنی‌های شیردار مهارت اضافه‌ی کف‌دهی و لاته‌آرت می‌خواهند.</li><li>مسابقات رسمی باریستا از نروژ آغاز شد؛ World Barista Championship هر سال در محلی دیگر برگزار می‌شود.</li><li>برای جزئیات برنامه‌ها و گواهینامه‌های SCA (مثل Coffee Skills Program) به sca.coffee مراجعه کنید.</li></ul>","kind":"item","src":[["Wikipedia — Specialty Coffee Association","https://en.wikipedia.org/wiki/Specialty_Coffee_Association"],["Wikipedia — Barista","https://en.wikipedia.org/wiki/Barista"]]},{"id":720,"title":"واژگان کاپینگ: چگونه قهوه را «بچشیم»","body":"<p>اصطلاحات رایج کاپینگ:</p><div class=\"table-wrap\"><table><thead><tr><th>اصطلاح</th><th>تعریف</th></tr></thead><tbody><tr><td>سُرپ (Slurp)</td><td>مکیدن صدادار قهوه از قاشق تا هوا بگیرد و روی زبان پخش شود.</td></tr><tr><td>بدنه (Body)</td><td>ویژگی فیزیکی نوشیدنی؛ حس دهانی کامل، قوی و خوشایند در برابر نازک.</td></tr><tr><td>اسیدیته (Acidity)</td><td>طعمی پایه از اسید آلی؛ وقتی تیز و دلپذیر باشد مطلوب است و با ترشی ناخوشایند تخمیر بیش‌ازحد فرق دارد.</td></tr><tr><td>شیرینی (Sweetness)</td><td>طعمی پایه از ساکارز یا فروکتوز؛ برای قهوه‌ی بدون طعم ناخوشایند.</td></tr><tr><td>طعم (Flavour)</td><td>«ویژگی‌هایی که در فنجان هست».</td></tr><tr><td>پس‌مزه (Aftertaste)</td><td>چیزی که چشندگان می‌سنجند؛ گزندگی (astringency) حس خشکی در دهان است.</td></tr><tr><td>آروما (Aroma)</td><td>توصیف‌هایی مثل میوه‌ای و مرکباتی، شکلاتی و خاکی.</td></tr></tbody></table></div><p>پروتکل دقیق کاپینگ و نمره‌دهی در آن صفحه نیست. تعریف قهوه‌ی تخصصی: امتیاز ۸۰ یا بیشتر از ۱۰۰ در فرم کاپینگ SCA؛ بازه‌ی ۸۰ تا ۸۴٫۹۹ «خیلی خوب». حداکثر پنج عیب در هر ۳۵۰ گرم دانه‌ی فرآوری‌شده.</p>","kind":"item","src":[["Wikipedia — Coffee cupping","https://en.wikipedia.org/wiki/Coffee_cupping"],["Wikipedia — Specialty coffee","https://en.wikipedia.org/wiki/Specialty_coffee"]]},{"id":721,"title":"از میوه تا دانه: واژگان فرآوری","body":"<div class=\"table-wrap\"><table><thead><tr><th>اصطلاح</th><th>تعریف</th></tr></thead><tbody><tr><td>میوه‌ی قهوه (Cherry)</td><td>میوه‌ای که دانه از آن می‌آید؛ حدود هشت ماه پس از گل‌دهی از سبز به قرمز می‌رسد.</td></tr><tr><td>فرآوری شسته (Washed)</td><td>پوشش میوه پیش از خشک‌کردن برداشته می‌شود؛ تخمیر و شست‌وشو دارد. اغلب بالاترین کیفیت را می‌دهد ولی آب و مهارت زیاد می‌خواهد.</td></tr><tr><td>فرآوری طبیعی (Natural)</td><td>کل میوه پس از برداشت تمیز و زیر آفتاب خشک می‌شود؛ قدیمی‌ترین روش است.</td></tr><tr><td>هانی (Honey)</td><td>پوست برداشته می‌شود و موسیلاژ روی پرگامنت می‌ماند؛ هانی زرد، قرمز یا سیاه یعنی میزان موسیلاژ باقی‌مانده.</td></tr><tr><td>پرگامنت (Parchment)</td><td>لایه‌ی سخت دور دانه پس از برداشتن پالپ.</td></tr><tr><td>موسیلاژ (Mucilage)</td><td>لایه‌ی چسبناک بین پرگامنت و پالپ.</td></tr><tr><td>تخمیر (Fermentation)</td><td>در شسته، حدود ۱۲ تا ۳۶ ساعت؛ زیاده‌روی قهوه را ترش می‌کند.</td></tr><tr><td>پوست‌گیری (Hulling)</td><td>برداشتن لایه‌های خشک تا دانه‌ی سبز بماند.</td></tr><tr><td>قهوه‌ی سبز (Green)</td><td>دانه‌ی برشته‌نشده؛ پس از تمیز و دسته‌بندی آماده‌ی توزیع است.</td></tr><tr><td>برداشت یک‌جا (Strip)</td><td>همه‌ی میوه‌ها، رسیده یا نارس، برداشته می‌شود؛ سریع‌تر و ارزان‌تر.</td></tr><tr><td>برداشت انتخابی (Selective)</td><td>فقط میوه‌ی رسیده، با دست؛ هر ۸ تا ۱۰ روز؛ پرهزینه‌تر و برای عربیکای مرغوب.</td></tr></tbody></table></div>","kind":"item","src":[["Wikipedia — Coffee production","https://en.wikipedia.org/wiki/Coffee_production"]]},{"id":722,"title":"نام برشته‌ها و دماهایشان","body":"<p>کرک اول حدود ۱۹۶ و کرک دوم حدود ۲۲۴ درجه‌ی سانتی‌گراد است. دانه‌ها ۱۵ تا ۱۸٪ جرم خود را از دست می‌دهند و فاز خشک‌شدن (زردشدن) حدود ۱۶۵ درجه است. قهوه‌ی برشته‌شده CO₂ آزاد می‌کند و اگر وکیوم بسته‌بندی شود باید چند روز گاززدایی شود.</p><div class=\"table-wrap\"><table><thead><tr><th>گروه</th><th>نام</th><th>دما (°C)</th><th>توضیح</th></tr></thead><tbody><tr><td>روشن</td><td>دارچینی (Cinnamon)</td><td>۱۹۶</td><td>سطح خشک؛ بدنه‌ی سبک، اسیدیته‌ی بیشتر؛ شخصیت منشأ بیشترین.</td></tr><tr><td>روشن</td><td>نیوانگلند</td><td>۲۰۵</td></tr><tr><td>متوسط</td><td>آمریکایی</td><td>۲۱۰</td><td>اسیدیته‌ی ملایم‌تر، بدنه‌ی بیشتر.</td></tr><tr><td>متوسط</td><td>سیتی</td><td>۲۱۹</td></tr><tr><td>تیره</td><td>فول‌سیتی</td><td>۲۲۵</td><td>قهوه‌ای متوسط-تیره؛ آغاز کرک دوم.</td></tr><tr><td>تیره</td><td>فرنچ</td><td>۲۴۰</td><td>قهوه‌ای تیره و براق و روغنی؛ پایان کرک دوم.</td></tr><tr><td>تیره</td><td>ایتالین</td><td>۲۴۵</td><td>تقریباً سیاه و براق؛ طعم سوخته، بدنه‌ی نازک.</td></tr></tbody></table></div><p>در برشته‌ی تیره شخصیت منشأ بیشتر از دست می‌رود.</p>","kind":"item","src":[["Wikipedia — Coffee roasting","https://en.wikipedia.org/wiki/Coffee_roasting"]]},{"id":723,"title":"استخراج: واژگان و اعداد","body":"<div class=\"table-wrap\"><table><thead><tr><th>اصطلاح</th><th>تعریف</th></tr></thead><tbody><tr><td>بازده استخراج (Extraction yield)</td><td>جرم منتقل‌شده از تفاله به آب، به‌صورت درصدی از جرم اولیه‌ی تفاله.</td></tr><tr><td>TDS</td><td>مواد محلول کل، به‌صورت درصدی از نوشیدنی نهایی.</td></tr><tr><td>غلظت (Strength)</td><td>درصد مواد محلول در هر واحد از نوشیدنی نهایی.</td></tr><tr><td>نسبت دم‌آوری (Brew ratio)</td><td>نسبت قهوه به آب بر پایه‌ی جرم.</td></tr><tr><td>کم‌استخراجی</td><td>بازده زیر ۱۸٪؛ نوشیدنی غالباً ترش.</td></tr><tr><td>بیش‌استخراجی</td><td>بازده بالای ۲۲٪؛ نوشیدنی غالباً تلخ.</td></tr></tbody></table></div><p>محدوده‌ی معمول در آمریکای شمالی: بازده ۱۸ تا ۲۲٪ و غلظت ۱٫۱۵ تا ۱٫۳۵٪. شمال اروپا ۱٫۳۰ تا ۱٫۵۰٪ و دیگر کشورهای اروپایی ۱٫۲۰ تا ۱٫۴۵٪. در اسپرسو آب ممکن است ستون قهوه را ناهمگون اشباع کند و استخراج ناهمگون شود.</p>","kind":"item","src":[["Wikipedia — Coffee extraction","https://en.wikipedia.org/wiki/Coffee_extraction"]]}]},{"id":"C16","icon":"safety","title":"تقلب، اصالت‌سنجی و ایمنی مصرف‌کننده","items":[{"id":136,"title":"مدل‌های غیرقهوه‌ای که در منوی کافه‌ها «قهوه» نامیده می‌شوند","body":"<h4 class=\"sub\">جایگزین‌های قهوه</h4><ul><li>جنگ جهانی دوم: بلوط، کاسنی برشته و غلات؛ Postum (سبوس و ملاس) وقتی قهوه سهمیه‌بندی شد محبوب شد.</li><li>محاصره‌ی قاره‌ای در فرانسه و جنگ داخلی آمریکا (لوئیزیانا): کاسنی جایگزین قهوه شد.</li><li>جو برشته: نوشیدنی‌هایی مثل Barleycup و Caffè d’orzo.</li></ul><h4 class=\"sub\">کاسنی</h4><ul><li>ریشه‌ی کاسنی برشته در اروپا به‌عنوان جایگزین یا افزودنی قهوه کشت می‌شد؛ در نیواورلئان با قهوه مخلوط می‌شود. این سنت به جنگ داخلی آمریکا و محاصره‌ی دریایی اتحادیه نسبت داده می‌شود؛ در دهه‌ی ۱۸۴۰ بندر نیواورلئان دومین واردکننده‌ی قهوه‌ی آمریکا بود. در بحران بزرگ و جنگ جهانی دوم هم مصرف کاسنی در اروپا بالا رفت.</li></ul>","kind":"item","src":[["Wikipedia — Coffee substitute","https://en.wikipedia.org/wiki/Coffee_substitute"],["Wikipedia — Chicory","https://en.wikipedia.org/wiki/Chicory"]]},{"id":566,"title":"قهوه و تقلب‌ها، جعل‌ها و کلاهبرداری‌ها (Coffee & Frauds, Fakes & Scams)","body":"<h4 class=\"sub\">تقلب در قهوه</h4><ul><li>ریشه‌ی کاسنی برشته (chicory) پرکننده‌ی رایج قهوه است؛ اگر روی برچسب اعلام نشود، تقلب محسوب می‌شود.</li><li>نمونه‌های تاریخی تقلب غذایی: ۱۸۲۰ Frederick Accum نخستین پژوهش را کرد؛ Arthur Hill Hassall؛ قانون ۱۸۶۰؛ John Postgate و قانون ۱۸۷۵ بریتانیا.</li><li>قهوه به‌دلیل ارزش بازار بالا جزو ۱۰ محصولی است که بیشترین خطر تقلب غذایی را دارند.</li><li>تقلب دو شکل اصلی دارد: افزودن مواد ارزان‌تر و جایگزینی عربیکا با دانه‌ی ارزان‌تر.</li><li>افزودنی‌های گزارش‌شده شامل پوسته‌ی قهوه، کاسنی، غلات، بافت چوبی، کاکائو یا سویا، بری آسای و شکل‌های افزوده است.</li><li>نخستین گزارش تقلب در قهوه به ۱۸۵۱ برمی‌گردد که مجله‌ی The Lancet کاسنی، ذرت، لوبیا و سیب‌زمینی را به‌عنوان افزودنی نام برد. در گزارش ۱۸۵۳ بعضی قهوه‌ها تا ۵۰٪ کاسنی داشتند.</li><li>اصالت قهوه‌ی کوپی لواک (Kopi Luwak) به‌سختی تأیید می‌شود، چون اثر عبور از دستگاه گوارش را می‌توان با میکروارگانیسم و آنزیم تقلید کرد.</li></ul>","kind":"item","src":[["Wikipedia — Adulterated food","https://en.wikipedia.org/wiki/Adulterated_food"],["UK Government — Review of methods for coffee bean authenticity testing","https://gov.uk/government/news/review-of-methods-for-coffee-bean-authenticity-testing"],["Embrapa — Review of coffee adulteration and detection methods","https://www.alice.cnptia.embrapa.br/alice/bitstream/doc/1092721/1/fyy0171versaofinal.pdf"],["BeverageDaily — Analytical methods to detect coffee adulteration reviewed","https://www.beveragedaily.com/Article/2017/04/12/Determining-dilution-adulterant-and-origin-of-coffee/"]]},{"id":703,"title":"نشانه‌های تقلب در قهوه و آزمون‌های ساده","body":"<h4 class=\"sub\">نشانه‌های تقلب</h4><ul><li>ریشه‌ی کاسنی برشته پرکننده‌ی رایج قهوه است و اگر روی برچسب اعلام نشود تقلب است.</li><li>کوپی‌لواک: ادعای «وحشی» اغلب جعلی است؛ بررسی‌های PETA و BBC تقلب گسترده یافتند و تأیید اصالت برای خریدار دشوار است. قیمت خرده‌فروشی تا حدود ۱۰۰ دلار/کیلو (پرورشی) و ۱۳۰۰ دلار/کیلو (وحشی)؛ بسیاری از اهل صنعت آن را بیشتر «کنجکاوی» می‌دانند تا قهوه‌ی برتر.</li><li>مواد افزودنی پنهان در غذا اغلب برای کاهش هزینه یا دشواری تولید و بدون اطلاع خریدار اضافه می‌شوند؛ ریشه‌ی کاسنی برشته در صورت ذکر نشدن روی برچسب تقلب به حساب می‌آید.</li><li>دم‌کرده‌ی ریشه‌ی کاسنی کافئین ندارد، تیره است و طعمی شبیه قهوه دارد؛ جانشین‌های دیگر قهوه مانند جو برشته، بلوط و شلغم‌های ریشه‌ای نیز در تاریخ به قهوه افزوده شده‌اند.</li><li>درباره‌ی کوپی‌لواک، انجمن قهوه‌ی تخصصی آمریکا اجماع صنعت را این می‌داند که طعم خوبی ندارد؛ در یک آزمون چشایی، متخصصان آن را «رقیق» توصیف کردند.</li><li>تولیدکنندگان گاهی قهوه‌ی سیوِت‌های قفسی را «وحشی» برچسب می‌زنند.</li></ul>","kind":"item","src":[["Wikipedia — Adulterated food","https://en.wikipedia.org/wiki/Adulterated_food"],["Wikipedia — Kopi luwak","https://en.wikipedia.org/wiki/Kopi_luwak"],["Wikipedia — Adulterant","https://en.wikipedia.org/wiki/Adulterant"],["Wikipedia — Coffee substitute","https://en.wikipedia.org/wiki/Coffee_substitute"]]},{"id":704,"title":"برچسب‌ها و گواهی‌های قهوه: چه چیزی را تضمین می‌کنند؟","body":"<h4 class=\"sub\">گواهی‌ها</h4><ul><li>Fairtrade: تولیدکنندگان کوچک؛ خریداران باید دست‌کم «حداقل قیمت» (کف قیمتی که میانگین هزینه‌ی تولید را می‌پوشاند) و «حق بیمه‌ی اجتماعی» (Premium) برای سرمایه‌گذاری در کسب‌وکار و رفاه کارگران بپردازند و قراردادهای بلندمدت امضا کنند.</li><li>کار اجباری و کار کودکان ممنوع است؛ دستمزد دست‌کم حداقل قانونی؛ اتحادیه‌ی مستقل آزاد.</li><li>نهادها: Fairtrade International (استانداردها)، FLOCERT (بازرسی)، Fair Trade USA، Fair Trade Federation، WFTO؛ UTZ را گاه «Fairtrade lite» می‌نامند.</li><li>برای قیمت روز به سایت رسمی Fairtrade مراجعه کنید.</li></ul>","kind":"item","src":[["Wikipedia — Fairtrade certification","https://en.wikipedia.org/wiki/Fairtrade_certification"]]},{"id":705,"title":"ایمنی مصرف: کافئین، آکریل‌آمید و آلودگی‌های احتمالی","body":"<ul><li><strong>کافئین:</strong> EFSA برای بزرگسالان سالم مصرف تا ۴۰۰ میلی‌گرم در روز (حدود ۵٫۷ میلی‌گرم به ازای هر کیلوگرم وزن) و دُز تکی تا ۲۰۰ میلی‌گرم را نگران‌کننده نمی‌داند؛ برای بارداری و شیردهی سقف ۲۰۰ میلی‌گرم در روز؛ برای کودکان و نوجوانان ۳ میلی‌گرم به ازای هر کیلوگرم در روز.</li><li><strong>آکریل‌آمید:</strong> در برشته‌کاری از واکنش مایار شکل می‌گیرد؛ EFSA قهوه را در کنار سیب‌زمینی سرخ‌کرده از مهم‌ترین منابع آکریل‌آمید رژیم بزرگسالان می‌داند و می‌گوید آکریل‌آمید در غذا می‌تواند خطر سرطان را بالا ببرد، اما شواهد انسانی «محدود و ناهمسو» است. بر اساس EFSA، برشته‌های روشن‌تر عموماً آکریل‌آمید بیشتری از متوسط و تیره دارند.</li><li><strong>دی‌ترپن‌ها (کافستول):</strong> قهوه‌ی بدون فیلتر (مثل اسپرسو در حد متوسط و دم‌آوری بدون صافی) دی‌ترپن‌هایی دارد که کلسترول LDL و تری‌گلیسرید را بالا می‌برد؛ قهوه‌ی فیلتری و فوری تقریباً دی‌ترپن ندارد (Harvard T.H. Chan).</li><li><strong>اُکراتوکسین A:</strong> سمی از کپک‌های Aspergillus و Penicillium. حد مجاز اتحادیه‌ی اروپا ۵ میکروگرم بر کیلوگرم برای قهوه‌ی برشته و ۱۰ برای فوری است؛ خشک‌شدن سریع (رطوبت ۸ تا ۱۲٫۵٪) و انبار خشک از آلودگی جلوگیری می‌کند و برشته‌کاری ۷۰ تا بیش از ۹۰٪ آن را تجزیه می‌کند. مرور سیستماتیک ۳٬۲۵۶ نمونه (۱۹۹۷–۲۰۲۴) خطر مصرف معمول را ناچیز دانسته است.</li><li><strong>IARC:</strong> خود قهوه را «غیرقابل‌طبقه‌بندی» (گروه ۳) اعلام کرده، اما نوشیدنی‌های بسیار داغ (بالای ۶۵ درجه) را «احتمالاً سرطان‌زا» (گروه ۲A) برای مری؛ مشکل از دماست، نه نوشیدنی.</li></ul><p>اگر بیماری یا حساسیت خاصی دارید (مثل بارداری، اضطراب یا فشار خون)، با پزشک مشورت کنید.</p>","kind":"item","src":[["EFSA — Caffeine","https://www.efsa.europa.eu/en/topics/topic/caffeine"],["EFSA — Acrylamide","https://www.efsa.europa.eu/en/topics/topic/acrylamide"],["Harvard T.H. Chan — Coffee","https://nutritionsource.hsph.harvard.edu/food-features/coffee/"],["ECF — Guidelines for the prevention of OTA in coffee","https://www.ecf-coffee.org/wp-content/uploads/2022/02/Guidelines-for-the-prevention-of-OTA-occurence-in-Coffee_February2022_FINAL.pdf"],["PubMed — OTA in coffee products, systematic review","https://pubmed.ncbi.nlm.nih.gov/39259858/"],["IARC — Press release 244","https://www.iarc.who.int/wp-content/uploads/2018/07/pr244_E.pdf"]]}]},{"id":"C17","icon":"future","title":"آینده، نوآوری و علوم میان‌رشته‌ای قهوه","items":[{"id":10,"title":"نوآوری‌های تکنولوژیک (Technological Innovations)","body":"<h4 class=\"sub\">نوآوری‌ها</h4><ul><li>گونه‌ی مقاوم C. stenophylla (جزئیات در مقاله‌ی «قهوه و تکنولوژی‌های نوظهور»).</li><li>کشت سلولی قهوه (VTT) و قهوه‌ی بدون دانه‌ی Atomo؛ جزئیات در مقاله‌ی «قهوه‌ی کشت‌شده در آزمایشگاه».</li><li>گونه‌ی C. stenophylla به میانگین دمای سالانه‌ی حدود ۲۴٫۹ درجه‌ی سانتی‌گراد نیاز دارد؛ حدود ۱٫۹ درجه بیشتر از روبوستا و ۶٫۲ تا ۶٫۸ درجه بیشتر از عربیکا.</li><li>این گونه از ۱۹۵۴ در طبیعت دیده نشده بود تا اینکه در اواخر ۲۰۱۸ دوباره کشف شد؛ میوه‌ی آن گیلاس سیاه است و در فهرست قرمز IUCN در رده‌ی «آسیب‌پذیر» قرار دارد.</li><li>در چشایی ۲۰۲۰ امتیاز تخصصی ۸۰٫۲۵ گرفت (حداقل امتیاز تخصصی ۸۰ است) و ۸۱ درصد داوران در آزمون کور آن را عربیکا تشخیص دادند.</li><li>در پروژه‌ی VTT فنلاند، کشت سلولی قهوه در بیوراکتور انجام شد، زیست‌توده آسیاب و برشته شد و پانل حسی شباهت آن را به قهوه‌ی معمولی دید، ولی گفت جای بهبود دارد.</li><li>VTT گفته بیوراکتورهای کشت سلول گیاهی نزدیک ۱۰۰٬۰۰۰ لیتر وجود دارند و دریافت تأییدیه‌های آمریکا یا اروپا ممکن است حدود چهار سال طول بکشد.</li><li>شرکت Atomo (سیاتل) ضایعات گیاهی را به جامدی شبیه دانه‌ی قهوه تبدیل می‌کند؛ طبق گزارش، کارخانه‌اش برای حدود ۱۰۰۰ وعده‌ی قهوه در روز کافی بود و هدف آن ۱۰٬۰۰۰ وعده در روز بود.</li></ul>","kind":"item","src":[["Global Coffee Report — World's first lab-grown coffee (VTT)","https://www.gcrmag.com/worlds-first-lab-grown-coffee-offers-sustainable-future-solution"],["Sci.News — Coffea stenophylla (Nature Plants, 2021)","https://www.sci.news/biology/coffea-stenophylla-09573.html"],["Royal Botanic Gardens, Kew — Forgotten coffee species futureproofing industry against climate change","https://www.kew.org/about-us/press-media/forgotten-coffee-species-futureproofing-industry-against-climate-change"],["CIRAD — Forgotten coffee species could help futureproof the coffee industry","https://www.cirad.fr/en/press-area/press-releases/2021/coffea-stenophylla-coffee-climate-change"],["Daily Coffee News — Finnish scientists transform plant cells into coffee-like drink","https://dailycoffeenews.com/2021/09/15/finnish-scientists-successfully-transform-plant-cells-into-coffee-like-drink/"],["SingularityHub — Scientists are on a quest to create the perfect cup of synthetic coffee","https://singularityhub.com/2021/10/22/scientists-are-on-a-quest-to-create-the-perfect-cup-of-synthetic-coffee/"]]},{"id":18,"title":"آینده قهوه (Future of Coffee)","body":"<h4 class=\"sub\">قهوه‌ی کشت‌شده در آزمایشگاه</h4><ul><li>VTT فنلاند (گزارش نوامبر ۲۰۲۱): ابتدا کشت سلولی قهوه و ایجاد رده‌های سلولی (حدود شش ماه تا یک سال)، سپس انتقال به بیوراکتور با محیط مایع مواد معدنی و قند (چند هفته)؛ برداشت و صاف‌کردن مایع، ماده‌ی دانه‌ریز حاصل معادل «دانه‌ی قهوه» است؛ فریز‌درای به پودر، برشته‌کاری در درجات مختلف و ارزیابی با پانل حسی.</li><li>کشت‌ها حدود ۲۰٪ پروتئین داشتند؛ طعم و بو «بسیار شبیه قهوه» گزارش شد؛ کافئین وجود دارد و می‌توان مقدارش را تنظیم کرد.</li><li>وضعیت: نمونه‌ی اولیه؛ هنوز تأیید نظارتی نگرفته و VTT به‌دنبال شریک صنعتی است.</li><li>Atomo (آمریکا): در ۲۰۱۹ قهوه‌ای بدون دانه از مواد گیاهی نامعلوم و کافئین نشان داد و ۲۰۲۱ مدتی کوتاه فروخت؛ شباهت مولکولی آن به قهوه روشن نیست.</li><li>اگر محصولی از نظر شیمیایی با قهوه یکی باشد، «قهوه‌ی آزمایشگاهی» است نه جایگزین قهوه.</li></ul>","kind":"item","src":[["Global Coffee Report — World's first lab-grown coffee (VTT)","https://www.gcrmag.com/worlds-first-lab-grown-coffee-offers-sustainable-future-solution"],["Wikipedia — Coffee substitute","https://en.wikipedia.org/wiki/Coffee_substitute"]]},{"id":172,"title":"آینده‌پژوهی قهوه (Futurism)","body":"<h4 class=\"sub\">قهوه‌ی کشت‌شده در آزمایشگاه</h4><ul><li>VTT فنلاند (گزارش نوامبر ۲۰۲۱): ابتدا کشت سلولی قهوه و ایجاد رده‌های سلولی (حدود شش ماه تا یک سال)، سپس انتقال به بیوراکتور با محیط مایع مواد معدنی و قند (چند هفته)؛ برداشت و صاف‌کردن مایع، ماده‌ی دانه‌ریز حاصل معادل «دانه‌ی قهوه» است؛ فریز‌درای به پودر، برشته‌کاری در درجات مختلف و ارزیابی با پانل حسی.</li><li>کشت‌ها حدود ۲۰٪ پروتئین داشتند؛ طعم و بو «بسیار شبیه قهوه» گزارش شد؛ کافئین وجود دارد و می‌توان مقدارش را تنظیم کرد.</li><li>وضعیت: نمونه‌ی اولیه؛ هنوز تأیید نظارتی نگرفته و VTT به‌دنبال شریک صنعتی است.</li><li>Atomo (آمریکا): در ۲۰۱۹ قهوه‌ای بدون دانه از مواد گیاهی نامعلوم و کافئین نشان داد و ۲۰۲۱ مدتی کوتاه فروخت؛ شباهت مولکولی آن به قهوه روشن نیست.</li><li>اگر محصولی از نظر شیمیایی با قهوه یکی باشد، «قهوه‌ی آزمایشگاهی» است نه جایگزین قهوه.</li></ul>","kind":"item","src":[["Global Coffee Report — World's first lab-grown coffee (VTT)","https://www.gcrmag.com/worlds-first-lab-grown-coffee-offers-sustainable-future-solution"],["Wikipedia — Coffee substitute","https://en.wikipedia.org/wiki/Coffee_substitute"]]},{"id":326,"title":"قهوه و تکنولوژی‌های نوظهور","body":"<h4 class=\"sub\">قهوه‌ی کشت‌شده در آزمایشگاه</h4><ul><li>VTT فنلاند (گزارش نوامبر ۲۰۲۱): ابتدا کشت سلولی قهوه و ایجاد رده‌های سلولی (حدود شش ماه تا یک سال)، سپس انتقال به بیوراکتور با محیط مایع مواد معدنی و قند (چند هفته)؛ برداشت و صاف‌کردن مایع، ماده‌ی دانه‌ریز حاصل معادل «دانه‌ی قهوه» است؛ فریز‌درای به پودر، برشته‌کاری در درجات مختلف و ارزیابی با پانل حسی.</li><li>کشت‌ها حدود ۲۰٪ پروتئین داشتند؛ طعم و بو «بسیار شبیه قهوه» گزارش شد؛ کافئین وجود دارد و می‌توان مقدارش را تنظیم کرد.</li><li>وضعیت: نمونه‌ی اولیه؛ هنوز تأیید نظارتی نگرفته و VTT به‌دنبال شریک صنعتی است.</li><li>Atomo (آمریکا): در ۲۰۱۹ قهوه‌ای بدون دانه از مواد گیاهی نامعلوم و کافئین نشان داد و ۲۰۲۱ مدتی کوتاه فروخت؛ شباهت مولکولی آن به قهوه روشن نیست.</li><li>اگر محصولی از نظر شیمیایی با قهوه یکی باشد، «قهوه‌ی آزمایشگاهی» است نه جایگزین قهوه.</li></ul><h4 class=\"sub\">گونه‌های مقاوم به آب‌وهوا</h4><ul><li>Coffea stenophylla بومی گینه، سیرالئون و ساحل عاج است؛ خشکی‌تحمل و تا حدی مقاوم به زنگ قهوه گزارش شده.</li><li>ممکن است میانگین دمای سالانه‌ی ۲۴٫۹ درجه را تحمل کند؛ دست‌کم ۶ درجه بیش از عربیکا (بهینه ۱۸–۲۲).</li><li>در ارزیابی حسی استاندارد، طعمی شبیه عربیکای باکیفیت داشت. پژوهش به رهبری Aaron P. Davis (باغ‌های سلطنتی کیو) در Nature Plants، ۲۰۲۱.</li></ul>","kind":"item","src":[["Global Coffee Report — World's first lab-grown coffee (VTT)","https://www.gcrmag.com/worlds-first-lab-grown-coffee-offers-sustainable-future-solution"],["Wikipedia — Coffee substitute","https://en.wikipedia.org/wiki/Coffee_substitute"],["Sci.News — Coffea stenophylla (Nature Plants, 2021)","https://www.sci.news/biology/coffea-stenophylla-09573.html"]]},{"id":506,"title":"قهوه و آینده‌ی نهایی (Coffee & Ultimate Future)","body":"<h4 class=\"sub\">قهوه در ایستگاه فضایی</h4><ul><li>ISSpresso ماشین اسپرسویی است که ایتالیایی‌ها و شرکت Lavazza ساختند و با کپسول SpaceX Dragon به ایستگاه فضایی بین‌المللی رسید.</li><li>سامانتا کریستوفورتی، فضانورد ایتالیایی، در ۳ مه ۲۰۱۵ عکس آن را در توییتر گذاشت.</li><li>فنجان مخصوص گرانش‌صفر: شش فنجان در ایستگاه است و به پژوهش Capillary Beverage کمک می‌کند که حرکت منفعل سیالات پیچیده را برای طراحی ظروف مهار جریان بررسی می‌کند.</li></ul>","kind":"item","src":[["NPR — Espresso on the ISS (2015)","https://www.npr.org/sections/thetwo-way/2015/05/04/404241117/space-shot-italian-astronaut-boldly-brews-espresso-on-space-station"]]}]}];